import { useState } from 'react';
import type { Field, Season } from '../../../../types';
import { getFieldsByFarmer, getSeasonsByFarmer, addField, updateField, deleteField, getState } from '../../../../store';
import { StatusBadge } from '../../../../components/base/StatusBadge';
import { EmptyState } from '../../../../components/base/EmptyState';
import { showToast } from '../../../../components/base/Toast';
import { confirmModal } from '../../../../components/base/ConfirmModal';
import { todayInputValue } from '../../../../utils/format';
import { useStore } from '../../../../hooks/useStore';

interface FieldTabProps {
  farmerId: string;
}

const loaiDatOptions = ['Đất phù sa', 'Đất đỏ bazan', 'Đất cát', 'Đất ngập mặn', 'Đất đen'];
const statusOptions = ['Đang canh tác', 'Tạm dừng', 'Bỏ trống'];

export default function FieldTab({ farmerId }: FieldTabProps) {
  const store = useStore();
  const fields = getFieldsByFarmer(farmerId);
  const seasons = getSeasonsByFarmer(farmerId);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [viewing, setViewing] = useState<Field | null>(null);
  const [form, setForm] = useState<Partial<Field>>({
    name: '',
    maThuaDat: '',
    area: 0,
    location: '',
    loaiDat: loaiDatOptions[0],
    status: 'Đang canh tác',
    hinhAnh: '',
    ghiChu: '',
  });

  const openCreate = () => {
    setEditingId(null);
    setForm({
      name: '',
      maThuaDat: '',
      area: 0,
      location: '',
      loaiDat: loaiDatOptions[0],
      status: 'Đang canh tác',
      hinhAnh: '',
      ghiChu: '',
    });
    setModalOpen(true);
  };

  const openEdit = (field: Field) => {
    setEditingId(field.id);
    setForm({ ...field });
    setModalOpen(true);
  };

  const openView = (field: Field) => {
    setViewing(field);
  };

  const closeView = () => setViewing(null);

  const seasonCountForField = (fieldId: string) =>
    seasons.filter((s) => s.fieldId === fieldId && s.status !== 'Kết thúc').length;

  const handleSave = () => {
    if (!form.name || !form.maThuaDat || !form.area || !form.location) {
      showToast('Vui lòng điền đầy đủ thông tin bắt buộc', 'warning');
      return;
    }
    const payload: Omit<Field, 'id'> = {
      farmerId,
      maThuaDat: form.maThuaDat || '',
      name: form.name || '',
      area: Number(form.area) || 0,
      location: form.location || '',
      loaiDat: form.loaiDat || loaiDatOptions[0],
      status: (form.status as Field['status']) || 'Đang canh tác',
      hinhAnh: form.hinhAnh || undefined,
      ghiChu: form.ghiChu || undefined,
    };
    if (editingId) {
      updateField(editingId, payload);
      showToast('Đã cập nhật thửa đất', 'success');
    } else {
      addField(payload);
      showToast('Đã thêm thửa đất mới', 'success');
    }
    setModalOpen(false);
  };

  const handleDelete = async (field: Field) => {
    const activeSeasons = seasonCountForField(field.id);
    if (activeSeasons > 0) {
      await confirmModal({
        title: 'Không thể xóa',
        message: 'Không thể xóa thửa đất đang có mùa vụ hoạt động.',
        confirmText: 'Đã hiểu',
        cancelText: 'Đóng',
        variant: 'danger',
      });
      return;
    }
    const ok = await confirmModal({
      title: 'Xác nhận xóa',
      message: `Bạn có chắc muốn xóa thửa đất "${field.name}"?`,
      confirmText: 'Xóa',
      cancelText: 'Hủy',
      variant: 'danger',
    });
    if (!ok) return;
    deleteField(field.id);
    showToast('Đã xóa thửa đất', 'success');
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-base font-semibold text-slate-900">
          Thửa đất ({fields.length})
        </h3>
        <button
          type="button"
          onClick={openCreate}
          className="px-3 py-2 rounded-md text-sm font-medium bg-agrida-700 hover:bg-agrida-800 text-white transition-colors whitespace-nowrap min-h-[44px]"
        >
          <span className="w-4 h-4 inline-flex items-center justify-center mr-1">
            <i className="ri-add-line" />
          </span>
          Thêm thửa đất
        </button>
      </div>

      {fields.length === 0 ? (
        <EmptyState icon="ri-map-pin-line" title="Chưa có thửa đất" description="Hãy thêm thửa đất để bắt đầu quản lý canh tác." />
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {fields.map((field) => (
            <div key={field.id} className="bg-white rounded-xl border border-slate-200 p-4 md:p-5">
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="text-sm font-semibold text-slate-900">{field.name}</p>
                    <StatusBadge status={field.status} />
                  </div>
                  <p className="text-xs text-slate-500 mt-1">Mã: {field.maThuaDat} · {field.area} ha · {field.loaiDat}</p>
                  <p className="text-xs text-slate-400 mt-0.5">{field.location}</p>
                  {field.ghiChu && <p className="text-xs text-slate-500 mt-1">Ghi chú: {field.ghiChu}</p>}
                  <p className="text-xs text-slate-400 mt-1">
                    <i className="ri-seedling-line mr-1" />
                    {seasonCountForField(field.id)} mùa vụ liên quan
                  </p>
                </div>
                {field.hinhAnh && (
                  <img
                    src={field.hinhAnh}
                    alt={field.name}
                    className="w-20 h-20 rounded-lg object-cover shrink-0 border border-slate-100"
                    loading="lazy"
                  />
                )}
              </div>
              <div className="flex items-center gap-2 mt-4">
                <button
                  type="button"
                  onClick={() => openView(field)}
                  className="px-3 py-1.5 rounded-md text-xs font-medium text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
                >
                  Xem chi tiết
                </button>
                <button
                  type="button"
                  onClick={() => openEdit(field)}
                  className="px-3 py-1.5 rounded-md text-xs font-medium text-agrida-700 bg-agrida-50 hover:bg-agrida-100 transition-colors whitespace-nowrap min-h-[44px]"
                >
                  Sửa
                </button>
                <button
                  type="button"
                  onClick={() => handleDelete(field)}
                  className="px-3 py-1.5 rounded-md text-xs font-medium text-red-700 bg-red-50 hover:bg-red-100 transition-colors whitespace-nowrap min-h-[44px]"
                >
                  Xóa
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* View modal */}
      {viewing && (
        <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={closeView} />
          <div className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-lg max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto animate-modal-panel">
            <div className="sticky top-0 bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between z-10">
              <h3 className="text-base font-semibold text-slate-900">Chi tiết thửa đất</h3>
              <button type="button" onClick={closeView} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400">
                <i className="ri-close-line text-lg" />
              </button>
            </div>
            <div className="p-4 space-y-3">
              {viewing.hinhAnh && (
                <img src={viewing.hinhAnh} alt={viewing.name} className="w-full h-48 rounded-lg object-cover" />
              )}
              <div className="grid grid-cols-2 gap-3">
                <div><p className="text-xs text-slate-400">Mã thửa đất</p><p className="text-sm font-medium">{viewing.maThuaDat}</p></div>
                <div><p className="text-xs text-slate-400">Tên thửa đất</p><p className="text-sm font-medium">{viewing.name}</p></div>
                <div><p className="text-xs text-slate-400">Diện tích</p><p className="text-sm font-medium">{viewing.area} ha</p></div>
                <div><p className="text-xs text-slate-400">Loại đất</p><p className="text-sm font-medium">{viewing.loaiDat}</p></div>
                <div><p className="text-xs text-slate-400">Vị trí</p><p className="text-sm font-medium">{viewing.location}</p></div>
                <div><p className="text-xs text-slate-400">Tình trạng</p><StatusBadge status={viewing.status} /></div>
                <div><p className="text-xs text-slate-400">Số mùa vụ liên quan</p><p className="text-sm font-medium">{seasonCountForField(viewing.id)}</p></div>
              </div>
              {viewing.ghiChu && (
                <div><p className="text-xs text-slate-400">Ghi chú</p><p className="text-sm">{viewing.ghiChu}</p></div>
              )}
            </div>
            <div className="sticky bottom-0 bg-white border-t border-slate-100 px-4 py-3">
              <button
                type="button"
                onClick={closeView}
                className="w-full px-4 py-2.5 rounded-lg text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
              >
                Đóng
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Create/Edit modal */}
      {modalOpen && (
        <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={() => setModalOpen(false)} />
          <div className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-lg max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto animate-modal-panel">
            <div className="sticky top-0 bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between z-10">
              <h3 className="text-base font-semibold text-slate-900">{editingId ? 'Sửa thửa đất' : 'Thêm thửa đất'}</h3>
              <button type="button" onClick={() => setModalOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400">
                <i className="ri-close-line text-lg" />
              </button>
            </div>
            <div className="px-4 py-4 space-y-3">
              <div>
                <label className="block text-xs text-slate-500 mb-1">Mã thửa đất *</label>
                <input
                  type="text"
                  value={form.maThuaDat || ''}
                  onChange={(e) => setForm((p) => ({ ...p, maThuaDat: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Tên thửa đất *</label>
                <input
                  type="text"
                  value={form.name || ''}
                  onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Diện tích (ha) *</label>
                  <input
                    type="number"
                    step="0.1"
                    value={form.area || ''}
                    onChange={(e) => setForm((p) => ({ ...p, area: Number(e.target.value) }))}
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                  />
                </div>
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Loại đất</label>
                  <select
                    value={form.loaiDat || loaiDatOptions[0]}
                    onChange={(e) => setForm((p) => ({ ...p, loaiDat: e.target.value }))}
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                  >
                    {loaiDatOptions.map((o) => <option key={o} value={o}>{o}</option>)}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Vị trí mô tả *</label>
                <input
                  type="text"
                  value={form.location || ''}
                  onChange={(e) => setForm((p) => ({ ...p, location: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Tình trạng</label>
                <select
                  value={form.status || 'Đang canh tác'}
                  onChange={(e) => setForm((p) => ({ ...p, status: e.target.value as Field['status'] }))}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                >
                  {statusOptions.map((o) => <option key={o} value={o}>{o}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Ảnh thửa đất (URL)</label>
                <input
                  type="text"
                  value={form.hinhAnh || ''}
                  onChange={(e) => setForm((p) => ({ ...p, hinhAnh: e.target.value }))}
                  placeholder="https://..."
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Ghi chú</label>
                <textarea
                  value={form.ghiChu || ''}
                  onChange={(e) => setForm((p) => ({ ...p, ghiChu: e.target.value }))}
                  rows={2}
                  maxLength={500}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
            </div>
            <div className="sticky bottom-0 bg-white border-t border-slate-100 px-4 py-3 flex gap-3 justify-end">
              <button
                type="button"
                onClick={() => setModalOpen(false)}
                className="px-4 py-2.5 rounded-lg text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
              >
                Hủy
              </button>
              <button
                type="button"
                onClick={handleSave}
                className="px-4 py-2.5 rounded-lg text-sm font-medium bg-agrida-700 hover:bg-agrida-800 text-white transition-colors whitespace-nowrap min-h-[44px]"
              >
                {editingId ? 'Lưu thay đổi' : 'Thêm'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}