    // eKYC aliases
    'Chưa xác thực':            EKYC_STATUS.REGISTERED,
    'Đang chờ xác thực':        EKYC_STATUS.PENDING,
    'Xác thực thành công':      EKYC_STATUS.VERIFIED,
    'Bổ sung thông tin':        EKYC_STATUS.NEED_MORE,
