/** eKYC: get color for a KycStatus (internal key). */
export function getKycColor(status: string): ColorPair {
  const map: Record<string, ColorPair> = {
    registered:      C.slate,
    ekyc_pending:    C.sky,
    ekyc_verified:   C.green,
    ekyc_need_more:  C.amber,
    ekyc_failed:     C.red,
  };
  return map[status] || FALLBACK_COLOR;
}

/** eKYC: get display label for a KycStatus (internal key). */
export function getKycLabel(status: string): string {
  const map: Record<string, string> = {
    registered:     EKYC_STATUS.REGISTERED,
    ekyc_pending:   EKYC_STATUS.PENDING,
    ekyc_verified:  EKYC_STATUS.VERIFIED,
    ekyc_need_more: EKYC_STATUS.NEED_MORE,
    ekyc_failed:    EKYC_STATUS.FAILED,
  };
  return map[status] || 'Không xác định';
}

/** Risk: get badge color for a RiskLevel. */
export function getRiskColor(risk?: string): ColorPair {
  return getStatusColor(risk || '');
}

/** Credit score: get label. */
export function getCreditScoreLabel(score: number | null | undefined): string {
  if (score == null) return 'Chưa có điểm';
  if (score >= 760) return 'Tốt';
  if (score >= 650) return 'Khá';
  if (score >= 550) return 'Cần chú ý';
  if (score >= 450) return 'Rủi ro cao';
  return 'Nguy cơ';
}

/** Credit score: get text color. */
export function getCreditScoreColor(score: number | null | undefined): string {
  if (score == null) return 'text-slate-400';
  if (score >= 760) return 'text-emerald-700';
  if (score >= 650) return 'text-teal-700';
  if (score >= 550) return 'text-amber-600';
  if (score >= 450) return 'text-orange-600';
  return 'text-red-600';
}

/** Credit score: get badge background class. */
export function getCreditScoreBg(score: number | null | undefined): string {
  if (score == null) return 'bg-slate-100';
  if (score >= 760) return 'bg-emerald-100';
  if (score >= 650) return 'bg-teal-100';
  if (score >= 550) return 'bg-amber-100';
  if (score >= 450) return 'bg-orange-100';
  return 'bg-red-100';
}

/** Credit score: get border class. */
export function getCreditScoreBorder(score: number | null | undefined): string {
  if (score == null) return 'border-slate-200';
  if (score >= 760) return 'border-emerald-300';
  if (score >= 650) return 'border-teal-300';
  if (score >= 550) return 'border-amber-300';
  if (score >= 450) return 'border-orange-300';
  return 'border-red-300';
}

/** Loan type: get badge color for Tiền/Vật tư. */
export function getLoanTypeColor(type?: string): ColorPair {
  if (type === LOAN_TYPE.MONEY) return C.sky;
  if (type === LOAN_TYPE.MATERIAL) return C.green;
  return C.slate;
}

