import { useState, useRef, useCallback } from 'react';
import { formatDate, todayInputValue } from '../../../../utils/format';
import { showToast } from '../../../../components/base/Toast';
import { useModalBackHandler } from '../../../../hooks/useModalBackHandler';
import type { Material, Season } from '../../../../types';

const NHOM_VAT_TU = [
  'Giống',
  'Phân bón',
  'Thuốc BVTV',
  'Hóa chất',
  'Bao bì',
  'Công cụ',
  'Khác',
];

const STATUS_OPTIONS: Material['status'][] = ['Đủ', 'Sắp hết', 'Thiếu'];

interface MaterialFormModalProps {
  editItem?: Material | null;
  seasons: Season[];
  onSave: (data: {
    tenVatTu: string;
    nhomVatTu: string;
    nguonGoc: Material['nguonGoc'];
    soLuong: number;
    tonKho: number;
    donVi: string;
    ngayCap: string;
    seasonId: string;
    ghiChu?: string;
    status: Material['status'];
  }) => void;
  onClose: () => void;
}

export function MaterialFormModal({ editItem, seasons, onSave, onClose }: MaterialFormModalProps) {
  useModalBackHandler(true, onClose);
  const isEdit = !!editItem;
  const isHtx = editItem?.nguonGoc === 'HTX cấp/ứng';

  const [tenVatTu, setTenVatTu] = useState(editItem?.tenVatTu || '');
  const [nhomVatTu, setNhomVatTu] = useState(editItem?.nhomVatTu || NHOM_VAT_TU[0]);
  const [nguonGoc, setNguonGoc] = useState<Material['nguonGoc']>(editItem?.nguonGoc || 'Nông hộ tự mua');
  const [soLuong, setSoLuong] = useState(String(editItem?.soLuong || ''));
  const [tonKho, setTonKho] = useState(String(editItem?.tonKho ?? editItem?.soLuong ?? ''));
  const [donVi, setDonVi] = useState(editItem?.donVi || 'kg');
  const [ngayCap, setNgayCap] = useState(editItem?.ngayCap || todayInputValue());
  const [seasonId, setSeasonId] = useState(editItem?.seasonId || seasons[0]?.id || '');
  const [ghiChu, setGhiChu] = useState(editItem?.ghiChu || '');
  const [status, setStatus] = useState<Material['status']>(editItem?.status || 'Đủ');

  const [previews, setPreviews] = useState<string[]>([]);
  const fileRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach((file) => {
      setPreviews((prev) => [...prev, URL.createObjectURL(file)]);
    });
    if (fileRef.current) fileRef.current.value = '';
  }, []);

  const removePreview = (idx: number) => {
    setPreviews((prev) => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = () => {
    const soLuongNum = Number(soLuong);
    const tonKhoNum = Number(tonKho);
    if (!tenVatTu.trim()) {
      showToast('Vui lòng nhập tên vật tư', 'warning');
      return;
    }
    if (!soLuongNum || soLuongNum <= 0) {
      showToast('Vui lòng nhập số lượng hợp lệ', 'warning');
      return;
    }
    if (!donVi.trim()) {
      showToast('Vui lòng nhập đơn vị', 'warning');
      return;
    }
    if (!ngayCap) {
      showToast('Vui lòng chọn ngày nhập', 'warning');
      return;
    }

    onSave({
      tenVatTu: tenVatTu.trim(),
      nhomVatTu,
      nguonGoc,
      soLuong: soLuongNum,
      tonKho: tonKhoNum,
      donVi: donVi.trim(),
      ngayCap,
      seasonId,
      ghiChu: ghiChu.trim() || undefined,
      status,
    });
    showToast(isEdit ? 'Cập nhật vật tư thành công' : 'Thêm vật tư thành công', 'success');
  };

  return (
    <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
      <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={onClose} />
      <div onClick={(e) => e.stopPropagation()} className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-lg max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto animate-modal-slide-up">
        <div className="sticky top-0 bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between z-10">
          <h3 className="text-base font-semibold text-slate-900">
            {isEdit ? 'Sửa vật tư' : 'Thêm vật tư mới'}
          </h3>
          <button type="button" onClick={onClose} className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-slate-600">
            <i className="ri-close-line text-xl" />
          </button>
        </div>

        <div className="p-4 space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Tên vật tư <span className="text-red-500">*</span></label>
            <input
              type="text"
              value={tenVatTu}
              onChange={(e) => setTenVatTu(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              placeholder="Tên vật tư"
              disabled={isEdit && isHtx}
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Nhóm vật tư</label>
            <select
              value={nhomVatTu}
              onChange={(e) => setNhomVatTu(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              disabled={isEdit && isHtx}
            >
              {NHOM_VAT_TU.map((n) => (<option key={n} value={n}>{n}</option>))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Nguồn vật tư</label>
            <select
              value={nguonGoc}
              onChange={(e) => setNguonGoc(e.target.value as Material['nguonGoc'])}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              disabled={isEdit}
            >
              <option value="Nông hộ tự mua">Nông hộ tự mua</option>
              <option value="HTX cấp/ứng">HTX cấp/ứng</option>
            </select>
            {isEdit && isHtx && (
              <p className="text-xs text-sky-600 mt-1">Vật tư HTX cấp/ứng không thể đổi nguồn.</p>
            )}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Số lượng tồn <span className="text-red-500">*</span></label>
              <input
                type="number"
                value={soLuong}
                onChange={(e) => setSoLuong(e.target.value)}
                className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                placeholder="Số lượng"
                disabled={isEdit && isHtx}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Đơn vị <span className="text-red-500">*</span></label>
              <input
                type="text"
                value={donVi}
                onChange={(e) => setDonVi(e.target.value)}
                className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                placeholder="kg, lít, cái..."
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Ngày nhập</label>
              <input
                type="date"
                value={ngayCap}
                onChange={(e) => setNgayCap(e.target.value)}
                className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                disabled={isEdit && isHtx}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Trạng thái</label>
              <select
                value={status}
                onChange={(e) => setStatus(e.target.value as Material['status'])}
                className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              >
                {STATUS_OPTIONS.map((s) => (<option key={s} value={s}>{s}</option>))}
              </select>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Mùa vụ liên quan</label>
            <select
              value={seasonId}
              onChange={(e) => setSeasonId(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              disabled={isEdit && isHtx}
            >
              <option value="">Chọn mùa vụ</option>
              {seasons.map((s) => (
                <option key={s.id} value={s.id}>{s.maMuaVu} - {s.name}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú</label>
            <input
              type="text"
              value={ghiChu}
              onChange={(e) => setGhiChu(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              placeholder="Ghi chú..."
            />
          </div>

          {!isEdit && (
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Ảnh / chứng từ nếu có</label>
              <button
                type="button"
                onClick={() => fileRef.current?.click()}
                className="px-3 py-2 rounded-lg border border-slate-200 text-xs font-medium text-slate-700 hover:bg-slate-50 flex items-center gap-1 whitespace-nowrap"
              >
                <span className="w-3 h-3 flex items-center justify-center"><i className="ri-image-line" /></span>
                Chọn ảnh
              </button>
              <input ref={fileRef} type="file" accept="image/*,video/*" multiple className="hidden" onChange={handleFileSelect} />
              {previews.length > 0 && (
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2 mt-2">
                  {previews.map((url, idx) => (
                    <div key={idx} className="relative aspect-square rounded-lg overflow-hidden bg-slate-100">
                      <img src={url} alt={`preview-${idx}`} className="w-full h-full object-cover" />
                      <button
                        type="button"
                        onClick={() => removePreview(idx)}
                        className="absolute top-1 right-1 w-5 h-5 bg-black/50 rounded-full text-white flex items-center justify-center text-xs"
                      >
                        <i className="ri-close-line" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        <div className="sticky bottom-0 bg-white border-t border-slate-100 px-4 py-3 flex gap-3 justify-end">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2.5 rounded-md text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
          >
            Hủy
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            className="px-4 py-2.5 rounded-md text-sm font-medium text-white bg-emerald-700 hover:bg-emerald-800 transition-colors whitespace-nowrap min-h-[44px]"
          >
            {isEdit ? 'Lưu thay đổi' : 'Thêm mới'}
          </button>
        </div>
      </div>
    </div>
  );
}