function normalizeFarmerNotes(farmers: Farmer[]): Farmer[] {
  return farmers.map((farmer) => {
    const note = farmer.ghiChu || '';
    const looksLikeQaNote = /PASS:|FAIL:|TEST CASE|SOURCE_NOT_ENOUGH|reconcile_failed/i.test(note);
    if (!looksLikeQaNote) return farmer;
    return { ...farmer, ghiChu: FARMER_NOTE_BY_ID[farmer.id] || note };
  });
}

