function migrateFinancialFlow(input: AppState): AppState {
  const notificationIds = new Set<string>();
  const notifications = input.notifications.map((notification, index) => {
    let id = notification.id;
    if (!id || notificationIds.has(id)) id = `${id || 'notif'}-${index}`;
    notificationIds.add(id);
    return id === notification.id ? notification : { ...notification, id };
  });

  const normalizedHtxLoanSources = input.htxLoanSources.length > 0
    ? input.htxLoanSources.map((source) => {
        if (source.loaiNguon !== 'Ngân hàng' && !/agribank|bidv|vietcombank|sacombank|vietinbank|mb bank/i.test(source.tenNguonVay)) return source;
        return {
          ...source,
          loaiNguon: 'Antesco' as const,
          tenNguonVay: source.tenNguonVay.replace(/Vay\s+.+/i, 'Nguồn vốn Antesco'),
          ghiChu: 'Nguồn vốn được chuyển đổi sang quan hệ cấp vốn trực tiếp Antesco - HTX.',
        };
      })
    : [{
        id: 'ls-antesco-default', maNguonVay: 'ANT-001', tenNguonVay: 'Nguồn vốn Antesco',
        loaiNguon: 'Antesco' as const, hanMuc: 8500000000, daSuDung: 2105000000, laiSuat: 0.45,
        kyHan: '36 tháng', ngayBatDau: '2026-01-01', ngayKetThuc: '2028-12-31',
        status: 'Đang hiệu lực' as const, ghiChu: 'Antesco cấp vốn trực tiếp cho HTX.',
      }];

  const htxLoanSources = mergeById(normalizedHtxLoanSources, [
    {
      id: 'ls-antesco-seasonal',
      maNguonVay: 'ANT-002',
      tenNguonVay: 'Nguồn vốn Antesco mùa vụ Hè Thu',
      loaiNguon: 'Antesco' as const,
      hanMuc: 800000000,
      daSuDung: 600000000,
      laiSuat: 0.48,
      kyHan: '12 tháng',
      ngayBatDau: '2026-05-16',
      ngayKetThuc: '2027-05-16',
      status: 'Đang hiệu lực' as const,
      ghiChu: 'Nguồn vốn ngắn hạn để HTX giải ngân nhóm khoản vay đã duyệt.',
    },
    {
      id: 'ls-antesco-near-due',
      maNguonVay: 'ANT-003',
      tenNguonVay: 'Nguồn vốn Antesco gần đến hạn',
      loaiNguon: 'Antesco' as const,
      hanMuc: 50000000,
      daSuDung: 20000000,
      laiSuat: 0.6,
      kyHan: '12 tháng',
      ngayBatDau: '2025-07-01',
      ngayKetThuc: '2026-06-30',
      status: 'Sắp hết hạn' as const,
      ghiChu: 'Khoản vay nhỏ dùng để mô phỏng cảnh báo đến hạn và luồng trả nợ.',
    },
    {
      id: 'ls-antesco-closed',
      maNguonVay: 'ANT-000',
      tenNguonVay: 'Nguồn vốn Antesco đã tất toán',
      loaiNguon: 'Antesco' as const,
      hanMuc: 300000000,
      daSuDung: 0,
      laiSuat: 0.5,
      kyHan: '6 tháng',
      ngayBatDau: '2025-09-01',
      ngayKetThuc: '2026-03-01',
      status: 'Đã kết thúc' as const,
      ghiChu: 'Lịch sử nguồn vốn đã tất toán, không tính vào hạn mức khả dụng.',
    },
  ]);

  const legacyPaymentStatuses: PaymentIntentStatus[] = [
    'farmer_confirmed_transfer', 'waiting_bank_credit', 'bank_credit_received', 'reconciled',
  ];

  const seeded = seedLendingMockData({ ...input, notifications, htxLoanSources });

  return {
    ...seeded,
    notifications: seeded.notifications,
    htxLoanSources: seeded.htxLoanSources,
    bankLoanRequests: seeded.bankLoanRequests.map((request) => ({
      ...request,
      nganHangDeXuat: 'Antesco',
      ghiChu: request.ghiChu?.replace(/ngân hàng/gi, 'Antesco'),
    })),
    bankLimitRequests: seeded.bankLimitRequests.map((request) => ({
      ...request,
      nganHangDeXuat: 'Antesco',
      ghiChu: request.ghiChu?.replace(/ngân hàng/gi, 'Antesco'),
    })),
    paymentIntents: seeded.paymentIntents.map((intent) => legacyPaymentStatuses.includes(intent.status)
      ? { ...intent, status: 'waiting_htx_confirmation', bankCreditMatch: true }
      : intent),
  };
}

function loadState(): AppState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as AppState;
      return migrateFinancialFlow({ ...initialState, ...parsed, users: parsed.users ?? initialState.users });
    }
  } catch {
    // ignore localStorage parse errors
  }
  return migrateFinancialFlow(JSON.parse(JSON.stringify(initialState)) as AppState);
}

function saveState(state: AppState) { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch {
  // ignore localStorage write errors
} }

let state = loadState();

const listeners = new Set<() => void>();
const syncChannel = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('agrida_realtime_store') : null;

export function subscribe(listener: () => void) { listeners.add(listener); return () => { listeners.delete(listener); }; }
function notify() { listeners.forEach((l) => l()); }

function applyExternalState(nextState: AppState) {
  const currentUser = state.currentUser;
  state = migrateFinancialFlow({ ...nextState, currentUser });
  notify();
}

syncChannel?.addEventListener('message', (event: MessageEvent<AppState>) => {
  if (event.data) applyExternalState(event.data);
});

if (typeof window !== 'undefined') {
  window.addEventListener('storage', (event) => {
    if (event.key !== STORAGE_KEY || !event.newValue) return;
    try { applyExternalState(JSON.parse(event.newValue) as AppState); } catch { /* ignore */ }
  });
}

export function getState(): AppState { return state; }
export function setState(updater: (prev: AppState) => AppState) {
  state = updater(state);
  saveState(state);
  notify();
  syncChannel?.postMessage(state);
}

export function login(username: string, password: string): User | null {
  const user = state.users.find((u) => u.username === username && u.password === password);
  if (user) { setState((prev) => ({ ...prev, currentUser: user })); return user; }
  return null;
}

export function register(data:{username:string;password:string;role:'Nông hộ'|'Hợp tác xã';displayName:string;code:string;phone?:string;address?:string;tinhThanh?:string;huyen?:string;xa?:string;loaiCay?:string;nguoiDaiDien?:string;chucVu?:string;dienTich?:number}):User{
  const now=Date.now();const userId=`u${now}`;const farmerId=`f${now}`;
  const newUser:User={id:userId,username:data.username,password:data.password,role:data.role,displayName:data.displayName,code:data.code,farmerId:data.role==='Nông hộ'?farmerId:undefined,kycStatus:'registered'};
  setState((prev)=>({...prev,users:[...prev.users,newUser],currentUser:newUser,farmers:data.role==='Nông hộ'?[...prev.farmers,{id:farmerId,code:data.code,name:data.displayName,phone:data.phone||'',address:data.address||'',tinhThanh:data.tinhThanh||'',huyen:data.huyen||'',xa:data.xa||'',dienTich:data.dienTich||0,soThanhVien:1,loaiCay:data.loaiCay||'',ngayBatDau:new Date().toISOString().split('T')[0],status:'Hoạt động',htxStatus:'Cần chú ý',ghiChu:'Nông hộ mới đăng ký, đang chờ eKYC',userId}]:prev.farmers}));
  return newUser;
}

export function updateKycStatus(userId:string,newStatus:KycStatus,reason?:string,creditScore?:number,riskLevel?:RiskLevel){
  setState((prev)=>{
    const users=prev.users.map((u)=>{if(u.id===userId){const updated:User={...u,kycStatus:newStatus,kycReason:reason||undefined};if(newStatus==='ekyc_verified'){updated.creditScore=creditScore;updated.riskLevel=riskLevel;updated.verifiedAt=new Date().toISOString();}return updated;}return u;});
    let currentUser=prev.currentUser;if(currentUser&&currentUser.id===userId){currentUser={...currentUser,kycStatus:newStatus,kycReason:reason||undefined};if(newStatus==='ekyc_verified'){currentUser.creditScore=creditScore;currentUser.riskLevel=riskLevel;currentUser.verifiedAt=new Date().toISOString();}}
    return{...prev,users,currentUser};
  });
}

