export interface FarmerKycInfo{kycStatus:KycStatus;kycReason?:string;creditScore?:number;riskLevel?:RiskLevel;verifiedAt?:string;cccdMask?:string;ocrName?:string;ocrDob?:string;ocrGender?:string;ocrAddress?:string;ocrIssueDate?:string;selfieResult?:string;}
export function getFarmerKyc(farmer: Farmer): FarmerKycInfo {
  return {
    kycStatus: farmer.kycStatus || 'ekyc_verified',
    kycReason: farmer.kycReason,
    creditScore: farmer.creditScore,
    riskLevel: farmer.riskLevel || 'Tốt',
    verifiedAt: farmer.verifiedAt,
    cccdMask: farmer.cccdMask,
    ocrName: farmer.ocrName,
    ocrDob: farmer.ocrDob,
    ocrGender: farmer.ocrGender,
    ocrAddress: farmer.ocrAddress,
    ocrIssueDate: farmer.ocrIssueDate,
    selfieResult: farmer.selfieResult,
  };
}
