export interface BankLimitResponse{status:'Đã duyệt'|'Từ chối'|'Cần bổ sung';lyDoTuChoi?:string;noiDungBoSung?:string;hanMucTangThem?:number;}
export function mockBankLimitRequest(htxUserId:string,soTien:number,lyDo:string,ghiChu?:string,nganHangDeXuat?:string,thoiGianMongMuon?:string):Promise<BankLimitResponse>{return new Promise((resolve)=>{const request=addBankLimitRequest({htxUserId,soTienDeNghi:soTien,lyDo,ghiChu,nganHangDeXuat,thoiGianMongMuon,ngayYeuCau:new Date().toISOString(),status:'Chờ duyệt'});const delay=1500+Math.random()*1500;setTimeout(()=>{const rand=Math.random();let response:BankLimitResponse;if(rand<0.45){response={status:'Đã duyệt',hanMucTangThem:1000000000};const bankNames=['Agribank - CN Đồng Tháp','BIDV - CN Đồng Tháp','Vietcombank - CN Đồng Tháp','Sacombank - CN Bình Minh'];const randomBank=bankNames[Math.floor(Math.random()*bankNames.length)];const sourceNum=state.htxLoanSources.length+1;addHtxLoanSource({maNguonVay:`NV-NH-${String(sourceNum).padStart(3,'0')}`,tenNguonVay:`Vay ${randomBank}`,loaiNguon:'Ngân hàng',hanMuc:response.hanMucTangThem!,daSuDung:0,laiSuat:0.6,kyHan:'24 tháng',ngayBatDau:new Date().toISOString().split('T')[0],ngayKetThuc:new Date(Date.now()+2*365*24*60*60*1000).toISOString().split('T')[0],status:'Đang hiệu lực',ghiChu:`Hạn mức ngân hàng mới được duyệt từ yêu cầu #${request.id}`});addEditHistory({entityType:'HtxLoanSource',entityId:request.id,truong:'Hạn mức HTX',giaTriCu:formatCurrencyCompact(state.htxLoanSources.reduce((s,l)=>s+l.hanMuc,0)-(response.hanMucTangThem||0)),giaTriMoi:formatCurrencyCompact(state.htxLoanSources.reduce((s,l)=>s+l.hanMuc,0)),ngaySua:new Date().toISOString(),nguoiSua:'Ngân hàng (mock)'});}else if(rand<0.75){response={status:'Từ chối',lyDoTuChoi:['Tỷ lệ nợ xấu của HTX vượt ngưỡng cho phép (6.5% > 5%).','Hạn mức đang sử dụng quá cao (trên 85%).','Điểm tín dụng HTX chưa đạt ngưỡng yêu cầu (cần ≥ 750).','Thiếu tài liệu xác minh năng lực tài chính của HTX.'][Math.floor(Math.random()*4)]};}else{response={status:'Cần bổ sung',noiDungBoSung:['Ngân hàng yêu cầu bổ sung:\n1) Báo cáo tài chính HTX 6 tháng gần nhất\n2) Danh sách nông hộ và dư nợ hiện tại\n3) Kế hoạch sử dụng vốn chi tiết kèm phương án thu hồi nợ.','Ngân hàng yêu cầu bổ sung:\n1) Hợp đồng bao tiêu với đối tác thu mua\n2) Dự toán chi phí sản xuất vụ tới\n3) Báo cáo kết quả kinh doanh năm trước.','Ngân hàng yêu cầu bổ sung:\n1) Phương án kinh doanh và dòng tiền dự kiến 3 năm\n2) Báo cáo kiểm toán độc lập\n3) Hồ sơ pháp lý HTX (giấy phép, điều lệ).'][Math.floor(Math.random()*3)]};}updateBankLimitRequest(request.id,{status:response.status,lyDoTuChoi:response.lyDoTuChoi,noiDungBoSung:response.noiDungBoSung,ketQuaHanMucMoi:response.hanMucTangThem,ngayCapNhat:new Date().toISOString()});resolve(response);},delay);});}

