// ─── Helpers ─────────────────────────────────────────────────

type ReminderLevel = 'none' | 't7' | 't3' | 't1' | 'due' | 'overdue';

function getReminderLevel(debt: Debt): ReminderLevel {
  if (debt.status === 'Đã tất toán') return 'none';
  if (debt.status === 'Quá hạn') return 'overdue';
  if (debt.status === 'Chờ thanh toán' || debt.status === 'Chờ xử lý lỗi thanh toán' || debt.status === 'Thu nợ lỗi') return 'none';
  const now = new Date();
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const dueDate = new Date(debt.ngayDenHan);
  const dueStart = new Date(dueDate.getFullYear(), dueDate.getMonth(), dueDate.getDate());
  const diffDays = Math.floor((dueStart.getTime() - todayStart.getTime()) / (1000 * 60 * 60 * 24));
  if (diffDays < 0) return 'overdue';
  if (diffDays === 0) return 'due';
  if (diffDays <= 1) return 't1';
  if (diffDays <= 3) return 't3';
  if (diffDays <= 7) return 't7';
  return 'none';
}

function DebtMetric({ label, value, tone = 'slate' }: { label: string; value: string; tone?: 'slate' | 'emerald' | 'rose' }) {
  const color = tone === 'emerald' ? 'text-emerald-700' : tone === 'rose' ? 'text-rose-700' : 'text-slate-800';
  return <div className="min-w-0 rounded-xl bg-slate-50 p-2.5"><p className="text-[10px] text-slate-400">{label}</p><p className={`mt-0.5 truncate text-xs font-bold ${color}`}>{value}</p></div>;
}

function DebtDetail({ label, value }: { label: string; value: string }) {
  return <div className="min-w-0"><p className="text-[10px] text-slate-400">{label}</p><p className="mt-0.5 text-xs font-semibold text-slate-700 text-safe-normal">{value}</p></div>;
}

const reminderBadge: Record<ReminderLevel, { label: string; bg: string; text: string; icon: string }> = {
  none: { label: '', bg: '', text: '', icon: '' },
  t7: { label: 'Còn 7 ngày', bg: 'bg-sky-100', text: 'text-sky-700', icon: 'ri-calendar-event-line' },
  t3: { label: 'Còn 3 ngày', bg: 'bg-amber-100', text: 'text-amber-700', icon: 'ri-calendar-check-line' },
  t1: { label: 'Còn 1 ngày', bg: 'bg-orange-100', text: 'text-orange-700', icon: 'ri-alarm-warning-line' },
  due: { label: 'Hôm nay!', bg: 'bg-red-100', text: 'text-red-700', icon: 'ri-error-warning-line' },
  overdue: { label: 'Quá hạn', bg: 'bg-red-200', text: 'text-red-800', icon: 'ri-timer-flash-line' },
};

function wasRemindedToday(debtId: string): boolean {
  const today = new Date().toISOString().split('T')[0];
  return getNotifications().some(
    (n) => n.type === 'debt_reminder' && n.debtId === debtId && n.ngayTao.startsWith(today)
  );
}

// ─── PI helpers ──────────────────────────────────────────────

function getDebtPIStatus(debt: Debt): PaymentIntentStatus | null {
  const pi = getActivePaymentIntentByDebt(debt.id);
  return pi?.status || null;
}

function mapPIStatusToDebtDisplayStatus(piStatus: PaymentIntentStatus): string {
  const map: Record<PaymentIntentStatus, string> = {
    qr_created: 'Chờ nông hộ xác nhận',
    farmer_confirmed_transfer: 'Chờ HTX xác nhận',
    waiting_bank_credit: 'Chờ HTX xác nhận',
    bank_credit_received: 'Chờ HTX xác nhận',
    reconciled: 'Chờ HTX xác nhận',
    waiting_htx_confirmation: 'Chờ HTX xác nhận',
    settled: 'Đã tất toán',
    reconcile_failed: 'Đối soát lỗi',
    cancelled: 'Đã hủy',
    complaint: 'Khiếu nại',
  };
  return map[piStatus] || piStatus;
}

const PI_CARD_STATUS_CLASS: Record<string, string> = {
  'Chờ HTX xác nhận': 'bg-indigo-100 text-indigo-700',
  'Đã tất toán': 'bg-emerald-100 text-emerald-700',
  'Đối soát lỗi': 'bg-red-100 text-red-700',
  'Đã hủy': 'bg-slate-100 text-slate-500',
  'Khiếu nại': 'bg-rose-100 text-rose-700',
  'Chờ nông hộ xác nhận': 'bg-orange-100 text-orange-700',
};

function getWrappedDebtStatus(debt: Debt): string {
  const piStatus = getDebtPIStatus(debt);
  if (piStatus) {
    return mapPIStatusToDebtDisplayStatus(piStatus);
  }
  return debt.status;
}

function getWrappedDebtStatusClass(debt: Debt): string {
  const piStatus = getDebtPIStatus(debt);
  if (piStatus) {
    const display = mapPIStatusToDebtDisplayStatus(piStatus);
    return PI_CARD_STATUS_CLASS[display] || 'bg-slate-100 text-slate-600';
  }
  const map: Record<string, string> = {
    'Đang vay': 'bg-sky-100 text-sky-700', 'Sắp đến hạn': 'bg-amber-100 text-amber-700',
    'Đến hạn': 'bg-orange-100 text-orange-700', 'Chờ thanh toán': 'bg-sky-100 text-sky-700',
    'Chờ xử lý lỗi thanh toán': 'bg-rose-100 text-rose-700', 'Quá hạn': 'bg-red-100 text-red-700',
    'Đã tất toán': 'bg-emerald-100 text-emerald-700', 'Thu nợ lỗi': 'bg-red-100 text-red-700',
  };
  return map[debt.status] || 'bg-slate-100 text-slate-600';
}

// ─── Filter chip config (centralized from status.ts) ─────────
function mapDebtToFilterKey(debt: Debt): string {
  const pi = getActivePaymentIntentByDebt(debt.id);

  if (pi) {
    // Check PI-based chips first
    for (const chip of DEBT_FILTER_CHIPS) {
      if (chip.piMatch && (chip.piMatch as readonly string[]).includes(pi.status)) {
        return chip.key;
      }
    }
  }

  // Check status-based chips
  for (const chip of DEBT_FILTER_CHIPS) {
    if (chip.statusMatch && (chip.statusMatch as readonly string[]).includes(debt.status)) {
      return chip.key;
    }
  }

  return 'active';
}

// ─── Auto overdue check ──────────────────────────────────────
function checkOverdue(debts: Debt[], farmers: ReturnType<typeof getFarmers>) {
  const now = new Date();
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  let changed = 0;
  const riskProfiles = getRiskProfiles();

  debts.forEach((debt) => {
    if (debt.status === 'Đã tất toán' || debt.status === 'Quá hạn') return;
    if (debt.status === 'Chờ xử lý lỗi thanh toán' || debt.status === 'Thu nợ lỗi') return;
    if (debt.status === 'Chờ thanh toán') return;
    const dueDate = new Date(debt.ngayDenHan);
    const dueStart = new Date(dueDate.getFullYear(), dueDate.getMonth(), dueDate.getDate());
    if (todayStart > dueStart) {
      updateDebt(debt.id, { status: 'Quá hạn' });
      changed++;
      const farmerName = farmers.find((f) => f.id === debt.farmerId)?.name || debt.farmerId;
      const rp = riskProfiles.find((r) => r.farmerId === debt.farmerId);
      if (rp) {
        const newRisk = rp.mucDo === 'Tốt' ? 'Cần chú ý' : 'Nguy cơ';
        updateRiskProfile(rp.id, { mucDo: newRisk, moTa: `Khoản vay ${debt.maKhoanVay || debt.id} quá hạn từ ${formatDate(debt.ngayDenHan)}.`, ngayCapNhat: new Date().toISOString() });
      }
      addNotification({ farmerId: debt.farmerId, title: 'Khoản vay quá hạn', content: `Khoản ${debt.maKhoanVay || debt.id} của ${farmerName} đã quá hạn. Số nợ: ${formatCompactCurrency(debt.conNo)}.`, type: 'debt_overdue', ngayTao: new Date().toISOString(), daDoc: false });
      addEditHistory({ entityType: 'Debt', entityId: debt.id, farmerId: debt.farmerId, truong: 'status', giaTriCu: debt.status, giaTriMoi: 'Quá hạn', ngaySua: new Date().toISOString(), nguoiSua: 'Hệ thống' });
    }
  });
  return changed;
}

