import { BrowserRouter } from "react-router-dom";
import { AppRoutes } from "./router";
import { I18nextProvider } from "react-i18next";
import i18n from "./i18n";
import { useEffect, useRef } from "react";
import { runDebtReminderScheduler } from "@/utils/debtReminderScheduler";
import {
  expireAllOverdueLocks, getLimitLocks, updateLoan, addNotification, addEditHistory,
  cancelDisbursementByLockExpired, getDisbursements,
} from "@/store";

function DebtReminderBoot() {
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    // Run once on app load
    runDebtReminderScheduler();

    intervalRef.current = setInterval(() => {
      runDebtReminderScheduler();
    }, 5 * 60 * 1000);

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, []);

  return null;
}

/**
 * Global lock expiry scheduler — runs every 15 seconds app-wide.
 * Ensures expired locks are processed even when not on DisbursementTab.
 */
function LimitLockExpiryBoot() {
  useEffect(() => {
    const interval = setInterval(() => {
      const { count, expiredLockIds } = expireAllOverdueLocks();
      if (count === 0) return;

      const allLocks = getLimitLocks();
      const allDisbs = getDisbursements();
      const now = new Date().toISOString();

      expiredLockIds.forEach((lockId) => {
        const lock = allLocks.find((l) => l.id === lockId);
        if (!lock) return;

        // Check if there's an active disbursement for this lock's loan
        const activeDr = allDisbs.find(
          (d) => d.advanceRequestId === lock.loanId
            && (d.status === 'sent_to_bank' || d.status === 'timeout' || d.status === 'Đã gửi ngân hàng')
        );

        if (activeDr) {
          // Cancel the stuck disbursement
          cancelDisbursementByLockExpired(activeDr.id);
          updateLoan(lock.loanId, { status: 'lock_expired' });
          addEditHistory({
            entityType: 'Disbursement', entityId: activeDr.id, farmerId: lock.farmerId,
            truong: 'status', giaTriCu: activeDr.status, giaTriMoi: 'cancelled_by_lock_expired',
            ngaySua: now, nguoiSua: 'Hệ thống (auto - global)',
          });
          addNotification({
            farmerId: lock.farmerId,
            title: 'Hết thời gian khóa hạn mức',
            content: `Lệnh giải ngân ${activeDr.bankRequestCode} đã bị hủy tự động do hết thời gian khóa hạn mức (10 phút). Vui lòng tạo lệnh mới nếu cần.`,
            type: 'disburse_failed',
            ngayTao: now,
            daDoc: false,
          });
        } else {
          // No active disbursement — just update loan status
          updateLoan(lock.loanId, { status: 'lock_expired' });
          addEditHistory({
            entityType: 'Loan', entityId: lock.loanId, farmerId: lock.farmerId,
            truong: 'status', giaTriCu: 'Đã duyệt', giaTriMoi: 'lock_expired',
            ngaySua: now, nguoiSua: 'Hệ thống (auto - global)',
          });
          addNotification({
            farmerId: lock.farmerId,
            title: 'Hết thời gian khóa hạn mức',
            content: `Thời gian khóa hạn mức (10 phút) cho khoản vay của bạn đã hết. Hạn mức đã được mở lại. Vui lòng liên hệ HTX để được duyệt lại nếu cần.`,
            type: 'general',
            ngayTao: now,
            daDoc: false,
          });
        }
      });
    }, 15000);

    return () => clearInterval(interval);
  }, []);

  return null;
}

function App() {
  return (
    <I18nextProvider i18n={i18n}>
      <BrowserRouter basename={__BASE_PATH__}>
        <DebtReminderBoot />
        <LimitLockExpiryBoot />
        <AppRoutes />
      </BrowserRouter>
    </I18nextProvider>
  );
}

export default App;
