export type LedgerAccount = 'ANTESCO_CAPITAL' | 'HTX_CASH' | `FARMER:${string}`;

export interface LedgerPosting {
  account: LedgerAccount;
  amount: number;
  label: string;
}

export interface MoneyLedgerEntry {
  id: string;
  code: string;
  type: 'ANTESCO_TO_HTX' | 'HTX_TO_ANTESCO' | 'HTX_TO_FARMER' | 'FARMER_TO_HTX';
  createdAt: string;
  description: string;
  postings: LedgerPosting[];
}

const LEDGER_KEY = 'agrida_money_ledger_v3';

function readLedger(): MoneyLedgerEntry[] {
  try {
    const value = localStorage.getItem(LEDGER_KEY);
    return value ? JSON.parse(value) as MoneyLedgerEntry[] : [];
  } catch {
    return [];
  }
}

export function getMoneyLedger(): MoneyLedgerEntry[] {
  return readLedger().sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export function recordBalancedEntry(
  entry: Omit<MoneyLedgerEntry, 'id' | 'createdAt'>,
): MoneyLedgerEntry {
  const total = entry.postings.reduce((sum, posting) => sum + posting.amount, 0);
  if (Math.abs(total) > 0.001) {
    throw new Error(`Bút toán không cân bằng: ${total}`);
  }
  if (entry.postings.some((posting) => !Number.isFinite(posting.amount))) {
    throw new Error('Bút toán có số tiền không hợp lệ');
  }

  const item: MoneyLedgerEntry = {
    ...entry,
    id: `ledger-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    createdAt: new Date().toISOString(),
  };
  const ledger = readLedger();
  localStorage.setItem(LEDGER_KEY, JSON.stringify([item, ...ledger]));
  return item;
}

export function getLedgerAudit(): { entries: number; unbalancedEntries: number; net: number } {
  const ledger = readLedger();
  const totals = ledger.map((entry) => entry.postings.reduce((sum, posting) => sum + posting.amount, 0));
  return {
    entries: ledger.length,
    unbalancedEntries: totals.filter((total) => Math.abs(total) > 0.001).length,
    net: totals.reduce((sum, total) => sum + total, 0),
  };
}
