/* eslint-disable react-refresh/only-export-components */
import { useState, useEffect } from 'react';

type ToastType = 'success' | 'error' | 'info' | 'warning';

interface ToastItem {
  id: number;
  message: string;
  type: ToastType;
}

let toastId = 0;
const listeners = new Set<(items: ToastItem[]) => void>();
let items: ToastItem[] = [];

function notify() {
  listeners.forEach((l) => l([...items]));
}

export function showToast(message: string, type: ToastType = 'info') {
  const id = ++toastId;
  items = [...items, { id, message, type }];
  notify();
  setTimeout(() => {
    items = items.filter((i) => i.id !== id);
    notify();
  }, 3000);
}

export function ToastContainer() {
  const [list, setList] = useState<ToastItem[]>([]);

  useEffect(() => {
    const cb = (newItems: ToastItem[]) => setList(newItems);
    listeners.add(cb);
    return () => { listeners.delete(cb); };
  }, []);

  const bgMap: Record<ToastType, string> = {
    success: 'bg-agrida-600',
    error: 'bg-red-600',
    info: 'bg-sky-600',
    warning: 'bg-amber-500',
  };

  const iconMap: Record<ToastType, string> = {
    success: 'ri-check-line',
    error: 'ri-close-line',
    info: 'ri-information-line',
    warning: 'ri-alert-line',
  };

  return (
    <div className="fixed top-4 right-4 z-[100] space-y-2">
      {list.map((t) => (
        <div
          key={t.id}
          className={`${bgMap[t.type]} text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-2 min-w-[260px] animate-[fadeIn_0.3s_ease-out]`}
        >
          <span className="w-5 h-5 flex items-center justify-center">
            <i className={`${iconMap[t.type]} text-lg`} />
          </span>
          <span className="text-sm font-medium">{t.message}</span>
        </div>
      ))}
    </div>
  );
}
