export function getBankLoanRequests(): BankLoanRequest[] {
  return getState().bankLoanRequests;
}

export function getBankLoanRequestsByHtx(htxUserId: string): BankLoanRequest[] {
  return getState().bankLoanRequests.filter((request) => request.htxUserId === htxUserId);
}

export function addBankLoanRequest(data: Omit<BankLoanRequest, 'id'>): BankLoanRequest {
  const item: BankLoanRequest = { ...data, id: `ant${Date.now()}` };
  setState((previous) => ({ ...previous, bankLoanRequests: [item, ...previous.bankLoanRequests] }));
  return item;
}

export function updateBankLoanRequest(id: string, data: Partial<BankLoanRequest>): BankLoanRequest | null {
  let updated: BankLoanRequest | null = null;
  setState((previous) => ({
    ...previous,
    bankLoanRequests: previous.bankLoanRequests.map((request) => {
      if (request.id !== id) return request;
      updated = { ...request, ...data };
      return updated;
    }),
  }));
  return updated;
}

export interface BankLoanResponse {
  status: 'Đã duyệt' | 'Từ chối';
  lyDoTuChoi?: string;
  laiSuatDuyet?: number;
  soTienDuyet?: number;
}

/** @deprecated Use requestAntescoFunding from antescoFundingService. */
export async function mockBankLoanRequest(..._legacyArguments: unknown[]): Promise<BankLoanResponse> {
  return {
    status: 'Từ chối',
    lyDoTuChoi: 'Luồng vay ngân hàng đã ngừng sử dụng. HTX chỉ nhận vốn từ Antesco.',
  };
}

export function initBankLoanMockData() {
  const requests = getState().bankLoanRequests;
  const containsLegacyBankData = requests.some((request) =>
    request.nganHangDeXuat && request.nganHangDeXuat !== 'Antesco',
  );
  if (requests.length === 0 || containsLegacyBankData) {
    setState((previous) => ({ ...previous, bankLoanRequests: initialAntescoFundingRequests }));
  }
}

export const getAntescoFundingRequests = getBankLoanRequests;
export const getAntescoFundingRequestsByHtx = getBankLoanRequestsByHtx;
export const addAntescoFundingRequest = addBankLoanRequest;
export const updateAntescoFundingRequest = updateBankLoanRequest;
