import { useState } from 'react';
import { EmptyState } from '@/components/base/EmptyState';
import { MobileMetricCard, MobileSectionHeader } from '@/components/base/MobileUi';
import { HtxDisbursementSheet } from '@/components/feature/HtxDisbursementSheet';
import { useStore } from '@/hooks/useStore';
import { getDisbursements, getFarmers, getLoans } from '@/store';
import type { AdvanceRequest } from '@/types';
import { checkDisburseEligibility } from '@/utils/disbursementService';
import { getHtxMoneySummary } from '@/utils/financeEngine';
import { formatCurrencyCompact } from '@/utils/formatters';

const READY_STATUSES = ['approved_locked', 'Đã duyệt', 'Chờ giải ngân', 'disbursement_failed', 'Giải ngân lỗi', 'lock_expired'];

export default function DisbursementTab() {
  useStore();
  const farmers = getFarmers();
  const summary = getHtxMoneySummary();
  const readyLoans = getLoans().filter((loan) => loan.loai === 'Tiền' && READY_STATUSES.includes(loan.status));
  const history = [...getDisbursements()].sort((a, b) => b.ngayGui.localeCompare(a.ngayGui));
  const [selected, setSelected] = useState<AdvanceRequest | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const getFarmerName = (farmerId: string) => farmers.find((farmer) => farmer.id === farmerId)?.name || farmerId;

  const openLoan = (loan: AdvanceRequest) => {
    setSelected(loan);
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        <MobileMetricCard label="Chờ giải ngân" value={readyLoans.length} caption="Khoản đã được duyệt" tone="sky" icon="ri-hourglass-line" />
        <MobileMetricCard label="Ví HTX" value={formatCurrencyCompact(summary.totalLimit)} caption="Tổng ngân sách hiện có" tone="slate" icon="ri-wallet-3-line" />
        <MobileMetricCard label="Đã giải ngân" value={formatCurrencyCompact(summary.usedLimit)} caption="Đã chuyển nông hộ" tone="amber" icon="ri-arrow-right-up-line" />
        <MobileMetricCard label="Khả dụng" value={formatCurrencyCompact(summary.availableLimit)} caption="Có thể giải ngân" tone="emerald" icon="ri-hand-coin-line" />
      </div>

      <section>
        <MobileSectionHeader title="Khoản chờ giải ngân" count={`${readyLoans.length} khoản`} />
        {readyLoans.length === 0 ? <EmptyState icon="ri-check-double-line" title="Không có khoản chờ giải ngân" description="Khoản vay đã duyệt sẽ xuất hiện tại đây." /> : (
          <div className="grid gap-2 sm:grid-cols-2">
            {readyLoans.map((loan) => {
              const check = checkDisburseEligibility(loan);
              return <button key={loan.id} type="button" onClick={() => openLoan(loan)} className="mobile-card p-3.5 text-left"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><h4 className="truncate text-sm font-bold text-slate-900">{getFarmerName(loan.farmerId)}</h4><p className="mt-1 line-clamp-1 text-xs text-slate-500">{loan.mucDich}</p></div><strong className="shrink-0 text-sm text-sky-700">{formatCurrencyCompact(loan.soTien)}</strong></div><div className="mt-3 flex items-center justify-between gap-2 border-t border-slate-100 pt-3"><span className={`text-[10px] font-semibold ${check.eligible ? 'text-emerald-600' : 'text-amber-600'}`}>{check.eligible ? 'Sẵn sàng' : 'Cần kiểm tra'}</span><i className="ri-arrow-right-s-line text-slate-400" /></div></button>;
            })}
          </div>
        )}
      </section>

      <section>
        <MobileSectionHeader title="Lịch sử giải ngân" count={`${history.length} giao dịch`} actionLabel={showHistory ? 'Thu gọn' : 'Xem lịch sử'} onAction={() => setShowHistory((value) => !value)} />
        {showHistory && <div className="space-y-2">{history.slice(0, 12).map((item) => <div key={item.id} className="mobile-card flex items-center justify-between gap-3 p-3"><div className="min-w-0"><p className="truncate text-xs font-semibold text-slate-800">{item.farmerName || getFarmerName(item.farmerId)}</p><p className="metric-caption mt-0.5 truncate text-[10px] text-slate-400">{item.transactionCode || item.bankRequestCode} · {new Date(item.ngayGui).toLocaleDateString('vi-VN')}</p></div><div className="shrink-0 text-right"><p className="text-xs font-bold text-slate-900">{formatCurrencyCompact(item.soTien)}</p><span className="text-[10px] font-medium text-emerald-600">{item.status === 'success' ? 'Thành công' : item.status}</span></div></div>)}</div>}
      </section>

      <HtxDisbursementSheet loan={selected} farmerName={selected ? getFarmerName(selected.farmerId) : ''} onClose={() => setSelected(null)} />
    </div>
  );
}
