import { useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import { useNavigate } from 'react-router-dom';
import { BottomSheet } from '@/components/base/BottomSheet';
import { EmptyState } from '@/components/base/EmptyState';
import { DebtReminderModal } from '@/components/feature/DebtReminderModal';
import { FarmerLimitSheet } from '@/components/feature/FarmerLimitSheet';
import { HtxDisbursementSheet } from '@/components/feature/HtxDisbursementSheet';
import { HtxFundRequestSheet } from '@/components/feature/HtxFundRequestSheet';
import { useStore } from '@/hooks/useStore';
import {
  getActivePaymentIntentByDebt,
  getLimitRequests,
  getRiskProfileByFarmer,
  getState,
} from '@/store';
import type { AdvanceRequest, Debt, LimitRequest } from '@/types';
import { getHtxMoneySummary } from '@/utils/financeEngine';
import { formatCurrencyCompact } from '@/utils/formatters';
import LoanApproveMoneyModal from '../../loan/components/LoanApproveMoneyModal';

export type HomeFinanceAction = 'approve_loan' | 'grant_limit' | 'disburse' | 'debts' | 'bank_limit' | 'bank_loan';

interface LimitTarget {
  farmerId: string;
  contractId?: string;
  requestId?: string;
}

const READY_STATUSES: AdvanceRequest['status'][] = ['approved_locked', 'Đã duyệt', 'Chờ giải ngân', 'disbursement_failed', 'Giải ngân lỗi', 'lock_expired'];

export function HomeFinanceQuickSheets({ action, onClose }: { action: HomeFinanceAction | null; onClose: () => void }) {
  useStore();
  const navigate = useNavigate();
  const state = getState();
  const [selectedLoan, setSelectedLoan] = useState<AdvanceRequest | null>(null);
  const [selectedDisbursement, setSelectedDisbursement] = useState<AdvanceRequest | null>(null);
  const [selectedDebt, setSelectedDebt] = useState<Debt | null>(null);
  const [limitTarget, setLimitTarget] = useState<LimitTarget | null>(null);

  useEffect(() => {
    setSelectedLoan(null);
    setSelectedDisbursement(null);
    setSelectedDebt(null);
    setLimitTarget(null);
  }, [action]);

  const closeAll = () => {
    setSelectedLoan(null);
    setSelectedDisbursement(null);
    setSelectedDebt(null);
    setLimitTarget(null);
    onClose();
  };

  const farmerName = (farmerId: string) => state.farmers.find((item) => item.id === farmerId)?.name || farmerId;
  const pendingLoans = state.advanceRequests.filter((loan) => loan.loai === 'Tiền' && loan.status === 'Chờ kiểm tra');
  const readyLoans = state.advanceRequests.filter((loan) => loan.loai === 'Tiền' && READY_STATUSES.includes(loan.status));
  const pendingLimitRequests = getLimitRequests().filter((request) => request.status === 'Chờ duyệt');
  const piAttentionStatuses = ['farmer_confirmed_transfer', 'waiting_bank_credit', 'bank_credit_received', 'reconciled', 'waiting_htx_confirmation', 'reconcile_failed'];
  const actionableDebts = state.debts
    .map((debt) => ({ debt, pi: getActivePaymentIntentByDebt(debt.id) }))
    .filter(({ debt, pi }) => debt.conNo > 0 && (debt.status === 'Quá hạn' || debt.status === 'Thu nợ lỗi' || (!!pi && piAttentionStatuses.includes(pi.status))))
    .sort((a, b) => (b.pi?.soTien || b.debt.conNo) - (a.pi?.soTien || a.debt.conNo));
  const htxAvailable = getHtxMoneySummary().availableLimit;

  if (selectedLoan) {
    const farmer = state.farmers.find((item) => item.id === selectedLoan.farmerId);
    const seasonName = state.seasons.find((item) => item.id === selectedLoan.seasonId)?.name || '';
    return (
      <LoanApproveMoneyModal
        loan={selectedLoan}
        farmerName={farmerName(selectedLoan.farmerId)}
        seasonName={seasonName}
        limits={state.limits.filter((item) => item.farmerId === selectedLoan.farmerId)}
        htxRemaining={htxAvailable}
        riskProfile={getRiskProfileByFarmer(selectedLoan.farmerId)}
        farmer={farmer}
        onClose={closeAll}
        onApprove={closeAll}
      />
    );
  }

  if (limitTarget) {
    return <FarmerLimitSheet open farmerId={limitTarget.farmerId} contractId={limitTarget.contractId} requestId={limitTarget.requestId} onClose={closeAll} />;
  }

  if (selectedDisbursement) {
    return <HtxDisbursementSheet loan={selectedDisbursement} farmerName={farmerName(selectedDisbursement.farmerId)} onClose={closeAll} />;
  }

  if (selectedDebt) {
    return <DebtReminderModal open debt={selectedDebt} farmerName={farmerName(selectedDebt.farmerId)} htxName={state.currentUser?.displayName} onClose={closeAll} />;
  }

  if (action === 'bank_limit' || action === 'bank_loan') {
    return <HtxFundRequestSheet open mode={action === 'bank_loan' ? 'loan' : 'limit'} onClose={closeAll} />;
  }

  if (action === 'approve_loan') {
    return (
      <SelectionSheet open title="Duyệt vay nông hộ" onClose={closeAll} empty={pendingLoans.length === 0} emptyTitle="Không có yêu cầu chờ duyệt">
        {pendingLoans.map((loan) => (
          <QuickItem key={loan.id} title={farmerName(loan.farmerId)} caption={loan.mucDich} value={formatCurrencyCompact(loan.soTien)} onClick={() => setSelectedLoan(loan)} />
        ))}
      </SelectionSheet>
    );
  }

  if (action === 'grant_limit') {
    return (
      <SelectionSheet open title="Hạn mức nông hộ" onClose={closeAll} empty={pendingLimitRequests.length === 0} emptyTitle="Không có yêu cầu hạn mức chờ duyệt">
        {pendingLimitRequests.length > 0 && <ListLabel label="Yêu cầu chờ duyệt" />}
        {pendingLimitRequests.map((request) => (
          <LimitRequestItem key={request.id} request={request} onClick={() => setLimitTarget({ farmerId: request.farmerId, contractId: request.contractId, requestId: request.id })} />
        ))}
      </SelectionSheet>
    );
  }

  if (action === 'disburse') {
    return (
      <SelectionSheet open title="Giải ngân nông hộ" onClose={closeAll} empty={readyLoans.length === 0} emptyTitle="Không có khoản chờ giải ngân">
        {readyLoans.map((loan) => (
          <QuickItem key={loan.id} title={farmerName(loan.farmerId)} caption={loan.mucDich} value={formatCurrencyCompact(loan.soTien)} onClick={() => setSelectedDisbursement(loan)} />
        ))}
      </SelectionSheet>
    );
  }

  if (action === 'debts') {
    return (
      <SelectionSheet open title="Công nợ cần xử lý" onClose={closeAll} empty={actionableDebts.length === 0} emptyTitle="Không có công nợ cần xử lý">
        {actionableDebts.map(({ debt, pi }) => (
          <QuickItem
            key={debt.id}
            title={farmerName(debt.farmerId)}
            caption={`${debt.maKhoanVay || debt.id} · ${pi ? (pi.status === 'reconcile_failed' ? 'Đối soát lỗi' : 'Chờ HTX xác nhận') : debt.status}`}
            value={formatCurrencyCompact(pi?.soTien || debt.conNo)}
            tone="rose"
            onClick={() => {
              if (pi) {
                closeAll();
                navigate('/htx/tai-chinh', { state: { tab: 'debt' } });
                return;
              }
              setSelectedDebt(debt);
            }}
          />
        ))}
      </SelectionSheet>
    );
  }

  return null;
}

function SelectionSheet({ open, title, onClose, empty, emptyTitle, children }: { open: boolean; title: string; onClose: () => void; empty: boolean; emptyTitle: string; children: ReactNode }) {
  return (
    <BottomSheet open={open} onClose={onClose} title={title}>
      {empty ? <EmptyState icon="ri-inbox-2-line" title={emptyTitle} description="Dữ liệu sẽ tự cập nhật khi có phát sinh mới." /> : <div className="space-y-2">{children}</div>}
    </BottomSheet>
  );
}

function QuickItem({ title, caption, value, tone = 'emerald', onClick }: { title: string; caption: string; value: string; tone?: 'emerald' | 'rose'; onClick: () => void }) {
  return (
    <button type="button" onClick={onClick} className="mobile-card flex w-full min-w-0 items-center justify-between gap-3 p-3.5 text-left active:scale-[0.99]">
      <span className="min-w-0">
        <strong className="block truncate text-sm text-slate-900">{title}</strong>
        <span className="mt-1 block line-clamp-2 text-xs text-slate-500">{caption}</span>
      </span>
      <span className={`shrink-0 text-right text-sm font-bold ${tone === 'rose' ? 'text-rose-600' : 'text-emerald-700'}`}>{value}</span>
    </button>
  );
}

function LimitRequestItem({ request, onClick }: { request: LimitRequest; onClick: () => void }) {
  return <QuickItem title={request.farmerName || request.farmerId} caption={`${request.contractSo || 'Hợp đồng nông hộ'} · Chờ duyệt`} value={formatCurrencyCompact(request.hanMucDeXuat)} onClick={onClick} />;
}

function ListLabel({ label }: { label: string }) {
  return <p className="px-1 pt-2 text-[10px] font-semibold uppercase tracking-wide text-slate-400">{label}</p>;
}
