import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { showToast } from '@/components/base/Toast';
import EkycFlow from '@/components/feature/EkycFlow';

export default function EkycPage() {
  const { user, updateKycStatus } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    if (!user) {
      navigate('/dang-nhap');
      return;
    }
    if (user.kycStatus === 'ekyc_verified') {
      if (user.role === 'Nông hộ') {
        navigate('/nong-ho/tong-quan');
      } else {
        navigate('/htx/tong-quan');
      }
    }
  }, [user, navigate]);

  if (!user) return null;

  const kycStatus = user.kycStatus || 'registered';

  if (kycStatus === 'ekyc_verified') return null;

  const handleBack = () => {
    if (user?.role === 'Nông hộ') {
      navigate('/nong-ho/tong-quan');
    } else {
      navigate('/htx/tong-quan');
    }
  };

  return (
    <div className="min-h-[100dvh] bg-white flex flex-col max-w-[430px] mx-auto">
      <div className="flex items-center px-4 h-14 border-b border-gray-100 shrink-0">
        <button
          type="button"
          onClick={handleBack}
          className="w-9 h-9 flex items-center justify-center rounded-lg hover:bg-gray-50 transition-colors"
          aria-label="Quay lại"
        >
          <i className="ri-arrow-left-line text-gray-700 text-lg" />
        </button>
        <h2 className="flex-1 text-center font-semibold text-gray-900 text-base mr-9">
          Xác thực danh tính
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto">
        {kycStatus === 'ekyc_pending' && <EkycPending user={user} />}
        {kycStatus === 'ekyc_need_more' && <EkycNeedMore user={user} updateKycStatus={updateKycStatus} />}
        {kycStatus === 'ekyc_failed' && <EkycFailed user={user} updateKycStatus={updateKycStatus} />}
        {kycStatus === 'registered' && <EkycFlow />}
      </div>
    </div>
  );
}

function EkycPending({ user }: { user: { displayName: string; role: string; kycReason?: string } }) {
  return (
    <div className="flex flex-col items-center justify-center px-4 py-10">
      <div className="w-24 h-24 rounded-full bg-amber-50 flex items-center justify-center mb-6">
        <span className="w-12 h-12 flex items-center justify-center">
          <i className="ri-time-line text-amber-500 text-4xl" />
        </span>
      </div>
      <h3 className="text-xl font-bold text-gray-900 mb-2 text-center">Đang chờ xác thực</h3>
      <p className="text-sm text-gray-500 text-center mb-1">
        {user.role === 'Nông hộ'
          ? 'Hồ sơ eKYC của bạn đang được HTX xem xét và phê duyệt.'
          : 'Hồ sơ eKYC của HTX đang được hệ thống xem xét và phê duyệt.'}
      </p>
      <p className="text-xs text-gray-400 text-center mb-6">
        Quá trình này có thể mất từ 1-2 ngày làm việc.
      </p>

      {user.kycReason && (
        <div className="w-full bg-amber-50 rounded-xl p-4 mb-6">
          <div className="flex items-start gap-3">
            <span className="w-5 h-5 flex items-center justify-center shrink-0 mt-0.5">
              <i className="ri-information-line text-amber-600" />
            </span>
            <div>
              <p className="text-sm font-medium text-amber-800">Ghi chú</p>
              <p className="text-xs text-amber-600 mt-1">{user.kycReason}</p>
            </div>
          </div>
        </div>
      )}

      <div className="w-full bg-amber-50 rounded-xl p-4 mb-6">
        <div className="flex items-start gap-3">
          <span className="w-5 h-5 flex items-center justify-center shrink-0 mt-0.5">
            <i className="ri-information-line text-amber-600" />
          </span>
          <div>
            <p className="text-sm font-medium text-amber-800">Thông tin hồ sơ</p>
            <p className="text-xs text-amber-600 mt-1">
              Tên: <strong>{user.displayName}</strong>
            </p>
            <p className="text-xs text-amber-600">
              Loại tài khoản: <strong>{user.role}</strong>
            </p>
            <p className="text-xs text-amber-600">
              Ngày gửi: <strong>{new Date().toLocaleDateString('vi-VN')}</strong>
            </p>
          </div>
        </div>
      </div>

      <p className="text-xs text-gray-400 text-center">
        Bạn sẽ nhận được thông báo khi hồ sơ được xử lý.{' '}
        <button type="button" className="text-agrida-600 font-medium" onClick={() => window.location.reload()}>
          Kiểm tra lại
        </button>
      </p>
    </div>
  );
}

function EkycNeedMore({ user, updateKycStatus }: {
  user: { id: string; displayName: string; kycReason?: string };
  updateKycStatus: (userId: string, status: string, reason?: string, score?: number, risk?: string) => void;
}) {
  const handleResubmit = () => {
    updateKycStatus(user.id, 'registered');
    showToast('Đã chuyển sang chế độ chụp lại. Vui lòng thực hiện lại các bước.', 'info');
  };

  return (
    <div className="flex flex-col items-center px-4 py-6">
      <div className="w-24 h-24 rounded-full bg-orange-50 flex items-center justify-center mb-6">
        <span className="w-12 h-12 flex items-center justify-center">
          <i className="ri-error-warning-line text-orange-500 text-4xl" />
        </span>
      </div>
      <h3 className="text-xl font-bold text-gray-900 mb-2 text-center">Cần bổ sung thông tin</h3>
      <p className="text-sm text-gray-500 text-center mb-6">
        Hồ sơ eKYC của bạn cần được bổ sung thêm một số thông tin trước khi được phê duyệt.
      </p>

      <div className="w-full bg-orange-50 rounded-xl p-4 mb-5">
        <div className="flex items-start gap-3">
          <span className="w-5 h-5 flex items-center justify-center shrink-0 mt-0.5">
            <i className="ri-alert-line text-orange-600" />
          </span>
          <div>
            <p className="text-sm font-medium text-orange-800 mb-1">Lý do cần bổ sung</p>
            <p className="text-sm text-orange-700">{user.kycReason || 'Cần bổ sung thông tin định danh.'}</p>
          </div>
        </div>
      </div>

      <div className="w-full bg-gray-50 rounded-xl p-4 mb-6">
        <p className="text-xs font-medium text-gray-600 mb-3">Hướng dẫn bổ sung:</p>
        <ul className="space-y-2">
          <li className="flex items-start gap-2">
            <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
              <i className="ri-checkbox-circle-line text-agrida-500 text-xs" />
            </span>
            <span className="text-xs text-gray-600">Chụp lại ảnh CMND/CCCD rõ nét, đủ 2 mặt</span>
          </li>
          <li className="flex items-start gap-2">
            <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
              <i className="ri-checkbox-circle-line text-agrida-500 text-xs" />
            </span>
            <span className="text-xs text-gray-600">Đảm bảo ảnh không bị mờ, chói sáng hoặc khuất góc</span>
          </li>
          <li className="flex items-start gap-2">
            <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
              <i className="ri-checkbox-circle-line text-agrida-500 text-xs" />
            </span>
            <span className="text-xs text-gray-600">Chụp ảnh chân dung rõ mặt, không đeo kính đen</span>
          </li>
        </ul>
      </div>

      <button
        type="button"
        onClick={handleResubmit}
        className="w-full bg-orange-500 hover:bg-orange-600 text-white font-semibold py-3.5 rounded-xl transition-colors whitespace-nowrap min-h-[48px] text-sm"
      >
        Chụp lại và gửi bổ sung
      </button>
    </div>
  );
}

function EkycFailed({ user, updateKycStatus }: {
  user: { id: string; displayName: string; kycReason?: string };
  updateKycStatus: (userId: string, status: string, reason?: string, score?: number, risk?: string) => void;
}) {
  const handleRetry = () => {
    updateKycStatus(user.id, 'registered');
    showToast('Vui lòng thực hiện lại eKYC từ đầu.', 'info');
  };

  return (
    <div className="flex flex-col items-center px-4 py-6">
      <div className="w-24 h-24 rounded-full bg-red-50 flex items-center justify-center mb-6">
        <span className="w-12 h-12 flex items-center justify-center">
          <i className="ri-close-circle-line text-red-500 text-4xl" />
        </span>
      </div>
      <h3 className="text-xl font-bold text-gray-900 mb-2 text-center">Xác thực thất bại</h3>
      <p className="text-sm text-gray-500 text-center mb-6">
        Hồ sơ eKYC của bạn không được phê duyệt. Vui lòng kiểm tra lại thông tin và thực hiện lại.
      </p>

      <div className="w-full bg-red-50 rounded-xl p-4 mb-5">
        <div className="flex items-start gap-3">
          <span className="w-5 h-5 flex items-center justify-center shrink-0 mt-0.5">
            <i className="ri-error-warning-line text-red-600" />
          </span>
          <div>
            <p className="text-sm font-medium text-red-800 mb-1">Lý do từ chối</p>
            <p className="text-sm text-red-700">{user.kycReason || 'Thông tin không hợp lệ. Vui lòng thực hiện lại.'}</p>
          </div>
        </div>
      </div>

      <div className="w-full bg-gray-50 rounded-xl p-4 mb-6">
        <p className="text-xs font-medium text-gray-600 mb-2">Lưu ý khi thực hiện lại:</p>
        <ul className="space-y-1.5">
          <li className="flex items-start gap-2">
            <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
              <i className="ri-arrow-right-line text-gray-400 text-xs" />
            </span>
            <span className="text-xs text-gray-600">Kiểm tra kỹ thông tin cá nhân trước khi gửi</span>
          </li>
          <li className="flex items-start gap-2">
            <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
              <i className="ri-arrow-right-line text-gray-400 text-xs" />
            </span>
            <span className="text-xs text-gray-600">Đảm bảo tên đăng ký khớp chính xác với CMND/CCCD</span>
          </li>
          <li className="flex items-start gap-2">
            <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
              <i className="ri-arrow-right-line text-gray-400 text-xs" />
            </span>
            <span className="text-xs text-gray-600">Ảnh chụp phải rõ nét, không chỉnh sửa</span>
          </li>
        </ul>
      </div>

      <button
        type="button"
        onClick={handleRetry}
        className="w-full bg-red-500 hover:bg-red-600 text-white font-semibold py-3.5 rounded-xl transition-colors whitespace-nowrap min-h-[48px] text-sm"
      >
        Thực hiện lại eKYC
      </button>
    </div>
  );
}
