import { useState, useMemo } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { showToast } from '@/components/base/Toast';
import { getState, getFarmerById, getFarmerKyc, getSeasonsByFarmer, getContractsByFarmer, getLimitsByFarmer, getFarmerStk, addLoan } from '@/store';
import { formatCurrencyCompact, formatCurrencyFull } from '@/utils/formatters';
import type { FarmerKycInfo } from '@/store';

interface ApplyLoanSheetProps {
  open: boolean;
  onClose: () => void;
  farmerId: string;
  kyc: FarmerKycInfo | null;
}

type Step = 'kyc_check' | 'form';

export function ApplyLoanSheet({ open, onClose, farmerId, kyc }: ApplyLoanSheetProps) {
  const [step, setStep] = useState<Step>('kyc_check');
  const [seasonId, setSeasonId] = useState('');
  const [contractId, setContractId] = useState('');
  const [loanAmount, setLoanAmount] = useState('');
  const [loanPurpose, setLoanPurpose] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const state = getState();
  const farmer = getFarmerById(farmerId);
  const isKycVerified = kyc?.kycStatus === 'ekyc_verified';

  // Only show active/valid seasons
  const seasons = useMemo(() =>
    getSeasonsByFarmer(farmerId).filter((s) =>
      s.status === 'Đang canh tác' || s.status === 'Chuẩn bị' || s.status === 'Sắp thu hoạch'
    ),
    [farmerId]
  );

  const moneyLimits = useMemo(() => getLimitsByFarmer(farmerId).filter((l) => l.loaiDinhMuc === 'Vay vốn sản xuất'), [farmerId]);
  const hanMucTienConLai = useMemo(() => {
    const total = moneyLimits.reduce((s, l) => s + l.hanMuc, 0);
    const used = moneyLimits.reduce((s, l) => s + l.daSuDung, 0);
    return Math.max(0, total - used);
  }, [moneyLimits]);
  const stk = useMemo(() => getFarmerStk(farmerId), [farmerId]);

  // Active contracts for dropdown
  const activeContracts = useMemo(() =>
    getContractsByFarmer(farmerId).filter((c) =>
      c.loaiHopDong === 'HTX-Nông hộ' &&
      (c.status === 'Đang hiệu lực' || c.status === 'Sắp hết hạn')
    ),
    [farmerId]
  );

  const selectedContract = useMemo(() =>
    contractId ? activeContracts.find((c) => c.id === contractId) : null,
    [contractId, activeContracts]
  );

  const contractWarning = selectedContract?.status === 'Sắp hết hạn';
  const hasExpiredContracts = useMemo(() =>
    getContractsByFarmer(farmerId).some((c) =>
      c.loaiHopDong === 'HTX-Nông hộ' && c.status === 'Hết hạn'
    ),
    [farmerId]
  );

  const handleSubmit = () => {
    if (!isKycVerified) {
      showToast('Bạn cần xác thực eKYC trước khi vay tiền', 'warning');
      return;
    }
    const amount = Number(loanAmount);
    if (!loanAmount || Number.isNaN(amount) || amount <= 0) {
      showToast('Số tiền không hợp lệ', 'warning');
      return;
    }
    if (amount > hanMucTienConLai) {
      showToast(`Số tiền vượt hạn mức còn lại (${formatCurrencyCompact(hanMucTienConLai)}). Vui lòng giảm số tiền hoặc xin tăng hạn mức.`, 'warning');
      return;
    }
    if (!seasonId) {
      showToast('Vui lòng chọn mùa vụ để HTX xét duyệt khoản vay.', 'warning');
      return;
    }
    setSubmitting(true);
    addLoan({
      farmerId,
      seasonId: seasonId || undefined,
      loai: 'Tiền',
      soTien: amount,
      mucDich: loanPurpose || 'Vay tiền sản xuất',
      ngayYeuCau: new Date().toISOString().split('T')[0],
      status: 'Chờ kiểm tra',
      isOverLimit: amount > hanMucTienConLai,
      ghiChu: contractId ? `Xét theo mùa vụ; hợp đồng nền: ${selectedContract?.soHopDong || contractId}` : 'Xét theo mùa vụ',
    });
    showToast('Đã gửi yêu cầu vay tiền đến HTX!', 'success');
    resetAndClose();
  };

  const resetAndClose = () => {
    setStep('kyc_check');
    setSeasonId('');
    setContractId('');
    setLoanAmount('');
    setLoanPurpose('');
    setSubmitting(false);
    onClose();
  };

  const handleClose = () => {
    resetAndClose();
  };

  const steps: Step[] = ['kyc_check', 'form'];

  return (
    <BottomSheet open={open} onClose={handleClose} title="Xin vay tiền">
      {/* Step Indicator */}
      <div className="flex items-center justify-center gap-2 mb-4">
        {steps.map((s, idx) => (
          <div key={s} className="flex items-center gap-2">
            <span className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${
              step === s ? 'bg-emerald-600 text-white' : idx < steps.indexOf(step) ? 'bg-emerald-500 text-white' : 'bg-gray-100 text-gray-400'
            }`}>
              {idx < steps.indexOf(step) ? <i className="ri-check-line text-xs" /> : (idx + 1)}
            </span>
            <span className={`text-[11px] font-medium ${step === s ? 'text-emerald-600' : 'text-gray-400'}`}>
              {s === 'kyc_check' ? 'Xác thực' : 'Thông tin vay'}
            </span>
            {idx < 1 && <div className="w-8 h-px bg-gray-200" />}
          </div>
        ))}
      </div>

      {step === 'kyc_check' && (
        <div className="space-y-4">
          {isKycVerified ? (
            <>
              <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 text-center">
                <span className="w-14 h-14 rounded-full bg-emerald-100 flex items-center justify-center mx-auto mb-2">
                  <i className="ri-shield-check-line text-emerald-600 text-2xl" />
                </span>
                <p className="text-sm font-bold text-emerald-800">Tài khoản đã xác thực</p>
                <p className="text-[11px] text-emerald-600 mt-1">Bạn có thể tiếp tục gửi yêu cầu vay tiền</p>
              </div>
              <button
                type="button"
                onClick={() => setStep('form')}
                className="w-full px-4 py-3 rounded-xl text-sm font-bold bg-emerald-600 text-white hover:bg-emerald-700 transition-colors whitespace-nowrap min-h-[48px]"
              >
                Tiếp tục nhập thông tin vay
              </button>
            </>
          ) : (
            <div className="space-y-4 text-center">
              <span className="w-16 h-16 rounded-full bg-amber-100 flex items-center justify-center mx-auto">
                <i className="ri-lock-line text-amber-600 text-2xl" />
              </span>
              <div>
                <p className="text-sm font-bold text-gray-900 mb-1">Cần xác thực eKYC</p>
                <p className="text-xs text-gray-500 leading-relaxed">
                  Tính năng vay tiền yêu cầu tài khoản đã được xác thực danh tính. Bạn cần hoàn tất eKYC trước khi gửi yêu cầu vay.
                </p>
              </div>
              <button
                type="button"
                onClick={() => { onClose(); }}
                className="w-full px-4 py-3 rounded-xl text-sm font-bold bg-emerald-600 text-white hover:bg-emerald-700 transition-colors whitespace-nowrap min-h-[48px]"
              >
                Thực hiện eKYC ngay
              </button>
            </div>
          )}
        </div>
      )}

      {step === 'form' && (
        <div className="space-y-3">
          <div className="flex items-center gap-1.5">
            <span className="text-[10px] font-medium px-1.5 py-0.5 rounded-full bg-emerald-50 text-emerald-700 whitespace-nowrap">Tiền</span>
            {farmer && (
              <span className="text-[10px] text-gray-400">{farmer.name}</span>
            )}
          </div>

          {/* Limit info */}
          <div className="bg-gray-50 rounded-xl p-3 grid grid-cols-2 gap-2">
            <div>
              <p className="text-[10px] text-gray-400 mb-0.5">Hạn mức tiền còn</p>
              <p className="text-sm font-bold text-emerald-700">{formatCurrencyCompact(hanMucTienConLai)}</p>
            </div>
            {stk && (
              <div>
                <p className="text-[10px] text-gray-400 mb-0.5">Tài khoản nhận</p>
                <p className="text-xs font-medium text-gray-700">{stk.nganHang}</p>
                <p className="text-[10px] text-gray-500">{stk.stkMask} - {stk.chuTaiKhoan}</p>
              </div>
            )}
          </div>

          {/* Mùa vụ */}
          <div>
            <label className="text-[11px] font-medium text-gray-500 mb-1 block">Mùa vụ</label>
            <select
              value={seasonId}
              onChange={(e) => setSeasonId(e.target.value)}
              className="w-full rounded-lg border border-gray-200 px-3 py-2.5 text-xs text-gray-900 bg-white focus:outline-none focus:border-emerald-500"
            >
              <option value="">-- Chọn mùa vụ --</option>
              {seasons.map((s) => (
                <option key={s.id} value={s.id}>{s.name} ({s.cayTrong} {s.variety})</option>
              ))}
            </select>
            {seasons.length === 0 && (
              <p className="text-[10px] text-amber-600 mt-1 flex items-center gap-1">
                <i className="ri-error-warning-line" /> Chưa có mùa vụ đang canh tác
              </p>
            )}
          </div>

          {/* Hợp đồng */}
          <div>
            <label className="text-[11px] font-medium text-gray-500 mb-1 block">
              Hợp đồng liên quan
            </label>
            <select
              value={contractId}
              onChange={(e) => setContractId(e.target.value)}
              className="w-full rounded-lg border border-gray-200 px-3 py-2.5 text-xs text-gray-900 bg-white focus:outline-none focus:border-emerald-500"
            >
              <option value="">-- Không chọn --</option>
              {activeContracts.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.soHopDong} ({c.status === 'Sắp hết hạn' ? 'Sắp HH' : 'Hiệu lực'})
                </option>
              ))}
            </select>
            {contractWarning && (
              <p className="text-[10px] text-amber-600 mt-1 flex items-center gap-1">
                <i className="ri-error-warning-line" /> Hợp đồng sắp hết hạn. Cân nhắc gia hạn.
              </p>
            )}
            {activeContracts.length === 0 && hasExpiredContracts && (
              <p className="text-[10px] text-red-500 mt-1 flex items-center gap-1">
                <i className="ri-close-circle-line" /> Hợp đồng đã hết hạn. Liên hệ HTX để gia hạn.
              </p>
            )}
            {activeContracts.length === 0 && !hasExpiredContracts && (
              <p className="text-[10px] text-amber-500 mt-1">Chưa có hợp đồng bao tiêu</p>
            )}
          </div>

          {/* Số tiền */}
          <div>
            <label className="text-[11px] font-medium text-gray-500 mb-1 block">Số tiền đề nghị (VNĐ)</label>
            <input
              type="number"
              value={loanAmount}
              onChange={(e) => setLoanAmount(e.target.value)}
              placeholder="VD: 10000000"
              className="w-full rounded-lg border border-gray-200 px-3 py-2.5 text-xs text-gray-900 bg-white focus:outline-none focus:border-emerald-500"
            />
            {loanAmount && !Number.isNaN(Number(loanAmount)) && (
              <p className="mt-1 text-[10px] italic text-gray-400">{formatCurrencyFull(Number(loanAmount))}</p>
            )}
            {Number(loanAmount) > hanMucTienConLai && (
              <p className="text-[10px] text-red-500 mt-1 flex items-center gap-1">
                <i className="ri-error-warning-line" /> Vượt hạn mức còn lại {formatCurrencyCompact(hanMucTienConLai)}. Không thể gửi yêu cầu.
              </p>
            )}
          </div>

          {/* Mục đích */}
          <div>
            <label className="text-[11px] font-medium text-gray-500 mb-1 block">Mục đích vay</label>
            <input
              type="text"
              value={loanPurpose}
              onChange={(e) => setLoanPurpose(e.target.value)}
              placeholder="VD: Mua phân bón vụ Đông Xuân"
              className="w-full rounded-lg border border-gray-200 px-3 py-2.5 text-xs text-gray-900 bg-white focus:outline-none focus:border-emerald-500"
            />
          </div>

          <div className="flex gap-2 pt-1">
            <button
              type="button"
              onClick={() => setStep('kyc_check')}
              className="flex-1 px-4 py-2.5 rounded-xl text-xs font-medium bg-gray-100 text-gray-600 hover:bg-gray-200 transition-colors whitespace-nowrap"
            >
              ← Quay lại
            </button>
            <button
              type="button"
              onClick={handleSubmit}
              disabled={submitting || !seasonId || !loanAmount || Number.isNaN(Number(loanAmount)) || Number(loanAmount) <= 0 || Number(loanAmount) > hanMucTienConLai}
              className="flex-1 px-4 py-2.5 rounded-xl text-xs font-bold bg-emerald-600 text-white hover:bg-emerald-700 disabled:bg-gray-300 disabled:text-gray-500 transition-colors whitespace-nowrap"
            >
              {submitting ? 'Đang gửi...' : 'Gửi yêu cầu vay tiền'}
            </button>
          </div>
        </div>
      )}
    </BottomSheet>
  );
}
