import { useState, useEffect, useRef, useCallback, type FC } from 'react';

type CaptureType = 'front' | 'back' | 'selfie';

interface MockCameraCaptureProps {
  type: CaptureType;
  onCapture: () => void;
  captured: boolean;
}

const MockCameraCapture: FC<MockCameraCaptureProps> = ({ type, onCapture, captured }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [cameraReady, setCameraReady] = useState(false);
  const [cameraError, setCameraError] = useState(false);
  const [flashing, setFlashing] = useState(false);
  const [usingMock, setUsingMock] = useState(false);

  const startCamera = useCallback(async () => {
    try {
      if (!navigator.mediaDevices?.getUserMedia) {
        setCameraError(true);
        return;
      }
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: type === 'selfie' ? 'user' : 'environment', width: { ideal: 640 }, height: { ideal: 480 } },
        audio: false,
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        await videoRef.current.play();
      }
      setCameraReady(true);
    } catch {
      setCameraError(true);
    }
  }, [type]);

  useEffect(() => {
    startCamera();
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((t) => t.stop());
        streamRef.current = null;
      }
    };
  }, [startCamera]);

  const handleCapture = () => {
    if (usingMock || !cameraReady) {
      setFlashing(true);
      setTimeout(() => {
        setFlashing(false);
        onCapture();
      }, 400);
      return;
    }
    setFlashing(true);
    setTimeout(() => {
      setFlashing(false);
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((t) => t.stop());
        streamRef.current = null;
      }
      onCapture();
    }, 400);
  };

  const handleUseMock = () => {
    setUsingMock(true);
    setCameraError(false);
  };

  const getTitle = () => {
    if (type === 'front') return 'Mặt trước CCCD';
    if (type === 'back') return 'Mặt sau CCCD';
    return 'Ảnh chân dung';
  };

  const getHint = () => {
    if (type === 'front') return 'Đặt CCCD trên mặt phẳng, chụp rõ toàn bộ mặt trước, không bị chói sáng';
    if (type === 'back') return 'Chụp rõ mặt sau CCCD, đảm bảo thông tin dễ đọc, không bị mờ';
    return 'Chụp ảnh chân dung rõ mặt, không đeo kính đen, nhìn thẳng vào camera';
  };

  if (captured) {
    return (
      <div className="w-full">
        <div className={`w-full overflow-hidden flex items-center justify-center relative ${
          type === 'selfie' ? 'aspect-square max-w-[240px] mx-auto rounded-full' : 'aspect-[3/2] rounded-xl'
        } bg-agrida-50`}>
          <div className="flex flex-col items-center gap-2">
            <span className="w-10 h-10 flex items-center justify-center">
              <i className="ri-check-double-line text-agrida-500 text-2xl" />
            </span>
            <span className="text-xs font-medium text-agrida-700">
              {type === 'selfie' ? 'Đã chụp chân dung' : `Đã chụp ${type === 'front' ? 'mặt trước' : 'mặt sau'} CCCD`}
            </span>
            <button
              type="button"
              onClick={() => {
                onCapture();
                if (!usingMock) startCamera();
              }}
              className="text-xs text-agrida-600 font-medium underline hover:text-agrida-700 whitespace-nowrap"
            >
              Chụp lại
            </button>
          </div>
        </div>
        <p className="text-xs text-gray-400 text-center mt-3">{getHint()}</p>
      </div>
    );
  }

  return (
    <div className="w-full">
      <div className={`w-full overflow-hidden relative ${
        type === 'selfie' ? 'aspect-square max-w-[240px] mx-auto rounded-full' : 'aspect-[3/2] rounded-xl'
      } bg-gray-900`}>
        {flashing && (
          <div className="absolute inset-0 bg-white z-20 animate-[flash_0.4s_ease-out]" />
        )}

        {cameraReady && !usingMock && (
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            className={`w-full h-full object-cover ${type === 'selfie' ? 'scale-x-[-1]' : ''}`}
          />
        )}

        {(!cameraReady || usingMock) && (
          <div className={`absolute inset-0 flex flex-col items-center justify-center ${
            usingMock ? 'bg-gray-800' : 'bg-gray-900'
          }`}>
            {cameraError && !usingMock ? (
              <div className="flex flex-col items-center gap-3 px-4">
                <span className="w-10 h-10 flex items-center justify-center">
                  <i className="ri-camera-off-line text-gray-400 text-2xl" />
                </span>
                <p className="text-xs text-gray-400 text-center">
                  Không thể truy cập camera hoặc trình duyệt không hỗ trợ
                </p>
                <button
                  type="button"
                  onClick={handleUseMock}
                  className="px-4 py-2 bg-agrida-600 hover:bg-agrida-700 text-white text-xs font-semibold rounded-lg transition-colors whitespace-nowrap min-h-[40px]"
                >
                  Dùng ảnh mẫu
                </button>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-3">
                {usingMock ? (
                  <>
                    <div className={`flex items-center justify-center ${
                      type === 'selfie' ? 'w-16 h-16 rounded-full bg-gray-700' : 'w-20 h-14 rounded bg-gray-700'
                    }`}>
                      {type === 'selfie' ? (
                        <span className="w-8 h-8 flex items-center justify-center">
                          <i className="ri-user-smile-line text-gray-400 text-xl" />
                        </span>
                      ) : (
                        <span className="w-8 h-8 flex items-center justify-center">
                          <i className="ri-id-card-line text-gray-400 text-xl" />
                        </span>
                      )}
                    </div>
                    <span className="text-[10px] text-gray-400">Ảnh mẫu {getTitle().toLowerCase()}</span>
                  </>
                ) : (
                  <>
                    <span className="w-10 h-10 flex items-center justify-center">
                      <i className="ri-camera-line text-gray-400 text-2xl animate-pulse" />
                    </span>
                    <span className="text-xs text-gray-400">Đang khởi động camera...</span>
                  </>
                )}
              </div>
            )}
          </div>
        )}
      </div>

      <p className="text-xs text-gray-400 text-center mt-3 mb-4">{getHint()}</p>

      <button
        type="button"
        onClick={handleCapture}
        disabled={!cameraReady && !usingMock}
        className="w-full bg-agrida-600 hover:bg-agrida-700 disabled:bg-gray-300 text-white font-semibold py-3.5 rounded-xl transition-colors disabled:cursor-not-allowed whitespace-nowrap min-h-[48px] text-sm flex items-center justify-center gap-2"
      >
        <span className="w-5 h-5 flex items-center justify-center">
          <i className="ri-camera-line" />
        </span>
        {flashing ? 'Đang chụp...' : `Chụp ${getTitle().toLowerCase()}`}
      </button>
    </div>
  );
};

export default MockCameraCapture;