import { useMemo, useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { CurrencyAmount } from '@/components/base/CurrencyAmount';
import { MobileMetricCard } from '@/components/base/MobileUi';
import { showToast } from '@/components/base/Toast';
import { ExceptionApprovalModal } from '@/components/feature/ExceptionApprovalModal';
import type { ExceptionApprovalData } from '@/components/feature/ExceptionApprovalModal';
import { getContracts, getDebtsByFarmer, getFarmerKyc, getLimitsByFarmer } from '@/store';
import type { AdvanceRequest, Farmer, Limit, RiskProfile } from '@/types';
import { requiresExceptionApproval } from '@/utils/creditScore';
import { formatDate, formatVND } from '@/utils/format';
import { formatCurrencyCompact } from '@/utils/formatters';
import { executeApproveLoan } from '@/utils/loanApprovalService';

interface LoanApproveMoneyModalProps {
  loan: AdvanceRequest;
  farmerName: string;
  seasonName: string;
  limits: Limit[];
  htxRemaining: number;
  riskProfile?: RiskProfile;
  farmer?: Farmer;
  onClose: () => void;
  onApprove: (approvedAmount: number, laiSuat: number, kyHan: number, ngayDenHan: string, ghiChu: string) => void;
}

export default function LoanApproveMoneyModal({ loan, farmerName, seasonName, htxRemaining, riskProfile, farmer, onClose, onApprove }: LoanApproveMoneyModalProps) {
  const [approvedAmount, setApprovedAmount] = useState(String(loan.soTien));
  const [interestRate, setInterestRate] = useState('0.5');
  const [term, setTerm] = useState('3');
  const [note, setNote] = useState('');
  const [showException, setShowException] = useState(false);
  const approved = Number(approvedAmount) || 0;
  const rate = Number(interestRate) || 0;
  const months = Number(term) || 0;
  const dueDate = useMemo(() => { const date = new Date(); date.setMonth(date.getMonth() + months); return date.toISOString().split('T')[0]; }, [months]);
  const totalRepayment = approved + Math.round(approved * rate * months / 100);
  const kyc = farmer ? getFarmerKyc(farmer) : null;
  const hasOverdue = farmer ? getDebtsByFarmer(farmer.id).some((debt) => debt.status === 'Quá hạn' || debt.status === 'Thu nợ lỗi') : false;
  const highRisk = riskProfile?.mucDo === 'Rủi ro cao' || riskProfile?.mucDo === 'Nguy cơ';
  const needsException = requiresExceptionApproval(kyc?.creditScore) || hasOverdue || highRisk;

  const exceptionData: ExceptionApprovalData | null = useMemo(() => {
    if (!farmer) return null;
    const debts = getDebtsByFarmer(farmer.id);
    const moneyLimits = getLimitsByFarmer(farmer.id).filter((limit) => limit.loaiDinhMuc.startsWith('Vay vốn sản xuất'));
    const overdue = debts.filter((debt) => debt.status === 'Quá hạn' || debt.status === 'Thu nợ lỗi');
    return {
      farmerName: farmer.name,
      farmerId: farmer.id,
      creditScore: kyc?.creditScore,
      loanId: loan.id,
      loanAmount: approved || loan.soTien,
      loanPurpose: loan.mucDich,
      totalDebt: debts.filter((debt) => debt.status !== 'Đã tất toán').reduce((sum, debt) => sum + debt.conNo, 0),
      overdueDebt: overdue.reduce((sum, debt) => sum + debt.conNo, 0),
      overdueCount: overdue.length,
      remainingLimit: moneyLimits.reduce((sum, limit) => sum + limit.hanMuc - limit.daSuDung, 0),
      hasOverdue: overdue.length > 0,
      ekycVerified: kyc?.kycStatus === 'ekyc_verified',
      activeContracts: getContracts().filter((contract) => contract.farmerId === farmer.id && contract.status === 'Đang hiệu lực').length,
      seasonName: seasonName || undefined,
      riskLevel: riskProfile?.mucDo,
      lockAmount: approved || loan.soTien,
    };
  }, [approved, farmer, kyc, loan, riskProfile, seasonName]);

  const approve = (exceptionReason?: string) => {
    if (!farmer) return;
    executeApproveLoan(loan, farmer, {
      exceptionReason,
      ghiChu: note.trim() || loan.ghiChu,
      approvedAmount: approved,
      interestRate: rate,
      termMonths: months,
      dueDate,
      approver: 'HTX Hòa Phát',
    });
    onApprove(approved, rate, months, dueDate, note.trim());
  };

  const submit = () => {
    if (!approved || approved <= 0) { showToast('Vui lòng nhập số tiền duyệt hợp lệ.', 'warning'); return; }
    if (approved > htxRemaining && htxRemaining > 0) { showToast(`Số tiền vượt nguồn HTX khả dụng (${formatVND(htxRemaining)}).`, 'warning'); return; }
    if (needsException) setShowException(true);
    else approve();
  };

  return (
    <>
      <BottomSheet open onClose={onClose} title="Duyệt yêu cầu vay" footer={<div className="mobile-action-row"><button type="button" onClick={onClose} className="rounded-xl bg-slate-100 px-4 py-3 text-sm font-semibold text-slate-700">Hủy</button><button type="button" onClick={submit} className={`rounded-xl px-4 py-3 text-sm font-semibold text-white ${needsException ? 'bg-amber-600' : 'bg-emerald-700'}`}>{needsException ? 'Xem xét ngoại lệ' : 'Xác nhận duyệt'}</button></div>}>
        <div className="space-y-4">
          <div className="rounded-2xl bg-slate-50 p-3.5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><h4 className="truncate text-sm font-bold text-slate-900">{farmerName}</h4><p className="metric-caption mt-0.5 truncate text-[10px] text-slate-400">{loan.id.toUpperCase()} · {formatDate(loan.ngayYeuCau)}{seasonName ? ` · ${seasonName}` : ''}</p></div><CurrencyAmount value={loan.soTien} className="shrink-0 text-lg font-bold text-emerald-700" /></div><p className="mt-2 line-clamp-2 text-xs text-slate-500">{loan.mucDich}</p></div>
          <div className="grid grid-cols-2 gap-2"><MobileMetricCard label="Điểm tín dụng" value={kyc?.creditScore || '--'} caption={riskProfile?.mucDo || 'Chưa đánh giá'} tone={needsException ? 'amber' : 'emerald'} icon="ri-line-chart-line" /><MobileMetricCard label="Nguồn HTX còn" value={formatCurrencyCompact(htxRemaining)} caption="Khả dụng để giải ngân" tone="sky" icon="ri-wallet-3-line" /></div>
          <label className="block"><span className="mb-1.5 block text-xs font-semibold text-slate-600">Số tiền duyệt</span><input type="number" value={approvedAmount} onChange={(event) => setApprovedAmount(event.target.value)} className="h-12 w-full rounded-xl border border-slate-200 px-3 text-sm outline-none focus:border-emerald-500" /><span className="metric-caption mt-1 block text-[10px] text-slate-400">Yêu cầu {formatVND(loan.soTien)}</span></label>
          <div className="grid grid-cols-2 gap-3"><label className="block"><span className="mb-1.5 block text-xs font-semibold text-slate-600">Lãi suất/tháng</span><input type="number" step="0.01" value={interestRate} onChange={(event) => setInterestRate(event.target.value)} className="h-12 w-full rounded-xl border border-slate-200 px-3 text-sm" /></label><label className="block"><span className="mb-1.5 block text-xs font-semibold text-slate-600">Kỳ hạn</span><select value={term} onChange={(event) => setTerm(event.target.value)} className="h-12 w-full rounded-xl border border-slate-200 px-3 text-sm"><option value="1">1 tháng</option><option value="3">3 tháng</option><option value="6">6 tháng</option><option value="12">12 tháng</option></select></label></div>
          <div className="grid grid-cols-2 gap-2"><MobileMetricCard label="Ngày đến hạn" value={formatDate(dueDate)} caption="Tự động theo kỳ hạn" tone="slate" /><MobileMetricCard label="Tổng dự kiến" value={formatCurrencyCompact(totalRepayment)} caption="Gốc và lãi" tone="emerald" /></div>
          <label className="block"><span className="mb-1.5 block text-xs font-semibold text-slate-600">Ghi chú</span><textarea value={note} onChange={(event) => setNote(event.target.value)} rows={2} className="w-full resize-none rounded-xl border border-slate-200 px-3 py-2.5 text-sm outline-none focus:border-emerald-500" placeholder="Thông tin cần lưu" /></label>
        </div>
      </BottomSheet>
      <ExceptionApprovalModal open={showException} data={exceptionData} onClose={() => setShowException(false)} onConfirm={(reason) => { setShowException(false); approve(reason); }} />
    </>
  );
}
