import { useEffect, useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { MobileMetricCard, MobileSectionHeader } from '@/components/base/MobileUi';
import { SearchFilterBar } from '@/components/base/SearchFilterBar';
import { showToast } from '@/components/base/Toast';
import { FarmerLimitSheet } from '@/components/feature/FarmerLimitSheet';
import { useStore } from '@/hooks/useStore';
import {
  getContractsByFarmer,
  getFarmerKyc,
  getFarmers,
  getLimitRequests,
  getLimits,
  updateLimit,
} from '@/store';
import type { Contract, Farmer, Limit, LimitRequest } from '@/types';
import { getFarmerMoneySummary, getHtxMoneySummary } from '@/utils/financeEngine';
import { formatCurrencyCompact } from '@/utils/format';
import { calculateLimitProposal } from '@/utils/limitProposal';

export default function FarmerLimitTab({ initialFarmerId }: { initialFarmerId?: string }) {
  useStore();
  const farmers = getFarmers();
  const allLimits = getLimits();
  const htxMoney = getHtxMoneySummary();
  const pendingRequests = getLimitRequests().filter((request) => request.status === 'Chờ duyệt');
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState<'all' | 'good' | 'attention' | 'locked'>('all');
  const [focusFarmerId, setFocusFarmerId] = useState(initialFarmerId || '');
  const [expandedId, setExpandedId] = useState('');
  const [selectedFarmer, setSelectedFarmer] = useState<Farmer | null>(null);
  const [selectedContract, setSelectedContract] = useState<Contract | null>(null);
  const [selectedRequestId, setSelectedRequestId] = useState('');
  const [pendingSheetOpen, setPendingSheetOpen] = useState(false);

  useEffect(() => { if (initialFarmerId) setFocusFarmerId(initialFarmerId); }, [initialFarmerId]);

  const getFarmerLimits = (farmerId: string) => allLimits.filter((limit) => limit.farmerId === farmerId);
  const filteredFarmers = (() => {
    const query = search.trim().toLowerCase();
    return farmers.filter((farmer) => {
      if (focusFarmerId && farmer.id !== focusFarmerId) return false;
      if (query && !`${farmer.name} ${farmer.code}`.toLowerCase().includes(query)) return false;
      const kyc = getFarmerKyc(farmer);
      const limits = getFarmerLimits(farmer.id);
      const locked = limits.some((limit) => limit.loaiDinhMuc.includes('(Khóa)'));
      if (filter === 'good') return kyc.riskLevel === 'Tốt' || kyc.riskLevel === 'Khá';
      if (filter === 'attention') return ['Cần chú ý', 'Rủi ro cao', 'Nguy cơ'].includes(kyc.riskLevel || '');
      if (filter === 'locked') return locked;
      return true;
    });
  })();

  const openEditor = (farmer: Farmer, request?: LimitRequest) => {
    const farmerContracts = getContractsByFarmer(farmer.id);
    const contract = farmerContracts.find((item) => item.id === request?.contractId)
      || farmerContracts.find((item) => item.loaiHopDong === 'HTX-Nông hộ' && ['Đang hiệu lực', 'Sắp hết hạn'].includes(item.status));
    if (!contract) { showToast('Nông hộ chưa có hợp đồng bao tiêu hiệu lực.', 'warning'); return; }
    const kyc = getFarmerKyc(farmer);
    if (kyc.kycStatus !== 'ekyc_verified') { showToast('Nông hộ cần hoàn tất eKYC trước khi cấp hạn mức.', 'warning'); return; }
    setSelectedFarmer(farmer);
    setSelectedContract(contract);
    setSelectedRequestId(request?.id || '');
  };

  const closeEditor = () => {
    setSelectedFarmer(null);
    setSelectedContract(null);
    setSelectedRequestId('');
  };

  const toggleLock = (limit: Limit) => {
    const locked = limit.loaiDinhMuc.includes('(Khóa)');
    updateLimit(limit.id, { loaiDinhMuc: locked ? limit.loaiDinhMuc.replace(' (Khóa)', '') : `${limit.loaiDinhMuc} (Khóa)` });
    showToast(locked ? 'Đã mở khóa hạn mức.' : 'Đã tạm khóa hạn mức.', 'success');
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        <MobileMetricCard label="Ví HTX" value={formatCurrencyCompact(htxMoney.totalLimit)} caption="Số dư cập nhật theo giao dịch" tone="sky" icon="ri-wallet-3-line" />
        <MobileMetricCard label="Khả dụng" value={formatCurrencyCompact(htxMoney.availableLimit)} caption="Chưa bị giải ngân hoặc khóa" tone="emerald" icon="ri-hand-coin-line" />
        <MobileMetricCard label="Đang khóa" value={formatCurrencyCompact(htxMoney.lockedAmount)} caption="Chờ hoàn tất giải ngân" tone="amber" icon="ri-lock-line" />
        <MobileMetricCard label="Nông hộ" value={farmers.length} caption="Tài khoản đang quản lý" tone="slate" icon="ri-group-line" />
      </div>

      <div className="grid grid-cols-2 gap-2">
        <button type="button" onClick={() => setPendingSheetOpen(true)} className="mobile-card flex min-h-20 items-center gap-3 border-amber-200 bg-amber-50 p-3 text-left">
          <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-amber-100 text-amber-700"><i className="ri-inbox-unarchive-line" /></span>
          <span className="min-w-0">
            <strong className="block text-sm text-amber-900">Yêu cầu chờ duyệt</strong>
            <span className="metric-caption mt-0.5 block text-[10px] text-amber-700">{pendingRequests.length} yêu cầu</span>
          </span>
        </button>
        <button type="button" onClick={() => { setFocusFarmerId(''); setFilter('all'); setSearch(''); }} className="mobile-card flex min-h-20 items-center gap-3 border-emerald-200 bg-emerald-50 p-3 text-left">
          <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-emerald-100 text-emerald-700"><i className="ri-user-settings-line" /></span>
          <span className="min-w-0">
            <strong className="block text-sm text-emerald-900">Quản lý bên dưới</strong>
            <span className="metric-caption mt-0.5 block text-[10px] text-emerald-700">Danh sách hạn mức nông hộ</span>
          </span>
        </button>
      </div>

      {pendingRequests.length > 0 && (
        <section>
          <MobileSectionHeader title="Yêu cầu cấp hạn mức" count={`${pendingRequests.length} chờ duyệt`} />
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
            {pendingRequests.map((request) => {
              const farmer = farmers.find((item) => item.id === request.farmerId);
              return (
                <button
                  key={request.id}
                  type="button"
                  onClick={() => farmer && openEditor(farmer, request)}
                  className="mobile-card flex min-w-0 items-center justify-between gap-3 p-3.5 text-left"
                >
                  <span className="min-w-0">
                    <strong className="block truncate text-sm text-slate-900">{request.farmerName || farmer?.name}</strong>
                    <span className="metric-caption mt-1 block truncate text-[10px] text-slate-400">{request.contractSo} · {new Date(request.ngayYeuCau).toLocaleDateString('vi-VN')}</span>
                  </span>
                  <span className="shrink-0 text-right">
                    <strong className="block text-sm text-emerald-700">{formatCurrencyCompact(request.hanMucDeXuat)}</strong>
                    <span className="text-[10px] font-medium text-amber-600">Xử lý</span>
                  </span>
                </button>
              );
            })}
          </div>
        </section>
      )}

      <SearchFilterBar
        value={search}
        onChange={setSearch}
        placeholder="Tìm nông hộ"
        selected={filter === 'all' ? '' : filter}
        onSelect={(value) => setFilter((value || 'all') as typeof filter)}
        options={[
          { value: '', label: 'Tất cả', count: farmers.length },
          { value: 'good', label: 'Tốt', dotClass: 'bg-emerald-500' },
          { value: 'attention', label: 'Cần chú ý', dotClass: 'bg-amber-500' },
          { value: 'locked', label: 'Đang khóa', dotClass: 'bg-rose-500' },
        ]}
      >
        {focusFarmerId && <button type="button" onClick={() => setFocusFarmerId('')} className="min-h-11 w-full rounded-xl bg-rose-50 px-3 text-left text-sm font-medium text-rose-600">Bỏ chọn nông hộ hiện tại</button>}
      </SearchFilterBar>

      <section>
        <MobileSectionHeader title="Hạn mức nông hộ" count={`${filteredFarmers.length} nông hộ`} />
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {filteredFarmers.map((farmer) => {
            const limits = getFarmerLimits(farmer.id);
            const summary = getFarmerMoneySummary(farmer.id);
            const kyc = getFarmerKyc(farmer);
            const contract = getContractsByFarmer(farmer.id).find((item) => item.loaiHopDong === 'HTX-Nông hộ' && ['Đang hiệu lực', 'Sắp hết hạn'].includes(item.status));
            const proposal = contract ? calculateLimitProposal(contract.giaTri, kyc.riskLevel, contract.hanMucDaCap || 0, kyc.creditScore) : null;
            const locked = limits.some((limit) => limit.loaiDinhMuc.includes('(Khóa)'));
            const percent = summary.hanMucTienTong > 0 ? Math.min(100, summary.hanMucTienDaDung / summary.hanMucTienTong * 100) : 0;
            const expanded = expandedId === farmer.id;
            return (
              <article key={farmer.id} className="mobile-card min-w-0 p-3.5">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0"><h4 className="truncate text-sm font-bold text-slate-900">{farmer.name}</h4><p className="metric-caption mt-0.5 text-[10px] text-slate-400">{farmer.code} · eKYC {kyc.kycStatus === 'ekyc_verified' ? 'đã xác thực' : 'chưa hoàn tất'}</p></div>
                  <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${riskClass(kyc.riskLevel)}`}>{kyc.riskLevel || 'Chưa đánh giá'}</span>
                </div>

                <div className="mt-3 grid grid-cols-3 gap-2">
                  <MiniMetric label="Hạn mức" value={formatCurrencyCompact(summary.hanMucTienTong)} />
                  <MiniMetric label="Đã dùng" value={formatCurrencyCompact(summary.hanMucTienDaDung)} tone="amber" />
                  <MiniMetric label="Còn lại" value={formatCurrencyCompact(summary.hanMucTienKhaDung)} tone="emerald" />
                </div>
                <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-emerald-500" style={{ width: `${percent}%` }} /></div>
                <p className="metric-caption mt-1 text-[10px] text-slate-400">Đã sử dụng {percent.toFixed(1)}% hạn mức</p>

                {expanded && (
                  <div className="mt-3 rounded-xl bg-slate-50 p-3 text-xs">
                    <div className="grid grid-cols-2 gap-3">
                      <Detail label="Hợp đồng" value={contract?.soHopDong || 'Chưa có'} />
                      <Detail label="Điểm tín dụng" value={kyc.creditScore ? String(kyc.creditScore) : 'Chưa có'} />
                      <Detail label="Mức đề xuất" value={proposal ? formatCurrencyCompact(proposal.suggestedLimit) : 'Chưa xác định'} />
                      <Detail label="Trạng thái" value={locked ? 'Đang khóa' : 'Hoạt động'} />
                    </div>
                  </div>
                )}

                <div className="mt-3 flex gap-2 border-t border-slate-100 pt-3">
                  <button type="button" onClick={() => openEditor(farmer)} className="min-h-11 flex-1 rounded-xl bg-emerald-700 px-3 text-xs font-semibold text-white">{limits.length ? 'Điều chỉnh' : 'Cấp hạn mức'}</button>
                  {limits[0] && <button type="button" onClick={() => toggleLock(limits[0])} className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-xl ${locked ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-600'}`} aria-label={locked ? 'Mở khóa' : 'Tạm khóa'}><i className={locked ? 'ri-lock-unlock-line' : 'ri-lock-line'} /></button>}
                  <button type="button" onClick={() => setExpandedId(expanded ? '' : farmer.id)} className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-slate-200 text-slate-500" aria-label="Xem thêm"><i className={expanded ? 'ri-arrow-up-s-line' : 'ri-arrow-down-s-line'} /></button>
                </div>
              </article>
            );
          })}
        </div>
      </section>

      <FarmerLimitSheet
        open={!!selectedFarmer && !!selectedContract}
        farmerId={selectedFarmer?.id || ''}
        contractId={selectedContract?.id}
        requestId={selectedRequestId || undefined}
        onClose={closeEditor}
      />

      <BottomSheet open={pendingSheetOpen} onClose={() => setPendingSheetOpen(false)} title="Yêu cầu hạn mức chờ duyệt">
        <div className="space-y-2">
          {pendingRequests.map((request) => {
            const farmer = farmers.find((item) => item.id === request.farmerId);
            return (
              <button
                key={request.id}
                type="button"
                onClick={() => {
                  if (farmer) openEditor(farmer, request);
                  setPendingSheetOpen(false);
                }}
                className="mobile-card flex min-w-0 items-center justify-between gap-3 p-3.5 text-left"
              >
                <span className="min-w-0">
                  <strong className="block truncate text-sm text-slate-900">{request.farmerName || farmer?.name}</strong>
                  <span className="metric-caption mt-1 block truncate text-[10px] text-slate-400">{request.contractSo} · {new Date(request.ngayYeuCau).toLocaleDateString('vi-VN')}</span>
                </span>
                <span className="shrink-0 text-right">
                  <strong className="block text-sm text-emerald-700">{formatCurrencyCompact(request.hanMucDeXuat)}</strong>
                  <span className="text-[10px] font-medium text-amber-600">Xử lý</span>
                </span>
              </button>
            );
          })}
          {pendingRequests.length === 0 && <div className="rounded-2xl border border-dashed border-slate-200 py-6 text-center text-xs text-slate-400">Không có yêu cầu chờ duyệt</div>}
        </div>
      </BottomSheet>
    </div>
  );
}

function MiniMetric({ label, value, tone = 'slate' }: { label: string; value: string; tone?: 'slate' | 'amber' | 'emerald' }) {
  const colors = { slate: 'text-slate-800', amber: 'text-amber-700', emerald: 'text-emerald-700' };
  return <div className="min-w-0 rounded-xl bg-slate-50 p-2.5 text-center"><p className="text-[10px] text-slate-400">{label}</p><p className={`mt-0.5 truncate text-xs font-bold ${colors[tone]}`}>{value}</p></div>;
}

function Detail({ label, value }: { label: string; value: string }) { return <div className="min-w-0"><p className="text-[10px] text-slate-400">{label}</p><p className="mt-0.5 text-xs font-semibold text-slate-700 text-safe-normal">{value}</p></div>; }

function riskClass(level?: string) {
  if (level === 'Tốt' || level === 'Khá') return 'bg-emerald-100 text-emerald-700';
  if (level === 'Cần chú ý') return 'bg-amber-100 text-amber-700';
  if (level === 'Rủi ro cao' || level === 'Nguy cơ') return 'bg-rose-100 text-rose-700';
  return 'bg-slate-100 text-slate-600';
}
