import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { isEkycVerified } from '@/store';
import { getKycColor, getKycLabel } from '@/utils/status';

export default function HtxProfilePage() {
  const { user } = useAuth();
  const navigate = useNavigate();

  if (!user) {
    return null;
  }

  const ekycVerified = isEkycVerified(user);
  const kycLabel = getKycLabel(user.kycStatus || 'ekyc_verified');
  const kycColorMap = getKycColor(user.kycStatus || 'ekyc_verified');

  return (
    <div className="px-4 py-4 pb-4 space-y-4">
      <div>
        <h2 className="text-lg font-bold text-gray-900">Hồ sơ HTX</h2>
        <p className="text-xs text-gray-500 mt-0.5">Thông tin hợp tác xã</p>
      </div>

      {/* ========== eKYC STATUS ========== */}
      <div className={`rounded-2xl border p-4 ${ekycVerified ? 'bg-gradient-to-br from-emerald-50 to-teal-50 border-emerald-200' : 'bg-gradient-to-br from-amber-50 to-orange-50 border-amber-200'}`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className={`w-10 h-10 rounded-full flex items-center justify-center ${ekycVerified ? 'bg-emerald-100' : 'bg-amber-100'}`}>
              <i className={`${ekycVerified ? 'ri-shield-check-line text-emerald-600' : 'ri-shield-user-line text-amber-600'} text-lg`} />
            </span>
            <div>
              <p className={`text-sm font-bold ${ekycVerified ? 'text-emerald-800' : 'text-amber-800'}`}>
                {kycLabel}
              </p>
              <p className="text-xs mt-0.5" style={{ color: ekycVerified ? '#065f46' : '#92400e' }}>
                {ekycVerified ? 'Danh tính đã được xác thực đầy đủ' : 'Cần xác thực để mở khóa chức năng tài chính'}
              </p>
            </div>
          </div>
          {!ekycVerified && (
            <button
              type="button"
              onClick={() => navigate('/ekyc')}
              className="shrink-0 bg-amber-600 hover:bg-amber-700 text-white text-xs font-bold px-4 py-2.5 rounded-xl whitespace-nowrap transition-colors min-h-[44px] flex items-center gap-1.5"
            >
              <span className="w-4 h-4 flex items-center justify-center"><i className="ri-shield-user-line" /></span>
              Thực hiện eKYC
            </button>
          )}
        </div>

        {user.kycReason && (
          <div className="mt-3 bg-white/60 rounded-xl p-3">
            <p className="text-[10px] uppercase tracking-wider mb-0.5" style={{ color: ekycVerified ? '#047857' : '#92400e' }}>Lý do</p>
            <p className="text-xs" style={{ color: ekycVerified ? '#047857' : '#92400e' }}>{user.kycReason}</p>
          </div>
        )}

        {ekycVerified && (
          <div className="mt-3 grid grid-cols-2 gap-2">
            {user.creditScore !== undefined && (
              <div className="bg-white/70 rounded-xl p-3">
                <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-0.5">Credit Score</p>
                <p className={`text-sm font-bold ${user.creditScore >= 700 ? 'text-emerald-600' : user.creditScore >= 550 ? 'text-amber-600' : 'text-red-600'}`}>
                  {user.creditScore}
                </p>
              </div>
            )}
            {user.riskLevel && (
              <div className="bg-white/70 rounded-xl p-3">
                <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-0.5">Mức độ rủi ro</p>
                <p className="text-sm font-bold text-slate-800">{user.riskLevel}</p>
              </div>
            )}
          </div>
        )}

        {user.verifiedAt && (
          <p className="text-[10px] text-right mt-2" style={{ color: ekycVerified ? '#047857' : '#78716c' }}>
            Xác thực lúc: {new Date(user.verifiedAt).toLocaleDateString('vi-VN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })}
          </p>
        )}
      </div>

      <div className="bg-gray-50 rounded-xl p-4 space-y-3">
        <div className="flex items-center gap-3">
          <span className="w-14 h-14 rounded-full bg-agrida-100 flex items-center justify-center">
            <i className="ri-building-line text-agrida-600 text-xl" />
          </span>
          <div>
            <p className="font-bold text-gray-900">HTX Nông nghiệp Hòa Phát</p>
            <p className="text-xs text-gray-500">Mã HTX: HTX-HP-2025</p>
          </div>
        </div>
      </div>

      <div className="space-y-1">
        <InfoRow icon="ri-map-pin-line" label="Địa chỉ" value="Xã Bình Minh, Huyện Đông Tháp, Tỉnh Đồng Tháp" />
        <InfoRow icon="ri-phone-line" label="Điện thoại" value="0277 1234 567" />
        <InfoRow icon="ri-mail-line" label="Email" value="htxhoaphat@agrida.vn" />
        <InfoRow icon="ri-user-star-line" label="Người đại diện" value="Nguyễn Văn Hòa - Giám đốc" />
        <InfoRow icon="ri-calendar-line" label="Ngày thành lập" value="15/03/2018" />
        <InfoRow icon="ri-team-line" label="Số thành viên" value="82 nông hộ" />
        <InfoRow icon="ri-seedling-line" label="Cây trồng chính" value="Lúa, Mít Thái, Sầu riêng, Cà phê" />
        <InfoRow icon="ri-landscape-line" label="Tổng diện tích" value="124.5 ha" />
      </div>
    </div>
  );
}

function InfoRow({ icon, label, value }: { icon: string; label: string; value: string }) {
  return (
    <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg">
      <span className="w-8 h-8 rounded-lg bg-agrida-100 flex items-center justify-center shrink-0">
        <i className={`${icon} text-agrida-600 text-sm`} />
      </span>
      <div className="min-w-0">
        <p className="text-[11px] text-gray-400">{label}</p>
        <p className="text-sm font-medium text-gray-900">{value}</p>
      </div>
    </div>
  );
}