import { MobileMetricCard, MobileSectionHeader } from '@/components/base/MobileUi';
import { useStore } from '@/hooks/useStore';
import { formatCompactCurrency4 as fcc } from '@/utils/format';
import { getFinanceDashboardStats } from '@/utils/financeCalculations';

export function FinanceOverviewTab({ onNavigate }: { onNavigate: (tab: string) => void }) {
  useStore();
  const dashboard = getFinanceDashboardStats();
  const activeDebts = dashboard.dangVay + dashboard.sapDenHan + dashboard.quaHan;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        <MobileMetricCard label="Tổng dư nợ" value={fcc(dashboard.totalDuNo)} caption={`${activeDebts} khoản đang theo dõi`} tone="sky" icon="ri-money-cny-circle-line" onClick={() => onNavigate('debt')} />
        <MobileMetricCard label="Nợ quá hạn" value={fcc(dashboard.overdueAmount)} caption={`${dashboard.quaHan} khoản cần xử lý`} tone={dashboard.quaHan > 0 ? 'rose' : 'slate'} icon="ri-timer-flash-line" onClick={() => onNavigate('debt')} />
        <MobileMetricCard label="Tổng thu" value={fcc(dashboard.tongThu)} caption="Dòng tiền vào HTX" tone="emerald" icon="ri-arrow-down-circle-line" onClick={() => onNavigate('transaction')} />
        <MobileMetricCard label="Chênh lệch" value={fcc(dashboard.chenhLech)} caption="Tổng thu trừ tổng chi" tone={dashboard.chenhLech >= 0 ? 'teal' : 'rose'} icon="ri-scales-line" />
      </div>

      <section>
        <MobileSectionHeader title="Nghiệp vụ tài chính" count="Chọn mục cần xử lý" />
        <div className="space-y-2">
          <ActionRow icon="ri-money-cny-circle-line" title="Công nợ nông hộ" caption={`${activeDebts} khoản · ${dashboard.choXacNhanTT || 0} chờ HTX xác nhận`} value={fcc(dashboard.totalDuNo)} onClick={() => onNavigate('debt')} />
          <ActionRow icon="ri-exchange-dollar-line" title="Thu chi và giao dịch" caption={`Thu ${fcc(dashboard.tongThu)} · Chi ${fcc(dashboard.tongChi)}`} value={fcc(dashboard.chenhLech)} onClick={() => onNavigate('transaction')} />
        </div>
      </section>
    </div>
  );
}

function ActionRow({ icon, title, caption, value, onClick }: { icon: string; title: string; caption: string; value: string; onClick: () => void }) {
  return <button type="button" onClick={onClick} className="mobile-card flex min-h-16 w-full min-w-0 items-center gap-3 p-3 text-left"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700"><i className={icon} /></span><span className="min-w-0 flex-1"><strong className="block truncate text-sm text-slate-900">{title}</strong><span className="metric-caption mt-0.5 block truncate text-[10px] text-slate-400">{caption}</span></span><span className="max-w-[32%] shrink-0 truncate text-xs font-bold text-slate-700">{value}</span><i className="ri-arrow-right-s-line shrink-0 text-slate-400" /></button>;
}
