import { useState, useMemo, type FC } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { showToast } from '@/components/base/Toast';
import EkycStepHeader from '@/components/feature/EkycStepHeader';
import MockCameraCapture from '@/components/feature/MockCameraCapture';
import OcrReviewForm from '@/components/feature/OcrReviewForm';
import type { OcrData } from '@/components/feature/OcrReviewForm';
import EkycResultScreen from '@/components/feature/EkycResultScreen';

type FlowStep = 1 | 2 | 3 | 4 | 5 | 6 | 7;
type ResultType = 'verified' | 'need_more' | 'failed' | 'pending';

function generateMockCccd(): string {
  const prefix = '079';
  const suffix = String(Math.floor(Math.random() * 900000) + 100000);
  return `${prefix}*********${suffix.slice(-2)}`;
}

function generateMockDob(): string {
  const y = 1970 + Math.floor(Math.random() * 30);
  const m = String(Math.floor(Math.random() * 12) + 1).padStart(2, '0');
  const d = String(Math.floor(Math.random() * 28) + 1).padStart(2, '0');
  return `${d}/${m}/${y}`;
}

function generateMockIssueDate(): string {
  const now = new Date();
  const y = now.getFullYear() - Math.floor(Math.random() * 6) - 1;
  const m = String(Math.floor(Math.random() * 12) + 1).padStart(2, '0');
  const d = String(Math.floor(Math.random() * 28) + 1).padStart(2, '0');
  return `${d}/${m}/${y}`;
}

function generateCreditScore(): number {
  return Math.floor(Math.random() * 601) + 300;
}

const EkycFlow: FC = () => {
  const { user, updateKycStatus } = useAuth();

  const [flowStep, setFlowStep] = useState<FlowStep>(1);
  const [frontCaptured, setFrontCaptured] = useState(false);
  const [backCaptured, setBackCaptured] = useState(false);
  const [selfieCaptured, setSelfieCaptured] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [resultType, setResultType] = useState<ResultType | null>(null);
  const [creditScore, setCreditScore] = useState<number>(0);

  const mockOcrData = useMemo<OcrData>(() => {
    const displayName = user?.displayName || 'Nguyễn Văn A';
    const nameParts = displayName.split(' ');
    const firstName = nameParts[nameParts.length - 1] || '';
    const isFemale = firstName.endsWith('g') || firstName === 'Hương' || firstName === 'Bình' || firstName === 'Dung' || firstName === 'Kim' || firstName === 'Phượng';

    const data: OcrData = {
      hoTen: displayName.toUpperCase(),
      soCccd: generateMockCccd(),
      ngaySinh: generateMockDob(),
      gioiTinh: isFemale ? 'Nữ' : 'Nam',
      diaChi: 'Thôn Đông, xã Bình Minh, huyện Đông Tháp, tỉnh Đồng Tháp',
      ngayCap: generateMockIssueDate(),
    };

    if (user?.role === 'Hợp tác xã') {
      data.tenHtx = displayName;
      data.maHtx = user.code || 'HTX-XXX-2025';
      data.vaiTroDaiDien = Math.random() > 0.5 ? 'Giám đốc HTX' : 'Chủ tịch HĐQT';
    }

    return data;
  }, [user]);

  const [ocrData, setOcrData] = useState<OcrData>(mockOcrData);

  const canProceed = (step: FlowStep): boolean => {
    switch (step) {
      case 2: return frontCaptured;
      case 3: return backCaptured;
      case 4: return selfieCaptured;
      default: return true;
    }
  };

  const handleNext = () => {
    if (flowStep < 6) {
      setFlowStep((flowStep + 1) as FlowStep);
    }
  };

  const handleBack = () => {
    if (flowStep > 1) {
      setFlowStep((flowStep - 1) as FlowStep);
    }
  };

  const handleSubmit = () => {
    setSubmitting(true);
    const score = generateCreditScore();

    setTimeout(() => {
      setSubmitting(false);
      setCreditScore(score);

      const roll = Math.random();
      let resType: ResultType;
      // Tỉ lệ: 70% thành công, 12% cần bổ sung, 10% thất bại, 8% đang chờ
      if (roll < 0.70) {
        resType = 'verified';
      } else if (roll < 0.82) {
        resType = 'need_more';
      } else if (roll < 0.92) {
        resType = 'failed';
      } else {
        resType = 'pending';
      }

      setResultType(resType);
      setFlowStep(7);
    }, 2000);
  };

  const handleEnterApp = () => {
    if (!user) return;

    const score = creditScore || generateCreditScore();
    let risk: 'Tốt' | 'Cần chú ý' | 'Nguy cơ' = 'Tốt';
    if (score < 550) risk = 'Nguy cơ';
    else if (score < 700) risk = 'Cần chú ý';

    updateKycStatus(user.id, 'ekyc_verified', undefined, score, risk);
    showToast('Xác thực thành công! Chào mừng bạn đến với Agrida.', 'success');
  };

  const handleRetry = () => {
    if (!user) return;
    updateKycStatus(user.id, 'registered');
    setFlowStep(1);
    setFrontCaptured(false);
    setBackCaptured(false);
    setSelfieCaptured(false);
    setResultType(null);
    setOcrData(mockOcrData);
    showToast('Vui lòng thực hiện lại eKYC từ đầu.', 'info');
  };

  const handleResubmit = () => {
    if (!user) return;
    updateKycStatus(user.id, 'ekyc_need_more', 'Cần bổ sung: Ảnh CCCD bị mờ, không đọc được số. Vui lòng chụp lại ảnh rõ nét hơn.');
    showToast('Đã gửi yêu cầu bổ sung. Vui lòng chờ xét duyệt.', 'success');
  };

  const handlePendingStay = () => {
    if (!user) return;
    updateKycStatus(user.id, 'ekyc_pending', 'Hồ sơ đang được hệ thống xét duyệt. Vui lòng chờ trong 1-2 ngày làm việc.');
    showToast('Hồ sơ của bạn đang được xét duyệt. Vui lòng kiểm tra lại sau.', 'info');
  };

  const getStepTitle = (step: FlowStep): string => {
    const titles: Record<FlowStep, string> = {
      1: 'Xác thực danh tính',
      2: 'Chụp CCCD mặt trước',
      3: 'Chụp CCCD mặt sau',
      4: 'Chụp ảnh chân dung',
      5: 'Xác nhận thông tin OCR',
      6: 'Xác nhận gửi hồ sơ',
      7: 'Kết quả eKYC',
    };
    return titles[step];
  };

  const getStepSubtitle = (step: FlowStep): string => {
    const subtitles: Record<FlowStep, string> = {
      1: 'Agrida cần xác thực danh tính để đảm bảo an toàn và bảo mật cho tài khoản của bạn.',
      2: 'Vui lòng chụp ảnh mặt trước CCCD gắn chip. Đặt CCCD trên mặt phẳng, đủ ánh sáng.',
      3: 'Vui lòng chụp ảnh mặt sau CCCD. Đảm bảo thông tin rõ ràng, không bị mờ.',
      4: 'Chụp ảnh chân dung rõ mặt, không đeo kính đen, nhìn thẳng vào camera.',
      5: 'Hệ thống đã tự động trích xuất thông tin từ CCCD. Vui lòng kiểm tra và sửa nếu cần.',
      6: 'Kiểm tra lại toàn bộ hồ sơ trước khi gửi. Thông tin phải chính xác và trùng khớp.',
      7: '',
    };
    return subtitles[step];
  };

  return (
    <div className="flex flex-col h-full">
      <div className="px-4 pt-4 pb-3 border-b border-gray-100">
        <EkycStepHeader currentStep={flowStep} />
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-4">
        <div className="mb-5">
          <h3 className="text-lg font-bold text-gray-900">{getStepTitle(flowStep)}</h3>
          {flowStep !== 7 && (
            <p className="text-sm text-gray-500 mt-1">{getStepSubtitle(flowStep)}</p>
          )}
        </div>

        {flowStep === 1 && <StepIntro role={user?.role || 'Nông hộ'} />}

        {flowStep === 2 && (
          <MockCameraCapture
            type="front"
            captured={frontCaptured}
            onCapture={() => setFrontCaptured(true)}
          />
        )}

        {flowStep === 3 && (
          <MockCameraCapture
            type="back"
            captured={backCaptured}
            onCapture={() => setBackCaptured(true)}
          />
        )}

        {flowStep === 4 && (
          <MockCameraCapture
            type="selfie"
            captured={selfieCaptured}
            onCapture={() => setSelfieCaptured(true)}
          />
        )}

        {flowStep === 5 && (
          <OcrReviewForm
            data={ocrData}
            role={user?.role || 'Nông hộ'}
            onChange={setOcrData}
          />
        )}

        {flowStep === 6 && <StepConfirm role={user?.role || 'Nông hộ'} frontDone={frontCaptured} backDone={backCaptured} selfieDone={selfieCaptured} ocrData={ocrData} />}

        {flowStep === 7 && resultType && (
          <EkycResultScreen
            resultType={resultType}
            creditScore={creditScore}
            role={user?.role || 'Nông hộ'}
            reason={user?.kycReason}
            onEnterApp={handleEnterApp}
            onRetry={handleRetry}
            onResubmit={handleResubmit}
            onPendingStay={handlePendingStay}
          />
        )}
      </div>

      {/* Bottom CTA bar - only one main action per step */}
      {flowStep < 7 && (
        <div className="px-4 py-3 border-t border-gray-100 bg-white flex gap-3">
          {flowStep > 1 && (
            <button
              type="button"
              onClick={handleBack}
              className="px-4 py-3 rounded-xl border border-gray-200 text-gray-700 font-medium text-sm hover:bg-gray-50 transition-colors whitespace-nowrap min-h-[48px] flex items-center gap-1.5"
            >
              <span className="w-4 h-4 flex items-center justify-center">
                <i className="ri-arrow-left-line" />
              </span>
              Quay lại
            </button>
          )}
          {flowStep < 6 ? (
            <button
              type="button"
              onClick={handleNext}
              disabled={!canProceed(flowStep)}
              className="flex-1 bg-agrida-600 hover:bg-agrida-700 disabled:bg-gray-300 text-white font-semibold py-3 rounded-xl transition-colors disabled:cursor-not-allowed whitespace-nowrap min-h-[48px] text-sm flex items-center justify-center gap-2"
            >
              Tiếp tục
              <span className="w-4 h-4 flex items-center justify-center">
                <i className="ri-arrow-right-line" />
              </span>
            </button>
          ) : (
            <button
              type="button"
              onClick={handleSubmit}
              disabled={submitting}
              className="flex-1 bg-agrida-600 hover:bg-agrida-700 disabled:bg-gray-300 text-white font-semibold py-3 rounded-xl transition-colors disabled:cursor-not-allowed whitespace-nowrap min-h-[48px] text-sm flex items-center justify-center gap-2"
            >
              {submitting ? (
                <>
                  <span className="w-4 h-4 flex items-center justify-center">
                    <i className="ri-loader-4-line animate-spin" />
                  </span>
                  Đang xử lý...
                </>
              ) : (
                <>
                  <span className="w-4 h-4 flex items-center justify-center">
                    <i className="ri-send-plane-line" />
                  </span>
                  Gửi hồ sơ eKYC
                </>
              )}
            </button>
          )}
        </div>
      )}
    </div>
  );
};

function StepIntro({ role }: { role: string }) {
  return (
    <div className="space-y-4">
      <div className="w-full aspect-[16/9] bg-gradient-to-br from-agrida-50 to-agrida-100 rounded-xl flex items-center justify-center mb-2">
        <div className="flex flex-col items-center gap-3">
          <span className="w-16 h-16 flex items-center justify-center">
            <i className="ri-shield-check-line text-agrida-400 text-5xl" />
          </span>
          <span className="text-agrida-600 text-sm font-semibold">Agrida eKYC</span>
        </div>
      </div>

      <div className="space-y-3">
        <div className="flex items-start gap-3 p-3 rounded-xl bg-gray-50">
          <span className="w-8 h-8 rounded-lg bg-agrida-100 flex items-center justify-center shrink-0">
            <i className="ri-check-line text-agrida-600 text-sm" />
          </span>
          <div>
            <p className="text-sm font-semibold text-gray-900">Xác thực nhanh chóng</p>
            <p className="text-xs text-gray-500">Chỉ mất 3-5 phút để hoàn tất xác thực danh tính qua CCCD gắn chip.</p>
          </div>
        </div>

        <div className="flex items-start gap-3 p-3 rounded-xl bg-gray-50">
          <span className="w-8 h-8 rounded-lg bg-agrida-100 flex items-center justify-center shrink-0">
            <i className="ri-lock-line text-agrida-600 text-sm" />
          </span>
          <div>
            <p className="text-sm font-semibold text-gray-900">Bảo mật tuyệt đối</p>
            <p className="text-xs text-gray-500">Dữ liệu được mã hóa và chỉ sử dụng cho mục đích xác thực, không chia sẻ với bên thứ ba.</p>
          </div>
        </div>

        <div className="flex items-start gap-3 p-3 rounded-xl bg-gray-50">
          <span className="w-8 h-8 rounded-lg bg-agrida-100 flex items-center justify-center shrink-0">
            <i className="ri-bank-card-line text-agrida-600 text-sm" />
          </span>
          <div>
            <p className="text-sm font-semibold text-gray-900">Mở khóa tính năng</p>
            <p className="text-xs text-gray-500">
              {role === 'Nông hộ'
                ? 'Sau khi xác thực, bạn có thể vay vốn, nhận vật tư và ký hợp đồng với HTX.'
                : 'Sau khi xác thực, bạn có thể quản lý HTX, duyệt vay và ký hợp đồng với đối tác.'}
            </p>
          </div>
        </div>
      </div>

      <div className="p-3 rounded-xl bg-amber-50 border border-amber-100">
        <div className="flex items-start gap-2">
          <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
            <i className="ri-information-line text-amber-500 text-xs" />
          </span>
          <div>
            <p className="text-xs font-medium text-amber-800">Cần chuẩn bị:</p>
            <ul className="mt-1 space-y-1">
              <li className="flex items-center gap-1.5 text-xs text-amber-700">
                <span className="w-1 h-1 rounded-full bg-amber-400 shrink-0" />
                CCCD gắn chip còn hiệu lực
              </li>
              <li className="flex items-center gap-1.5 text-xs text-amber-700">
                <span className="w-1 h-1 rounded-full bg-amber-400 shrink-0" />
                Điện thoại có camera hoạt động tốt
              </li>
              <li className="flex items-center gap-1.5 text-xs text-amber-700">
                <span className="w-1 h-1 rounded-full bg-amber-400 shrink-0" />
                Đủ ánh sáng, không bị chói
              </li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

function StepConfirm({ role, frontDone, backDone, selfieDone, ocrData }: {
  role: string;
  frontDone: boolean;
  backDone: boolean;
  selfieDone: boolean;
  ocrData: OcrData;
}) {
  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2 mb-2">
        <span className="w-7 h-7 rounded-lg bg-agrida-50 flex items-center justify-center">
          <i className="ri-file-check-line text-agrida-600 text-sm" />
        </span>
        <div>
          <p className="text-sm font-semibold text-gray-900">Tổng quan hồ sơ</p>
          <p className="text-[11px] text-gray-500">Kiểm tra lại trước khi gửi</p>
        </div>
      </div>

      <div className="bg-gray-50 rounded-xl p-4 space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="w-5 h-5 flex items-center justify-center">
              <i className={`text-sm ${frontDone ? 'ri-checkbox-circle-fill text-agrida-500' : 'ri-checkbox-blank-circle-line text-gray-300'}`} />
            </span>
            <span className="text-sm text-gray-700">Ảnh CCCD mặt trước</span>
          </div>
          <span className={`text-xs font-medium ${frontDone ? 'text-agrida-600' : 'text-gray-400'}`}>
            {frontDone ? 'Đã chụp' : 'Chưa chụp'}
          </span>
        </div>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="w-5 h-5 flex items-center justify-center">
              <i className={`text-sm ${backDone ? 'ri-checkbox-circle-fill text-agrida-500' : 'ri-checkbox-blank-circle-line text-gray-300'}`} />
            </span>
            <span className="text-sm text-gray-700">Ảnh CCCD mặt sau</span>
          </div>
          <span className={`text-xs font-medium ${backDone ? 'text-agrida-600' : 'text-gray-400'}`}>
            {backDone ? 'Đã chụp' : 'Chưa chụp'}
          </span>
        </div>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="w-5 h-5 flex items-center justify-center">
              <i className={`text-sm ${selfieDone ? 'ri-checkbox-circle-fill text-agrida-500' : 'ri-checkbox-blank-circle-line text-gray-300'}`} />
            </span>
            <span className="text-sm text-gray-700">Ảnh chân dung</span>
          </div>
          <span className={`text-xs font-medium ${selfieDone ? 'text-agrida-600' : 'text-gray-400'}`}>
            {selfieDone ? 'Đã chụp' : 'Chưa chụp'}
          </span>
        </div>
      </div>

      <div className="bg-gray-50 rounded-xl p-4">
        <p className="text-xs font-semibold text-gray-500 uppercase mb-3">Thông tin OCR</p>
        <div className="space-y-2">
          <InfoRow label="Họ và tên" value={ocrData.hoTen} />
          <InfoRow label="Số CCCD" value={ocrData.soCccd} />
          <InfoRow label="Ngày sinh" value={ocrData.ngaySinh} />
          <InfoRow label="Giới tính" value={ocrData.gioiTinh} />
          <InfoRow label="Địa chỉ" value={ocrData.diaChi} />
          <InfoRow label="Ngày cấp" value={ocrData.ngayCap} />
          {role === 'Hợp tác xã' && (
            <>
              <div className="border-t border-gray-200 my-2" />
              <InfoRow label="Tên HTX" value={ocrData.tenHtx || ''} />
              <InfoRow label="Mã HTX" value={ocrData.maHtx || ''} />
              <InfoRow label="Vai trò" value={ocrData.vaiTroDaiDien || ''} />
            </>
          )}
        </div>
      </div>

      <div className="p-3 rounded-xl bg-agrida-50 border border-agrida-100">
        <div className="flex items-start gap-2">
          <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
            <i className="ri-information-line text-agrida-600 text-xs" />
          </span>
          <p className="text-[11px] text-agrida-700">
            Bằng việc gửi hồ sơ, bạn xác nhận thông tin trên là chính xác và đồng ý với{' '}
            <strong>Điều khoản sử dụng</strong> và <strong>Chính sách bảo mật</strong> của Agrida.
          </p>
        </div>
      </div>
    </div>
  );
}

function InfoRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between">
      <span className="text-xs text-gray-500">{label}</span>
      <span className="text-xs font-semibold text-gray-900 text-right max-w-[60%] truncate">{value || '—'}</span>
    </div>
  );
}

export default EkycFlow;