import { useState, type FC } from 'react';

export interface OcrData {
  hoTen: string;
  soCccd: string;
  ngaySinh: string;
  gioiTinh: string;
  diaChi: string;
  ngayCap: string;
  tenHtx?: string;
  maHtx?: string;
  vaiTroDaiDien?: string;
}

interface OcrReviewFormProps {
  data: OcrData;
  role: 'Nông hộ' | 'Hợp tác xã';
  onChange: (data: OcrData) => void;
}

const OcrReviewForm: FC<OcrReviewFormProps> = ({ data, role, onChange }) => {
  const [editing, setEditing] = useState(false);

  const handleChange = (field: keyof OcrData, value: string) => {
    onChange({ ...data, [field]: value });
  };

  const fields: { key: keyof OcrData; label: string; icon: string }[] = [
    { key: 'hoTen', label: 'Họ và tên', icon: 'ri-user-line' },
    { key: 'soCccd', label: 'Số CCCD', icon: 'ri-id-card-line' },
    { key: 'ngaySinh', label: 'Ngày sinh', icon: 'ri-calendar-line' },
    { key: 'gioiTinh', label: 'Giới tính', icon: 'ri-men-line' },
    { key: 'diaChi', label: 'Địa chỉ', icon: 'ri-map-pin-line' },
    { key: 'ngayCap', label: 'Ngày cấp', icon: 'ri-calendar-check-line' },
  ];

  const htxFields: { key: keyof OcrData; label: string; icon: string }[] = [
    { key: 'tenHtx', label: 'Tên HTX', icon: 'ri-building-line' },
    { key: 'maHtx', label: 'Mã HTX', icon: 'ri-barcode-line' },
    { key: 'vaiTroDaiDien', label: 'Vai trò người đại diện', icon: 'ri-shield-user-line' },
  ];

  const allFields = role === 'Hợp tác xã' ? [...fields, ...htxFields] : fields;

  return (
    <div className="w-full">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <span className="w-7 h-7 rounded-lg bg-agrida-50 flex items-center justify-center">
            <i className="ri-scan-2-line text-agrida-600 text-sm" />
          </span>
          <div>
            <p className="text-sm font-semibold text-gray-900">Thông tin từ OCR</p>
            <p className="text-[11px] text-gray-500">Dữ liệu được tự động trích xuất từ ảnh CCCD</p>
          </div>
        </div>
        <button
          type="button"
          onClick={() => setEditing(!editing)}
          className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors whitespace-nowrap min-h-[44px] ${
            editing
              ? 'bg-agrida-100 text-agrida-700'
              : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
          }`}
        >
          {editing ? 'Xong' : 'Chỉnh sửa'}
        </button>
      </div>

      <div className="space-y-2">
        {allFields.map(({ key, label, icon }) => {
          const value = data[key] || '';
          const isHtxField = htxFields.some((f) => f.key === key);

          return (
            <div
              key={key}
              className={`rounded-xl p-3 transition-colors ${
                isHtxField ? 'bg-sky-50 border border-sky-100' : 'bg-gray-50'
              }`}
            >
              <div className="flex items-center gap-2 mb-1">
                <span className="w-4 h-4 flex items-center justify-center">
                  <i className={`${icon} ${isHtxField ? 'text-sky-500' : 'text-gray-400'} text-xs`} />
                </span>
                <span className={`text-[11px] font-medium ${isHtxField ? 'text-sky-600' : 'text-gray-500'}`}>
                  {label}
                </span>
                {isHtxField && (
                  <span className="text-[9px] bg-sky-100 text-sky-600 px-1.5 py-0.5 rounded-full font-medium">HTX</span>
                )}
              </div>
              {editing ? (
                <input
                  type="text"
                  value={value}
                  onChange={(e) => handleChange(key, e.target.value)}
                  className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 text-sm text-gray-900 focus:outline-none focus:border-agrida-400 focus:ring-1 focus:ring-agrida-200 transition-colors"
                />
              ) : (
                <p className="text-sm font-semibold text-gray-900 pl-6">{value || '—'}</p>
              )}
            </div>
          );
        })}
      </div>

      <div className="mt-4 p-3 rounded-xl bg-amber-50 border border-amber-100">
        <div className="flex items-start gap-2">
          <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
            <i className="ri-information-line text-amber-500 text-xs" />
          </span>
          <p className="text-[11px] text-amber-700">
            Vui lòng kiểm tra kỹ thông tin OCR. Nếu có sai sót, nhấn <strong>Chỉnh sửa</strong> để sửa lại trước khi gửi hồ sơ.
          </p>
        </div>
      </div>
    </div>
  );
};

export default OcrReviewForm;