import {
  addEditHistory,
  addLimit,
  addNotification,
  getState,
  updateContract,
  updateLimit,
  updateLimitRequest,
} from '@/store';
import { formatCurrencyCompact } from '@/utils/formatters';

export interface GrantLimitOptions {
  farmerId: string;
  farmerName: string;
  contractId: string;
  hanMuc: number;
  limitId?: string;
  requestId?: string;
  overrideReason?: string;
  approver?: string;
}

export interface GrantLimitResult {
  success: boolean;
  limitId: string;
  isUpdate: boolean;
}

export function executeGrantLimit(options: GrantLimitOptions): GrantLimitResult {
  const state = getState();
  const contract = state.contracts.find((item) => item.id === options.contractId);
  if (!contract) throw new Error('Không tìm thấy hợp đồng để cấp hạn mức.');
  if (!Number.isFinite(options.hanMuc) || options.hanMuc <= 0) throw new Error('Hạn mức phải lớn hơn 0.');

  const existingLimit = options.limitId
    ? state.limits.find((item) => item.id === options.limitId)
    : state.limits.find((item) => item.farmerId === options.farmerId && item.contractId === options.contractId);
  const previousAmount = existingLimit?.hanMuc || 0;
  const nowIso = new Date().toISOString();
  const approver = options.approver || 'HTX Hòa Phát';

  let limitId: string;
  let finalLimitAmount = options.hanMuc;
  if (existingLimit) {
    limitId = existingLimit.id;
    finalLimitAmount = previousAmount + options.hanMuc;
    updateLimit(existingLimit.id, {
      hanMuc: finalLimitAmount,
      loaiDinhMuc: existingLimit.loaiDinhMuc.replace(' (Khóa)', ''),
    });
  } else {
    const created = addLimit({
      farmerId: options.farmerId,
      contractId: options.contractId,
      loaiDinhMuc: 'Vay vốn sản xuất',
      hanMuc: options.hanMuc,
      daSuDung: 0,
      nam: new Date().getFullYear(),
    });
    limitId = created.id;
  }

  return finalizeGrant(limitId, previousAmount, finalLimitAmount, !!existingLimit, options, contract.giaTri, contract.hanMucDaCap || 0, nowIso, approver);
}

function finalizeGrant(
  limitId: string,
  previousAmount: number,
  finalLimitAmount: number,
  isUpdate: boolean,
  options: GrantLimitOptions,
  contractValue: number,
  currentAllocated: number,
  nowIso: string,
  approver: string,
): GrantLimitResult {
  const allocated = Math.max(0, currentAllocated + options.hanMuc);
  updateContract(options.contractId, {
    hanMucDaCap: allocated,
    hanMucConLai: Math.max(0, contractValue - allocated),
  });

  if (options.requestId) updateLimitRequest(options.requestId, { status: 'Đã duyệt' });

  addNotification({
    farmerId: options.farmerId,
    title: isUpdate ? 'Hạn mức vay đã được cấp thêm' : 'Hạn mức vay mới đã được cấp',
    content: `HTX đã ${isUpdate ? 'cấp thêm' : 'cấp'} ${formatCurrencyCompact(options.hanMuc)}. Tổng hạn mức hợp đồng hiện là ${formatCurrencyCompact(finalLimitAmount)}.`,
    type: 'general',
    ngayTao: nowIso,
    daDoc: false,
    sentBy: approver,
  });

  addEditHistory({
    entityType: 'Limit',
    entityId: limitId,
    farmerId: options.farmerId,
    truong: 'hanMuc',
    giaTriCu: String(previousAmount),
    giaTriMoi: `${finalLimitAmount} (+${options.hanMuc})${options.overrideReason ? ` | ${options.overrideReason}` : ''}`,
    ngaySua: nowIso,
    nguoiSua: approver,
  });

  return { success: true, limitId, isUpdate };
}
