// Centralized HTX -> farmer disbursement service.
// Banks are not funding or approval parties in this flow. The principal is
// deducted from an HTX funding source and recorded as a farmer debt atomically.

import {
  addDebt,
  addDisbursement,
  addEditHistory,
  addFinance,
  addNotification,
  convertLimitLock,
  createLimitLock,
  expireLimitLock,
  getActiveLockByLoan,
  getState,
  updateDisbursement,
  updateLoan,
} from '@/store';
import { showToast } from '@/components/base/Toast';
import { formatVND } from '@/utils/format';
import {
  allocateDisbursedToHtxSources,
  allocateDisbursedToLimits,
  getAvailableHtxSourceLimit,
  getAvailableFarmerLimit,
} from '@/utils/financeCalculations';
import { recordBalancedEntry } from '@/utils/moneyLedger';

export interface DisbursementResult {
  status: 'success' | 'failed' | 'timeout';
  message: string;
}

function createHtxTransactionCode(): string {
  const date = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const suffix = Math.random().toString(36).slice(2, 7).toUpperCase();
  return `HTX-${date}-${suffix}`;
}

export function checkDisburseEligibility(loan: {
  id: string;
  farmerId: string;
  soTien: number;
  status: string;
}): { eligible: boolean; reason: string } {
  const validStatuses = [
    'approved_locked', 'Đã duyệt', 'disbursement_failed', 'Giải ngân lỗi',
    'lock_expired', 'Chờ giải ngân',
  ];
  if (!validStatuses.includes(loan.status)) {
    return { eligible: false, reason: `Trạng thái "${loan.status}" không đủ điều kiện giải ngân` };
  }

  const activeLock = getActiveLockByLoan(loan.id);
  const reservedForThisLoan = activeLock?.status === 'active' ? activeLock.amount : 0;
  const farmerAvailable = getAvailableFarmerLimit(loan.farmerId) + reservedForThisLoan;
  if (loan.soTien > farmerAvailable) {
    return {
      eligible: false,
      reason: `Hạn mức nông hộ khả dụng ${formatVND(farmerAvailable)}, không đủ ${formatVND(loan.soTien)}`,
    };
  }

  const htxAvailable = getAvailableHtxSourceLimit() + reservedForThisLoan;
  if (loan.soTien > htxAvailable) {
    return {
      eligible: false,
      reason: `Nguồn tiền HTX khả dụng ${formatVND(htxAvailable)}, không đủ ${formatVND(loan.soTien)}`,
    };
  }

  return { eligible: true, reason: 'Đủ điều kiện giải ngân từ nguồn tiền HTX' };
}

export async function submitHtxDisbursement(
  loan: { id: string; farmerId: string; soTien: number; mucDich?: string },
  farmerName: string,
  confirmNote?: string,
): Promise<DisbursementResult & { disbursementId: string }> {
  const eligibility = checkDisburseEligibility({ ...loan, status: getState().advanceRequests.find((item) => item.id === loan.id)?.status || '' });
  if (!eligibility.eligible) {
    return { status: 'failed', message: eligibility.reason, disbursementId: '' };
  }

  const now = new Date();
  const nowIso = now.toISOString();
  const today = nowIso.split('T')[0];
  const transactionCode = createHtxTransactionCode();
  const request = addDisbursement({
    advanceRequestId: loan.id,
    bankRequestCode: transactionCode,
    farmerId: loan.farmerId,
    farmerName,
    soTien: loan.soTien,
    nganHang: 'Sổ quỹ HTX',
    stkMask: `AGRIDA-${loan.farmerId.toUpperCase()}`,
    status: 'success',
    transactionCode,
    ngayGui: nowIso,
    ngayCapNhat: nowIso,
    ghiChu: confirmNote || loan.mucDich || '',
    sourceName: 'Ví HTX',
  });

  allocateDisbursedToHtxSources(loan.soTien);

  allocateDisbursedToLimits(loan.farmerId, loan.soTien);
  updateLoan(loan.id, { status: 'disbursed', ngayDuyet: today });

  const dueDate = new Date(now);
  dueDate.setMonth(dueDate.getMonth() + 3);
  const loanCode = `KV-${now.getFullYear()}-${String(Math.floor(Math.random() * 900) + 100)}`;

  addDebt({
    farmerId: loan.farmerId,
    advanceRequestId: loan.id,
    disbursementId: request.id,
    maKhoanVay: loanCode,
    soTien: loan.soTien,
    daTra: 0,
    conNo: loan.soTien,
    ngayDenHan: dueDate.toISOString().split('T')[0],
    status: 'Đang vay',
    laiSuat: 0.5,
    ngayVay: today,
    phuongThucTra: 'Thanh toán trực tiếp cho HTX',
    kyHan: '3 tháng',
  });

  addFinance({
    farmerId: loan.farmerId,
    loai: 'Chi',
    soTien: loan.soTien,
    moTa: `HTX giải ngân khoản vay ${loanCode}`,
    ngay: today,
    trangThai: 'Hoàn thành',
    nguonGoc: 'Ví HTX',
    maGiaoDich: transactionCode,
    phanLoai: 'Giải ngân',
  });

  recordBalancedEntry({
    code: transactionCode,
    type: 'HTX_TO_FARMER',
    description: `HTX giải ngân khoản vay ${loanCode} cho ${farmerName}`,
    postings: [
      { account: 'HTX_CASH', amount: -loan.soTien, label: 'HTX giải ngân' },
      { account: `FARMER:${loan.farmerId}`, amount: loan.soTien, label: 'Nông hộ nhận vốn' },
    ],
  });

  const activeLock = getActiveLockByLoan(loan.id);
  if (activeLock) convertLimitLock(activeLock.id);

  addNotification({
    farmerId: loan.farmerId,
    title: 'HTX đã giải ngân',
    content: `HTX đã giải ngân ${formatVND(loan.soTien)} cho khoản vay ${loanCode}. Giao dịch được ghi trực tiếp từ nguồn tiền HTX, mã ${transactionCode}.`,
    type: 'disburse_success',
    ngayTao: nowIso,
    daDoc: false,
  });

  addEditHistory({
    entityType: 'Disbursement',
    entityId: request.id,
    farmerId: loan.farmerId,
    truong: 'Luồng tiền',
    giaTriCu: 'Nguồn tiền HTX',
    giaTriMoi: `HTX -${formatVND(loan.soTien)} / Nông hộ +${formatVND(loan.soTien)}`,
    ngaySua: nowIso,
    nguoiSua: 'HTX Hòa Phát',
  });

  showToast(`Đã giải ngân ${formatVND(loan.soTien)} trực tiếp từ nguồn tiền HTX.`, 'success');
  return { status: 'success', message: `Giải ngân thành công ${formatVND(loan.soTien)}`, disbursementId: request.id };
}

// Backward-compatible name used by existing screens.
export const submitDisbursementToBank = submitHtxDisbursement;

// Kept for compatibility with a legacy import. New flows call
// submitHtxDisbursement and no longer process an external bank response.
export function handleDisbursementResult(): DisbursementResult {
  return { status: 'failed', message: 'Luồng phản hồi ngân hàng đã ngừng sử dụng' };
}

export interface CanRelockResult {
  canLock: boolean;
  reasons: string[];
  farmerAvailableLimit: number;
  htxAvailableLimit: number;
  requiredAmount: number;
  farmerShortfall: number;
  htxShortfall: number;
  hasStk: boolean;
  farmerName: string;
}

export function canCreateNewLockForLoan(loanId: string): CanRelockResult {
  const state = getState();
  const loan = state.advanceRequests.find((item) => item.id === loanId);
  if (!loan) {
    return { canLock: false, reasons: ['Không tìm thấy khoản vay'], farmerAvailableLimit: 0, htxAvailableLimit: 0, requiredAmount: 0, farmerShortfall: 0, htxShortfall: 0, hasStk: true, farmerName: '' };
  }
  const farmerAvailableLimit = getAvailableFarmerLimit(loan.farmerId);
  const htxAvailableLimit = getAvailableHtxSourceLimit();
  const farmerShortfall = Math.max(0, loan.soTien - farmerAvailableLimit);
  const htxShortfall = Math.max(0, loan.soTien - htxAvailableLimit);
  const reasons: string[] = [];
  if (farmerShortfall > 0) reasons.push('Hạn mức nông hộ không đủ');
  if (htxShortfall > 0) reasons.push('Nguồn tiền HTX không đủ');
  const finalStatuses = ['Đã giải ngân', 'Đã tất toán', 'Từ chối', 'Đã hủy', 'disbursed'];
  if (finalStatuses.includes(loan.status)) reasons.push(`Khoản vay đang ở trạng thái ${loan.status}`);
  return {
    canLock: reasons.length === 0,
    reasons,
    farmerAvailableLimit,
    htxAvailableLimit,
    requiredAmount: loan.soTien,
    farmerShortfall,
    htxShortfall,
    hasStk: true,
    farmerName: state.farmers.find((farmer) => farmer.id === loan.farmerId)?.name || loan.farmerId,
  };
}

export function relockLoanForDisbursement(loanId: string, createdBy: string): { success: boolean; message: string; lockExpiresAtFormatted?: string } {
  const check = canCreateNewLockForLoan(loanId);
  if (!check.canLock) return { success: false, message: check.reasons.join('; ') };
  const state = getState();
  const loan = state.advanceRequests.find((item) => item.id === loanId);
  if (!loan) return { success: false, message: 'Không tìm thấy khoản vay' };
  state.limitLocks.filter((lock) => lock.loanId === loanId && lock.status === 'active').forEach((lock) => expireLimitLock(lock.id));
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 10 * 60 * 1000);
  createLimitLock({
    loanId,
    farmerId: loan.farmerId,
    amount: loan.soTien,
    sourceType: 'both',
    status: 'active',
    lockedAt: now.toISOString(),
    expiresAt: expiresAt.toISOString(),
    createdBy,
  });
  updateLoan(loanId, { status: 'approved_locked' });
  return { success: true, message: 'Đã khóa lại hạn mức để giải ngân từ nguồn HTX', lockExpiresAtFormatted: expiresAt.toLocaleTimeString('vi-VN') };
}
