// ─── Public API ──────────────────────────────────────────────

/**
 * Get score band info from a numeric score (300–900).
 * Returns default "Chưa tính" for null/undefined or scores < 300.
 */
export function getScoreBand(score: number | null | undefined): ScoreBandInfo {
  if (score == null || score < 300) return BAND_DEFAULT;
  for (const band of SCORE_BANDS) {
    if (score >= band.min && score <= band.max) return band;
  }
  // If score > 900, cap at Tốt
  return SCORE_BANDS[0];
}

/**
 * Get the normalized RiskLevel string (old enum format) from a score.
 */
export function getRiskLevelFromScore(score: number | null | undefined): string {
  return getScoreBand(score).band;
}

/**
 * Check if approving a loan requires the exception confirmation modal.
 */
export function requiresExceptionApproval(score: number | null | undefined): boolean {
  return getScoreBand(score).requiresConfirm;
}

/**
 * Format score as "735/900 — Khá"
 */
export function formatScoreDisplay(score: number | null | undefined): string {
  if (score == null) return 'Chưa có điểm';
  const band = getScoreBand(score);
  return `${score}/900 — ${band.band}`;
}

/**
 * Score bar percentage (0–100) for visual progress bars.
 * Uses 300–900 as the visual range.
 */
export function getScoreBarPercent(score: number | null | undefined): number {
  if (score == null || score < 300) return 0;
  return Math.min(100, ((score - 300) / 600) * 100);
}

/**
 * Get the color for the score bar based on the band.
 */
export function getScoreBarColor(score: number | null | undefined): string {
  return getScoreBand(score).barColor;
}

// ─── Risk Assessment Aggregation ─────────────────────────────

export interface RiskFactor {
  name: string;
  score: number; // 0–100
  detail: string;
  weight: number; // 0–1
}

export interface RiskAssessment {
  totalScore: number;      // 300–900
  band: ScoreBandInfo;
  factors: RiskFactor[];
  hasOverdueDebt: boolean;
  overdueCount: number;
  overdueAmount: number;
  pendingDisbursementAmount: number;
  totalDebt: number;
  remainingLimit: number;
  ekycVerified: boolean;
  activeContracts: number;
}

/**
 * Build a comprehensive risk assessment for a farmer.
 * Used in the exception approval modal and risk profile displays.
 */
export function buildRiskAssessment(
  ekycScore: number,
  diaryScore: number,
  yieldScore: number,
  debtScore: number,
  contractScore: number,
  hasOverdue: boolean,
  overdueCount: number,
  overdueAmount: number,
  pendingDisbursementAmount: number,
  totalDebt: number,
  remainingLimit: number,
  ekycVerified: boolean,
  activeContracts: number,
): RiskAssessment {
  const factors: RiskFactor[] = [
    { name: 'eKYC & Định danh', score: ekycScore, detail: ekycVerified ? 'Đã xác thực' : 'Chưa xác thực', weight: 0.2 },
    { name: 'Nhật ký canh tác', score: diaryScore, detail: '', weight: 0.16 },
    { name: 'Sản lượng thu hoạch', score: yieldScore, detail: '', weight: 0.2 },
    { name: 'Lịch sử thanh toán', score: debtScore, detail: hasOverdue ? `Có ${overdueCount} khoản quá hạn` : 'Thanh toán đúng hạn', weight: 0.2 },
    { name: 'Hợp đồng bao tiêu', score: contractScore, detail: `${activeContracts} hợp đồng hiệu lực`, weight: 0.16 },
  ];

  // Scale: each factor max 100, weighted sum, then scale to 300–900
  let rawScore = 0;
  factors.forEach((f) => {
    rawScore += f.score * f.weight;
  });
  // rawScore is 0–100
  // Map to 300–900
  const totalScore = Math.round(300 + (rawScore / 100) * 600);

  // Penalty for overdue
  let adjustedScore = totalScore;
  if (hasOverdue) {
    adjustedScore = Math.max(300, adjustedScore - overdueCount * 40);
  }

  const band = getScoreBand(adjustedScore);

  return {
    totalScore: adjustedScore,
    band,
    factors,
    hasOverdueDebt: hasOverdue,
    overdueCount,
    overdueAmount,
    pendingDisbursementAmount,
    totalDebt,
    remainingLimit,
    ekycVerified,
    activeContracts,
  };
}

