import { useState, useMemo, useCallback, useRef } from 'react';
import type { Contract, ContractAttachment } from '../../../../types';
import { getFarmers, getSeasonsByFarmer, getSeasons, getFieldsByFarmer } from '../../../../store';
import { formatVND, todayInputValue, formatNumber } from '../../../../utils/format';
import { showToast } from '../../../../components/base/Toast';
import { useModalBackHandler } from '../../../../hooks/useModalBackHandler';

interface ContractFormModalProps {
  editItem: Contract | null;
  onClose: () => void;
  onSave: (data: Omit<Contract, 'id' | 'soHopDong'>, attachments: ContractAttachment[]) => void;
}

export default function ContractFormModal({ editItem, onClose, onSave }: ContractFormModalProps) {
  useModalBackHandler(true, onClose);
  const farmers = getFarmers();
  const allSeasons = getSeasons();

  const [step, setStep] = useState(1);

  const [farmerId, setFarmerId] = useState(editItem?.farmerId || farmers[0]?.id || '');
  const [loaiHopDong, setLoaiHopDong] = useState<Contract['loaiHopDong']>(editItem?.loaiHopDong || 'HTX-Nông hộ');
  const [doiTac, setDoiTac] = useState(editItem?.doiTac || '');
  const [ngayKy, setNgayKy] = useState(editItem?.ngayKy || todayInputValue());
  const [ngayHieuLuc, setNgayHieuLuc] = useState(editItem?.ngayHieuLuc || '');
  const [ngayHetHan, setNgayHetHan] = useState(editItem?.ngayHetHan || '');
  const [selectedSeasons, setSelectedSeasons] = useState<string[]>(editItem?.seasonIds || []);
  const [giaTri, setGiaTri] = useState(editItem ? String(editItem.giaTri) : '');
  const [donGiaDuKien, setDonGiaDuKien] = useState(editItem?.donGiaDuKien ? String(editItem.donGiaDuKien) : '');
  const [noiDung, setNoiDung] = useState(editItem?.noiDung || '');
  const [status, setStatus] = useState<Contract['status']>(editItem?.status || 'Nháp');
  const [ghiChu, setGhiChu] = useState(editItem?.ghiChu || '');
  const [attachments, setAttachments] = useState<ContractAttachment[]>(editItem?.attachments || []);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const farmerSeasons = useMemo(() => getSeasonsByFarmer(farmerId), [farmerId]);
  const farmerFields = useMemo(() => getFieldsByFarmer(farmerId), [farmerId]);
  const selectedFarmerName = farmers.find((f) => f.id === farmerId)?.name || '';

  // Auto-fill fields when seasons are selected
  const autoFillData = useMemo(() => {
    if (selectedSeasons.length === 0) return null;
    const seasons = selectedSeasons
      .map((sid) => allSeasons.find((s) => s.id === sid))
      .filter(Boolean);
    if (seasons.length === 0) return null;

    const firstSeason = seasons[0];
    const field = farmerFields.find((f) => f.id === firstSeason?.fieldId);
    const totalYield = seasons.reduce((s, se) => s + (se?.expectedYield || 0), 0);
    const totalArea = seasons.reduce((s, se) => {
      const f = farmerFields.find((fi) => fi.id === se?.fieldId);
      return s + (f?.area || 0);
    }, 0);

    return {
      cayTrong: firstSeason?.cayTrong || '',
      giong: firstSeason?.variety || '',
      dienTich: totalArea,
      sanLuongDuKien: totalYield * 1000,
      fieldName: field?.name || '',
      muaVuRisk: seasons.some((s) => s?.status === 'Có rủi ro'),
    };
  }, [selectedSeasons, allSeasons, farmerFields]);

  const toggleSeason = useCallback((id: string) => {
    setSelectedSeasons((prev) =>
      prev.includes(id) ? prev.filter((s) => s !== id) : [...prev, id]
    );
  }, []);

  const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach((file) => {
      const ext = file.name.split('.').pop()?.toLowerCase() || '';
      const allowed = ['pdf', 'jpg', 'jpeg', 'png', 'doc', 'docx', 'xls', 'xlsx', 'txt'];
      if (!allowed.includes(ext)) {
        showToast(`Không hỗ trợ file ${ext.toUpperCase()}`, 'warning');
        return;
      }
      if (file.size > 10 * 1024 * 1024) {
        showToast('File vượt quá 10MB', 'warning');
        return;
      }
      const newAtt: ContractAttachment = {
        id: `att_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
        name: file.name,
        type: file.type || `application/${ext}`,
        size: file.size,
        url: URL.createObjectURL(file),
        uploadDate: new Date().toISOString(),
      };
      setAttachments((prev) => [...prev, newAtt]);
    });
    // reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  }, []);

  const removeAttachment = useCallback((id: string) => {
    setAttachments((prev) => prev.filter((a) => a.id !== id));
  }, []);

  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const getFileIcon = (type: string): string => {
    if (type.includes('pdf')) return 'ri-file-pdf-line';
    if (type.includes('image')) return 'ri-image-line';
    if (type.includes('word') || type.includes('document')) return 'ri-file-word-line';
    if (type.includes('excel') || type.includes('sheet')) return 'ri-file-excel-line';
    return 'ri-file-line';
  };

  const totalValue = useMemo(() => {
    const dg = Number(donGiaDuKien);
    const sl = autoFillData?.sanLuongDuKien || 0;
    if (dg && sl) return dg * sl;
    return Number(giaTri) || 0;
  }, [donGiaDuKien, autoFillData, giaTri]);

  const handleSubmit = () => {
    if (!farmerId || !ngayKy || !ngayHetHan || !noiDung.trim()) {
      showToast('Vui lòng điền đầy đủ thông tin bắt buộc', 'warning');
      return;
    }
    if (selectedSeasons.length === 0) {
      showToast('Vui lòng chọn ít nhất một mùa vụ', 'warning');
      return;
    }
    const data: Omit<Contract, 'id' | 'soHopDong'> = {
      farmerId,
      loaiHopDong,
      doiTac: loaiHopDong === 'HTX-Nông hộ' ? selectedFarmerName : doiTac.trim() || selectedFarmerName,
      ngayKy,
      ngayHieuLuc: ngayHieuLuc || undefined,
      ngayHetHan,
      noiDung: noiDung.trim(),
      giaTri: totalValue,
      donGiaDuKien: donGiaDuKien ? Number(donGiaDuKien) : undefined,
      status,
      seasonIds: selectedSeasons,
      cayTrong: autoFillData?.cayTrong || undefined,
      giong: autoFillData?.giong || undefined,
      dienTich: autoFillData?.dienTich || undefined,
      sanLuongDuKien: autoFillData?.sanLuongDuKien || undefined,
      ghiChu: ghiChu.trim() || undefined,
      taiLieuUrl: attachments[0]?.url,
    };
    onSave(data, attachments);
  };

  const loaiOptions: Contract['loaiHopDong'][] = ['HTX-Nông hộ', 'HTX-Đối tác thu mua', 'Cung ứng/Vật tư'];
  const statusOptions: Contract['status'][] = ['Nháp', 'Chờ ký', 'Đang hiệu lực', 'Sắp hết hạn', 'Hết hạn', 'Thiếu tài liệu', 'Tạm dừng', 'Hủy'];

  const isMobile = typeof window !== 'undefined' && window.innerWidth < 1024;

  return (
    <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
      <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={onClose} />
      <div onClick={(e) => e.stopPropagation()} className={`relative bg-white rounded-t-2xl sm:rounded-xl shadow-xl w-full sm:max-w-3xl max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto ${isMobile ? 'h-[95dvh]' : ''}`}>
        {/* Header */}
        <div className="sticky top-0 bg-white border-b border-slate-200 px-4 sm:px-6 py-3 flex items-center justify-between z-10 rounded-t-2xl sm:rounded-t-xl">
          <h3 className="text-base sm:text-lg font-semibold text-slate-900">
            {editItem ? `Sửa hợp đồng ${editItem.soHopDong}` : 'Tạo hợp đồng mới'}
          </h3>
          <button type="button" onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-500">
            <span className="w-5 h-5 flex items-center justify-center"><i className="ri-close-line" /></span>
          </button>
        </div>

        {/* Step indicator */}
        <div className="px-4 sm:px-6 pt-4">
          <div className="flex items-center gap-2">
            <div className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-xs font-medium ${step === 1 ? 'bg-emerald-700 text-white' : 'bg-slate-100 text-slate-500'}`}>
              <span className="w-4 h-4 flex items-center justify-center"><i className="ri-file-list-line" /></span>
              Thông tin
            </div>
            <div className="h-px w-6 bg-slate-200" />
            <div className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-xs font-medium ${step === 2 ? 'bg-emerald-700 text-white' : 'bg-slate-100 text-slate-500'}`}>
              <span className="w-4 h-4 flex items-center justify-center"><i className="ri-attachment-line" /></span>
              Tài liệu
            </div>
          </div>
        </div>

        {/* Body */}
        <div className="px-4 sm:px-6 py-4 space-y-4">
          {step === 1 && (
            <>
              {/* Loại hợp đồng */}
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1.5">Loại hợp đồng <span className="text-red-500">*</span></label>
                <div className="flex flex-wrap gap-2">
                  {loaiOptions.map((l) => (
                    <button
                      key={l}
                      type="button"
                      onClick={() => { setLoaiHopDong(l); if (l === 'HTX-Nông hộ') setDoiTac(selectedFarmerName); }}
                      className={`px-3 py-2 rounded-lg text-xs sm:text-sm font-medium border transition-colors whitespace-nowrap ${loaiHopDong === l ? 'bg-emerald-700 text-white border-emerald-700' : 'bg-white text-slate-600 border-slate-200 hover:border-emerald-300'}`}
                    >
                      {l}
                    </button>
                  ))}
                </div>
              </div>

              {/* Nông hộ + Đối tác */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Nông hộ liên quan <span className="text-red-500">*</span></label>
                  <select
                    value={farmerId}
                    onChange={(e) => { const id = e.target.value; setFarmerId(id); setSelectedSeasons([]); if (loaiHopDong === 'HTX-Nông hộ') setDoiTac(farmers.find((f) => f.id === id)?.name || ''); }}
                    className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 bg-white"
                  >
                    {farmers.map((f) => (<option key={f.id} value={f.id}>{f.name} ({f.code})</option>))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">
                    {loaiHopDong === 'HTX-Nông hộ' ? 'Tên nông hộ (tự điền)' : 'Đối tác / Nhà cung cấp'}
                  </label>
                  <input
                    type="text"
                    value={doiTac}
                    onChange={(e) => setDoiTac(e.target.value)}
                    disabled={loaiHopDong === 'HTX-Nông hộ'}
                    placeholder={loaiHopDong === 'HTX-Nông hộ' ? selectedFarmerName : 'Nhập tên đối tác...'}
                    className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 disabled:bg-slate-50 disabled:text-slate-500"
                  />
                </div>
              </div>

              {/* Dates */}
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Ngày ký <span className="text-red-500">*</span></label>
                  <input type="date" value={ngayKy} onChange={(e) => setNgayKy(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Ngày hiệu lực</label>
                  <input type="date" value={ngayHieuLuc} onChange={(e) => setNgayHieuLuc(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Ngày hết hạn <span className="text-red-500">*</span></label>
                  <input type="date" value={ngayHetHan} onChange={(e) => setNgayHetHan(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" />
                </div>
              </div>

              {/* Mùa vụ */}
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1.5">Mùa vụ liên quan <span className="text-red-500">*</span></label>
                <div className="flex flex-wrap gap-2">
                  {farmerSeasons.map((s) => (
                    <button
                      key={s.id}
                      type="button"
                      onClick={() => toggleSeason(s.id)}
                      className={`px-3 py-1.5 rounded-md text-xs font-medium border transition-colors ${selectedSeasons.includes(s.id) ? 'bg-emerald-700 text-white border-emerald-700' : 'bg-white text-slate-600 border-slate-200 hover:border-emerald-300'}`}
                    >
                      {s.name}
                    </button>
                  ))}
                  {farmerSeasons.length === 0 && (
                    <p className="text-xs text-slate-400 italic">Nông hộ chưa có mùa vụ nào.</p>
                  )}
                </div>
                {selectedSeasons.length > 0 && (
                  <p className="text-xs text-emerald-600 mt-1">Đã chọn {selectedSeasons.length} mùa vụ</p>
                )}
              </div>

              {/* Auto-fill display */}
              {autoFillData && (
                <div className="bg-sky-50 border border-sky-100 rounded-lg p-3 space-y-1.5">
                  <div className="flex items-center gap-1.5 text-sm font-medium text-sky-800">
                    <span className="w-4 h-4 flex items-center justify-center"><i className="ri-magic-line" /></span>
                    Thông tin tự điền từ mùa vụ
                  </div>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-x-4 gap-y-1 text-xs text-sky-700">
                    <p><span className="text-sky-500">Cây trồng:</span> {autoFillData.cayTrong || '-'}</p>
                    <p><span className="text-sky-500">Giống:</span> {autoFillData.giong || '-'}</p>
                    <p><span className="text-sky-500">Diện tích:</span> {autoFillData.dienTich > 0 ? `${autoFillData.dienTich} ha` : '-'}</p>
                    <p><span className="text-sky-500">Sản lượng dự kiến:</span> {autoFillData.sanLuongDuKien > 0 ? `${formatNumber(autoFillData.sanLuongDuKien)} kg` : '-'}</p>
                    <p><span className="text-sky-500">Thửa đất:</span> {autoFillData.fieldName || '-'}</p>
                    {autoFillData.muaVuRisk && (
                      <p className="flex items-center gap-1 text-red-600">
                        <span className="w-3 h-3 flex items-center justify-center"><i className="ri-alarm-warning-line" /></span>
                        Có mùa vụ rủi ro
                      </p>
                    )}
                  </div>
                </div>
              )}

              {/* Giá trị */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Đơn giá dự kiến (VND/kg)</label>
                  <input
                    type="number"
                    value={donGiaDuKien}
                    onChange={(e) => setDonGiaDuKien(e.target.value)}
                    placeholder="Nhập đơn giá..."
                    className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Giá trị dự kiến (VND)</label>
                  <input
                    type="number"
                    value={giaTri}
                    onChange={(e) => setGiaTri(e.target.value)}
                    placeholder="Tự tính từ đơn giá × sản lượng..."
                    className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                  />
                  {totalValue > 0 && (
                    <p className="text-xs text-slate-400 mt-1">
                      Tính toán: {formatVND(totalValue)}
                    </p>
                  )}
                </div>
              </div>

              {/* Trạng thái + Nội dung */}
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Trạng thái <span className="text-red-500">*</span></label>
                <select
                  value={status}
                  onChange={(e) => setStatus(e.target.value as Contract['status'])}
                  className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 bg-white"
                >
                  {statusOptions.map((s) => (<option key={s} value={s}>{s}</option>))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Nội dung hợp đồng <span className="text-red-500">*</span></label>
                <textarea
                  value={noiDung}
                  onChange={(e) => setNoiDung(e.target.value)}
                  placeholder="Mô tả nội dung hợp đồng..."
                  className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 min-h-[80px]"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú</label>
                <textarea
                  value={ghiChu}
                  onChange={(e) => setGhiChu(e.target.value)}
                  placeholder="Ghi chú thêm..."
                  className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 min-h-[60px]"
                />
              </div>
            </>
          )}

          {step === 2 && (
            <>
              {/* Upload area */}
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">Tài liệu đính kèm</label>
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full border-2 border-dashed border-slate-300 rounded-lg p-6 flex flex-col items-center justify-center gap-2 hover:border-emerald-400 transition-colors bg-slate-50/50"
                >
                  <span className="w-8 h-8 flex items-center justify-center text-slate-400">
                    <i className="ri-upload-cloud-2-line text-2xl" />
                  </span>
                  <p className="text-sm font-medium text-slate-600">Tải tài liệu lên</p>
                  <p className="text-xs text-slate-400">PDF, JPG, PNG, DOC, XLS, TXT (tối đa 10MB)</p>
                </button>
                <input
                  ref={fileInputRef}
                  type="file"
                  multiple
                  accept=".pdf,.jpg,.jpeg,.png,.doc,.docx,.xls,.xlsx,.txt"
                  onChange={handleFileChange}
                  className="hidden"
                />
              </div>

              {/* Attachment list */}
              {attachments.length > 0 ? (
                <div className="space-y-2">
                  {attachments.map((att) => (
                    <div key={att.id} className="flex items-center gap-3 bg-white border border-slate-200 rounded-lg p-3">
                      <div className="w-10 h-10 rounded-lg bg-slate-50 flex items-center justify-center shrink-0">
                        <span className="w-5 h-5 flex items-center justify-center text-slate-500">
                          <i className={getFileIcon(att.type)} />
                        </span>
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-slate-900 truncate">{att.name}</p>
                        <p className="text-xs text-slate-400">
                          {formatFileSize(att.size)} · {att.type.split('/')[1]?.toUpperCase() || 'FILE'}
                        </p>
                      </div>
                      <div className="flex items-center gap-1 shrink-0">
                        <button
                          type="button"
                          onClick={() => window.open(att.url, '_blank', 'noopener,noreferrer')}
                          className="w-8 h-8 flex items-center justify-center rounded-md text-sky-600 hover:bg-sky-50"
                          title="Xem"
                        >
                          <span className="w-4 h-4 flex items-center justify-center"><i className="ri-eye-line" /></span>
                        </button>
                        <button
                          type="button"
                          onClick={() => removeAttachment(att.id)}
                          className="w-8 h-8 flex items-center justify-center rounded-md text-red-600 hover:bg-red-50"
                          title="Xóa"
                        >
                          <span className="w-4 h-4 flex items-center justify-center"><i className="ri-delete-bin-line" /></span>
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="flex items-center gap-2 text-sm text-amber-600 bg-amber-50 border border-amber-200 rounded-lg p-3">
                  <span className="w-4 h-4 flex items-center justify-center"><i className="ri-error-warning-line" /></span>
                  Chưa có tài liệu đính kèm
                </div>
              )}
            </>
          )}
        </div>

        {/* Footer */}
        <div className="sticky bottom-0 bg-white border-t border-slate-200 px-4 sm:px-6 py-3 flex items-center justify-between gap-3 rounded-b-2xl sm:rounded-b-xl">
          <div>
            {step > 1 && (
              <button
                type="button"
                onClick={() => setStep(step - 1)}
                className="px-4 py-2.5 rounded-md text-sm font-medium text-slate-600 hover:bg-slate-100 transition-colors flex items-center gap-1"
              >
                <span className="w-4 h-4 flex items-center justify-center"><i className="ri-arrow-left-line" /></span>
                Quay lại
              </button>
            )}
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2.5 rounded-md text-sm font-medium text-slate-600 hover:bg-slate-100 transition-colors whitespace-nowrap min-h-[44px]"
            >
              Hủy
            </button>
            {step === 1 ? (
              <button
                type="button"
                onClick={() => setStep(2)}
                className="px-4 py-2.5 rounded-md text-sm font-medium text-white bg-emerald-700 hover:bg-emerald-800 transition-colors whitespace-nowrap min-h-[44px] flex items-center gap-1"
              >
                Tiếp theo
                <span className="w-4 h-4 flex items-center justify-center"><i className="ri-arrow-right-line" /></span>
              </button>
            ) : (
              <button
                type="button"
                onClick={handleSubmit}
                className="px-4 py-2.5 rounded-md text-sm font-medium text-white bg-emerald-700 hover:bg-emerald-800 transition-colors whitespace-nowrap min-h-[44px]"
              >
                {editItem ? 'Lưu thay đổi' : 'Tạo hợp đồng'}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}