import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { showToast } from '@/components/base/Toast';

type Step = 'select_role' | 'fill_form' | 'success';

export default function RegisterPage() {
  const [step, setStep] = useState<Step>('select_role');
  const [role, setRole] = useState<'Nông hộ' | 'Hợp tác xã' | null>(null);
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();
  const navigate = useNavigate();

  // Common fields
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  // Farmer fields
  const [farmerName, setFarmerName] = useState('');
  const [tinhThanh, setTinhThanh] = useState('Đồng Tháp');
  const [huyen, setHuyen] = useState('');
  const [xa, setXa] = useState('');
  const [loaiCay, setLoaiCay] = useState('');
  const [dienTich, setDienTich] = useState('');
  const [farmerBank, setFarmerBank] = useState('');
  const [farmerAccount, setFarmerAccount] = useState('');

  // HTX fields
  const [htxName, setHtxName] = useState('');
  const [htxCode, setHtxCode] = useState('');
  const [nguoiDaiDien, setNguoiDaiDien] = useState('');
  const [chucVu, setChucVu] = useState('');
  const [htxAddress, setHtxAddress] = useState('');
  const [htxBank, setHtxBank] = useState('');
  const [htxAccount, setHtxAccount] = useState('');

  // ─── New state: bank info filled ───
  const [bankFilled, setBankFilled] = useState(false);

  const handleSelectRole = (r: 'Nông hộ' | 'Hợp tác xã') => {
    setRole(r);
    setStep('fill_form');
  };

  const handleBack = () => {
    setStep('select_role');
    setRole(null);
  };

  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newErrors: Record<string, string> = {};

    if (!phone.trim()) {
      newErrors.phone = 'Vui lòng nhập số điện thoại';
    } else if (!/^[0-9]{10}$/.test(phone.trim())) {
      newErrors.phone = 'Số điện thoại phải có đúng 10 chữ số';
    }

    if (!password.trim()) {
      newErrors.password = 'Vui lòng nhập mật khẩu';
    } else if (password.length < 6) {
      newErrors.password = 'Mật khẩu phải có ít nhất 6 ký tự';
    }

    if (!confirmPassword.trim()) {
      newErrors.confirmPassword = 'Vui lòng xác nhận mật khẩu';
    } else if (password !== confirmPassword) {
      newErrors.confirmPassword = 'Mật khẩu xác nhận không khớp';
    }

    if (role === 'Nông hộ') {
      if (!farmerName.trim()) newErrors.farmerName = 'Vui lòng nhập họ tên';
      if (!huyen.trim()) newErrors.huyen = 'Vui lòng nhập huyện';
      if (!xa.trim()) newErrors.xa = 'Vui lòng nhập xã';
    } else {
      if (!htxName.trim()) newErrors.htxName = 'Vui lòng nhập tên HTX';
      if (!nguoiDaiDien.trim()) newErrors.nguoiDaiDien = 'Vui lòng nhập tên người đại diện';
      if (!chucVu.trim()) newErrors.chucVu = 'Vui lòng chọn chức vụ';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      showToast('Vui lòng kiểm tra lại thông tin', 'warning');
      return;
    }

    setErrors({});

    setLoading(true);

    setTimeout(() => {
      const now = Date.now();

      if (role === 'Nông hộ') {
        const dienTichNum = parseFloat(dienTich) || parseFloat((Math.random() * 4 + 1).toFixed(1));
        register({
          username: phone.trim(),
          password: password,
          role: 'Nông hộ',
          displayName: farmerName.trim(),
          code: `NH-DT-${new Date().getFullYear()}-${String(now).slice(-4)}`,
          phone: phone.trim(),
          tinhThanh,
          huyen: huyen.trim(),
          xa: xa.trim(),
          loaiCay: loaiCay.trim(),
          dienTich: dienTichNum,
        });
      } else {
        register({
          username: phone.trim(),
          password: password,
          role: 'Hợp tác xã',
          displayName: htxName.trim(),
          code: htxCode.trim() || `HTX-${String(now).slice(-6)}`,
          phone: phone.trim(),
          address: htxAddress.trim(),
          nguoiDaiDien: nguoiDaiDien.trim(),
          chucVu: chucVu.trim(),
        });
      }

      setBankFilled(!!(role === 'Nông hộ' ? farmerBank.trim() || farmerAccount.trim() : htxBank.trim() || htxAccount.trim()));

      showToast('Đăng ký thành công!', 'success');
      setStep('success');
      setLoading(false);
    }, 600);
  };

  const handleGoToEkyc = () => {
    navigate('/ekyc');
  };

  const handleSkipEkyc = () => {
    if (role === 'Nông hộ') {
      navigate('/nong-ho/tong-quan');
    } else {
      navigate('/htx/tong-quan');
    }
  };

  // ──────────────────────────────────
  // STEP: success — eKYC SUGGESTION
  // ──────────────────────────────────
  if (step === 'success') {
    return (
      <div className="min-h-[100dvh] bg-white flex flex-col max-w-[430px] mx-auto p-4">
        <div className="flex-1 flex flex-col justify-center">
          {/* Success checkmark */}
          <div className="text-center mb-5">
            <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-emerald-50 flex items-center justify-center">
              <span className="w-10 h-10 flex items-center justify-center">
                <i className="ri-check-line text-emerald-500 text-3xl" />
              </span>
            </div>
            <h2 className="text-xl font-extrabold text-gray-900">Đăng ký thành công!</h2>
            <p className="text-sm text-gray-500 mt-1">Tài khoản của bạn đã được tạo.</p>
          </div>

          {/* eKYC suggestion card */}
          <div className="bg-gradient-to-br from-agrida-50 to-emerald-50 rounded-2xl border border-agrida-100 p-5 mb-5">
            <div className="flex items-center gap-3 mb-3">
              <span className="w-12 h-12 rounded-2xl bg-agrida-100 flex items-center justify-center shrink-0">
                <i className="ri-shield-check-line text-agrida-600 text-xl" />
              </span>
              <div>
                <h3 className="text-sm font-bold text-gray-900">Xác thực eKYC</h3>
                <p className="text-[10px] text-agrida-600 font-medium">để sử dụng đầy đủ chức năng tài chính</p>
              </div>
            </div>

            <p className="text-[13px] text-gray-600 leading-relaxed mb-2">
              Bạn có thể bỏ qua bước này. Tuy nhiên, để <strong>vay vốn</strong>, <strong>xin/cấp hạn mức</strong> hoặc <strong>xử lý giải ngân</strong>, tài khoản cần được xác thực eKYC.
            </p>

            <div className="flex items-start gap-2 mt-3 mb-1">
              <span className="w-4 h-4 flex items-center justify-center shrink-0 mt-0.5">
                <i className="ri-information-line text-amber-500 text-xs" />
              </span>
              <p className="text-[11px] text-amber-700">
                Các chức năng như nhật ký, hồ sơ, vật tư vẫn sử dụng bình thường.
              </p>
            </div>
          </div>

          {/* Account summary */}
          <div className="bg-gray-50 rounded-xl p-4 mb-5">
            <p className="text-xs font-semibold text-gray-500 uppercase mb-3">Thông tin tài khoản</p>
            <div className="space-y-2">
              <div className="flex justify-between">
                <span className="text-xs text-gray-500">Loại tài khoản</span>
                <span className="text-xs font-semibold text-gray-800">{role === 'Nông hộ' ? 'Nông hộ' : 'Hợp tác xã'}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-xs text-gray-500">Số điện thoại</span>
                <span className="text-xs font-semibold text-gray-800">{phone}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-xs text-gray-500">Trạng thái eKYC</span>
                <span className="text-xs font-semibold text-amber-600">Chưa xác thực</span>
              </div>
            </div>
          </div>

          {/* CTAs */}
          <button
            type="button"
            onClick={handleGoToEkyc}
            className="w-full bg-agrida-600 hover:bg-agrida-700 text-white font-semibold py-3.5 rounded-xl transition-colors whitespace-nowrap min-h-[48px] text-sm mb-2.5"
          >
            Thực hiện eKYC ngay
          </button>

          <button
            type="button"
            onClick={handleSkipEkyc}
            className="w-full bg-white hover:bg-gray-50 text-gray-600 font-medium py-3.5 rounded-xl border border-gray-200 transition-colors whitespace-nowrap min-h-[48px] text-sm"
          >
            Bỏ qua, thực hiện sau
          </button>

          <p className="text-center text-[11px] text-gray-400 mt-4">
            Bạn có thể thực hiện eKYC bất kỳ lúc nào trong phần <strong>Hồ sơ</strong> hoặc <strong>Dashboard</strong>.
          </p>
        </div>
      </div>
    );
  }

  if (step === 'select_role') {
    return (
      <div className="min-h-[100dvh] bg-white flex flex-col max-w-[430px] mx-auto p-4">
        <div className="flex-1 flex flex-col justify-center">
          <div className="text-center mb-8">
            <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-agrida-100 flex items-center justify-center">
              <span className="w-8 h-8 flex items-center justify-center">
                <i className="ri-user-add-line text-agrida-600 text-2xl" />
              </span>
            </div>
            <h1 className="text-2xl font-extrabold text-gray-900">Tạo tài khoản Agrida</h1>
            <p className="text-sm text-gray-500 mt-1.5">Bạn là ai? Chọn loại tài khoản phù hợp</p>
          </div>

          <div className="space-y-3">
            <button
              type="button"
              onClick={() => handleSelectRole('Nông hộ')}
              className="w-full p-4 rounded-xl border-2 border-gray-100 hover:border-orange-200 hover:bg-orange-50/30 transition-all text-left flex items-start gap-4 group"
            >
              <span className="w-12 h-12 rounded-xl bg-orange-50 flex items-center justify-center shrink-0 group-hover:bg-orange-100 transition-colors">
                <i className="ri-user-line text-orange-600 text-xl" />
              </span>
              <div className="flex-1 min-w-0">
                <h3 className="font-semibold text-gray-900 text-base">Nông hộ</h3>
                <p className="text-xs text-gray-500 mt-0.5">Dành cho hộ nông dân canh tác độc lập, tham gia HTX</p>
                <div className="flex flex-wrap gap-1.5 mt-2">
                  <span className="px-2 py-0.5 bg-orange-50 text-orange-700 text-[11px] rounded-full font-medium">Nhật ký canh tác</span>
                  <span className="px-2 py-0.5 bg-orange-50 text-orange-700 text-[11px] rounded-full font-medium">Vay vốn</span>
                  <span className="px-2 py-0.5 bg-orange-50 text-orange-700 text-[11px] rounded-full font-medium">Vật tư</span>
                </div>
              </div>
              <span className="w-5 h-5 flex items-center justify-center shrink-0 self-center">
                <i className="ri-arrow-right-s-line text-gray-300 text-lg" />
              </span>
            </button>

            <button
              type="button"
              onClick={() => handleSelectRole('Hợp tác xã')}
              className="w-full p-4 rounded-xl border-2 border-gray-100 hover:border-agrida-300 hover:bg-agrida-50/30 transition-all text-left flex items-start gap-4 group"
            >
              <span className="w-12 h-12 rounded-xl bg-agrida-50 flex items-center justify-center shrink-0 group-hover:bg-agrida-100 transition-colors">
                <i className="ri-building-line text-agrida-600 text-xl" />
              </span>
              <div className="flex-1 min-w-0">
                <h3 className="font-semibold text-gray-900 text-base">Hợp tác xã</h3>
                <p className="text-xs text-gray-500 mt-0.5">Dành cho HTX quản lý nông hộ, vật tư, tài chính</p>
                <div className="flex flex-wrap gap-1.5 mt-2">
                  <span className="px-2 py-0.5 bg-agrida-50 text-agrida-700 text-[11px] rounded-full font-medium">Quản lý nông hộ</span>
                  <span className="px-2 py-0.5 bg-agrida-50 text-agrida-700 text-[11px] rounded-full font-medium">Hợp đồng</span>
                  <span className="px-2 py-0.5 bg-agrida-50 text-agrida-700 text-[11px] rounded-full font-medium">Tài chính</span>
                  <span className="px-2 py-0.5 bg-agrida-50 text-agrida-700 text-[11px] rounded-full font-medium">Cung ứng</span>
                </div>
              </div>
              <span className="w-5 h-5 flex items-center justify-center shrink-0 self-center">
                <i className="ri-arrow-right-s-line text-gray-300 text-lg" />
              </span>
            </button>
          </div>

          <p className="text-center text-xs text-gray-400 mt-6">
            Đã có tài khoản?{' '}
            <Link to="/dang-nhap" className="text-agrida-600 font-medium hover:text-agrida-700">
              Đăng nhập
            </Link>
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-[100dvh] bg-white flex flex-col max-w-[430px] mx-auto">
      <div className="flex items-center px-4 h-14 border-b border-gray-100">
        <button
          type="button"
          onClick={handleBack}
          className="w-9 h-9 flex items-center justify-center rounded-lg hover:bg-gray-50 transition-colors"
        >
          <i className="ri-arrow-left-line text-gray-700 text-lg" />
        </button>
        <h2 className="flex-1 text-center font-semibold text-gray-900 text-base mr-9">
          {role === 'Nông hộ' ? 'Đăng ký Nông hộ' : 'Đăng ký HTX'}
        </h2>
      </div>

      <div className="flex-1 px-4 py-5 overflow-y-auto">
        <form onSubmit={handleSubmit} className="space-y-4">
          {role === 'Nông hộ' ? (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Họ tên <span className="text-red-500">*</span></label>
                <input
                  type="text"
                  value={farmerName}
                  onChange={(e) => { setFarmerName(e.target.value); setErrors((prev) => ({ ...prev, farmerName: '' })); }}
                  className={`w-full px-4 py-3 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.farmerName ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                  placeholder="Nhập họ và tên"
                />
                {errors.farmerName && <p className="text-[11px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-xs" />{errors.farmerName}</p>}
              </div>
            </>
          ) : (
            <>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Tên HTX <span className="text-red-500">*</span></label>
                <input
                  type="text"
                  value={htxName}
                  onChange={(e) => { setHtxName(e.target.value); setErrors((prev) => ({ ...prev, htxName: '' })); }}
                  className={`w-full px-4 py-3 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.htxName ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                  placeholder="Nhập tên hợp tác xã"
                />
                {errors.htxName && <p className="text-[11px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-xs" />{errors.htxName}</p>}
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Mã HTX</label>
                <input
                  type="text"
                  value={htxCode}
                  onChange={(e) => setHtxCode(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                  placeholder="Mã HTX (tự động nếu để trống)"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Người đại diện <span className="text-red-500">*</span></label>
                <input
                  type="text"
                  value={nguoiDaiDien}
                  onChange={(e) => { setNguoiDaiDien(e.target.value); setErrors((prev) => ({ ...prev, nguoiDaiDien: '' })); }}
                  className={`w-full px-4 py-3 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.nguoiDaiDien ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                  placeholder="Nhập tên người đại diện HTX"
                />
                {errors.nguoiDaiDien && <p className="text-[11px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-xs" />{errors.nguoiDaiDien}</p>}
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Chức vụ <span className="text-red-500">*</span></label>
                <select
                  value={chucVu}
                  onChange={(e) => { setChucVu(e.target.value); setErrors((prev) => ({ ...prev, chucVu: '' })); }}
                  className={`w-full px-4 py-3 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.chucVu ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                >
                  <option value="">Chọn chức vụ</option>
                  <option value="Giám đốc HTX">Giám đốc HTX</option>
                  <option value="Chủ tịch HĐQT">Chủ tịch HĐQT</option>
                  <option value="Phó Giám đốc">Phó Giám đốc</option>
                  <option value="Kế toán trưởng">Kế toán trưởng</option>
                  <option value="Trưởng ban Kiểm soát">Trưởng ban Kiểm soát</option>
                </select>
                {errors.chucVu && <p className="text-[11px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-xs" />{errors.chucVu}</p>}
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Địa chỉ HTX</label>
                <input
                  type="text"
                  value={htxAddress}
                  onChange={(e) => setHtxAddress(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                  placeholder="Nhập địa chỉ HTX"
                />
              </div>
            </>
          )}

          {role === 'Nông hộ' && (
            <>
              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Tỉnh</label>
                  <input
                    type="text"
                    value={tinhThanh}
                    onChange={(e) => setTinhThanh(e.target.value)}
                    className="w-full px-3 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Huyện <span className="text-red-500">*</span></label>
                  <input
                    type="text"
                    value={huyen}
                    onChange={(e) => { setHuyen(e.target.value); setErrors((prev) => ({ ...prev, huyen: '' })); }}
                    className={`w-full px-3 py-3 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.huyen ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                    placeholder="Huyện"
                  />
                  {errors.huyen && <p className="text-[10px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-[10px]" />{errors.huyen}</p>}
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Xã <span className="text-red-500">*</span></label>
                  <input
                    type="text"
                    value={xa}
                    onChange={(e) => { setXa(e.target.value); setErrors((prev) => ({ ...prev, xa: '' })); }}
                    className={`w-full px-3 py-3 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.xa ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                    placeholder="Xã"
                  />
                  {errors.xa && <p className="text-[10px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-[10px]" />{errors.xa}</p>}
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Cây trồng chính</label>
                <input
                  type="text"
                  value={loaiCay}
                  onChange={(e) => setLoaiCay(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                  placeholder="Ví dụ: Lúa, Cà phê, Sầu riêng..."
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Diện tích canh tác (ha)</label>
                <input
                  type="number"
                  step="0.1"
                  min="0.1"
                  value={dienTich}
                  onChange={(e) => setDienTich(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                  placeholder="Ví dụ: 2.5 (tự động ước tính nếu để trống)"
                />
              </div>
            </>
          )}

          {/* Payout and certification information */}
          <div className="border-t border-gray-100 pt-4">
            <p className="text-xs font-medium text-gray-500 mb-3 uppercase tracking-wide">Thông tin nhận tiền và xác thực</p>
            {role === 'Nông hộ' ? (
              <div className="space-y-3">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Kênh nhận tiền</label>
                  <input
                    type="text"
                    value={farmerBank}
                    onChange={(e) => setFarmerBank(e.target.value)}
                    className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                    placeholder="VD: Ví Agrida hoặc tài khoản thanh toán"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Số tài khoản</label>
                  <input
                    type="text"
                    value={farmerAccount}
                    onChange={(e) => setFarmerAccount(e.target.value)}
                    className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                    placeholder="VD: 3306123456789 (tự động nếu để trống)"
                  />
                </div>
              </div>
            ) : (
              <div className="space-y-3">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Đơn vị chứng nhận liên kết</label>
                  <input
                    type="text"
                    value={htxBank}
                    onChange={(e) => setHtxBank(e.target.value)}
                    className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                    placeholder="Ngân hàng chứng nhận tuân thủ (không cấp vốn)"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Số tài khoản HTX</label>
                  <input
                    type="text"
                    value={htxAccount}
                    onChange={(e) => setHtxAccount(e.target.value)}
                    className="w-full px-4 py-3 rounded-xl border border-gray-200 text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all"
                    placeholder="VD: 0071123456789 (tự động nếu để trống)"
                  />
                </div>
              </div>
            )}
          </div>

          {/* Login credentials section */}
          <div className="border-t border-gray-100 pt-4">
            <p className="text-xs font-medium text-gray-500 mb-3 uppercase tracking-wide">Thông tin đăng nhập</p>
            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Số điện thoại <span className="text-red-500">*</span></label>
                <input
                  type="tel"
                  value={phone}
                  onChange={(e) => { setPhone(e.target.value.replace(/\D/g, '').slice(0, 10)); setErrors((prev) => ({ ...prev, phone: '' })); }}
                  className={`w-full px-4 py-3 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.phone ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                  placeholder="Số điện thoại dùng để đăng nhập"
                  maxLength={10}
                />
                {errors.phone && <p className="text-[11px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-xs" />{errors.phone}</p>}
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Mật khẩu <span className="text-red-500">*</span></label>
                <div className="relative">
                  <input type={showPassword ? 'text' : 'password'} value={password} onChange={(e) => { setPassword(e.target.value); setErrors((prev) => ({ ...prev, password: '' })); }} className={`w-full px-4 py-3 pr-12 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.password ? 'border-red-300 bg-red-50' : 'border-gray-200'}`} placeholder="Tối thiểu 6 ký tự" />
                  <button type="button" onClick={() => setShowPassword((value) => !value)} className="absolute right-1 top-1/2 flex h-10 w-10 -translate-y-1/2 items-center justify-center text-gray-400" aria-label={showPassword ? 'Ẩn mật khẩu' : 'Hiện mật khẩu'}><i className={showPassword ? 'ri-eye-off-line' : 'ri-eye-line'} /></button>
                </div>
                {errors.password && <p className="text-[11px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-xs" />{errors.password}</p>}
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Xác nhận mật khẩu <span className="text-red-500">*</span></label>
                <div className="relative">
                  <input type={showConfirmPassword ? 'text' : 'password'} value={confirmPassword} onChange={(e) => { setConfirmPassword(e.target.value); setErrors((prev) => ({ ...prev, confirmPassword: '' })); }} className={`w-full px-4 py-3 pr-12 rounded-xl border text-sm bg-gray-50 focus:outline-none focus:ring-2 focus:ring-agrida-500 focus:border-transparent focus:bg-white transition-all ${errors.confirmPassword ? 'border-red-300 bg-red-50' : 'border-gray-200'}`} placeholder="Nhập lại mật khẩu" />
                  <button type="button" onClick={() => setShowConfirmPassword((value) => !value)} className="absolute right-1 top-1/2 flex h-10 w-10 -translate-y-1/2 items-center justify-center text-gray-400" aria-label={showConfirmPassword ? 'Ẩn mật khẩu xác nhận' : 'Hiện mật khẩu xác nhận'}><i className={showConfirmPassword ? 'ri-eye-off-line' : 'ri-eye-line'} /></button>
                </div>
                {errors.confirmPassword && <p className="text-[11px] text-red-500 mt-1 flex items-center gap-1"><i className="ri-error-warning-line text-xs" />{errors.confirmPassword}</p>}
              </div>
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-agrida-600 hover:bg-agrida-700 text-white font-semibold py-3.5 rounded-xl transition-colors disabled:opacity-60 whitespace-nowrap min-h-[48px] text-sm mt-2"
          >
            {loading ? 'Đang tạo tài khoản...' : 'Tạo tài khoản'}
          </button>
        </form>
      </div>
    </div>
  );
}
