import { useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { MobileMetricCard } from '@/components/base/MobileUi';
import { formatCurrencyCompact } from '@/utils/formatters';

export interface ExceptionApprovalData {
  farmerName: string;
  farmerId: string;
  creditScore: number | undefined;
  loanId: string;
  loanAmount: number;
  loanPurpose: string;
  totalDebt: number;
  overdueDebt: number;
  overdueCount: number;
  remainingLimit: number;
  hasOverdue: boolean;
  ekycVerified: boolean;
  activeContracts: number;
  seasonName?: string;
  fieldActivity?: string;
  riskLevel?: string;
  lockAmount?: number;
}

interface ExceptionApprovalModalProps {
  open: boolean;
  data: ExceptionApprovalData | null;
  onClose: () => void;
  onConfirm: (reason: string) => void;
}

export function ExceptionApprovalModal({ open, data, onClose, onConfirm }: ExceptionApprovalModalProps) {
  const [reason, setReason] = useState('');
  const [checked, setChecked] = useState(false);
  const close = () => { setReason(''); setChecked(false); onClose(); };
  const confirm = () => { if (!reason.trim() || !checked) return; onConfirm(reason.trim()); setReason(''); setChecked(false); };

  return (
    <BottomSheet
      open={open && !!data}
      onClose={close}
      title="Phê duyệt ngoại lệ"
      footer={<div className="mobile-action-row"><button type="button" onClick={close} className="rounded-xl bg-slate-100 px-4 py-3 text-sm font-semibold text-slate-700">Không duyệt</button><button type="button" onClick={confirm} disabled={!reason.trim() || !checked} className="rounded-xl bg-rose-600 px-4 py-3 text-sm font-semibold text-white disabled:bg-slate-300">Xác nhận ngoại lệ</button></div>}
    >
      {data && (
        <div className="space-y-4">
          <div className="rounded-2xl bg-slate-50 p-3.5">
            <div className="flex items-start justify-between gap-3"><div className="min-w-0"><h4 className="truncate text-sm font-bold text-slate-900">{data.farmerName}</h4><p className="metric-caption mt-0.5 truncate text-[10px] text-slate-400">{data.loanId.toUpperCase()} · {data.loanPurpose}</p></div><strong className="shrink-0 text-lg text-emerald-700">{formatCurrencyCompact(data.loanAmount)}</strong></div>
          </div>

          <div className="grid grid-cols-2 gap-2">
            <MobileMetricCard label="Điểm tín dụng" value={data.creditScore || '--'} caption={data.riskLevel || 'Chưa đánh giá'} tone={(data.creditScore || 0) < 550 ? 'rose' : 'amber'} icon="ri-line-chart-line" />
            <MobileMetricCard label="Hạn mức còn" value={formatCurrencyCompact(Math.max(0, data.remainingLimit))} caption="Trước khi duyệt" tone="emerald" icon="ri-wallet-3-line" />
            <MobileMetricCard label="Dư nợ hiện tại" value={formatCurrencyCompact(data.totalDebt)} caption={`${data.activeContracts} hợp đồng hiệu lực`} tone="slate" icon="ri-money-cny-circle-line" />
            <MobileMetricCard label="Nợ quá hạn" value={formatCurrencyCompact(data.overdueDebt)} caption={`${data.overdueCount} khoản`} tone={data.hasOverdue ? 'rose' : 'slate'} icon="ri-timer-flash-line" />
          </div>

          <label className="block"><span className="mb-1.5 block text-xs font-semibold text-slate-600">Lý do phê duyệt</span><textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={3} maxLength={500} placeholder="Nhập căn cứ phê duyệt ngắn gọn" className="w-full resize-none rounded-xl border border-slate-200 px-3 py-2.5 text-sm outline-none focus:border-emerald-500" /><span className="metric-caption mt-1 block text-right text-[10px] text-slate-400">{reason.length}/500</span></label>
          <label className="flex cursor-pointer items-start gap-2.5 rounded-xl bg-slate-50 p-3"><input type="checkbox" checked={checked} onChange={(event) => setChecked(event.target.checked)} className="mt-0.5 h-4 w-4 shrink-0 rounded border-slate-300 text-emerald-600" /><span className="text-xs leading-relaxed text-slate-600">Tôi đã kiểm tra hồ sơ và chịu trách nhiệm với quyết định phê duyệt ngoại lệ.</span></label>
        </div>
      )}
    </BottomSheet>
  );
}
