import { useMemo } from 'react';
import type { Farmer } from '../../../../types';
import { getFieldsByFarmer, getSeasonsByFarmer, getHarvestsByFarmer, getLogsByFarmer } from '../../../../store';
import { StatusBadge } from '../../../../components/base/StatusBadge';
import { EmptyState } from '../../../../components/base/EmptyState';
import { formatDate, formatNumber } from '../../../../utils/format';
import { useStore } from '../../../../hooks/useStore';

interface DetailProductionTabProps {
  farmer: Farmer;
}

const WARNING_KEYWORDS = ['sâu bệnh', 'thiếu phân', 'khô hạn', 'vàng lá', 'giảm năng suất'];

export default function DetailProductionTab({ farmer }: DetailProductionTabProps) {
  useStore();
  const fields = getFieldsByFarmer(farmer.id);
  const seasons = getSeasonsByFarmer(farmer.id);
  const harvests = getHarvestsByFarmer(farmer.id).filter((h) => !h.isDeleted);
  const diaries = getLogsByFarmer(farmer.id).filter((d) => !d.isDeleted);
  const totalArea = fields.reduce((s, f) => s + f.area, 0);

  const activeSeasons = seasons.filter((s) => s.status === 'Đang canh tác' || s.status === 'Sắp thu hoạch' || s.status === 'Chuẩn bị');
  const recentHarvests = useMemo(() => harvests.filter((h) => h.status !== 'Dự kiến').slice(0, 3), [harvests]);
  const recentDiaries = useMemo(() => diaries.slice(0, 5), [diaries]);

  const warningDiaries = diaries.filter((d) => {
    const txt = (d.hoatDong || '') + ' ' + (d.chiTiet || '');
    return WARNING_KEYWORDS.some((k) => txt.toLowerCase().includes(k));
  });

  const getFieldName = (id?: string) => fields.find((f) => f.id === id)?.name || '-';
  const getSeasonName = (id?: string) => seasons.find((s) => s.id === id)?.name || '-';

  return (
    <div className="space-y-5">
      {/* ── Fields summary ── */}
      <div>
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-base font-semibold text-slate-900">Thửa đất ({fields.length})</h3>
          <span className="text-xs text-slate-500">Tổng: {totalArea.toFixed(1)} ha</span>
        </div>
        {fields.length === 0 ? (
          <EmptyState icon="ri-map-pin-line" title="Chưa có thửa đất" description="Nông hộ chưa khai báo thửa đất nào." />
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {fields.map((fi) => (
              <div key={fi.id} className="bg-white rounded-xl border border-slate-200 p-3">
                <div className="flex items-center gap-2 flex-wrap mb-1">
                  <p className="text-sm font-semibold text-slate-900">{fi.name}</p>
                  <StatusBadge status={fi.status} size="sm" />
                </div>
                <p className="text-xs text-slate-500">Mã: {fi.maThuaDat} · {fi.area} ha · {fi.loaiDat}</p>
                <p className="text-xs text-slate-400 mt-0.5">{fi.location}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ── Active seasons ── */}
      <div>
        <h3 className="text-base font-semibold text-slate-900 mb-3">Mùa vụ đang quản lý ({activeSeasons.length})</h3>
        {activeSeasons.length === 0 ? (
          <EmptyState icon="ri-calendar-line" title="Chưa có mùa vụ" description="Nông hộ chưa tạo mùa vụ nào." />
        ) : (
          <div className="space-y-3">
            {activeSeasons.map((s) => {
              const field = fields.find((f) => f.id === s.fieldId);
              return (
                <div key={s.id} className="bg-white rounded-xl border border-slate-200 p-3 md:p-4">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <p className="text-sm font-semibold text-slate-900">{s.name}</p>
                    <StatusBadge status={s.status} size="sm" />
                  </div>
                  <p className="text-xs text-slate-500">Mã: {s.maMuaVu} · {s.cayTrong} ({s.variety}) · {field?.name || '-'}</p>
                  <div className="flex flex-wrap gap-x-4 gap-y-1 mt-1.5 text-xs text-slate-600">
                    <span>{formatDate(s.startDate)}{s.endDate ? ` - ${formatDate(s.endDate)}` : ''}</span>
                    <span>Sản lượng dự kiến: {s.expectedYield} {s.unit}</span>
                    {s.dinhMucVatTu && <span>Định mức: {s.dinhMucVatTu}</span>}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* ── Production warnings ── */}
      {warningDiaries.length > 0 && (
        <div className="bg-amber-50 rounded-xl border border-amber-100 p-4">
          <h3 className="text-sm font-semibold text-amber-800 mb-2 flex items-center gap-1.5">
            <span className="w-4 h-4 flex items-center justify-center"><i className="ri-alert-line" /></span>
            Cảnh báo sản xuất ({warningDiaries.length})
          </h3>
          <div className="space-y-1.5">
            {warningDiaries.slice(0, 3).map((d) => (
              <p key={d.id} className="text-xs text-amber-700">
                <span className="font-medium">{formatDate(d.ngay)}</span> — {d.hoatDong}: {d.chiTiet.length > 80 ? d.chiTiet.slice(0, 80) + '...' : d.chiTiet}
              </p>
            ))}
          </div>
        </div>
      )}

      {/* ── Recent harvest ── */}
      {recentHarvests.length > 0 && (
        <div>
          <h3 className="text-base font-semibold text-slate-900 mb-3">Thu hoạch gần nhất</h3>
          <div className="space-y-3">
            {recentHarvests.map((h) => {
              const seasonExpected = (() => { const s = seasons.find((se) => se.id === h.seasonId); return s ? s.expectedYield * 1000 : 0; })();
              const actual = h.actualYieldConfirmed || h.actualYield || 0;
              const chenh = actual - seasonExpected;

              return (
                <div key={h.id} className="bg-white rounded-xl border border-slate-200 p-3 md:p-4">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <p className="text-sm font-semibold text-slate-900">{h.maLanThuHoach}</p>
                    <StatusBadge status={h.status} size="sm" />
                    {h.canhBao && <span className="inline-flex items-center px-2 py-0.5 rounded-md text-xs font-medium bg-red-50 text-red-700 border border-red-200">{h.canhBao}</span>}
                  </div>
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-x-3 gap-y-1 text-xs">
                    <div><span className="text-slate-400">Ngày thu:</span> <span className="font-medium text-slate-700">{h.ngayThuHoach ? formatDate(h.ngayThuHoach) : '—'}</span></div>
                    <div><span className="text-slate-400">Sản lượng:</span> <span className="font-medium text-slate-700">{formatNumber(actual)} {h.donVi}</span></div>
                    <div><span className="text-slate-400">Chênh lệch:</span> <span className={`font-medium ${chenh >= 0 ? 'text-emerald-700' : 'text-red-600'}`}>{seasonExpected > 0 ? `${chenh >= 0 ? '+' : ''}${formatNumber(chenh)} ${h.donVi}` : '—'}</span></div>
                    <div><span className="text-slate-400">Chất lượng:</span> <span className="font-medium text-slate-700">{h.chatLuong || '—'}</span></div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* ── Recent diaries ── */}
      <div>
        <h3 className="text-base font-semibold text-slate-900 mb-3">Nhật ký gần đây</h3>
        {recentDiaries.length === 0 ? (
          <EmptyState icon="ri-book-open-line" title="Chưa có nhật ký" description="Nông hộ chưa ghi nhật ký nào." />
        ) : (
          <div className="space-y-2">
            {recentDiaries.map((d) => (
              <div key={d.id} className="bg-white rounded-xl border border-slate-200 p-3">
                <div className="flex items-center gap-2 flex-wrap mb-0.5">
                  <p className="text-xs font-semibold text-slate-900">{formatDate(d.ngay)}</p>
                  <span className="text-xs text-slate-400">{getFieldName(d.fieldId)}</span>
                </div>
                <p className="text-sm text-slate-700">{d.hoatDong}</p>
                <p className="text-xs text-slate-500 mt-0.5 line-clamp-2">{d.chiTiet}</p>
                {d.ghiChuHTX && <span className="inline-flex items-center px-1.5 py-0.5 rounded-full text-xs font-medium bg-emerald-100 text-emerald-700 mt-1">Ghi chú HTX</span>}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}