import { useState, useMemo, useEffect } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { useStore } from '@/hooks/useStore';
import { useNavigate } from 'react-router-dom';
import {
  getLoansByFarmer, getSeasonsByFarmer, getDebtsByFarmer, getLimitsByFarmer,
  getContractsByFarmer, getFarmerKyc, getFarmerById, getFarmerStk,
  getLimitRequests,
  addLoan, deleteLoan, updateDebt,
  createPaymentIntent, getActivePaymentIntentByDebt,
} from '@/store';
import { EmptyState } from '@/components/base/EmptyState';
import { showToast } from '@/components/base/Toast';
import { confirmModal } from '@/components/base/ConfirmModal';
import { formatCompactCurrency } from '@/utils/format';
import { calculateLoanInterest } from '@/utils/financeCalculations';
import { LoanFilters } from './components/LoanFilters';
import { LoanCard } from './components/LoanCard';
import { LoanDetailModal } from './components/LoanDetailModal';
import { LoanFormModal } from './components/LoanFormModal';
import { ApplyLimitSheet } from '@/pages/farmer/info/components/ApplyLimitSheet';
import type { AdvanceRequest, Debt } from '@/types';
import { getFarmerMoneySummary, getAvailableFarmerLimit } from '@/utils/financeCalculations';
import { runDebtReminderScheduler } from '@/utils/debtReminderScheduler';

export default function FarmerLoanPage() {
  useStore();
  const { user } = useAuth();
  const navigate = useNavigate();
  const farmerId = user?.farmerId || 'f1';

  const farmer = getFarmerById(farmerId);
  const kyc = farmer ? getFarmerKyc(farmer) : null;
  const isKycVerified = kyc?.kycStatus === 'ekyc_verified';

  const allLoans = getLoansByFarmer(farmerId);
  const seasons = getSeasonsByFarmer(farmerId);
  const debts = getDebtsByFarmer(farmerId);
  const limits = getLimitsByFarmer(farmerId);
  const contracts = getContractsByFarmer(farmerId);
  const limitRequests = getLimitRequests()
    .filter((request) => request.farmerId === farmerId)
    .sort((a, b) => b.ngayYeuCau.localeCompare(a.ngayYeuCau));
  const stk = farmerId ? getFarmerStk(farmerId) : undefined;

  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterLoai, setFilterLoai] = useState('');
  const [formOpen, setFormOpen] = useState(false);
  const [limitOpen, setLimitOpen] = useState(false);
  const [detailItem, setDetailItem] = useState<AdvanceRequest | null>(null);
  const [qrModalOpen, setQrModalOpen] = useState(false);
  const [qrDebt, setQrDebt] = useState<Debt | null>(null);

  // Run reminder scheduler on mount
  useEffect(() => {
    runDebtReminderScheduler();
  }, []);

  const moneySummary = useMemo(() => getFarmerMoneySummary(farmerId), [farmerId]);
  const hanMucTong = moneySummary.hanMucTienTong;
  const daSuDung = moneySummary.hanMucTienDaDung;
  const conLai = moneySummary.hanMucTienKhaDung;
  const duNo = moneySummary.duNo;

  const sapDenHan = debts.filter((d) => d.status === 'Sắp đến hạn' || d.status === 'Đến hạn');
  const quaHan = debts.filter((d) => d.status === 'Quá hạn');
  const hasOverdue = quaHan.length > 0;

  const moneyLoansOnly = allLoans.filter((l) => l.loai === 'Tiền');
  const materialLoansOnly = allLoans.filter((l) => l.loai === 'Vật tư');
  const matChoKiemTra = materialLoansOnly.filter((l) => l.status === 'Chờ kiểm tra').length;
  const matDaDuyet = materialLoansOnly.filter((l) => l.status === 'Đã duyệt' || l.status === 'Chờ nhập kho').length;
  const matDaCap = materialLoansOnly.filter((l) => l.status === 'Đã cấp vật tư').length;
  const matChoNhapKho = materialLoansOnly.filter((l) => l.status === 'Chờ nhập kho').length;

  const isMaterialFilter = filterLoai === 'Vật tư';

  const statusCounts = useMemo(() => {
    const counts: Record<string, number> = { '': allLoans.length };
    allLoans.forEach((loan) => {
      counts[loan.status] = (counts[loan.status] || 0) + 1;
    });
    return counts;
  }, [allLoans]);

  const typeCounts = useMemo(() => ({
    '': allLoans.length,
    'Tiền': moneyLoansOnly.length,
    'Vật tư': materialLoansOnly.length,
  }), [allLoans.length, materialLoansOnly.length, moneyLoansOnly.length]);

  const filteredLoans = useMemo(() => {
    let list = [...allLoans];
    if (filterStatus) list = list.filter((l) => l.status === filterStatus);
    if (filterLoai) list = list.filter((l) => l.loai === filterLoai);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter((l) =>
        l.id.toLowerCase().includes(q) ||
        l.mucDich.toLowerCase().includes(q) ||
        (l.tenVatTu || '').toLowerCase().includes(q)
      );
    }
    return list.sort((a, b) => (b.ngayYeuCau > a.ngayYeuCau ? 1 : -1));
  }, [allLoans, filterStatus, filterLoai, search]);

  const handleCreate = (data: {
    loai: 'Tiền' | 'Vật tư';
    seasonId: string;
    soTien: number;
    mucDich: string;
    tenVatTu?: string;
    soLuongVatTu?: number;
    donViVatTu?: string;
    nhomVatTu?: string;
    thoiGianMongMuon?: string;
    ghiChu?: string;
    hinhAnh?: string;
    isOverLimit: boolean;
    ngayYeuCau: string;
    contractId?: string;
  }) => {
    if (!isKycVerified) {
      showToast('Bạn cần xác thực eKYC trước khi gửi yêu cầu vay', 'warning');
      return;
    }
    const availableLimit = getAvailableFarmerLimit(farmerId);
    if (data.loai === 'Tiền' && data.soTien > availableLimit) {
      showToast(`Hạn mức khả dụng còn ${formatCompactCurrency(availableLimit)}, không đủ ${formatCompactCurrency(data.soTien)}`, 'warning');
      return;
    }
    const linkedContract = data.contractId ? contracts.find((contract) => contract.id === data.contractId) : undefined;
    const loanNote = [
      data.ghiChu,
      data.loai === 'Tiền' ? `Xét duyệt theo mùa vụ${linkedContract ? `; hợp đồng nền: ${linkedContract.soHopDong}` : ''}` : undefined,
    ].filter(Boolean).join(' | ');

    addLoan({
      farmerId,
      seasonId: data.seasonId || undefined,
      loai: data.loai,
      soTien: data.soTien,
      mucDich: data.mucDich,
      tenVatTu: data.tenVatTu,
      soLuongVatTu: data.soLuongVatTu,
      donViVatTu: data.donViVatTu,
      nhomVatTu: data.nhomVatTu,
      thoiGianMongMuon: data.thoiGianMongMuon,
      ghiChu: loanNote || undefined,
      hinhAnh: data.hinhAnh,
      isOverLimit: data.isOverLimit,
      ngayYeuCau: data.ngayYeuCau,
      status: 'Chờ kiểm tra',
    });
    showToast('Đã gửi yêu cầu vay đến HTX', 'success');
    setFormOpen(false);
  };

  const handleDelete = async (item: AdvanceRequest) => {
    if (item.status !== 'Chờ kiểm tra') {
      showToast('Chỉ có thể xóa yêu cầu đang chờ HTX kiểm tra', 'warning');
      return;
    }
    const ok = await confirmModal({
      title: 'Xóa yêu cầu vay',
      message: `Bạn có chắc muốn xóa yêu cầu ${item.id} không?`,
      variant: 'danger',
      confirmText: 'Xóa',
    });
    if (ok) {
      deleteLoan(item.id);
      showToast('Đã xóa yêu cầu vay', 'success');
    }
  };

  // QR payment: mark debt as paid if the user confirms
  const handleOpenQr = (debt: Debt) => {
    setQrDebt(debt);
    setQrModalOpen(true);
  };

  const handleConfirmPayment = () => {
    if (!qrDebt) return;
    const now = new Date().toISOString();
    const lai = calculateLoanInterest(qrDebt);
    const tongPhaiTra = Math.max(1, qrDebt.soTien + lai - qrDebt.daTra);
    const noiDungCK = `AGRIDA PAY ${qrDebt.maKhoanVay || qrDebt.id} ${qrDebt.farmerId.toUpperCase()}`;

    // Create PaymentIntent instead of directly settling
    createPaymentIntent({
      debtId: qrDebt.id,
      farmerId: qrDebt.farmerId,
      loanId: qrDebt.advanceRequestId,
      maKhoanVay: qrDebt.maKhoanVay,
      soTien: tongPhaiTra,
      noiDungChuyenKhoan: noiDungCK,
      nguoiTra: farmer?.name || qrDebt.farmerId,
      status: 'waiting_htx_confirmation',
      qrCreatedAt: now,
      farmerConfirmedAt: now,
      bankCreditMatch: true,
    });

    // Update debt to 'Chờ thanh toán' — matching CongNoTab flow
    updateDebt(qrDebt.id, {
      status: 'Chờ thanh toán',
      phuongThucTra: 'QR Code',
    });

    showToast('Đã gửi xác nhận thanh toán trực tiếp cho HTX.', 'success');
    setQrModalOpen(false);
    setQrDebt(null);
  };

  const activeDebts = debts.filter((d) =>
    d.status !== 'Đã tất toán' && d.status !== 'Thu nợ lỗi'
  );

  // Helper: get display status considering PI
  const getDebtDisplayStatus = (debt: Debt): { label: string; className: string } => {
    const pi = getActivePaymentIntentByDebt(debt.id);
    if (pi) {
      if (pi.status === 'farmer_confirmed_transfer' || pi.status === 'waiting_bank_credit') {
        return { label: 'Trạng thái cũ', className: 'bg-amber-50 text-amber-700' };
      }
      if (pi.status === 'bank_credit_received' || pi.status === 'reconciled' || pi.status === 'waiting_htx_confirmation') {
        return { label: 'Chờ HTX xác nhận', className: 'bg-sky-50 text-sky-700' };
      }
      if (pi.status === 'settled') {
        return { label: 'Đã tất toán', className: 'bg-emerald-50 text-emerald-700' };
      }
      if (pi.status === 'reconcile_failed') {
        return { label: 'Đối soát lỗi', className: 'bg-red-50 text-red-700' };
      }
      if (pi.status === 'qr_created') {
        return { label: 'Chờ xác nhận CK', className: 'bg-orange-50 text-orange-700' };
      }
    }
    const map: Record<string, { label: string; className: string }> = {
      'Đang vay': { label: 'Đang vay', className: 'bg-slate-100 text-slate-600' },
      'Sắp đến hạn': { label: 'Sắp đến hạn', className: 'bg-amber-50 text-amber-700' },
      'Đến hạn': { label: 'Đến hạn', className: 'bg-orange-50 text-orange-700' },
      'Quá hạn': { label: 'Quá hạn', className: 'bg-red-50 text-red-700' },
      'Chờ thanh toán': { label: 'Chờ HTX xác nhận', className: 'bg-amber-50 text-amber-700' },
      'Chờ xử lý lỗi thanh toán': { label: 'Lỗi thanh toán', className: 'bg-orange-50 text-orange-700' },
      'Đã tất toán': { label: 'Đã tất toán', className: 'bg-emerald-50 text-emerald-700' },
    };
    return map[debt.status] || { label: debt.status, className: 'bg-slate-100 text-slate-600' };
  };

  const conPhaiTra = (debt: Debt): number => Math.max(0, debt.soTien + calculateLoanInterest(debt) - debt.daTra);

  return (
    <div className="pb-4 max-w-[800px] mx-auto">
      {/* Credit Limit Section */}
      <div className="mx-4 mt-4 space-y-3">
        <div className="flex items-center justify-between">
          <h2 className="text-base font-bold text-slate-900">Vay vốn</h2>
          {!isKycVerified && (
            <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full bg-amber-50 border border-amber-200 text-[10px] font-medium text-amber-700">
              <span className="w-3 h-3 flex items-center justify-center"><i className="ri-shield-user-line text-[10px]" /></span>
              Chưa eKYC
            </span>
          )}
        </div>

        {/* Hạn mức tiền cards — chỉ hiện khi KHÔNG lọc Vật tư */}
        {!isMaterialFilter && (
          <>
            <div className="grid grid-cols-3 gap-2">
              <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
                <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Hạn mức tiền</p>
                <p className="text-sm font-bold text-slate-800">{formatCompactCurrency(hanMucTong)}</p>
              </div>
              <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
                <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Đã dùng</p>
                <p className="text-sm font-bold text-amber-600">{formatCompactCurrency(daSuDung)}</p>
              </div>
              <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
                <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Còn lại</p>
                <p className={`text-sm font-bold ${conLai > 0 ? 'text-emerald-600' : 'text-red-600'}`}>
                  {formatCompactCurrency(conLai)}
                </p>
              </div>
            </div>

            {/* Dư nợ + Sắp đến hạn */}
            <div className="flex gap-2">
              <div className={`flex-1 rounded-xl border p-3 ${duNo > 0 ? 'bg-amber-50 border-amber-200' : 'bg-white border-slate-200'}`}>
                <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Dư nợ tiền</p>
                <p className={`text-sm font-bold ${duNo > 0 ? 'text-amber-700' : 'text-slate-500'}`}>
                  {formatCompactCurrency(duNo)}
                </p>
              </div>
              {(sapDenHan.length > 0 || quaHan.length > 0) && (
                <div className={`flex-1 rounded-xl border p-3 ${quaHan.length > 0 ? 'bg-red-50 border-red-200' : 'bg-amber-50 border-amber-200'}`}>
                  <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">
                    {quaHan.length > 0 ? 'Quá hạn' : 'Sắp đến hạn'}
                  </p>
                  <p className={`text-sm font-bold ${quaHan.length > 0 ? 'text-red-700' : 'text-amber-700'}`}>
                    {quaHan.length > 0 ? quaHan.length : sapDenHan.length} khoản
                  </p>
                </div>
              )}
            </div>
          </>
        )}

        {/* Vật tư summary — chỉ hiện khi lọc Vật tư */}
        {isMaterialFilter && (
          <div className="grid grid-cols-3 gap-2">
            <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
              <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Yêu cầu VT</p>
              <p className="text-sm font-bold text-slate-800">{materialLoansOnly.length}</p>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
              <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Chờ xử lý</p>
              <p className="text-sm font-bold text-amber-600">{matChoKiemTra + matDaDuyet + matChoNhapKho}</p>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
              <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Đã cấp</p>
              <p className="text-sm font-bold text-emerald-600">{matDaCap}</p>
            </div>
          </div>
        )}

        {/* eKYC warning / overdue warning — chỉ khi không lọc Vật tư */}
        {!isMaterialFilter && (
          <>
            {!isKycVerified && (
              <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 flex items-start gap-2">
                <span className="w-5 h-5 flex items-center justify-center shrink-0 text-amber-600 mt-0.5">
                  <i className="ri-error-warning-line" />
                </span>
                <div>
                  <p className="text-xs font-medium text-amber-800">Chưa xác thực eKYC</p>
                  <p className="text-[10px] text-amber-600 mt-0.5">Bạn cần hoàn tất eKYC trước khi gửi yêu cầu vay vốn.</p>
                </div>
              </div>
            )}

            {hasOverdue && (
              <div className="bg-red-50 border border-red-200 rounded-xl p-3 flex items-start gap-2">
                <span className="w-5 h-5 flex items-center justify-center shrink-0 text-red-600 mt-0.5">
                  <i className="ri-alert-line" />
                </span>
                <div>
                  <p className="text-xs font-medium text-red-800">Có {quaHan.length} khoản nợ quá hạn</p>
                  <p className="text-[10px] text-red-600 mt-0.5">
                    Vui lòng thanh toán khoản quá hạn trước khi tạo yêu cầu vay mới.
                    Tổng nợ quá hạn: {formatCompactCurrency(quaHan.reduce((s, d) => s + d.conNo, 0))}
                  </p>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* Contracts and limit request history */}
      <div className="mx-4 mt-4 space-y-4">
        {contracts.length > 0 && (
          <section>
            <div className="mb-2 flex items-center justify-between">
              <h3 className="text-sm font-semibold text-slate-900">Hợp đồng bao tiêu</h3>
              <span className="text-[10px] text-slate-400">{contracts.length} hợp đồng</span>
            </div>
            <div className="space-y-2">
              {contracts.map((contract) => {
                const linkedSeasons = seasons.filter((season) => contract.seasonIds?.includes(season.id));
                return (
                  <article key={contract.id} className="rounded-xl border border-slate-200 bg-white p-3">
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0">
                        <h4 className="truncate text-sm font-bold text-slate-900">{contract.soHopDong}</h4>
                        <p className="mt-0.5 line-clamp-2 text-[11px] text-slate-500">{contract.noiDung}</p>
                      </div>
                      <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${contract.status === 'Đang hiệu lực' ? 'bg-emerald-100 text-emerald-700' : contract.status === 'Sắp hết hạn' ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-600'}`}>{contract.status}</span>
                    </div>
                    <div className="mt-2 grid grid-cols-3 gap-2">
                      <MiniHistoryMetric label="Giá trị" value={formatCompactCurrency(contract.giaTri)} />
                      <MiniHistoryMetric label="Đã cấp" value={formatCompactCurrency(contract.hanMucDaCap || 0)} tone="amber" />
                      <MiniHistoryMetric label="Mùa vụ" value={String(linkedSeasons.length || contract.seasonIds?.length || 0)} tone="emerald" />
                    </div>
                    {linkedSeasons.length > 0 && (
                      <p className="mt-2 line-clamp-1 text-[10px] text-slate-400">Mùa vụ: {linkedSeasons.map((season) => season.name).join(', ')}</p>
                    )}
                  </article>
                );
              })}
            </div>
          </section>
        )}

        <section>
          <div className="mb-2 flex items-center justify-between">
            <h3 className="text-sm font-semibold text-slate-900">Lịch sử xin cấp hạn mức</h3>
            <span className="text-[10px] text-slate-400">{limitRequests.length} yêu cầu</span>
          </div>
          {limitRequests.length === 0 ? (
            <div className="rounded-xl border border-dashed border-slate-200 py-6 text-center text-xs text-slate-400">Chưa có yêu cầu hạn mức</div>
          ) : (
            <div className="space-y-2">
              {limitRequests.map((request) => (
                <article key={request.id} className="rounded-xl border border-slate-200 bg-white p-3">
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <h4 className="text-sm font-bold text-slate-900">{formatCompactCurrency(request.hanMucDeXuat)}</h4>
                      <p className="mt-0.5 text-[11px] text-slate-500">{request.contractSo || 'Hợp đồng bao tiêu'} · {new Date(request.ngayYeuCau).toLocaleDateString('vi-VN')}</p>
                    </div>
                    <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${request.status === 'Đã duyệt' ? 'bg-emerald-100 text-emerald-700' : request.status === 'Từ chối' ? 'bg-rose-100 text-rose-700' : 'bg-amber-100 text-amber-700'}`}>{request.status}</span>
                  </div>
                  {request.lyDoVuot && <p className="mt-2 line-clamp-2 text-[11px] text-slate-500">{request.lyDoVuot}</p>}
                </article>
              ))}
            </div>
          )}
        </section>
      </div>

      {/* Active debts with QR payment */}
      {activeDebts.length > 0 && (
        <div className="mx-4 mt-4">
          <div className="flex items-center justify-between mb-2">
            <h3 className="text-sm font-semibold text-slate-900">Khoản vay đang trả</h3>
            <span className="text-[10px] text-slate-400">{activeDebts.length} khoản</span>
          </div>
          <div className="space-y-2">
            {activeDebts.map((debt) => {
              const ds = getDebtDisplayStatus(debt);
              const isPendingPI = ds.label === 'Trạng thái cũ' || ds.label === 'Chờ HTX xác nhận' || ds.label === 'Chờ xác nhận CK' || ds.label === 'Đối soát lỗi';
              const remaining = conPhaiTra(debt);
              return (
              <div key={debt.id} className="bg-white rounded-xl border border-slate-200 p-3 flex items-center justify-between">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-semibold text-slate-800">{debt.maKhoanVay || debt.id}</span>
                    <span className={`inline-flex px-1.5 py-0.5 rounded-full text-[9px] font-medium ${ds.className}`}>{ds.label}</span>
                  </div>
                  <p className="text-[10px] text-slate-500 mt-0.5">
                    Còn nợ: <span className="font-semibold text-slate-700">{formatCompactCurrency(debt.conNo)}</span>
                    {' '}· Hạn: {debt.ngayDenHan}
                  </p>
                  <div className="mt-1.5 w-full bg-slate-100 rounded-full h-1.5 overflow-hidden">
                    <div
                      className={`h-full rounded-full transition-all ${debt.daTra / debt.soTien >= 1 ? 'bg-emerald-500' : debt.daTra / debt.soTien >= 0.5 ? 'bg-amber-500' : 'bg-slate-400'}`}
                      style={{ width: `${Math.min(100, (debt.daTra / debt.soTien) * 100)}%` }}
                    />
                  </div>
                </div>
                {!isPendingPI && remaining > 0 && (
                  <button
                    type="button"
                    onClick={() => handleOpenQr(debt)}
                    className="shrink-0 ml-3 px-3 py-2 rounded-lg text-xs font-medium bg-agrida-600 hover:bg-agrida-700 text-white transition-colors whitespace-nowrap min-h-[44px] flex items-center gap-1"
                  >
                    <span className="w-3.5 h-3.5 flex items-center justify-center"><i className="ri-qr-code-line" /></span>
                    Trả ngay
                  </button>
                )}
                {isPendingPI && (
                  <span className="shrink-0 ml-3 px-3 py-2 rounded-lg text-xs font-medium bg-amber-100 text-amber-700 whitespace-nowrap flex items-center gap-1">
                    <span className="w-3.5 h-3.5 flex items-center justify-center"><i className="ri-time-line" /></span>
                    Đang xử lý
                  </span>
                )}
              </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Loan Request List */}
      <div className="mx-4 mt-4">
        <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
          <h3 className="text-sm font-semibold text-slate-900">Yêu cầu vay</h3>
          <div className="flex gap-2">
            <button type="button" onClick={() => navigate('/nong-ho/han-muc')} className="flex min-h-11 items-center gap-1 rounded-xl border border-amber-200 bg-amber-50 px-3 text-xs font-bold text-amber-700 transition hover:bg-amber-100"><i className="ri-scales-3-line" />Hạn mức</button>
            <button type="button" onClick={() => setFormOpen(true)} className="flex min-h-11 items-center gap-1 rounded-xl bg-agrida-600 px-3 text-xs font-bold text-white shadow-lg shadow-emerald-600/15 transition hover:bg-agrida-700 active:scale-[0.98]"><i className="ri-add-line" />Xin vay</button>
          </div>
        </div>

        <div className="mb-3 grid grid-cols-2 gap-2">
          <LoanFilterMetric label="Hạn mức" value={formatCompactCurrency(hanMucTong)} />
          <LoanFilterMetric label="Còn lại" value={formatCompactCurrency(conLai)} tone={conLai > 0 ? 'emerald' : 'rose'} />
          <LoanFilterMetric label="Đã dùng" value={formatCompactCurrency(daSuDung)} tone="amber" />
          <LoanFilterMetric label="Dư nợ" value={formatCompactCurrency(duNo)} tone={duNo > 0 ? 'rose' : 'slate'} />
        </div>

        <LoanFilters
          filterStatus={filterStatus}
          onFilterChange={setFilterStatus}
          search={search}
          onSearchChange={setSearch}
          filterLoai={filterLoai}
          onFilterLoaiChange={setFilterLoai}
          statusCounts={statusCounts}
          typeCounts={typeCounts}
        />

        {filteredLoans.length === 0 ? (
          <EmptyState
            icon="ri-money-cny-circle-line"
            title="Chưa có yêu cầu vay"
            description="Tạo yêu cầu vay vốn hoặc vật tư để HTX xét duyệt."
          />
        ) : (
          <div className="space-y-2 mt-3">
            {filteredLoans.map((loan) => (
              <LoanCard
                key={loan.id}
                loan={loan}
                season={seasons.find((s) => s.id === loan.seasonId)}
                onView={() => setDetailItem(loan)}
                onDelete={loan.status === 'Chờ kiểm tra' ? () => handleDelete(loan) : undefined}
              />
            ))}
          </div>
        )}
      </div>

      {/* Create form modal */}
      {formOpen && (
        <LoanFormModal
          seasons={seasons}
          hanMucConLai={moneySummary.hanMucTienKhaDung}
          isKycVerified={isKycVerified}
          hasOverdue={hasOverdue}
          stk={stk}
          contracts={contracts}
          onSubmit={handleCreate}
          onClose={() => setFormOpen(false)}
        />
      )}

      {farmer && (
        <ApplyLimitSheet
          open={limitOpen}
          onClose={() => setLimitOpen(false)}
          farmerId={farmerId}
          farmerName={farmer.name}
          kyc={kyc}
        />
      )}

      {/* Detail modal */}
      {detailItem && (
        <LoanDetailModal
          loan={detailItem}
          season={seasons.find((s) => s.id === detailItem.seasonId)}
          debt={debts.find((debt) => debt.advanceRequestId === detailItem.id)}
          onPayDebt={handleOpenQr}
          onClose={() => setDetailItem(null)}
        />
      )}

      {/* QR Payment Modal */}
      {qrModalOpen && qrDebt && (
        <div className="fixed inset-0 z-[90] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-black/50 animate-modal-backdrop" onClick={() => { setQrModalOpen(false); setQrDebt(null); }} />
          <div onClick={(e) => e.stopPropagation()} className="relative bg-white rounded-t-2xl sm:rounded-2xl shadow-xl w-full sm:max-w-sm max-h-[90vh] overflow-y-auto animate-modal-slide-up">
            <div className="sticky top-0 bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between z-10">
              <h3 className="text-sm font-bold text-slate-900">QR Thanh toán</h3>
              <button type="button" onClick={() => { setQrModalOpen(false); setQrDebt(null); }} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400">
                <i className="ri-close-line text-lg" />
              </button>
            </div>
            <div className="p-4 space-y-4 text-center">
              <div className="bg-slate-50 rounded-xl p-3">
                <p className="text-xs text-slate-500 mb-1">Mã khoản vay</p>
                <p className="text-sm font-bold text-slate-900">{qrDebt.maKhoanVay || qrDebt.id}</p>
              </div>
              <div className="bg-slate-50 rounded-xl p-3">
                <p className="text-xs text-slate-500 mb-1">Số tiền cần thanh toán (gốc + lãi)</p>
                <p className="text-lg font-bold text-red-600">{formatCompactCurrency(conPhaiTra(qrDebt))}</p>
              </div>
              {/* Mock QR Code */}
              <div className="mx-auto w-48 h-48 bg-white border-2 border-slate-800 rounded-xl flex items-center justify-center relative overflow-hidden">
                <div className="absolute inset-0 grid grid-cols-8 grid-rows-8 gap-0.5 p-4">
                  {Array.from({ length: 64 }).map((_, i) => (
                    <div
                      key={i}
                      className={`rounded-sm ${Math.random() > 0.55 ? 'bg-slate-800' : 'bg-transparent'}`}
                    />
                  ))}
                </div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-10 h-10 bg-white rounded-lg flex items-center justify-center">
                    <span className="w-6 h-6 flex items-center justify-center text-agrida-600"><i className="ri-qr-code-line text-xl" /></span>
                  </div>
                </div>
              </div>
              <p className="text-[10px] text-slate-400">
                QR chứa mã user: {farmerId} · Mã khoản vay: {qrDebt.maKhoanVay || qrDebt.id}
              </p>
              <div className="bg-amber-50 border border-amber-200 rounded-xl p-3">
                <p className="text-[10px] text-amber-700">
                  <strong>Lưu ý:</strong> Vui lòng thanh toán đúng số tiền. Thanh toán thiếu sẽ không được ghi nhận.
                </p>
              </div>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => { setQrModalOpen(false); setQrDebt(null); }}
                  className="flex-1 px-4 py-2.5 rounded-xl text-xs font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
                >
                  Đóng
                </button>
                <button
                  type="button"
                  onClick={handleConfirmPayment}
                  className="flex-1 px-4 py-2.5 rounded-xl text-xs font-bold bg-emerald-600 hover:bg-emerald-700 text-white transition-colors whitespace-nowrap min-h-[44px]"
                >
                  Xác nhận đã thanh toán
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function MiniHistoryMetric({ label, value, tone = 'slate' }: { label: string; value: string; tone?: 'slate' | 'amber' | 'emerald' }) {
  const color = tone === 'amber' ? 'text-amber-700' : tone === 'emerald' ? 'text-emerald-700' : 'text-slate-800';
  return <div className="min-w-0 rounded-lg bg-slate-50 p-2 text-center"><p className="text-[10px] text-slate-400">{label}</p><p className={`mt-0.5 truncate text-xs font-bold ${color}`}>{value}</p></div>;
}

function LoanFilterMetric({ label, value, tone = 'slate' }: { label: string; value: string; tone?: 'slate' | 'emerald' | 'amber' | 'rose' }) {
  const color = tone === 'emerald' ? 'text-emerald-700' : tone === 'amber' ? 'text-amber-700' : tone === 'rose' ? 'text-rose-700' : 'text-slate-800';
  return (
    <div className="min-w-0 rounded-xl border border-slate-200 bg-white px-3 py-2.5">
      <p className="text-[10px] font-medium text-slate-400">{label}</p>
      <p className={`mt-0.5 truncate text-sm font-bold ${color}`}>{value}</p>
    </div>
  );
}
