// ============================================================
// AGRIDA — SHARED LOAN APPROVAL SERVICE
// Single source of truth for ALL loan approval operations.
// Used by the canonical HTX loan approval forms.
// DO NOT duplicate approval logic anywhere else.
// ============================================================

import {
  updateLoan, createLimitLockForLoan, addNotification, addEditHistory,
  getFarmerKyc, getDebtsByFarmer, addLoanApprovalHistory, getActiveLockByLoan,
} from '@/store';
import { showToast } from '@/components/base/Toast';
import { formatCurrencyCompact } from '@/utils/formatters';
import { getScoreBand } from '@/utils/creditScore';
import type { AdvanceRequest, Farmer } from '@/types';

export interface ApproveLoanOptions {
  ghiChu?: string;
  approvedAmount?: number;
  interestRate?: number;
  termMonths?: number;
  dueDate?: string;
  /** If set, this is an exception approval */
  exceptionReason?: string;
  /** Name of the approver */
  approver?: string;
}

export interface ApproveLoanResult {
  success: boolean;
  lockExpiresAt?: string;
  lockExpireLabel?: string;
}

/**
 * Execute the full loan approval flow:
 * 1. Update loan status → approved_locked (có khóa hạn mức 10 phút)
 * 2. Create LimitLock (10 min)
 * 3. Send notifications to farmer
 * 4. Log edit history
 * 5. If exception → log exception history
 *
 * This is THE ONLY function that should approve a money loan.
 * Every component MUST call this instead of doing its own updateLoan.
 */
export function executeApproveLoan(
  loan: AdvanceRequest,
  farmer: Farmer,
  options: ApproveLoanOptions = {},
): ApproveLoanResult {
  const today = new Date().toISOString().split('T')[0];
  const nowIso = new Date().toISOString();
  const approver = options.approver || 'HTX Hòa Phát';
  const kycInfo = getFarmerKyc(farmer);
  const scoreBand = getScoreBand(kycInfo?.creditScore);
  const isException = !!options.exceptionReason;
  const approvedLoan = {
    ...loan,
    soTien: options.approvedAmount && options.approvedAmount > 0 ? options.approvedAmount : loan.soTien,
  };

  // Build final ghiChu
  const finalGhiChu = [
    isException ? `[DUYỆT NGOẠI LỆ] Score: ${kycInfo?.creditScore || 'N/A'}/900 (${scoreBand.band})` : '',
    isException ? `Lý do: ${options.exceptionReason}` : '',
    options.ghiChu?.trim() ? `Ghi chú: ${options.ghiChu.trim()}` : '',
    options.interestRate !== undefined ? `Lãi suất: ${options.interestRate}%/tháng` : '',
    options.termMonths ? `Kỳ hạn: ${options.termMonths} tháng` : '',
    options.dueDate ? `Đến hạn: ${options.dueDate}` : '',
    loan.ghiChu || '',
  ].filter(Boolean).join('. ');

  // 1. Update loan status → approved_locked (có khóa hạn mức 10 phút)
  updateLoan(loan.id, {
    status: 'approved_locked' as AdvanceRequest['status'],
    soTien: approvedLoan.soTien,
    ngayDuyet: today,
    ghiChu: finalGhiChu || loan.ghiChu,
  });

  // 2. Create limit lock (10 min)
  let lockExpiresAt: string | undefined;
  let lockExpireLabel: string | undefined;

  if (loan.loai === 'Tiền') {
    const lock = createLimitLockForLoan(approvedLoan, approver);
    lockExpiresAt = lock.expiresAt;
    lockExpireLabel = new Date(lock.expiresAt).toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' });

    addNotification({
      farmerId: loan.farmerId,
      title: 'Hạn mức đã bị khóa tạm thời',
      content: `Hạn mức ${formatCurrencyCompact(lock.amount)} đã bị khóa đến ${lockExpireLabel} để chờ giải ngân. Vui lòng hoàn tất giải ngân trước thời gian này.`,
      type: 'general',
      ngayTao: nowIso,
      daDoc: false,
      sentBy: 'Hệ thống',
    });
  }

  // 3. Farmer notification
  addNotification({
    farmerId: loan.farmerId,
    title: 'Yêu cầu vay tiền đã được duyệt',
    content: `Yêu cầu vay ${formatCurrencyCompact(approvedLoan.soTien)} của bạn đã được HTX duyệt. Khoản vay sẽ được giải ngân trong thời gian sớm nhất.`,
    type: 'loan_approved',
    ngayTao: nowIso,
    daDoc: false,
  });

  // 4. Edit history
  addEditHistory({
    entityType: 'Loan',
    entityId: loan.id,
    farmerId: loan.farmerId,
    truong: 'status',
    giaTriCu: loan.status,
    giaTriMoi: isException ? 'Đã duyệt (ngoại lệ)' : 'Đã duyệt',
    ngaySua: nowIso,
    nguoiSua: approver,
  });

  // 5. Exception approval — extra logging
  if (isException) {
    addEditHistory({
      entityType: 'ExceptionApproval',
      entityId: loan.id,
      farmerId: loan.farmerId,
      truong: `Phê duyệt ngoại lệ - Score ${kycInfo?.creditScore || 'N/A'} (${scoreBand.band})`,
      giaTriCu: loan.status,
      giaTriMoi: 'Đã duyệt (ngoại lệ)',
      ngaySua: nowIso,
      nguoiSua: approver,
    });

    addEditHistory({
      entityType: 'ExceptionApproval',
      entityId: loan.id,
      farmerId: loan.farmerId,
      truong: 'Lý do phê duyệt ngoại lệ',
      giaTriCu: '',
      giaTriMoi: options.exceptionReason || '',
      ngaySua: nowIso,
      nguoiSua: approver,
    });
  }

  // 6. Audit log — LoanApprovalHistory
  const lock = loan.loai === 'Tiền' ? getActiveLockByLoan(loan.id) : undefined;
  const debts = getDebtsByFarmer(loan.farmerId);
  const overdueDebts = debts.filter((d) => d.status === 'Quá hạn' || d.status === 'Thu nợ lỗi');
  const totalOverdue = overdueDebts.reduce((s, d) => s + d.conNo, 0);
  
  // Build failed checklist items for exception
  const failedItems: string[] = [];
  if (isException) {
    if ((kycInfo?.creditScore ?? 0) < 550) failedItems.push(`Score ${kycInfo?.creditScore || 'N/A'}`);
    if (kycInfo?.riskLevel === 'Rủi ro cao' || kycInfo?.riskLevel === 'Nguy cơ') failedItems.push(`Risk ${kycInfo?.riskLevel}`);
    if (overdueDebts.length > 0) failedItems.push(`Nợ quá hạn (${overdueDebts.length} khoản)`);
    if (kycInfo?.kycStatus !== 'ekyc_verified') failedItems.push(`eKYC ${kycInfo?.kycStatus}`);
  }

  addLoanApprovalHistory({
    loanId: loan.id,
    farmerId: loan.farmerId,
    soTien: approvedLoan.soTien,
    oldStatus: loan.status,
    newStatus: 'approved_locked',
    approver,
    approvedAt: nowIso,
    lockId: lock?.id,
    lockExpiresAt: lock?.expiresAt,
    isException,
    exceptionReason: isException ? options.exceptionReason : undefined,
    creditScoreAtApproval: kycInfo?.creditScore,
    riskLevelAtApproval: kycInfo?.riskLevel,
    overdueDebtCount: overdueDebts.length,
    totalOverdueDebt: totalOverdue,
    availableLimitAtApproval: undefined,
    failedChecklistItems: failedItems.length > 0 ? failedItems.join('; ') : undefined,
    exceptionConfirmedBy: isException ? approver : undefined,
    exceptionConfirmedAt: isException ? nowIso : undefined,
  });

  showToast(
    isException
      ? 'Đã duyệt yêu cầu vay tiền (phê duyệt ngoại lệ)! Chuyển sang trạng thái Đã duyệt - chờ giải ngân.'
      : 'Đã duyệt yêu cầu vay tiền! Chuyển sang trạng thái Đã duyệt - chờ giải ngân.',
    'success',
  );

  return { success: true, lockExpiresAt, lockExpireLabel };
}

/**
 * Check if a farmer has overdue debts — used to determine
 * if exception approval is needed even when score is OK.
 */
export function hasFarmerOverdueDebts(farmerId: string): boolean {
  const debts = getDebtsByFarmer(farmerId);
  return debts.some((d) => d.status === 'Quá hạn' || d.status === 'Thu nợ lỗi');
}
