import { useEffect, useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { showToast } from '@/components/base/Toast';
import { useStore } from '@/hooks/useStore';
import { getState } from '@/store';
import { requestAntescoFunding, requestAntescoLimit } from '@/services/antescoFundingService';
import { formatCurrencyFull } from '@/utils/formatters';

export type HtxFundAction = 'loan' | 'limit';

export function HtxFundRequestSheet({ open, mode, onClose }: { open: boolean; mode: HtxFundAction; onClose: () => void }) {
  useStore();
  const state = getState();
  const [amount, setAmount] = useState('');
  const [purpose, setPurpose] = useState('');
  const [term, setTerm] = useState('12 tháng');
  const [submitting, setSubmitting] = useState(false);
  const htxUser = state.currentUser;
  const htxRiskLevel = htxUser?.riskLevel || 'Tốt';
  const htxCreditScore = htxUser?.creditScore || 780;
  const htxEkycOk = htxUser?.kycStatus === 'ekyc_verified';
  const mockDecision = htxEkycOk && htxCreditScore >= 700 ? 'Đạt điều kiện mock' : htxEkycOk ? 'Cần HTX giải trình thêm' : 'Cần hoàn tất eKYC';

  useEffect(() => {
    if (!open) return;
    setAmount('');
    setPurpose('');
    setTerm('12 tháng');
  }, [mode, open]);

  const submit = async () => {
    const numericAmount = Number(amount);
    if (!state.currentUser || numericAmount <= 0 || !purpose.trim()) {
      showToast('Vui lòng nhập số tiền và mục đích sử dụng.', 'warning');
      return;
    }
    setSubmitting(true);
    const riskNote = `Mock risk profile HTX: eKYC ${htxEkycOk ? 'đã xác thực' : 'chưa hoàn tất'}, score ${htxCreditScore}, rủi ro ${htxRiskLevel}, kết quả sơ bộ ${mockDecision}.`;
    try {
      if (mode === 'loan') {
        await requestAntescoFunding({ htxUserId: state.currentUser.id, amount: numericAmount, purpose: purpose.trim(), term, note: riskNote });
        showToast('Yêu cầu vay đã được gửi và cập nhật vào Quỹ HTX.', 'success');
      } else {
        await requestAntescoLimit({ htxUserId: state.currentUser.id, amount: numericAmount, purpose: purpose.trim(), note: riskNote });
        showToast('Yêu cầu cấp hạn mức đã được gửi và cập nhật vào Quỹ HTX.', 'success');
      }
      onClose();
    } catch (error) {
      showToast(error instanceof Error ? error.message : 'Không thể gửi yêu cầu.', 'error');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <BottomSheet open={open} onClose={onClose} title={mode === 'loan' ? 'HTX xin vay' : 'Hạn mức HTX'}>
      <div className="space-y-4">
        <section className="rounded-xl border border-emerald-100 bg-emerald-50 p-3">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <p className="text-xs font-bold text-emerald-900">Risk profile HTX</p>
              <p className="mt-1 text-[11px] leading-relaxed text-emerald-700">Mock eKYC và chấm điểm rủi ro trước khi gửi sang bên cấp vốn.</p>
            </div>
            <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${htxEkycOk ? 'bg-white text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>{htxEkycOk ? 'eKYC hợp lệ' : 'Cần eKYC'}</span>
          </div>
          <div className="mt-3 grid grid-cols-3 gap-2">
            <RiskMetric label="Score" value={String(htxCreditScore)} />
            <RiskMetric label="Rủi ro" value={htxRiskLevel} />
            <RiskMetric label="Kết quả" value={mockDecision} />
          </div>
        </section>
        <label className="block">
          <span className="mb-1.5 block text-xs font-medium text-slate-600">Số tiền đề nghị</span>
          <input type="number" value={amount} onChange={(event) => setAmount(event.target.value)} placeholder="500000000" className="w-full rounded-xl border border-slate-200 px-3 py-3 text-sm outline-none focus:border-emerald-500" />
          {Number(amount) > 0 && <span className="metric-caption mt-1 block text-[10px] text-slate-400">{formatCurrencyFull(Number(amount))}</span>}
        </label>
        <label className="block">
          <span className="mb-1.5 block text-xs font-medium text-slate-600">Mục đích sử dụng</span>
          <textarea value={purpose} onChange={(event) => setPurpose(event.target.value)} rows={3} placeholder="Bổ sung quỹ giải ngân cho nông hộ..." className="w-full resize-none rounded-xl border border-slate-200 px-3 py-3 text-sm outline-none focus:border-emerald-500" />
        </label>
        {mode === 'loan' && (
          <label className="block">
            <span className="mb-1.5 block text-xs font-medium text-slate-600">Kỳ hạn</span>
            <select value={term} onChange={(event) => setTerm(event.target.value)} className="w-full rounded-xl border border-slate-200 px-3 py-3 text-sm">
              <option>6 tháng</option><option>12 tháng</option><option>24 tháng</option><option>36 tháng</option>
            </select>
          </label>
        )}
        <button type="button" onClick={submit} disabled={submitting} className="w-full rounded-xl bg-emerald-700 px-4 py-3 text-sm font-bold text-white disabled:bg-slate-300">{submitting ? 'Đang gửi...' : 'Gửi yêu cầu'}</button>
      </div>
    </BottomSheet>
  );
}

function RiskMetric({ label, value }: { label: string; value: string }) {
  return (
    <div className="min-w-0 rounded-lg bg-white/80 p-2 text-center">
      <p className="text-[10px] text-emerald-700/70">{label}</p>
      <p className="mt-0.5 truncate text-xs font-bold text-emerald-900">{value}</p>
    </div>
  );
}
