/**
 * Count of pending money loan requests across all farmers.
 */
export function getGlobalPendingMoneyLoans(): number {
  const state = getState();
  return state.advanceRequests.filter(
    (l) => l.loai === 'Tiền' && l.status === 'Chờ kiểm tra',
  ).length;
}

/**
 * Count of approved loans waiting for disbursement.
 */
export function getGlobalPendingDisbursement(): number {
  const state = getState();
  return state.advanceRequests.filter(
    (l) => l.loai === 'Tiền' && (l.status === 'Đã duyệt' || l.status === 'Chờ giải ngân'),
  ).length;
}

/**
 * Count of failed disbursements.
 */
export function getGlobalDisbursementErrors(): number {
  const state = getState();
  return state.advanceRequests.filter(
    (l) => l.loai === 'Tiền' && l.status === 'Giải ngân lỗi',
  ).length;
}

/**
 * Global debt statistics with PaymentIntent integration.
 */
export function getDebtStats() {
  const state = getState();
  const allDebts = state.debts;
  const allPIs = getPaymentIntents();
  const active = allDebts.filter((d) => d.status !== 'Đã tất toán');

  const activePIs = allPIs.filter((p) => p.status !== 'settled' && p.status !== 'cancelled');

  return {
    totalDuNo: active.reduce((sum, d) => sum + getDebtOutstandingAmount(d), 0),
    dangVay: active.filter((d) => d.status === 'Đang vay').length,
    sapDenHan: active.filter((d) => d.status === 'Sắp đến hạn' || d.status === 'Đến hạn').length,
    quaHan: active.filter((d) => d.status === 'Quá hạn').length,
    choBaoCo: activePIs.filter((p) => p.status === 'farmer_confirmed_transfer' || p.status === 'waiting_bank_credit' || p.status === 'bank_credit_received' || p.status === 'qr_created').length,
    choXacNhanTT: activePIs.filter((p) => p.status === 'reconciled' || p.status === 'waiting_htx_confirmation').length,
    doiSoatLoi: activePIs.filter((p) => p.status === 'reconcile_failed').length,
    daTatToan: allDebts.filter((d) => d.status === 'Đã tất toán').length + allPIs.filter((p) => p.status === 'settled').length,
    overdueAmount: active.filter((d) => d.status === 'Quá hạn').reduce((sum, d) => sum + getDebtOutstandingAmount(d), 0),
    nearDueAmount: active.filter((d) => d.status === 'Sắp đến hạn' || d.status === 'Đến hạn').reduce((sum, d) => sum + getDebtOutstandingAmount(d), 0),
    choBaoCoAmount: activePIs.filter((p) => p.status === 'farmer_confirmed_transfer' || p.status === 'waiting_bank_credit' || p.status === 'bank_credit_received' || p.status === 'qr_created').reduce((s, p) => s + p.soTien, 0),
    choXacNhanTTAmount: activePIs.filter((p) => p.status === 'reconciled' || p.status === 'waiting_htx_confirmation').reduce((s, p) => s + p.soTien, 0),
  };
}

