/**
 * Disbursement stats.
 */
export function getDisbursementStats() {
  const state = getState();
  const all = state.disbursementRequests;

  return {
    pending: all.filter((d) => d.status === 'Chưa gửi' || d.status === 'Đã gửi ngân hàng' || d.status === 'Đang xử lý').length,
    success: all.filter((d) => d.status === 'Thành công').length,
    failed: all.filter((d) => d.status === 'Thất bại').length,
    cancelled: all.filter((d) => d.status === 'Đã hủy').length,
    total: all.length,
    totalSuccessAmount: all.filter((d) => d.status === 'Thành công').reduce((s, d) => s + d.soTien, 0),
    totalFailedAmount: all.filter((d) => d.status === 'Thất bại').reduce((s, d) => s + d.soTien, 0),
    totalPendingAmount: all.filter((d) => d.status === 'Chưa gửi' || d.status === 'Đã gửi ngân hàng' || d.status === 'Đang xử lý').reduce((s, d) => s + d.soTien, 0),
  };
}

/**
 * Comprehensive dashboard stats (HTX overview / finance dashboard).
 */
export function getFinanceDashboardStats() {
  const state = getState();
  const effectiveSources = getEffectiveHtxSources();
  const totalLimit = effectiveSources.reduce((s, src) => s + src.hanMuc, 0);
  const totalUsed = effectiveSources.reduce((s, src) => s + src.daSuDung, 0);
  const totalLocked = getActiveLockedAmountGlobal();
  const totalAvailable = Math.max(0, totalLimit - totalUsed - totalLocked);

  const debtStats = getDebtStats();
  const loanStats = getLoanRequestStats();
  const disbStats = getDisbursementStats();
  const lockStats = getLimitLockStats();

  const finances = state.financeSources;
  const tongThu = finances.filter((f) => f.loai === 'Thu').reduce((s, f) => s + f.soTien, 0);
  const tongChi = finances.filter((f) => f.loai === 'Chi').reduce((s, f) => s + f.soTien, 0);

  const allDebts = state.debts;
  const tongLai = allDebts.reduce((s, d) => s + calculateLoanInterest(d), 0);

  const nearlyExpiredSources = getExpiredOrNearlyExpiredSources();

  return {
    // HTX source
    htxTotalLimit: totalLimit,
    htxUsed: totalUsed,
    htxLocked: totalLocked,
    htxAvailable: totalAvailable,
    htxUsagePercent: totalLimit > 0 ? (totalUsed / totalLimit) * 100 : 0,
    htxActiveSourceCount: effectiveSources.length,
    htxExpiringCount: nearlyExpiredSources.length,
    htxExpiringAmount: nearlyExpiredSources.reduce((s, e) => s + e.source.hanMuc, 0),
    // Debt
    ...debtStats,
    // Loan requests
    ...loanStats,
    // Disbursements
    ...disbStats,
    // Cash flow
    tongThu,
    tongChi,
    chenhLech: tongThu - tongChi,
    tongLai,
    tongGiaiNganAmount: finances.filter((f) => f.loai === 'Chi' && f.phanLoai === 'Giải ngân').reduce((s, f) => s + f.soTien, 0),
    // Lock stats
    lockActiveCount: lockStats.activeCount,
    lockActiveAmount: lockStats.activeAmount,
    lockExpiredCount: lockStats.expiredCount,
    lockExpiredAmount: lockStats.expiredAmount,
    lockNearExpiryCount: lockStats.nearExpiryCount,
  };
}

// ═══════════════════════════════════════════════════════════
// BORROWING ELIGIBILITY
// ═══════════════════════════════════════════════════════════

/**
 * Check if a farmer can borrow a given amount (money only).
 * Limit still comes from bao tieu contracts; the request context can be a season.
 */
export function canFarmerBorrow(farmerId: string, amount: number, seasonId?: string): { allowed: boolean; reason: string } {
  if (amount <= 0) return { allowed: false, reason: 'Số tiền không hợp lệ' };

  if (seasonId) {
    const season = getState().seasons.find((item) => item.id === seasonId && item.farmerId === farmerId);
    if (!season) return { allowed: false, reason: 'Mùa vụ không thuộc nông hộ này' };
  }

  const available = getAvailableFarmerLimit(farmerId);
  if (amount > available) {
    const locked = getActiveLockedAmountByFarmer(farmerId);
    if (locked > 0) {
      return {
        allowed: false,
        reason: `Vượt hạn mức khả dụng nông hộ (còn ${available.toLocaleString('vi-VN')}đ, đang khóa ${locked.toLocaleString('vi-VN')}đ)`,
      };
    }
    return { allowed: false, reason: `Vượt hạn mức nông hộ (còn ${available.toLocaleString('vi-VN')}đ)` };
  }

  const overdueCount = getFarmerOverdueCount(farmerId);
  if (overdueCount > 0) {
    return { allowed: false, reason: `Có ${overdueCount} khoản nợ quá hạn, không thể vay thêm` };
  }

  const htxAvailable = getAvailableHtxSourceLimit();
  if (amount > htxAvailable) {
    return { allowed: false, reason: `Hạn mức HTX khả dụng không đủ (còn ${htxAvailable.toLocaleString('vi-VN')}đ)` };
  }

  return { allowed: true, reason: '' };
}

// ═══════════════════════════════════════════════════════════
// LIMIT LOCK HELPERS
// ═══════════════════════════════════════════════════════════

export interface LimitLockInfo {
  lock: LimitLock | null;
  isLocked: boolean;
  isExpired: boolean;
  isWarning: boolean;
  remainingSeconds: number;
  totalSeconds: number;
  displayText: string;
}

const LOCK_DURATION_SECONDS = 10 * 60;
const WARNING_THRESHOLD_SECONDS = 2 * 60;

/**
 * Get lock info for a specific loan.
 */
export function getLimitLockInfo(loanId: string): LimitLockInfo {
  const lock = getActiveLockByLoan(loanId);
  if (!lock) {
    return { lock: null, isLocked: false, isExpired: false, isWarning: false, remainingSeconds: 0, totalSeconds: LOCK_DURATION_SECONDS, displayText: '' };
  }

  const now = Date.now();
  const expiresMs = new Date(lock.expiresAt).getTime();
  const remainingMs = Math.max(0, expiresMs - now);
  const remainingSeconds = Math.floor(remainingMs / 1000);
  const totalSeconds = LOCK_DURATION_SECONDS;
  // Also treat as expired if status is already 'expired' or time has passed
  const isExpired = remainingSeconds <= 0 || lock.status === 'expired';
  const isWarning = !isExpired && remainingSeconds <= WARNING_THRESHOLD_SECONDS;

  const mins = Math.floor(remainingSeconds / 60);
  const secs = remainingSeconds % 60;
  const displayText = isExpired ? 'Đã hết khóa' : `Còn ${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;

  return { lock, isLocked: !isExpired && lock.status === 'active', isExpired, isWarning, remainingSeconds, totalSeconds, displayText };
}

/**
 * Check if a loan has an expired lock (was locked but now expired).
 */
export function hasExpiredLock(loanId: string): boolean {
  const allLocks = getLimitLocks();
  return allLocks.some((l) => l.loanId === loanId && l.status === 'expired');
}

/**
 * Get lock statistics.
 */
export function getLimitLockStats() {
  const allLocks = getLimitLocks();
  const active = allLocks.filter((l) => l.status === 'active');
  const expired = allLocks.filter((l) => l.status === 'expired');
  const converted = allLocks.filter((l) => l.status === 'converted');
  const released = allLocks.filter((l) => l.status === 'released');
  const cancelled = allLocks.filter((l) => l.status === 'cancelled');

  const now = new Date();
  const warningExpiry = new Date(now.getTime() + WARNING_THRESHOLD_SECONDS * 1000).toISOString();
  const nearExpiry = active.filter((l) => l.expiresAt <= warningExpiry);

  return {
    activeCount: active.length,
    activeAmount: active.reduce((s, l) => s + l.amount, 0),
    expiredCount: expired.length,
    expiredAmount: expired.reduce((s, l) => s + l.amount, 0),
    nearExpiryCount: nearExpiry.length,
    nearExpiryAmount: nearExpiry.reduce((s, l) => s + l.amount, 0),
    convertedCount: converted.length,
    releasedCount: released.length,
    cancelledCount: cancelled.length,
    totalActive: active.length,
  };
}

// ═══════════════════════════════════════════════════════════
// FARMER MONEY SUMMARY
// ═══════════════════════════════════════════════════════════

export interface FarmerMoneySummary {
  hanMucTienTong: number;
  hanMucTienDaDung: number;
  hanMucTienConLai: number;
  hanMucTienKhaDung: number;
  hanMucTienDangKhoa: number;
  duNo: number;
  choGiaiNgan: number;
  quaHan: number;
  sapDenHan: number;
  choKiemTra: number;
  daDuyet: number;
}

export function getFarmerMoneySummary(farmerId: string): FarmerMoneySummary {
  const hanMucTienTong = getFarmerTotalLimit(farmerId);
  const hanMucTienDaDung = getUsedLimitByFarmer(farmerId);
  const hanMucTienDangKhoa = getActiveLockedAmountByFarmer(farmerId);
  const hanMucTienKhaDung = Math.max(0, hanMucTienTong - hanMucTienDaDung - hanMucTienDangKhoa);
  const hanMucTienConLai = Math.max(0, hanMucTienTong - hanMucTienDaDung);
  const duNo = getOutstandingDebtByFarmer(farmerId);
  const choGiaiNgan = hanMucTienDangKhoa;

  const debts = getDebtsByFarmer(farmerId);
  const quaHan = debts.filter((d) => d.status === 'Quá hạn').length;
  const sapDenHan = debts.filter((d) => d.status === 'Sắp đến hạn' || d.status === 'Đến hạn').length;

  const loans = getFarmerMoneyLoans(farmerId);
  const choKiemTra = loans.filter((l) => l.status === 'Chờ kiểm tra').length;
  const daDuyet = loans.filter((l) => ['Đã duyệt', 'Chờ giải ngân', 'approved_locked'].includes(l.status)).length;

  return {
    hanMucTienTong,
    hanMucTienDaDung,
    hanMucTienConLai,
    hanMucTienKhaDung,
    hanMucTienDangKhoa,
    duNo,
    choGiaiNgan,
    quaHan,
    sapDenHan,
    choKiemTra,
    daDuyet,
  };
}

// ═══════════════════════════════════════════════════════════
// HTX MONEY SUMMARY
// ═══════════════════════════════════════════════════════════

export interface HtxMoneySummary {
  totalLimit: number;
  usedLimit: number;
  lockedAmount: number;
  availableLimit: number;
  remainingLimit: number;
  usagePercent: number;
  activeSources: number;
  nearlyExpiredSources: number;
  nearlyExpiredAmount: number;
  pendingMoneyLoans: number;
  pendingDisbursement: number;
  disbursementErrors: number;
  overdueDebts: number;
  nearDueDebts: number;
}

export function getHtxMoneySummary(): HtxMoneySummary {
  const state = getState();
  const effectiveSources = getEffectiveHtxSources();
  const totalLimit = effectiveSources.reduce((sum, s) => sum + s.hanMuc, 0);
  const usedLimit = effectiveSources.reduce((sum, s) => sum + s.daSuDung, 0);
  const lockedAmount = getActiveLockedAmountGlobal();
  const availableLimit = Math.max(0, totalLimit - usedLimit - lockedAmount);
  const remainingLimit = Math.max(0, totalLimit - usedLimit);

  const nearlyExpired = state.htxLoanSources.filter((s) => s.status === 'Sắp hết hạn');

  return {
    totalLimit,
    usedLimit,
    lockedAmount,
    availableLimit,
    remainingLimit,
    usagePercent: totalLimit > 0 ? (usedLimit / totalLimit) * 100 : 0,
    activeSources: effectiveSources.length,
    nearlyExpiredSources: nearlyExpired.length,
    nearlyExpiredAmount: nearlyExpired.reduce((s, src) => s + src.hanMuc, 0),
    pendingMoneyLoans: getGlobalPendingMoneyLoans(),
    pendingDisbursement: getGlobalPendingDisbursement(),
    disbursementErrors: getGlobalDisbursementErrors(),
    overdueDebts: state.debts.filter((d) => d.status === 'Quá hạn').length,
    nearDueDebts: state.debts.filter((d) => d.status === 'Sắp đến hạn' || d.status === 'Đến hạn').length,
  };
}

// ═══════════════════════════════════════════════════════════
// ALLOCATION HELPERS
// Used to consistently allocate amounts across limits/sources
// on disbursement and release on settlement.
// ═══════════════════════════════════════════════════════════

import { updateLimit, updateHtxLoanSource, getHtxLoanSources } from '@/store';

/**
 * Allocate a disbursed amount across farmer limits (increase daSuDung).
 * Distributes proportionally to available capacity in each limit.
 */
export function allocateDisbursedToLimits(farmerId: string, amount: number): void {
  if (amount <= 0) return;
  const limits = getLimitsByFarmer(farmerId).filter((l) => l.loaiDinhMuc === 'Vay vốn sản xuất');
  // Sort by available capacity descending for efficient allocation
  const sorted = [...limits].sort((a, b) => (b.hanMuc - b.daSuDung) - (a.hanMuc - a.daSuDung));
  let remaining = amount;
  for (const lm of sorted) {
    if (remaining <= 0) break;
    const available = lm.hanMuc - lm.daSuDung;
    if (available > 0) {
      const deduct = Math.min(available, remaining);
      updateLimit(lm.id, { daSuDung: lm.daSuDung + deduct });
      remaining -= deduct;
    }
  }
}

/**
 * Release settled debt amount from farmer limits (decrease daSuDung).
 * Distributes proportionally starting from limits with highest daSuDung.
 */
export function releaseSettledFromLimits(farmerId: string, amount: number): void {
  if (amount <= 0) return;
  const limits = getLimitsByFarmer(farmerId).filter((l) => l.loaiDinhMuc === 'Vay vốn sản xuất');
  const sorted = [...limits].sort((a, b) => b.daSuDung - a.daSuDung);
  let remaining = amount;
  for (const lm of sorted) {
    if (remaining <= 0) break;
    if (lm.daSuDung > 0) {
      const restore = Math.min(lm.daSuDung, remaining);
      updateLimit(lm.id, { daSuDung: Math.max(0, lm.daSuDung - restore) });
      remaining -= restore;
    }
  }
}

/**
 * Allocate a disbursed amount across HTX loan sources (increase daSuDung).
 */
export function allocateDisbursedToHtxSources(amount: number): void {
  if (amount <= 0) return;
  const sources = getEffectiveHtxSources();
  const sorted = [...sources].sort((a, b) => (b.hanMuc - b.daSuDung) - (a.hanMuc - a.daSuDung));
  let remaining = amount;
  for (const src of sorted) {
    if (remaining <= 0) break;
    // Skip excluded or non-effective sources
    if (isSourceExcluded(src) || !EFFECTIVE_SOURCE_STATUSES.includes(src.status)) continue;
    const available = src.hanMuc - src.daSuDung;
    if (available > 0) {
      const deduct = Math.min(available, remaining);
      updateHtxLoanSource(src.id, { daSuDung: src.daSuDung + deduct });
      remaining -= deduct;
    }
  }
}

/**
 * Release settled debt amount from HTX loan sources (decrease daSuDung).
 */
export function releaseSettledFromHtxSources(amount: number): void {
  if (amount <= 0) return;
  const sources = getEffectiveHtxSources();
  const sorted = [...sources].sort((a, b) => b.daSuDung - a.daSuDung);
  let remaining = amount;
  for (const src of sorted) {
    if (remaining <= 0) break;
    if (src.daSuDung > 0) {
      const restore = Math.min(src.daSuDung, remaining);
      updateHtxLoanSource(src.id, { daSuDung: Math.max(0, src.daSuDung - restore) });
      remaining -= restore;
    }
  }
}

/**
 * Allocate disbursed amount to a SPECIFIC HTX source (single source, no splitting).
 * Used when HTX explicitly selects a source for disbursement.
 * Returns true if allocation succeeded, false if source not found or insufficient.
 */
export function allocateToSpecificHtxSource(sourceId: string, amount: number): boolean {
  if (amount <= 0) return false;
  const state = getState();
  const source = state.htxLoanSources.find((s) => s.id === sourceId);
  if (!source) return false;
  if (isSourceExcluded(source)) return false;
  const available = source.hanMuc - source.daSuDung;
  if (available < amount) return false;
  updateHtxLoanSource(sourceId, { daSuDung: source.daSuDung + amount });
  return true;
}

/**
 * Release settled debt from a SPECIFIC HTX source.
 */
export function releaseFromSpecificHtxSource(sourceId: string, amount: number): boolean {
  if (amount <= 0) return false;
  const state = getState();
  const source = state.htxLoanSources.find((s) => s.id === sourceId);
  if (!source) return false;
  if (source.daSuDung <= 0) return false;
  const restore = Math.min(source.daSuDung, amount);
  updateHtxLoanSource(sourceId, { daSuDung: Math.max(0, source.daSuDung - restore) });
  return true;
}

/**
 * Check if a specific source has enough available funds.
 * Returns { available, enough, remaining }.
 */
export function checkSourceAvailability(sourceId: string, amount: number): { available: number; enough: boolean; remaining: number; sourceName: string; sourceType: string } {
  const state = getState();
  const source = state.htxLoanSources.find((s) => s.id === sourceId);
  if (!source) return { available: 0, enough: false, remaining: 0, sourceName: 'Không tìm thấy', sourceType: '' };
  const remaining = Math.max(0, source.hanMuc - source.daSuDung);
  return {
    available: source.hanMuc,
    enough: amount <= remaining && !isSourceExcluded(source),
    remaining,
    sourceName: source.tenNguonVay,
    sourceType: source.loaiNguon,
  };
}

/**
 * Get all sources eligible for disbursement (Đang hiệu lực + Sắp hết hạn).
 * Returns list with available amount info for source selection dropdown.
 */
export interface DisbursableSource {
  id: string;
  name: string;
  type: string;
  hanMuc: number;
  daSuDung: number;
  remaining: number;
  status: string;
  isWarning: boolean;
}
export function getDisbursableSources(): DisbursableSource[] {
  return getEffectiveHtxSources().map((s) => ({
    id: s.id,
    name: s.tenNguonVay,
    type: s.loaiNguon,
    hanMuc: s.hanMuc,
    daSuDung: s.daSuDung,
    remaining: Math.max(0, s.hanMuc - s.daSuDung),
    status: s.status,
    isWarning: s.status === 'Sắp hết hạn',
  })).sort((a, b) => b.remaining - a.remaining);
}

