/**
 * Tổng hạn mức tiền đã cấp cho tất cả nông hộ.
 * Sum of all "Vay vốn sản xuất" limits' hanMuc across all farmers.
 */
export function getTotalFarmerLimitsGranted(): number {
  return getState().limits
    .filter((l) => l.loaiDinhMuc === 'Vay vốn sản xuất')
    .reduce((sum, l) => sum + l.hanMuc, 0);
}

/**
 * Số nông hộ đã được cấp ít nhất 1 hạn mức tiền.
 * Counts distinct farmerIds that have at least one "Vay vốn sản xuất" limit.
 */
export function getFarmerCountWithMoneyLimits(): number {
  const farmerIds = new Set(
    getState().limits
      .filter((l) => l.loaiDinhMuc === 'Vay vốn sản xuất')
      .map((l) => l.farmerId),
  );
  return farmerIds.size;
}

/**
 * Tổng hạn mức đã cấp tính theo số tiền thực đã giải ngân (used).
 */
export function getTotalFarmerLimitsUsed(): number {
  return getState().limits
    .filter((l) => l.loaiDinhMuc === 'Vay vốn sản xuất')
    .reduce((sum, l) => sum + l.daSuDung, 0);
}

/**
 * "Xử lý giải ngân" badge — counts loans ready for disbursement action.
 * Includes: Đã duyệt (locked), Chờ giải ngân, bank_timeout, Giải ngân lỗi,
 *           waiting_bank_response, lock_expired, disbursement_failed.
 * Excludes: đã giải ngân thành công, đã tất toán, từ chối.
 */
export function getPendingDisbursementActionCount(): number {
  const actionStatuses = [
    'Đã duyệt', 'Chờ giải ngân', 'approved_locked', 'bank_timeout', 'Giải ngân lỗi',
    'waiting_bank_response', 'lock_expired', 'disbursement_failed',
  ];
  return getState().advanceRequests.filter(
    (l) => l.loai === 'Tiền' && actionStatuses.includes(l.status),
  ).length;
}

/**
 * "Xem công nợ" badge — counts debts requiring HTX attention.
 * Includes: overdue debts + PIs waiting HTX confirmation + PIs with reconcile errors.
 * This captures: Quá hạn, Thu nợ lỗi, PI waiting_htx_confirmation, PI reconcile_failed.
 */
export function getActionableDebtCount(): number {
  const state = getState();
  const debts = state.debts;

  const overdueCount = debts.filter(
    (d) => d.status === 'Quá hạn' || d.status === 'Thu nợ lỗi',
  ).length;

  const pis = getPaymentIntents();
  const piAttentionCount = pis.filter(
    (p) => ['farmer_confirmed_transfer', 'waiting_bank_credit', 'bank_credit_received', 'reconciled', 'waiting_htx_confirmation', 'reconcile_failed'].includes(p.status),
  ).length;

  return overdueCount + piAttentionCount;
}

/**
 * "eKYC hồ sơ" badge — counts farmers with non-terminal eKYC issues.
 * Includes: ekyc_pending, ekyc_need_more, ekyc_failed.
 * Excludes: ekyc_verified (done), registered (not yet submitted — not actionable by HTX).
 */
export function getPendingEkycActionCount(): number {
  const actionableStatuses: string[] = ['ekyc_pending', 'ekyc_need_more', 'ekyc_failed'];
  return getState().farmers.filter((f) => {
    const kyc = getFarmerKyc(f);
    return actionableStatuses.includes(kyc.kycStatus);
  }).length;
}

