import { useMemo, useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { MobileMetricCard } from '@/components/base/MobileUi';
import { StatusBadge } from '@/components/base/StatusBadge';
import { ExceptionApprovalModal } from '@/components/feature/ExceptionApprovalModal';
import type { ExceptionApprovalData } from '@/components/feature/ExceptionApprovalModal';
import {
  getContracts,
  getFarmerKyc,
  getLoanApprovalHistoriesByLoan,
} from '@/store';
import type { AdvanceRequest, Contract, Debt, Farmer, Limit, RiskProfile } from '@/types';
import { requiresExceptionApproval } from '@/utils/creditScore';
import { formatCurrencyCompact } from '@/utils/formatters';
import { executeApproveLoan } from '@/utils/loanApprovalService';

interface LoanDetailModalProps {
  loan: AdvanceRequest;
  farmer: Farmer;
  farmerName: string;
  seasonName: string;
  fieldName: string;
  riskProfile?: RiskProfile;
  limits: Limit[];
  debts: Debt[];
  contracts: Contract[];
  htxRemaining: number;
  onClose: () => void;
  onApprove: () => void;
  onReject: () => void;
  onNeedMore: () => void;
  onAdjustLimit: () => void;
  onViewContract: (contractId: string) => void;
}

interface CheckItem {
  label: string;
  value: string;
  status: 'pass' | 'warn' | 'fail';
}

const APPROVED_STATUSES: AdvanceRequest['status'][] = [
  'Đã duyệt',
  'approved_locked',
  'Chờ giải ngân',
  'disbursement_failed',
  'Giải ngân lỗi',
];

export default function LoanDetailModal({
  loan,
  farmer,
  farmerName,
  seasonName,
  fieldName,
  riskProfile,
  limits,
  debts,
  contracts,
  htxRemaining,
  onClose,
  onApprove,
  onReject,
  onNeedMore,
  onAdjustLimit,
  onViewContract,
}: LoanDetailModalProps) {
  const [showChecks, setShowChecks] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [showExceptionModal, setShowExceptionModal] = useState(false);

  const kyc = getFarmerKyc(farmer);
  const activeContracts = contracts.filter(
    (contract) => contract.farmerId === loan.farmerId && contract.status === 'Đang hiệu lực',
  );
  const totalLimit = limits.reduce((sum, limit) => sum + limit.hanMuc, 0);
  const usedLimit = limits.reduce((sum, limit) => sum + limit.daSuDung, 0);
  const farmerRemaining = Math.max(0, totalLimit - usedLimit);
  const activeDebts = debts.filter((debt) => debt.status !== 'Đã tất toán');
  const totalDebt = activeDebts.reduce((sum, debt) => sum + debt.conNo, 0);
  const overdueDebts = debts.filter(
    (debt) => debt.status === 'Quá hạn' || debt.status === 'Thu nợ lỗi',
  );
  const overdueTotal = overdueDebts.reduce((sum, debt) => sum + debt.conNo, 0);
  const history = getLoanApprovalHistoriesByLoan(loan.id);

  const isWaiting = loan.status === 'Chờ kiểm tra' || loan.status === 'Cần bổ sung';
  const isApproved = APPROVED_STATUSES.includes(loan.status);
  const limitsAreEnough = farmerRemaining >= loan.soTien && htxRemaining >= loan.soTien;
  const profileIsComplete = kyc.kycStatus === 'ekyc_verified' && activeContracts.length > 0;
  const hasHighRisk = riskProfile?.mucDo === 'Rủi ro cao' || riskProfile?.mucDo === 'Nguy cơ';
  const needsException =
    requiresExceptionApproval(kyc.creditScore) || overdueDebts.length > 0 || hasHighRisk;
  const canApprove = limitsAreEnough && profileIsComplete;

  const checks: CheckItem[] = [
    {
      label: 'Hồ sơ định danh',
      value: kyc.kycStatus === 'ekyc_verified' ? 'eKYC hợp lệ' : 'Cần hoàn tất eKYC',
      status: kyc.kycStatus === 'ekyc_verified' ? 'pass' : 'fail',
    },
    {
      label: 'Hợp đồng',
      value: activeContracts.length ? `${activeContracts.length} hợp đồng hiệu lực` : 'Chưa có hợp đồng hiệu lực',
      status: activeContracts.length ? 'pass' : 'fail',
    },
    {
      label: 'Hạn mức nông hộ',
      value: `Còn ${formatCurrencyCompact(farmerRemaining)}`,
      status: farmerRemaining >= loan.soTien ? 'pass' : 'fail',
    },
    {
      label: 'Ví HTX',
      value: `Còn ${formatCurrencyCompact(htxRemaining)}`,
      status: htxRemaining >= loan.soTien ? 'pass' : 'fail',
    },
    {
      label: 'Công nợ',
      value: overdueDebts.length
        ? `${overdueDebts.length} khoản quá hạn`
        : totalDebt > 0
          ? `Dư nợ ${formatCurrencyCompact(totalDebt)}`
          : 'Không có dư nợ',
      status: overdueDebts.length ? 'warn' : 'pass',
    },
  ];

  const exceptionData: ExceptionApprovalData = useMemo(
    () => ({
      farmerName,
      farmerId: farmer.id,
      creditScore: kyc.creditScore,
      loanId: loan.id,
      loanAmount: loan.soTien,
      loanPurpose: loan.mucDich,
      totalDebt,
      overdueDebt: overdueTotal,
      overdueCount: overdueDebts.length,
      remainingLimit: farmerRemaining,
      hasOverdue: overdueDebts.length > 0,
      ekycVerified: kyc.kycStatus === 'ekyc_verified',
      activeContracts: activeContracts.length,
      seasonName,
      fieldActivity: fieldName,
      riskLevel: riskProfile?.mucDo,
      lockAmount: loan.soTien,
    }),
    [
      activeContracts.length,
      farmer.id,
      farmerName,
      farmerRemaining,
      fieldName,
      kyc.creditScore,
      kyc.kycStatus,
      loan,
      overdueDebts.length,
      overdueTotal,
      riskProfile?.mucDo,
      seasonName,
      totalDebt,
    ],
  );

  const approve = () => {
    if (needsException) {
      setShowExceptionModal(true);
      return;
    }
    onApprove();
  };

  const confirmException = (reason: string) => {
    executeApproveLoan(loan, farmer, {
      exceptionReason: reason,
      approver: 'HTX Hòa Phát',
    });
    setShowExceptionModal(false);
    onClose();
  };

  const footer = isApproved ? (
    <div className="mobile-action-row">
      <button type="button" onClick={onClose} className="rounded-xl bg-slate-100 px-4 py-3 text-sm font-semibold text-slate-700">
        Đóng
      </button>
      <button type="button" onClick={onApprove} className="rounded-xl bg-emerald-600 px-4 py-3 text-sm font-bold text-white">
        Đi tới giải ngân
      </button>
    </div>
  ) : isWaiting ? (
    <div className="grid grid-cols-2 gap-2">
      <button type="button" onClick={onNeedMore} className="rounded-xl bg-amber-50 px-3 py-3 text-sm font-semibold text-amber-700">
        Cần bổ sung
      </button>
      <button type="button" onClick={onReject} className="rounded-xl bg-rose-50 px-3 py-3 text-sm font-semibold text-rose-700">
        Từ chối
      </button>
      <button type="button" onClick={onClose} className="rounded-xl bg-slate-100 px-3 py-3 text-sm font-semibold text-slate-700">
        Đóng
      </button>
      <button
        type="button"
        onClick={approve}
        disabled={!canApprove}
        className="rounded-xl bg-emerald-600 px-3 py-3 text-sm font-bold text-white disabled:bg-slate-300"
      >
        {needsException ? 'Duyệt ngoại lệ' : 'Duyệt vay'}
      </button>
    </div>
  ) : (
    <button type="button" onClick={onClose} className="w-full rounded-xl bg-slate-100 px-4 py-3 text-sm font-semibold text-slate-700">
      Đóng
    </button>
  );

  return (
    <>
      <BottomSheet open onClose={onClose} title="Chi tiết khoản vay" footer={footer}>
        <div className="space-y-4">
          <div className="flex items-center justify-between gap-3">
            <div className="min-w-0">
              <p className="truncate text-sm font-bold text-slate-900">{farmerName}</p>
              <p className="metric-caption mt-0.5 truncate text-[10px] text-slate-400">
                {loan.id.toUpperCase()} · {seasonName || 'Chưa gắn mùa vụ'}
              </p>
            </div>
            <StatusBadge status={loan.status} />
          </div>

          <section className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-center">
            <p className="text-[11px] font-medium text-emerald-700">Số tiền đề nghị</p>
            <strong className="mt-1 block text-2xl text-emerald-700">
              {formatCurrencyCompact(loan.soTien)}
            </strong>
            <p className="metric-caption mt-2 text-xs text-emerald-700">{loan.mucDich}</p>
          </section>

          <div className="grid grid-cols-2 gap-2">
            <MobileMetricCard
              label="Hạn mức còn"
              value={formatCurrencyCompact(farmerRemaining)}
              caption="Của nông hộ"
              tone={farmerRemaining >= loan.soTien ? 'emerald' : 'rose'}
              icon="ri-user-settings-line"
            />
            <MobileMetricCard
              label="Ví HTX còn"
              value={formatCurrencyCompact(htxRemaining)}
              caption="Khả dụng để giải ngân"
              tone={htxRemaining >= loan.soTien ? 'emerald' : 'rose'}
              icon="ri-wallet-3-line"
            />
            <MobileMetricCard
              label="eKYC"
              value={kyc.kycStatus === 'ekyc_verified' ? 'Đã xác thực' : 'Chưa đạt'}
              caption={kyc.creditScore ? `Điểm ${kyc.creditScore}` : 'Chưa có điểm'}
              tone={kyc.kycStatus === 'ekyc_verified' ? 'emerald' : 'amber'}
              icon="ri-shield-user-line"
            />
            <MobileMetricCard
              label="Công nợ"
              value={formatCurrencyCompact(totalDebt)}
              caption={overdueDebts.length ? `${overdueDebts.length} khoản quá hạn` : 'Không quá hạn'}
              tone={overdueDebts.length ? 'rose' : 'slate'}
              icon="ri-money-cny-circle-line"
            />
          </div>

          {(fieldName || activeContracts.length > 0) && (
            <div className="flex items-center justify-between gap-3 rounded-xl bg-slate-50 px-3 py-2.5 text-xs">
              <span className="min-w-0 truncate text-slate-500">{fieldName || 'Hồ sơ khoản vay'}</span>
              {activeContracts.length > 0 && (
                <button
                  type="button"
                  onClick={() => onViewContract(activeContracts[0].id)}
                  className="shrink-0 font-semibold text-emerald-700"
                >
                  Xem hợp đồng
                </button>
              )}
            </div>
          )}

          <section className="mobile-panel p-0">
            <button
              type="button"
              onClick={() => setShowChecks((value) => !value)}
              className="flex w-full items-center justify-between gap-3 px-3.5 py-3 text-left"
            >
              <span>
                <span className="block text-sm font-bold text-slate-900">Điều kiện duyệt</span>
                <span className="metric-caption text-[10px] text-slate-400">
                  {checks.filter((item) => item.status === 'pass').length}/{checks.length} điều kiện đạt
                </span>
              </span>
              <i className={`ri-arrow-down-s-line text-lg text-slate-400 transition-transform ${showChecks ? 'rotate-180' : ''}`} />
            </button>
            {showChecks && (
              <div className="space-y-1.5 border-t border-slate-100 p-3">
                {checks.map((item) => (
                  <div key={item.label} className="flex items-center justify-between gap-3 rounded-xl bg-slate-50 px-3 py-2.5">
                    <div className="flex min-w-0 items-center gap-2">
                      <i
                        className={`${
                          item.status === 'pass'
                            ? 'ri-checkbox-circle-fill text-emerald-500'
                            : item.status === 'warn'
                              ? 'ri-error-warning-fill text-amber-500'
                              : 'ri-close-circle-fill text-rose-500'
                        } shrink-0`}
                      />
                      <span className="truncate text-xs font-semibold text-slate-700">{item.label}</span>
                    </div>
                    <span className="max-w-[52%] text-right text-[11px] text-slate-500">{item.value}</span>
                  </div>
                ))}
                {!canApprove && farmerRemaining < loan.soTien && (
                  <button type="button" onClick={onAdjustLimit} className="mt-2 w-full rounded-xl bg-amber-50 px-3 py-2.5 text-xs font-semibold text-amber-700">
                    Điều chỉnh hạn mức nông hộ
                  </button>
                )}
              </div>
            )}
          </section>

          {history.length > 0 && (
            <section className="mobile-panel p-0">
              <button
                type="button"
                onClick={() => setShowHistory((value) => !value)}
                className="flex w-full items-center justify-between gap-3 px-3.5 py-3 text-left"
              >
                <span className="text-sm font-bold text-slate-900">Lịch sử phê duyệt</span>
                <i className={`ri-arrow-down-s-line text-lg text-slate-400 transition-transform ${showHistory ? 'rotate-180' : ''}`} />
              </button>
              {showHistory && (
                <div className="space-y-2 border-t border-slate-100 p-3">
                  {history.map((item) => (
                    <div key={item.id} className="rounded-xl bg-slate-50 p-3">
                      <div className="flex items-center justify-between gap-2">
                        <span className="text-xs font-semibold text-slate-700">{item.newStatus}</span>
                        <span className="text-[10px] text-slate-400">
                          {new Date(item.approvedAt).toLocaleDateString('vi-VN')}
                        </span>
                      </div>
                      <p className="metric-caption mt-1 text-[10px] text-slate-500">{item.approver}</p>
                    </div>
                  ))}
                </div>
              )}
            </section>
          )}
        </div>
      </BottomSheet>

      <ExceptionApprovalModal
        open={showExceptionModal}
        data={exceptionData}
        onClose={() => setShowExceptionModal(false)}
        onConfirm={confirmException}
      />
    </>
  );
}
