import { useState } from 'react';
import { formatVND, formatDate } from '../../../../utils/format';
import { showToast } from '../../../../components/base/Toast';
import { useModalBackHandler } from '../../../../hooks/useModalBackHandler';
import type { AdvanceRequest } from '../../../../types';

interface LoanRejectModalProps {
  loan: AdvanceRequest;
  farmerName: string;
  onClose: () => void;
  onReject: (reasonGroup: string, ghiChu: string) => void;
}

const REASON_GROUPS = [
  'Không đủ điều kiện vay',
  'eKYC chưa hoàn tất',
  'Credit score không đạt',
  'Risk profile nguy cơ cao',
  'Vượt hạn mức nông hộ',
  'Vượt hạn mức HTX',
  'Có nợ quá hạn',
  'Hồ sơ không đầy đủ',
  'Phương án vay không khả thi',
  'Nông hộ không còn hoạt động',
  'Khác',
];

export default function LoanRejectModal({ loan, farmerName, onClose, onReject }: LoanRejectModalProps) {
  useModalBackHandler(true, onClose);
  const [reasonGroup, setReasonGroup] = useState('');
  const [ghiChu, setGhiChu] = useState('');

  const handleSubmit = () => {
    if (!reasonGroup) {
      showToast('Vui lòng chọn nhóm lý do từ chối', 'warning');
      return;
    }
    onReject(reasonGroup, ghiChu.trim());
  };

  return (
    <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
      <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={onClose} />
      <div onClick={(e) => e.stopPropagation()} className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-md max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto animate-modal-slide-up">
        <div className="sticky top-0 bg-white border-b border-slate-200 px-4 sm:px-6 py-3 flex items-center justify-between z-10">
          <div>
            <h3 className="text-base sm:text-lg font-semibold text-slate-900">Từ chối yêu cầu vay</h3>
            <p className="text-xs text-slate-400 mt-0.5">{farmerName} · {formatDate(loan.ngayYeuCau)}</p>
          </div>
          <button type="button" onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400">
            <i className="ri-close-line text-lg" />
          </button>
        </div>

        <div className="px-4 sm:px-6 py-4 space-y-4">
          <div className="bg-slate-50 rounded-lg p-3">
            <div className="flex items-start justify-between gap-2 text-sm">
              <span className="text-slate-500 shrink-0">Mục đích</span>
              <span className="font-medium text-slate-900 text-right break-words max-w-[60%]">{loan.mucDich}</span>
            </div>
            <div className="flex items-start justify-between gap-2 text-sm mt-1">
              <span className="text-slate-500 shrink-0">Số tiền</span>
              <span className="font-medium text-slate-900 text-right break-words max-w-[60%]">{formatVND(loan.soTien)}</span>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">
              Nhóm lý do từ chối <span className="text-red-500">*</span>
            </label>
            <select
              value={reasonGroup}
              onChange={(e) => setReasonGroup(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
            >
              <option value="">-- Chọn nhóm lý do --</option>
              {REASON_GROUPS.map((r) => (
                <option key={r} value={r}>{r}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú chi tiết</label>
            <textarea
              value={ghiChu}
              onChange={(e) => setGhiChu(e.target.value)}
              maxLength={500}
              rows={4}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 resize-none"
              placeholder="Nhập lý do chi tiết, tài liệu cần bổ sung, hạn bổ sung..."
            />
            <p className="text-xs text-slate-400 text-right">{ghiChu.length}/500</p>
          </div>

          <div className="bg-red-50 rounded-lg p-3">
            <div className="flex items-start gap-2">
              <span className="w-5 h-5 flex items-center justify-center text-red-600 shrink-0"><i className="ri-information-line" /></span>
              <p className="text-xs text-red-700">Sau khi từ chối, yêu cầu sẽ chuyển sang trạng thái &quot;Từ chối&quot; và không thể tiếp tục xử lý.</p>
            </div>
          </div>
        </div>

        <div className="sticky bottom-0 bg-white border-t border-slate-200 px-4 sm:px-6 py-3 flex gap-2 justify-end">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2.5 rounded-md text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
          >
            Hủy
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            className="px-4 py-2.5 rounded-md text-sm font-medium text-white bg-red-600 hover:bg-red-700 transition-colors whitespace-nowrap min-h-[44px]"
          >
            Xác nhận từ chối
          </button>
        </div>
      </div>
    </div>
  );
}