import { useState, useEffect } from 'react';
import { todayInputValue, formatNumber } from '../../../../utils/format';
import { useModalBackHandler } from '../../../../hooks/useModalBackHandler';
import { showToast } from '../../../../components/base/Toast';
import { addSupplyHistory, updateSupplyItem } from '../../../../store';
import type { SupplyItem } from '../../../../types';

interface InStockModalProps {
  item: SupplyItem | null;
  onClose: () => void;
}

export function InStockModal({ item, onClose }: InStockModalProps) {
  useModalBackHandler(true, onClose);
  const [form, setForm] = useState({ soLuong: '', ngay: todayInputValue(), loHang: '', hanSuDung: '', lyDo: '', ghiChu: '' });

  useEffect(() => {
    if (item) {
      setForm({ soLuong: '', ngay: todayInputValue(), loHang: item.loHang || '', hanSuDung: item.hanSuDung || '', lyDo: '', ghiChu: '' });
    }
  }, [item]);

  if (!item) return null;

  const handleSave = () => {
    const soLuong = Number(form.soLuong);
    if (!soLuong || soLuong <= 0) { showToast('Số lượng nhập phải lớn hơn 0', 'warning'); return; }
    if (!form.ngay) { showToast('Vui lòng chọn ngày nhập', 'warning'); return; }

    const newStock = item.stock + soLuong;
    const newAvailable = item.available + soLuong;
    let newStatus: SupplyItem['status'] = item.status;
    if (newStock > 0 && item.ngưỡngCảnhBáo && newStock > item.ngưỡngCảnhBáo) newStatus = 'Đủ';

    updateSupplyItem(item.id, {
      stock: newStock,
      available: newAvailable,
      loHang: form.loHang || item.loHang,
      hanSuDung: form.hanSuDung || item.hanSuDung,
      status: newStatus,
    });
    addSupplyHistory({
      supplyId: item.id,
      loai: 'Nhập',
      soLuong,
      soLuongCu: item.stock,
      soLuongMoi: newStock,
      ngay: form.ngay,
      lyDo: form.lyDo || `Nhập kho ${item.name}`,
      nguoiThucHien: 'HTX Hòa Phát',
    });
    showToast(`Nhập kho thành công: +${soLuong} ${item.unit}`, 'success');
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
      <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={onClose} />
      <div onClick={(e) => e.stopPropagation()} className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-md max-h-[90vh] overflow-y-auto animate-modal-slide-up">
        <div className="sticky top-0 bg-white border-b border-slate-100 px-6 py-4 flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold text-slate-900">Nhập kho</h3>
            <p className="text-xs text-slate-400">{item.maVatTu} · {item.name}</p>
          </div>
          <button type="button" onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400"><i className="ri-close-line text-lg" /></button>
        </div>
        <div className="px-6 py-4 space-y-4">
          <div className="bg-slate-50 rounded-lg p-3 flex items-center justify-between">
            <span className="text-sm text-slate-500">Tồn kho hiện tại</span>
            <span className="text-sm font-bold text-slate-900">{formatNumber(item.stock)} {item.unit}</span>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Số lượng nhập <span className="text-red-500">*</span></label>
            <input type="number" value={form.soLuong} onChange={(e) => setForm({ ...form, soLuong: e.target.value })} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder={`Nhập số lượng (${item.unit})`} />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Ngày nhập <span className="text-red-500">*</span></label>
            <input type="date" value={form.ngay} onChange={(e) => setForm({ ...form, ngay: e.target.value })} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Lô hàng</label>
            <input type="text" value={form.loHang} onChange={(e) => setForm({ ...form, loHang: e.target.value })} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder="Lô hàng mới" />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Hạn sử dụng</label>
            <input type="date" value={form.hanSuDung} onChange={(e) => setForm({ ...form, hanSuDung: e.target.value })} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Lý do nhập</label>
            <input type="text" value={form.lyDo} onChange={(e) => setForm({ ...form, lyDo: e.target.value })} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder="Lý do nhập kho" />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú</label>
            <textarea value={form.ghiChu} onChange={(e) => setForm({ ...form, ghiChu: e.target.value })} maxLength={500} rows={2} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder="Ghi chú..." />
          </div>
          {form.soLuong && (
            <div className="bg-emerald-50 rounded-lg p-3 text-sm">
              <p className="text-emerald-700">Tồn kho sau nhập: {formatNumber(item.stock + Number(form.soLuong))} {item.unit}</p>
            </div>
          )}
        </div>
        <div className="sticky bottom-0 bg-white border-t border-slate-100 px-6 py-4 flex gap-3 justify-end">
          <button type="button" onClick={onClose} className="px-4 py-2.5 rounded-lg text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]">Hủy</button>
          <button type="button" onClick={handleSave} className="px-4 py-2.5 rounded-lg text-sm font-medium text-white bg-emerald-700 hover:bg-emerald-800 transition-colors whitespace-nowrap min-h-[44px]">Nhập kho</button>
        </div>
      </div>
    </div>
  );
}