import { useMemo, useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { showToast } from '@/components/base/Toast';
import { addLog, addMaterial, addNotification, getFieldsByFarmer, getMaterialsByFarmer, getSeasonsByFarmer } from '@/store';

interface QuickDiarySheetProps {
  open: boolean;
  onClose: () => void;
  farmerId: string;
}

const RISK_KEYWORDS = ['sâu bệnh', 'vàng lá', 'thiếu nước', 'rầy nâu', 'đạo ôn', 'cháy lá', 'thối rễ', 'héo rũ', 'khô hạn', 'ngập úng'];
const DEMO_SCRIPTS = [
  'Kiểm tra ruộng, cây phát triển ổn định, chưa thấy sâu bệnh mới.',
  'Phát hiện vài khóm lúa vàng lá ở khu phía nam, cần theo dõi thêm.',
  'Đã bón phân theo đúng định lượng, đất đủ ẩm sau khi tưới.',
];

export function QuickDiarySheet({ open, onClose, farmerId }: QuickDiarySheetProps) {
  const [fieldId, setFieldId] = useState('');
  const [title, setTitle] = useState('');
  const [detail, setDetail] = useState('');
  const [materialId, setMaterialId] = useState('');
  const [newMaterialName, setNewMaterialName] = useState('');
  const [materialQty, setMaterialQty] = useState('');
  const [materialUnit, setMaterialUnit] = useState('kg');
  const [recordingField, setRecordingField] = useState<'title' | 'detail' | null>(null);
  const [photoName, setPhotoName] = useState('');

  const fields = useMemo(() => getFieldsByFarmer(farmerId).filter((field) => field.status === 'Đang canh tác'), [farmerId]);
  const seasons = useMemo(() => getSeasonsByFarmer(farmerId), [farmerId]);
  const materials = useMemo(() => getMaterialsByFarmer(farmerId), [farmerId]);

  const linkedSeasonId = useMemo(() => {
    if (!fieldId) return undefined;
    return seasons.find((season) => season.fieldId === fieldId && ['Đang canh tác', 'Chuẩn bị'].includes(season.status))?.id;
  }, [fieldId, seasons]);

  const detectRiskKeywords = (text: string): string[] => {
    const lower = text.toLowerCase();
    return RISK_KEYWORDS.filter((keyword) => lower.includes(keyword.toLowerCase()));
  };

  const appendScript = (target: 'title' | 'detail') => {
    const script = DEMO_SCRIPTS[Math.floor(Math.random() * DEMO_SCRIPTS.length)];
    if (target === 'title') setTitle((prev) => prev ? `${prev} ${script.slice(0, 36)}` : script.slice(0, 44));
    if (target === 'detail') setDetail((prev) => prev ? `${prev}\n${script}` : script);
    showToast('Đã chuyển ghi âm thành nội dung mô phỏng', 'success');
  };

  const startRecord = (target: 'title' | 'detail') => {
    setRecordingField(target);
    showToast('Đang ghi âm realtime (mock)...', 'info');
  };

  const stopRecord = () => {
    if (!recordingField) return;
    appendScript(recordingField);
    setRecordingField(null);
  };

  const handleSave = () => {
    if (!fieldId) {
      showToast('Vui lòng chọn thửa đất', 'warning');
      return;
    }
    if (!title.trim()) {
      showToast('Vui lòng nhập tiêu đề nhật ký', 'warning');
      return;
    }
    if (!detail.trim()) {
      showToast('Vui lòng nhập chi tiết kiểm tra', 'warning');
      return;
    }

    const selectedMaterial = materials.find((item) => item.id === materialId);
    let materialsNote = '';
    if (selectedMaterial && materialQty) materialsNote = `${selectedMaterial.tenVatTu} ${materialQty}${materialUnit}`;
    if (!selectedMaterial && newMaterialName.trim() && materialQty) {
      materialsNote = `${newMaterialName.trim()} ${materialQty}${materialUnit}`;
      addMaterial({
        farmerId,
        seasonId: linkedSeasonId,
        tenVatTu: newMaterialName.trim(),
        nhomVatTu: 'Tự nhập',
        soLuong: Number(materialQty) || 0,
        tonKho: Number(materialQty) || 0,
        donVi: materialUnit,
        nguonGoc: 'Nông hộ tự mua',
        ngayCap: new Date().toISOString().split('T')[0],
        status: 'Đủ',
        ghiChu: 'Tạo nhanh từ nhật ký',
      });
    }

    addLog({
      farmerId,
      fieldId,
      seasonId: linkedSeasonId,
      ngay: new Date().toISOString().split('T')[0],
      hoatDong: title.trim(),
      chiTiet: detail.trim(),
      materialsNote: materialsNote || undefined,
      hinhAnh: photoName || undefined,
      hinhAnhList: photoName ? [photoName] : undefined,
      ghiAmScript: detail.trim(),
    });

    const risks = detectRiskKeywords(`${title} ${detail}`);
    if (risks.length > 0) {
      addNotification({
        farmerId,
        title: 'Cảnh báo rủi ro từ nhật ký',
        content: `Nhật ký "${title}" có từ khóa rủi ro: ${risks.join(', ')}. HTX cần theo dõi hỗ trợ.`,
        type: 'general',
        ngayTao: new Date().toISOString(),
        daDoc: false,
      });
      showToast('Đã lưu nhật ký và tạo cảnh báo rủi ro', 'warning');
    } else {
      showToast('Đã lưu nhật ký mới', 'success');
    }
    resetAndClose();
  };

  const resetAndClose = () => {
    setFieldId('');
    setTitle('');
    setDetail('');
    setMaterialId('');
    setNewMaterialName('');
    setMaterialQty('');
    setMaterialUnit('kg');
    setRecordingField(null);
    setPhotoName('');
    onClose();
  };

  return (
    <BottomSheet open={open} onClose={resetAndClose} title="Tạo nhật ký nhanh">
      <div className="space-y-3">
        <label className="block">
          <span className="mb-1 block text-xs font-semibold text-slate-500">Thửa đất</span>
          <select value={fieldId} onChange={(event) => setFieldId(event.target.value)} className="h-11 w-full rounded-xl border border-slate-200 px-3 text-sm">
            <option value="">Chọn thửa đất</option>
            {fields.map((field) => (
              <option key={field.id} value={field.id}>{field.name} · {field.area}ha</option>
            ))}
          </select>
        </label>

        <VoiceTextField label="Tiêu đề" value={title} onChange={setTitle} recording={recordingField === 'title'} onHoldStart={() => startRecord('title')} onHoldEnd={stopRecord} placeholder="VD: Kiểm tra ruộng sau mưa" />
        <VoiceTextArea label="Chi tiết kiểm tra" value={detail} onChange={setDetail} recording={recordingField === 'detail'} onHoldStart={() => startRecord('detail')} onHoldEnd={stopRecord} />

        <div className="rounded-xl border border-slate-200 bg-white p-3">
          <div className="mb-2 flex items-center justify-between">
            <p className="text-xs font-semibold text-slate-700">Vật tư đã sử dụng</p>
            <span className="text-[10px] text-slate-400">Nếu có</span>
          </div>
          <div className="grid grid-cols-[1fr_auto_auto] gap-2">
            <select value={materialId} onChange={(event) => setMaterialId(event.target.value)} className="min-w-0 rounded-lg border border-slate-200 px-2 py-2 text-xs">
              <option value="">+ Vật tư mới</option>
              {materials.map((material) => (
                <option key={material.id} value={material.id}>{material.tenVatTu}</option>
              ))}
            </select>
            <input value={materialQty} onChange={(event) => setMaterialQty(event.target.value)} placeholder="SL" className="w-16 rounded-lg border border-slate-200 px-2 py-2 text-xs" />
            <input value={materialUnit} onChange={(event) => setMaterialUnit(event.target.value)} placeholder="kg" className="w-14 rounded-lg border border-slate-200 px-2 py-2 text-xs" />
          </div>
          {!materialId && (
            <input value={newMaterialName} onChange={(event) => setNewMaterialName(event.target.value)} placeholder="Tên vật tư mới" className="mt-2 h-10 w-full rounded-lg border border-slate-200 px-3 text-xs" />
          )}
        </div>

        <div className="grid grid-cols-2 gap-2">
          <button type="button" onClick={() => setPhotoName(`album_${Date.now()}.jpg`)} className="min-h-11 rounded-xl border border-slate-200 text-xs font-bold text-slate-700">
            <i className="ri-image-add-line mr-1" />
            Thêm ảnh
          </button>
          <button type="button" onClick={() => setPhotoName(`camera_${Date.now()}.jpg`)} className="min-h-11 rounded-xl border border-slate-200 text-xs font-bold text-slate-700">
            <i className="ri-camera-line mr-1" />
            Chụp ảnh
          </button>
        </div>
        {photoName && <p className="rounded-lg bg-slate-50 px-3 py-2 text-xs text-slate-500">Đã thêm: {photoName}</p>}

        <button type="button" onClick={handleSave} className="min-h-12 w-full rounded-xl bg-agrida-600 text-sm font-bold text-white">
          Lưu nhật ký
        </button>
      </div>
    </BottomSheet>
  );
}

function VoiceButton({ recording, onHoldStart, onHoldEnd }: { recording: boolean; onHoldStart: () => void; onHoldEnd: () => void }) {
  return (
    <button
      type="button"
      onMouseDown={onHoldStart}
      onMouseUp={onHoldEnd}
      onMouseLeave={recording ? onHoldEnd : undefined}
      onTouchStart={onHoldStart}
      onTouchEnd={onHoldEnd}
      className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-lg ${recording ? 'bg-rose-500 text-white animate-pulse' : 'bg-sky-100 text-sky-700'}`}
      aria-label="Giữ để ghi âm"
    >
      <i className={recording ? 'ri-stop-circle-fill' : 'ri-mic-line'} />
    </button>
  );
}

function VoiceTextField({ label, value, onChange, recording, onHoldStart, onHoldEnd, placeholder }: { label: string; value: string; onChange: (value: string) => void; recording: boolean; onHoldStart: () => void; onHoldEnd: () => void; placeholder: string }) {
  return (
    <label className="block">
      <span className="mb-1 block text-xs font-semibold text-slate-500">{label}</span>
      <div className="flex items-center gap-2 rounded-2xl border border-slate-200 bg-white p-2">
        <input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="min-w-0 flex-1 border-0 px-1 text-sm outline-none" />
        <VoiceButton recording={recording} onHoldStart={onHoldStart} onHoldEnd={onHoldEnd} />
      </div>
    </label>
  );
}

function VoiceTextArea({ label, value, onChange, recording, onHoldStart, onHoldEnd }: { label: string; value: string; onChange: (value: string) => void; recording: boolean; onHoldStart: () => void; onHoldEnd: () => void }) {
  return (
    <label className="block">
      <span className="mb-1 block text-xs font-semibold text-slate-500">{label}</span>
      <div className="flex items-start gap-2 rounded-2xl border border-slate-200 bg-white p-2">
        <textarea value={value} onChange={(event) => onChange(event.target.value)} placeholder="Mô tả tình trạng, công việc đã làm..." rows={4} className="min-w-0 flex-1 resize-none border-0 px-1 text-sm outline-none" />
        <VoiceButton recording={recording} onHoldStart={onHoldStart} onHoldEnd={onHoldEnd} />
      </div>
    </label>
  );
}
