import { useState, useCallback, useMemo, useEffect } from 'react';
import { useStore } from '../../../hooks/useStore';
import {
  getHarvests, getFarmers, getFieldsByFarmer, getSeasonsByFarmer,
  getSeasons, getContracts, updateHarvest, addHarvest, deleteHarvest,
  updateSeason, addEditHistory, updateContract, updateRiskProfile,
  getRiskProfileByFarmer,
} from '../../../store';
import { showToast } from '../../../components/base/Toast';
import { formatNumber } from '../../../utils/format';
import { confirmModal } from '../../../components/base/ConfirmModal';
import { EmptyState } from '../../../components/base/EmptyState';
import HarvestStats from './components/HarvestStats';
import HarvestFilters from './components/HarvestFilters';
import HarvestCard from './components/HarvestCard';
import HarvestFormModal from './components/HarvestFormModal';
import HarvestDetailModal from './components/HarvestDetailModal';
import HarvestConfirmModal from './components/HarvestConfirmModal';
import type { Harvest } from '../../../types';

export default function HtxHarvestPage() {
  useStore();
  const harvests = getHarvests();
  const farmers = getFarmers();
  const allSeasons = getSeasons();
  const allContracts = getContracts();

  const [filtered, setFiltered] = useState<Harvest[]>(harvests);
  const [formOpen, setFormOpen] = useState(false);
  const [editItem, setEditItem] = useState<Harvest | null>(null);
  const [detailItem, setDetailItem] = useState<Harvest | null>(null);
  const [confirmItem, setConfirmItem] = useState<Harvest | null>(null);

  const farmerOptions = useMemo(() => farmers.map((f) => ({ id: f.id, name: f.name })), [farmers]);
  const seasonOptions = useMemo(() => allSeasons.map((s) => ({ id: s.id, name: s.name })), [allSeasons]);

  // Sync filtered when harvests change
  useEffect(() => {
    if (filtered.length === 0 && harvests.length > 0) {
      setFiltered(harvests);
    }
  }, [harvests, filtered.length]);

  const getFieldName = (farmerId: string, id?: string) => getFieldsByFarmer(farmerId).find((f) => f.id === id)?.name || '-';
  const getSeasonName = (id?: string) => allSeasons.find((s) => s.id === id)?.name || '-';
  const getSeasonExpectedYield = useCallback((id?: string) => {
    const s = allSeasons.find((se) => se.id === id);
    if (!s) return 0;
    return s.expectedYield * 1000; // convert to kg
  }, [allSeasons]);

  const getContractWarning = (harvest: Harvest) => {
    const contracts = allContracts.filter(
      (c) => c.farmerId === harvest.farmerId && c.seasonIds?.includes(harvest.seasonId || '')
    );
    const active = contracts.find((c) => c.status === 'Đang hiệu lực' || c.status === 'Sắp hết hạn');
    if (active) return `Ảnh hưởng đến hợp đồng ${active.soHopDong}`;
    return undefined;
  };

  const openCreate = () => {
    setEditItem(null);
    setFormOpen(true);
  };

  const openEdit = (item: Harvest) => {
    setEditItem(item);
    setFormOpen(true);
  };

  const openDetail = (item: Harvest) => {
    setDetailItem(item);
  };

  const openConfirm = (item: Harvest) => {
    setConfirmItem(item);
  };

  const handleSave = useCallback((data: Omit<Harvest, 'id' | 'maLanThuHoach'>) => {
    if (editItem) {
      // Update existing
      const oldData = { ...editItem };
      const updated = {
        ...oldData,
        ...data,
      };
      updateHarvest(editItem.id, updated);

      // Track edit history
      if (oldData.soLuong !== updated.soLuong) {
        addEditHistory({
          entityType: 'Harvest',
          entityId: editItem.id,
          farmerId: editItem.farmerId,
          truong: 'soLuong',
          giaTriCu: String(oldData.soLuong),
          giaTriMoi: String(updated.soLuong),
          ngaySua: new Date().toISOString(),
          nguoiSua: 'HTX Hòa Phát',
        });
      }
      if (oldData.status !== updated.status) {
        addEditHistory({
          entityType: 'Harvest',
          entityId: editItem.id,
          farmerId: editItem.farmerId,
          truong: 'status',
          giaTriCu: oldData.status,
          giaTriMoi: updated.status,
          ngaySua: new Date().toISOString(),
          nguoiSua: 'HTX Hòa Phát',
        });
      }

      showToast('Đã cập nhật lần thu hoạch', 'success');
    } else {
      // Create new
      const nextNum = harvests.length + 1;
      const maLanThuHoach = `TH-${String(nextNum).padStart(3, '0')}`;
      const newHarvest: Harvest = {
        id: `ha${Date.now()}`,
        maLanThuHoach,
        ...data,
        lichSuCapNhat: [{ thoiGian: new Date().toISOString(), nguoiCapNhat: 'HTX Hòa Phát', noiDung: 'HTX tạo lần thu hoạch mới' }],
      } as Harvest;
      addHarvest(newHarvest);
      showToast('Đã tạo lần thu hoạch mới', 'success');
    }
    setFormOpen(false);
    setEditItem(null);
  }, [editItem, harvests.length]);

  const handleDelete = async (item: Harvest) => {
    const ok = await confirmModal({
      title: 'Xóa lần thu hoạch',
      message: `Bạn có chắc muốn xóa "${item.maLanThuHoach}" không?`,
      variant: 'danger',
      confirmText: 'Xóa',
    });
    if (ok) {
      // Soft delete
      updateHarvest(item.id, { isDeleted: true, status: 'Hủy' });
      showToast('Đã xóa lần thu hoạch', 'success');
    }
  };

  const handleConfirmHarvest = useCallback((confirmedYield: number, qualityNote: string) => {
    if (!confirmItem) return;
    const h = confirmItem;
    const season = allSeasons.find((s) => s.id === h.seasonId);
    const seasonExpected = getSeasonExpectedYield(h.seasonId);

    const isLowYield = seasonExpected > 0 && confirmedYield < seasonExpected * 0.8;
    const newStatus: Harvest['status'] = isLowYield ? 'Sản lượng thấp' : 'HTX đã xác nhận';

    const lichSu = [
      ...(h.lichSuCapNhat || []),
      { thoiGian: new Date().toISOString(), nguoiCapNhat: 'HTX Hòa Phát', noiDung: `HTX xác nhận sản lượng ${formatNumber(confirmedYield)} ${h.donVi}${isLowYield ? ' - cảnh báo sản lượng thấp' : ''}` },
    ];

    // 1. Update harvest
    updateHarvest(h.id, {
      actualYieldConfirmed: confirmedYield,
      ghiChuChatLuong: qualityNote || h.ghiChuChatLuong,
      status: newStatus,
      canhBao: isLowYield ? 'Sản lượng thấp' : h.canhBao,
      lichSuCapNhat: lichSu,
    });

    // 2. Update season
    if (season) {
      const seasonUpdates: Partial<typeof season> = {
        status: isLowYield ? 'Có rủi ro' : 'Đã thu hoạch',
        ghiChu: isLowYield
          ? `${season.ghiChu || ''} | Sản lượng thực tế ${formatNumber(confirmedYield)} ${h.donVi} thấp hơn 20% dự kiến`.trim()
          : `${season.ghiChu || ''} | Đã thu hoạch ${formatNumber(confirmedYield)} ${h.donVi}`.trim(),
      };
      updateSeason(season.id, seasonUpdates);
    }

    // 3. Update contract
    const relatedContracts = allContracts.filter(
      (c) => c.farmerId === h.farmerId && c.seasonIds?.includes(h.seasonId || '')
    );
    relatedContracts.forEach((contract) => {
      updateContract(contract.id, {
        ghiChu: isLowYield
          ? `${contract.ghiChu || ''} | Sản lượng thấp: ${formatNumber(confirmedYield)} ${h.donVi}`.trim()
          : undefined,
      });
    });

    // 4. Update risk profile if low yield
    if (isLowYield) {
      const risk = getRiskProfileByFarmer(h.farmerId);
      if (risk) {
        updateRiskProfile(risk.id, {
          mucDo: 'Cần chú ý',
          moTa: `${risk.moTa} | Thu hoạch ${h.maLanThuHoach} sản lượng thấp (${formatNumber(confirmedYield)} ${h.donVi}, chỉ ${((confirmedYield / seasonExpected) * 100).toFixed(1)}% dự kiến).`,
          ngayCapNhat: new Date().toISOString().split('T')[0],
        });
      } else {
        // Create risk profile if not exists
        addEditHistory({
          entityType: 'RiskProfile',
          entityId: h.farmerId,
          farmerId: h.farmerId,
          truong: 'mucDo',
          giaTriCu: 'Chưa có',
          giaTriMoi: 'Cần chú ý',
          ngaySua: new Date().toISOString(),
          nguoiSua: 'HTX Hòa Phát',
        });
      }
    }

    showToast('Đã xác nhận thu hoạch', 'success');
    setConfirmItem(null);
    setDetailItem(null);
  }, [confirmItem, allSeasons, allContracts, getSeasonExpectedYield]);

  // Check for late harvests via useEffect (side effect, not useMemo)
  useEffect(() => {
    const today = new Date();
    harvests.forEach((h) => {
      if (h.ngayDuKien && !h.ngayThuHoach && h.status !== 'Hủy' && h.status !== 'Hoàn thành' && h.status !== 'HTX đã xác nhận') {
        const duKien = new Date(h.ngayDuKien);
        if (duKien < today && h.canhBao !== 'Thu hoạch trễ') {
          updateHarvest(h.id, { canhBao: 'Thu hoạch trễ' });
        }
      }
    });
  }, [harvests]);

  const displayList = filtered.length > 0 ? filtered : harvests;
  const activeList = displayList.filter((h) => !h.isDeleted);

  return (
    <div className="px-4 py-4 pb-4 space-y-4 max-w-[1200px] mx-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h2 className="text-xl font-bold text-slate-900">Quản lý thu hoạch</h2>
          <p className="text-sm text-slate-500 mt-1">
            Quản lý các lần thu hoạch theo mùa vụ, xác nhận sản lượng và theo dõi chất lượng.
          </p>
        </div>
        <button
          type="button"
          onClick={openCreate}
          className="bg-emerald-700 hover:bg-emerald-800 text-white text-sm font-medium px-4 py-2.5 rounded-lg transition-colors whitespace-nowrap min-h-[44px] flex items-center gap-2 shrink-0"
        >
          <span className="w-4 h-4 flex items-center justify-center"><i className="ri-add-line" /></span>
          Tạo lần thu hoạch
        </button>
      </div>

      {/* Stats */}
      <HarvestStats />

      {/* Filters */}
      <HarvestFilters
        harvests={harvests}
        farmers={farmerOptions}
        seasons={seasonOptions}
        onFilterChange={setFiltered}
      />

      {/* List */}
      {activeList.length === 0 ? (
        <EmptyState
          icon="ri-shopping-basket-line"
          title="Chưa có thu hoạch"
          description="Chưa có dữ liệu thu hoạch nào. Hãy tạo lần thu hoạch đầu tiên."
        />
      ) : (
        <div className="space-y-3">
          {activeList.map((h) => (
            <HarvestCard
              key={h.id}
              harvest={h}
              farmerName={farmers.find((f) => f.id === h.farmerId)?.name || '-'}
              seasonName={getSeasonName(h.seasonId)}
              fieldName={getFieldName(h.farmerId, h.fieldId)}
              seasonExpectedYield={getSeasonExpectedYield(h.seasonId)}
              onViewDetail={() => openDetail(h)}
              onConfirm={() => openConfirm(h)}
            />
          ))}
        </div>
      )}

      {/* Form modal */}
      {formOpen && (
        <HarvestFormModal
          editItem={editItem}
          onClose={() => { setFormOpen(false); setEditItem(null); }}
          onSave={handleSave}
        />
      )}

      {/* Detail modal */}
      {detailItem && (
        <HarvestDetailModal
          harvest={detailItem}
          farmerName={farmers.find((f) => f.id === detailItem.farmerId)?.name || '-'}
          seasonName={getSeasonName(detailItem.seasonId)}
          fieldName={getFieldName(detailItem.farmerId, detailItem.fieldId)}
          seasonExpectedYield={getSeasonExpectedYield(detailItem.seasonId)}
          contractWarning={getContractWarning(detailItem)}
          onClose={() => setDetailItem(null)}
          onConfirm={() => {
            setDetailItem(null);
            setConfirmItem(detailItem);
          }}
        />
      )}

      {/* Confirm modal */}
      {confirmItem && (
        <HarvestConfirmModal
          harvest={confirmItem}
          seasonExpectedYield={getSeasonExpectedYield(confirmItem.seasonId)}
          onClose={() => setConfirmItem(null)}
          onConfirm={handleConfirmHarvest}
        />
      )}
    </div>
  );
}
