import { useState, useRef, useCallback } from 'react';
import { formatVND, todayInputValue } from '@/utils/format';
import { showToast } from '@/components/base/Toast';
import { useModalBackHandler } from '@/hooks/useModalBackHandler';
import type { Season } from '@/types';

const NHOM_VAT_TU = [
  'Giống', 'Phân bón', 'Thuốc BVTV', 'Hóa chất', 'Bao bì', 'Công cụ',
  'Dịch vụ thuê máy', 'Dịch vụ vận chuyển', 'Khác',
];

interface LoanFormModalProps {
  seasons: Season[];
  hanMucConLai: number;
  isKycVerified: boolean;
  hasOverdue: boolean;
  stk?: { nganHang: string; stkMask: string; chuTaiKhoan: string };
  contracts: { id: string; soHopDong: string; status: string }[];
  onSubmit: (data: {
    loai: 'Tiền' | 'Vật tư';
    seasonId: string;
    soTien: number;
    mucDich: string;
    tenVatTu?: string;
    soLuongVatTu?: number;
    donViVatTu?: string;
    nhomVatTu?: string;
    thoiGianMongMuon?: string;
    ghiChu?: string;
    hinhAnh?: string;
    isOverLimit: boolean;
    ngayYeuCau: string;
    contractId?: string;
  }) => void;
  onClose: () => void;
}

export function LoanFormModal({
  seasons, hanMucConLai, isKycVerified, hasOverdue, stk, contracts, onSubmit, onClose,
}: LoanFormModalProps) {
  useModalBackHandler(true, onClose);
  const [step, setStep] = useState<1 | 2>(1);
  const [loai, setLoai] = useState<'Tiền' | 'Vật tư'>('Tiền');
  const [seasonId, setSeasonId] = useState(seasons[0]?.id || '');
  const [contractId, setContractId] = useState('');
  const [soTien, setSoTien] = useState('');
  const [mucDich, setMucDich] = useState('');
  const [tenVatTu, setTenVatTu] = useState('');
  const [soLuongVatTu, setSoLuongVatTu] = useState('');
  const [donViVatTu, setDonViVatTu] = useState('');
  const [nhomVatTu, setNhomVatTu] = useState(NHOM_VAT_TU[0]);
  const [thoiGianMongMuon, setThoiGianMongMuon] = useState('');
  const [ghiChu, setGhiChu] = useState('');
  const [previews, setPreviews] = useState<string[]>([]);

  const fileRef = useRef<HTMLInputElement>(null);

  const soTienNum = Number(soTien) || 0;
  const isOverLimit = soTienNum > hanMucConLai;

  // Only active contracts
  const activeContracts = contracts.filter((c) =>
    c.status === 'Đang hiệu lực' || c.status === 'Sắp hết hạn'
  );
  const expiredContracts = contracts.filter((c) => c.status === 'Hết hạn');
  const hasExpiredOnly = activeContracts.length === 0 && expiredContracts.length > 0;

  // Only active/valid seasons
  const activeSeasons = seasons.filter((s) =>
    s.status === 'Đang canh tác' || s.status === 'Chuẩn bị' || s.status === 'Sắp thu hoạch'
  );

  const selectedContract = contractId ? contracts.find((c) => c.id === contractId) : null;
  const contractWarning = selectedContract?.status === 'Sắp hết hạn';
  const contractExpired = selectedContract?.status === 'Hết hạn';

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach((file) => {
      setPreviews((prev) => [...prev, URL.createObjectURL(file)]);
    });
    if (fileRef.current) fileRef.current.value = '';
  }, []);

  const removePreview = (idx: number) => {
    setPreviews((prev) => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = () => {
    if (loai === 'Tiền' && !isKycVerified) {
      showToast('Bạn cần xác thực eKYC trước khi gửi yêu cầu vay tiền', 'warning');
      return;
    }
    if (loai === 'Tiền' && (!soTienNum || soTienNum <= 0)) {
      showToast('Vui lòng nhập số tiền hợp lệ', 'warning');
      return;
    }
    if (!mucDich.trim()) {
      showToast('Vui lòng nhập mục đích sử dụng', 'warning');
      return;
    }
    if (!seasonId) {
      showToast('Vui lòng chọn mùa vụ', 'warning');
      return;
    }
    if (loai === 'Vật tư' && !tenVatTu.trim()) {
      showToast('Vui lòng nhập tên vật tư', 'warning');
      return;
    }
    if (hasOverdue && loai === 'Tiền') {
      showToast('Bạn có nợ quá hạn. Vui lòng thanh toán trước khi tạo yêu cầu mới.', 'warning');
      return;
    }
    if (contractExpired && loai === 'Tiền') {
      showToast('Hợp đồng đã hết hạn. Vui lòng chọn hợp đồng khác hoặc liên hệ HTX để gia hạn.', 'warning');
      return;
    }

    onSubmit({
      loai,
      seasonId,
      soTien: loai === 'Tiền' ? soTienNum : 0,
      mucDich: mucDich.trim(),
      tenVatTu: loai === 'Vật tư' ? tenVatTu.trim() : undefined,
      soLuongVatTu: loai === 'Vật tư' ? (Number(soLuongVatTu) || undefined) : undefined,
      donViVatTu: loai === 'Vật tư' ? (donViVatTu.trim() || undefined) : undefined,
      nhomVatTu: loai === 'Vật tư' ? nhomVatTu : undefined,
      thoiGianMongMuon: thoiGianMongMuon || undefined,
      ghiChu: ghiChu.trim() || undefined,
      hinhAnh: previews[0] || undefined,
      isOverLimit: loai === 'Tiền' ? isOverLimit : false,
      ngayYeuCau: todayInputValue(),
      contractId: contractId || undefined,
    });
  };

  return (
    <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
      <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={onClose} />
      <div onClick={(e) => e.stopPropagation()} className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-lg max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto animate-modal-slide-up">
        <div className="sticky top-0 bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between z-10">
          <h3 className="text-sm font-semibold text-slate-900">
            {step === 1 ? 'Tạo yêu cầu vay' : loai === 'Tiền' ? 'Vay tiền' : 'Vay vật tư'}
          </h3>
          <button type="button" onClick={onClose} className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-slate-600 rounded-full hover:bg-slate-100">
            <i className="ri-close-line text-lg" />
          </button>
        </div>

        <div className="p-4 space-y-4">
          {/* eKYC & overdue warnings */}
          {!isKycVerified && (
            <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 flex items-start gap-2">
              <span className="w-5 h-5 flex items-center justify-center shrink-0 text-amber-600 mt-0.5"><i className="ri-error-warning-line" /></span>
              <div>
                <p className="text-xs font-medium text-amber-800">Chưa xác thực eKYC</p>
                <p className="text-[10px] text-amber-600 mt-0.5">Bạn cần hoàn tất eKYC trước khi gửi yêu cầu vay. Vào Hồ sơ → Xác thực ngay.</p>
              </div>
            </div>
          )}
          {hasOverdue && (
            <div className="bg-red-50 border border-red-200 rounded-xl p-3 flex items-start gap-2">
              <span className="w-5 h-5 flex items-center justify-center shrink-0 text-red-600 mt-0.5"><i className="ri-alert-line" /></span>
              <div>
                <p className="text-xs font-medium text-red-800">Có nợ quá hạn</p>
                <p className="text-[10px] text-red-600 mt-0.5">Vui lòng thanh toán khoản nợ quá hạn trước khi tạo yêu cầu vay mới.</p>
              </div>
            </div>
          )}

          {/* Contract expired warning */}
          {hasExpiredOnly && loai === 'Tiền' && (
            <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 flex items-start gap-2">
              <span className="w-5 h-5 flex items-center justify-center shrink-0 text-amber-600 mt-0.5"><i className="ri-file-warning-line" /></span>
              <div>
                <p className="text-xs font-medium text-amber-800">Hợp đồng nền đã hết hiệu lực</p>
                <p className="text-[10px] text-amber-600 mt-0.5">Các hợp đồng bao tiêu đã hết hạn. Bạn vẫn có thể gửi yêu cầu nhưng HTX sẽ cần rà soát hạn mức.</p>
              </div>
            </div>
          )}

          {step === 1 && (
            <div className="space-y-3">
              <p className="text-sm text-slate-600">Chọn loại vay bạn muốn gửi:</p>
              <button
                type="button"
                onClick={() => { setLoai('Tiền'); setStep(2); }}
                className={`w-full text-left px-4 py-3 rounded-xl border transition-colors flex items-center gap-3 ${
                  loai === 'Tiền' ? 'border-emerald-300 bg-emerald-50' : 'border-slate-200 hover:border-slate-300'
                }`}
              >
                <span className="w-8 h-8 flex items-center justify-center rounded-full bg-emerald-100 text-emerald-700"><i className="ri-money-cny-circle-line" /></span>
                <div>
                  <p className="text-sm font-semibold text-slate-900">Vay tiền</p>
                  <p className="text-xs text-slate-500">Yêu cầu vay tiền mặt hoặc chuyển khoản</p>
                </div>
              </button>
              <button
                type="button"
                onClick={() => { setLoai('Vật tư'); setStep(2); }}
                className={`w-full text-left px-4 py-3 rounded-xl border transition-colors flex items-center gap-3 ${
                  loai === 'Vật tư' ? 'border-emerald-300 bg-emerald-50' : 'border-slate-200 hover:border-slate-300'
                }`}
              >
                <span className="w-8 h-8 flex items-center justify-center rounded-full bg-sky-100 text-sky-700"><i className="ri-seedling-line" /></span>
                <div>
                  <p className="text-sm font-semibold text-slate-900">Vay vật tư</p>
                  <p className="text-xs text-slate-500">Yêu cầu cung cấp vật tư nông nghiệp</p>
                </div>
              </button>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-4">
              <button
                type="button"
                onClick={() => setStep(1)}
                className="text-xs text-slate-500 hover:text-slate-700 flex items-center gap-1"
              >
                <span className="w-3 h-3 flex items-center justify-center"><i className="ri-arrow-left-line" /></span>
                Quay lại
              </button>

              {/* Season dropdown - only active */}
              <div>
                <label className="block text-xs font-medium text-slate-700 mb-1">Mùa vụ <span className="text-red-500">*</span></label>
                <select
                  value={seasonId}
                  onChange={(e) => setSeasonId(e.target.value)}
                  className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                >
                  <option value="">Chọn mùa vụ</option>
                  {activeSeasons.map((s) => (<option key={s.id} value={s.id}>{s.maMuaVu} - {s.name} ({s.cayTrong})</option>))}
                </select>
                {activeSeasons.length === 0 && (
                  <p className="text-[10px] text-amber-600 mt-1 flex items-center gap-1">
                    <i className="ri-error-warning-line" /> Chưa có mùa vụ đang canh tác
                  </p>
                )}
              </div>

              {/* Contract dropdown */}
              {loai === 'Tiền' && activeContracts.length > 0 && (
                <div>
                  <label className="block text-xs font-medium text-slate-700 mb-1">Hợp đồng liên quan</label>
                  <select
                    value={contractId}
                    onChange={(e) => setContractId(e.target.value)}
                    className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                  >
                    <option value="">Không chọn</option>
                    {activeContracts.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.soHopDong} {c.status === 'Sắp hết hạn' ? '(Sắp HH)' : '(Hiệu lực)'}
                      </option>
                    ))}
                  </select>
                  {contractWarning && (
                    <p className="text-[10px] text-amber-600 mt-1 flex items-center gap-1">
                      <i className="ri-error-warning-line" /> Hợp đồng sắp hết hạn - vẫn có thể gửi yêu cầu
                    </p>
                  )}
                </div>
              )}

              {loai === 'Tiền' && (
                <>
                  <div>
                    <label className="block text-xs font-medium text-slate-700 mb-1">
                      Số tiền đề nghị (VND) <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="number"
                      value={soTien}
                      onChange={(e) => setSoTien(e.target.value)}
                      className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                      placeholder="Nhập số tiền"
                    />
                    {isOverLimit && (
                      <div className="mt-1.5 bg-red-50 border border-red-200 rounded-lg p-2.5 flex items-start gap-2">
                        <span className="w-4 h-4 flex items-center justify-center text-red-600 shrink-0 mt-0.5"><i className="ri-error-warning-line" /></span>
                        <p className="text-xs text-red-700">
                          Số tiền <strong>{formatVND(soTienNum)}</strong> vượt hạn mức còn lại <strong>{formatVND(hanMucConLai)}</strong>. Bạn vẫn có thể gửi, HTX sẽ xem xét.
                        </p>
                      </div>
                    )}
                    <p className="text-[10px] text-slate-400 mt-1">Hạn mức còn: {formatVND(hanMucConLai)}</p>
                  </div>

                  {stk && (
                    <div className="bg-slate-50 rounded-xl p-3 space-y-1">
                      <p className="text-[10px] text-slate-400 uppercase tracking-wider mb-1">Tài khoản nhận</p>
                      <p className="text-xs font-medium text-slate-800">{stk.nganHang}</p>
                      <p className="text-xs text-slate-600">{stk.stkMask} - {stk.chuTaiKhoan}</p>
                    </div>
                  )}
                </>
              )}

              {loai === 'Vật tư' && (
                <>
                  <div>
                    <label className="block text-xs font-medium text-slate-700 mb-1">Nhóm vật tư</label>
                    <select
                      value={nhomVatTu}
                      onChange={(e) => setNhomVatTu(e.target.value)}
                      className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
                    >
                      {NHOM_VAT_TU.map((n) => (<option key={n} value={n}>{n}</option>))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-slate-700 mb-1">Tên vật tư <span className="text-red-500">*</span></label>
                    <input type="text" value={tenVatTu} onChange={(e) => setTenVatTu(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder="Tên vật tư cụ thể" />
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-xs font-medium text-slate-700 mb-1">Số lượng</label>
                      <input type="number" value={soLuongVatTu} onChange={(e) => setSoLuongVatTu(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder="Số lượng" />
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-slate-700 mb-1">Đơn vị</label>
                      <input type="text" value={donViVatTu} onChange={(e) => setDonViVatTu(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder="kg, lít..." />
                    </div>
                  </div>
                </>
              )}

              <div>
                <label className="block text-xs font-medium text-slate-700 mb-1">Mục đích sử dụng <span className="text-red-500">*</span></label>
                <input type="text" value={mucDich} onChange={(e) => setMucDich(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder={loai === 'Tiền' ? 'Mục đích sử dụng tiền' : 'Lý do cần vật tư'} />
              </div>

              <div>
                <label className="block text-xs font-medium text-slate-700 mb-1">Ngày mong muốn nhận</label>
                <input type="date" value={thoiGianMongMuon} onChange={(e) => setThoiGianMongMuon(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" />
              </div>

              <div>
                <label className="block text-xs font-medium text-slate-700 mb-1">Ghi chú</label>
                <input type="text" value={ghiChu} onChange={(e) => setGhiChu(e.target.value)} className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder="Ghi chú thêm..." />
              </div>

              <div>
                <label className="block text-xs font-medium text-slate-700 mb-2">Ảnh / chứng từ</label>
                <button
                  type="button"
                  onClick={() => fileRef.current?.click()}
                  className="px-3 py-2 rounded-lg border border-slate-200 text-xs font-medium text-slate-700 hover:bg-slate-50 flex items-center gap-1 whitespace-nowrap"
                >
                  <span className="w-3 h-3 flex items-center justify-center"><i className="ri-camera-line" /></span>
                  Chụp ảnh / Chọn ảnh
                </button>
                <input ref={fileRef} type="file" accept="image/*" multiple className="hidden" onChange={handleFileSelect} />
                {previews.length > 0 && (
                  <div className="grid grid-cols-3 gap-2 mt-2">
                    {previews.map((url, idx) => (
                      <div key={idx} className="relative aspect-square rounded-lg overflow-hidden bg-slate-100">
                        <img src={url} alt={`preview-${idx}`} className="w-full h-full object-cover" />
                        <button type="button" onClick={() => removePreview(idx)} className="absolute top-1 right-1 w-5 h-5 bg-black/50 rounded-full text-white flex items-center justify-center text-[10px]">
                          <i className="ri-close-line" />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        <div className="sticky bottom-0 bg-white border-t border-slate-100 px-4 py-3 flex gap-2 justify-end">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2.5 rounded-lg text-xs font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
          >
            Hủy
          </button>
          {step === 2 && (
            <button
              type="button"
              onClick={handleSubmit}
              disabled={loai === 'Tiền' && (!isKycVerified || hasOverdue)}
              className={`px-4 py-2.5 rounded-lg text-xs font-bold text-white transition-colors whitespace-nowrap min-h-[44px] ${
                loai === 'Vật tư' || (isKycVerified && !hasOverdue)
                  ? 'bg-emerald-600 hover:bg-emerald-700'
                  : 'bg-slate-300 cursor-not-allowed'
              }`}
            >
              Gửi yêu cầu
            </button>
          )}
        </div>
      </div>
    </div>
  );
}