// ============================================================
// AGRIDA — DEBT REMINDER SCHEDULER
// Automatically schedules and sends in-app reminders for debt
// approaching due date at thresholds: 7d, 3d, 1d, 12h, 6h, 1h, due, overdue.
// Each threshold fires only once per debt. Respects PaymentIntent
// status to avoid "chưa thanh toán" reminders when payment is in progress.
// ============================================================

import {
  getDebts,
  getReminderLogs,
  hasReminderSent,
  addReminderLog,
  addNotification,
  updateDebt,
  addEditHistory,
  getRiskProfiles,
  updateRiskProfile,
  getPaymentIntents,
  getFarmers,
} from '@/store';
import type { Debt, ReminderThreshold } from '@/types';
import { formatCompactCurrency } from '@/utils/format';

// ─── Threshold Config ───────────────────────────────────────

interface ThresholdConfig {
  threshold: ReminderThreshold;
  title: string;
  contentTemplate: (debt: Debt) => string;
  hoursBefore: number; // negative = after due
  priority: 'low' | 'medium' | 'high' | 'critical';
}

const THRESHOLD_CONFIGS: ThresholdConfig[] = [
  {
    threshold: '7d',
    title: 'Khoản vay sắp đến hạn sau 7 ngày',
    contentTemplate: (d) => `Khoản vay ${d.maKhoanVay || d.id} của bạn sẽ đến hạn vào ngày ${d.ngayDenHan}. Số tiền còn nợ: ${formatCompactCurrency(d.conNo)}. Vui lòng chuẩn bị kế hoạch tất toán.`,
    hoursBefore: 7 * 24,
    priority: 'low',
  },
  {
    threshold: '3d',
    title: 'Cần chuẩn bị tất toán khoản vay',
    contentTemplate: (d) => `Khoản vay ${d.maKhoanVay || d.id} còn 3 ngày nữa đến hạn. Số tiền cần tất toán: ${formatCompactCurrency(d.conNo)}. Vui lòng chuẩn bị tiền và làm theo hướng dẫn QR.`,
    hoursBefore: 3 * 24,
    priority: 'medium',
  },
  {
    threshold: '1d',
    title: 'Khoản vay đến hạn trong 24 giờ',
    contentTemplate: (d) => `GẤP: Khoản vay ${d.maKhoanVay || d.id} sẽ đến hạn vào NGÀY MAI (${d.ngayDenHan}). Số tiền: ${formatCompactCurrency(d.conNo)}. Thanh toán ngay để tránh phí phạt quá hạn!`,
    hoursBefore: 24,
    priority: 'high',
  },
  {
    threshold: '12h',
    title: 'Khoản vay đến hạn trong 12 giờ',
    contentTemplate: (d) => `CẢNH BÁO: Khoản vay ${d.maKhoanVay || d.id} đến hạn trong 12 giờ. Số tiền: ${formatCompactCurrency(d.conNo)}. Thanh toán ngay qua QR hoặc liên hệ HTX nếu gặp khó khăn.`,
    hoursBefore: 12,
    priority: 'critical',
  },
  {
    threshold: '6h',
    title: 'Khoản vay đến hạn trong 6 giờ',
    contentTemplate: (d) => `KHẨN CẤP: Khoản vay ${d.maKhoanVay || d.id} đến hạn trong 6 giờ. Số tiền: ${formatCompactCurrency(d.conNo)}. Nếu chưa thanh toán, khoản vay sẽ bị quá hạn và ảnh hưởng credit score!`,
    hoursBefore: 6,
    priority: 'critical',
  },
  {
    threshold: '1h',
    title: 'Khoản vay sắp đến hạn trong 1 giờ',
    contentTemplate: (d) => `!! CỰC KỲ KHẨN CẤP: Khoản vay ${d.maKhoanVay || d.id} đến hạn trong 1 GIỜ NỮA. Số tiền: ${formatCompactCurrency(d.conNo)}. Thanh toán ngay lập tức để tránh nợ xấu và phí phạt!`,
    hoursBefore: 1,
    priority: 'critical',
  },
  {
    threshold: 'due',
    title: 'Khoản vay đến hạn hôm nay',
    contentTemplate: (d) => `Khoản vay ${d.maKhoanVay || d.id} ĐẾN HẠN HÔM NAY. Số tiền còn nợ: ${formatCompactCurrency(d.conNo)}. Vui lòng thanh toán trong ngày hôm nay để tránh chuyển sang quá hạn.`,
    hoursBefore: 0,
    priority: 'high',
  },
  {
    threshold: 'overdue',
    title: 'Khoản vay đã quá hạn',
    contentTemplate: (d) => `Khoản vay ${d.maKhoanVay || d.id} đã QUÁ HẠN từ ngày ${d.ngayDenHan}. Số tiền: ${formatCompactCurrency(d.conNo)}. Khoản nợ quá hạn sẽ ảnh hưởng nghiêm trọng đến credit score và khả năng vay trong tương lai. Thanh toán ngay!`,
    hoursBefore: -24, // negative = past due
    priority: 'critical',
  },
];

// ─── PI-aware content override ──────────────────────────────

function getPIStatusContent(debt: Debt): { title: string; content: string } | null {
  const allPIs = getPaymentIntents();
  const activePI = allPIs.find(
    (p) => p.debtId === debt.id && !['settled', 'cancelled'].includes(p.status),
  );
  if (!activePI) return null;

  if (
    activePI.status === 'farmer_confirmed_transfer' ||
    activePI.status === 'waiting_bank_credit' ||
    activePI.status === 'bank_credit_received'
  ) {
    return {
      title: `Đang chờ xác nhận thanh toán - ${debt.maKhoanVay || debt.id}`,
      content: `Khoản vay ${debt.maKhoanVay || debt.id} đang chờ HTX xác nhận khoản thanh toán. Bạn không cần thanh toán lại. Nếu chờ quá lâu, vui lòng liên hệ trực tiếp HTX.`,
    };
  }
  if (
    activePI.status === 'reconciled' ||
    activePI.status === 'waiting_htx_confirmation'
  ) {
    return {
      title: `Đang chờ HTX xác nhận tất toán - ${debt.maKhoanVay || debt.id}`,
      content: `Khoản vay ${debt.maKhoanVay || debt.id} đã đối soát thành công và đang chờ HTX xác nhận tất toán. Bạn không cần thực hiện thêm thao tác nào.`,
    };
  }

  return null;
}

// ─── Core Scheduler ──────────────────────────────────────────

export function runDebtReminderScheduler(now: Date = new Date()): number {
  const debts = getDebts();
  const riskProfiles = getRiskProfiles();
  const farmers = getFarmers();
  let triggered = 0;

  debts.forEach((debt) => {
    // Skip already settled debts
    if (debt.status === 'Đã tất toán') return;

    // Skip if status is "Chờ xử lý lỗi thanh toán" or "Thu nợ lỗi" — handled manually
    if (debt.status === 'Chờ xử lý lỗi thanh toán' || debt.status === 'Thu nợ lỗi') return;

    const dueDate = new Date(debt.ngayDenHan);
    // Set due time to 23:59:59 of ngayDenHan
    const dueDateTime = new Date(
      dueDate.getFullYear(),
      dueDate.getMonth(),
      dueDate.getDate(),
      23, 59, 59,
    );
    const diffMs = dueDateTime.getTime() - now.getTime();
    const diffHours = diffMs / (1000 * 60 * 60);

    // Check PI status for override content
    const piOverride = getPIStatusContent(debt);

    for (const cfg of THRESHOLD_CONFIGS) {
      // Already sent this threshold? Skip.
      if (hasReminderSent(debt.id, cfg.threshold)) continue;

      let shouldFire = false;

      if (cfg.threshold === 'overdue') {
        // Fire when past due date
        shouldFire = diffHours < 0;
      } else if (cfg.threshold === 'due') {
        // Fire on the due date (within the last 24h of due date)
        shouldFire = diffHours >= 0 && diffHours <= 24;
      } else {
        // Fire when approaching threshold
        // For 7d: diffHours <= 168 && diffHours > 72
        // For 3d: diffHours <= 72 && diffHours > 24
        // For 1d: diffHours <= 24 && diffHours > 12
        // For 12h: diffHours <= 12 && diffHours > 6
        // For 6h: diffHours <= 6 && diffHours > 1
        // For 1h: diffHours <= 1 && diffHours > 0
        if (cfg.hoursBefore <= 0) continue; // invalid

        const nextThreshold = THRESHOLD_CONFIGS.find(
          (c) => c.threshold !== 'overdue' && c.threshold !== 'due' && c.hoursBefore < cfg.hoursBefore,
        );
        const upperBound = cfg.hoursBefore;
        const lowerBound = nextThreshold ? nextThreshold.hoursBefore : 0;
        shouldFire = diffHours <= upperBound && diffHours > lowerBound;
      }

      if (!shouldFire) continue;

      // PI-aware: if debt is in payment process, use PI content for time-sensitive thresholds
      if (piOverride && (cfg.threshold === 'due' || cfg.threshold === '12h' || cfg.threshold === '6h' || cfg.threshold === '1h')) {
        // Use PI override content instead of debt reminder content
        const nowISO = now.toISOString();
        addReminderLog({
          debtId: debt.id,
          farmerId: debt.farmerId,
          threshold: cfg.threshold,
          scheduledAt: nowISO,
          sentAt: nowISO,
          status: 'sent',
          channel: 'in_app',
          title: piOverride.title,
          content: piOverride.content,
        });

        addNotification({
          farmerId: debt.farmerId,
          debtId: debt.id,
          title: piOverride.title,
          content: piOverride.content,
          type: 'debt_reminder',
          ngayTao: nowISO,
          daDoc: false,
        });

        triggered++;
        break; // Only fire one threshold per run per debt
      }

      // Regular reminder
      const content = cfg.contentTemplate(debt);
      const nowISO = now.toISOString();

      addReminderLog({
        debtId: debt.id,
        farmerId: debt.farmerId,
        threshold: cfg.threshold,
        scheduledAt: nowISO,
        sentAt: nowISO,
        status: 'sent',
        channel: 'in_app',
        title: cfg.title,
        content,
      });

      addNotification({
        farmerId: debt.farmerId,
        debtId: debt.id,
        title: cfg.title,
        content,
        type: cfg.threshold === 'overdue' ? 'debt_overdue' : 'debt_reminder',
        ngayTao: nowISO,
        daDoc: false,
      });

      // Overdue: update debt status + risk profile
      if (cfg.threshold === 'overdue' && debt.status !== 'Quá hạn') {
        updateDebt(debt.id, { status: 'Quá hạn' });
        const farmerName = farmers.find((f) => f.id === debt.farmerId)?.name || debt.farmerId;
        const rp = riskProfiles.find((r) => r.farmerId === debt.farmerId);
        if (rp) {
          const newRisk = rp.mucDo === 'Tốt' ? 'Cần chú ý' : rp.mucDo === 'Khá' ? 'Cần chú ý' : 'Nguy cơ';
          updateRiskProfile(rp.id, {
            mucDo: newRisk,
            moTa: `Khoản vay ${debt.maKhoanVay || debt.id} quá hạn từ ${debt.ngayDenHan}.`,
            ngayCapNhat: nowISO,
          });
        }
        addEditHistory({
          entityType: 'Debt',
          entityId: debt.id,
          farmerId: debt.farmerId,
          truong: 'status',
          giaTriCu: debt.status,
          giaTriMoi: 'Quá hạn',
          ngaySua: nowISO,
          nguoiSua: 'Hệ thống (Reminder Scheduler)',
        });
        addNotification({
          farmerId: debt.farmerId,
          title: 'Khoản vay chuyển trạng thái Quá hạn',
          content: `Khoản ${debt.maKhoanVay || debt.id} của ${farmerName} đã bị chuyển trạng thái Quá hạn. Tổng nợ quá hạn: ${formatCompactCurrency(debt.conNo)}.`,
          type: 'debt_overdue',
          ngayTao: nowISO,
          daDoc: false,
        });
      }

      // If near-due time-based threshold, update debt status accordingly
      if (cfg.threshold === 'due' && debt.status !== 'Đến hạn' && debt.status !== 'Quá hạn') {
        updateDebt(debt.id, { status: 'Đến hạn' });
      } else if (cfg.threshold === '1d' && debt.status === 'Đang vay') {
        updateDebt(debt.id, { status: 'Sắp đến hạn' });
      } else if (cfg.threshold === '3d' && debt.status === 'Đang vay') {
        updateDebt(debt.id, { status: 'Sắp đến hạn' });
      } else if (cfg.threshold === '7d' && debt.status === 'Đang vay') {
        updateDebt(debt.id, { status: 'Sắp đến hạn' });
      }

      triggered++;
      break; // Only fire one threshold per run per debt
    }
  });

  return triggered;
}

// ─── Reminder timeline helper ────────────────────────────────

export interface ReminderTimelineEntry {
  threshold: ReminderThreshold;
  label: string;
  sent: boolean;
  sentAt?: string;
}

export function getDebtReminderTimeline(debtId: string): ReminderTimelineEntry[] {
  const logs = getReminderLogs().filter((r) => r.debtId === debtId);

  const labelMap: Record<ReminderThreshold, string> = {
    '7d': 'T-7 ngày',
    '3d': 'T-3 ngày',
    '1d': 'T-1 ngày',
    '12h': 'T-12 giờ',
    '6h': 'T-6 giờ',
    '1h': 'T-1 giờ',
    'due': 'Đến hạn',
    'overdue': 'Quá hạn',
  };

  const thresholds: ReminderThreshold[] = ['7d', '3d', '1d', '12h', '6h', '1h', 'due', 'overdue'];

  return thresholds.map((th) => {
    const log = logs.find((l) => l.threshold === th && l.status === 'sent');
    return {
      threshold: th,
      label: labelMap[th],
      sent: !!log,
      sentAt: log?.sentAt,
    };
  });
}
