import { Navigate } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';

interface RoleGuardProps {
  allowedRole: 'Nông hộ' | 'Hợp tác xã';
  requireEkyc?: boolean;
  children: React.ReactNode;
}

export function RoleGuard({ allowedRole, requireEkyc = true, children }: RoleGuardProps) {
  const { user } = useAuth();
  if (!user) return <Navigate to="/dang-nhap" replace />;

  if (requireEkyc && user.kycStatus !== 'ekyc_verified') return <Navigate to="/ekyc" replace />;

  if (user.role !== allowedRole) return <Navigate to="/dang-nhap" replace />;
  return <>{children}</>;
}
