import { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { useStore } from '@/hooks/useStore';
import { FinanceOverviewTab } from './components/FinanceOverviewTab';
import { CongNoTab } from './components/CongNoTab';
import { TransactionTab } from './components/TransactionTab';
import { runDebtReminderScheduler } from '@/utils/debtReminderScheduler';
import { MobileTabs } from '@/components/base/MobileUi';

const TABS = [
  { id: 'overview', label: 'Tổng quan', icon: 'ri-dashboard-line' },
  { id: 'debt', label: 'Công nợ', icon: 'ri-money-cny-circle-line' },
  { id: 'transaction', label: 'Giao dịch', icon: 'ri-exchange-line' },
];

export default function HtxFinancePage() {
  useStore();
  const location = useLocation();
  const navState = (location.state as { tab?: string } | null);
  const [activeTab, setActiveTab] = useState(TABS.some((tab) => tab.id === navState?.tab) ? navState!.tab! : 'overview');

  // Run reminder scheduler on mount
  useEffect(() => {
    runDebtReminderScheduler();
  }, []);

  const handleNavigate = (tab: string) => {
    setActiveTab(tab);
  };

  return (
    <div className="mobile-page space-y-4">
      <div>
        <h2 className="text-lg font-bold text-slate-900">Tài chính HTX</h2>
        <p className="metric-caption mt-0.5 text-[11px] text-slate-400">Công nợ và giao dịch của HTX</p>
      </div>
      <MobileTabs tabs={TABS} value={activeTab} onChange={setActiveTab} equal />
      <div className="min-w-0">
          {activeTab === 'overview' && <FinanceOverviewTab onNavigate={handleNavigate} />}
          {activeTab === 'debt' && <CongNoTab onNavigate={handleNavigate} />}
          {activeTab === 'transaction' && <TransactionTab />}
      </div>
    </div>
  );
}
