import { useMemo, useState } from 'react';
import { Outlet, Navigate, useNavigate } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';
import { useStore } from '../../hooks/useStore';
import { BottomNav } from './BottomNav';
import { SlideMenu } from './SlideMenu';
import { AvatarMenu } from './AvatarMenu';
import { Sidebar } from './Sidebar';
import { ToastContainer } from '../base/Toast';
import { ConfirmModal } from '../base/ConfirmModal';
import { getNotificationsByFarmer, getUnreadNotificationsByFarmer } from '../../store';
import type { KycStatus, Notification } from '../../types';

const REDIRECT_KYC_STATUSES: KycStatus[] = ['ekyc_pending', 'ekyc_need_more', 'ekyc_failed'];

export function PrivateLayout() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const state = useStore();
  const [menuOpen, setMenuOpen] = useState(false);
  const [avatarMenuOpen, setAvatarMenuOpen] = useState(false);
  const [noticeOpen, setNoticeOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  if (!user) {
    return <Navigate to="/dang-nhap" replace />;
  }

  if (REDIRECT_KYC_STATUSES.includes(user.kycStatus as KycStatus)) {
    return <Navigate to="/ekyc" replace />;
  }

  const unreadNotificationCount = user.role === 'Nông hộ' && user.farmerId
    ? getUnreadNotificationsByFarmer(user.farmerId).length
    : 0;

  const htxActivityItems = useMemo(() => buildHtxActivityItems(state), [state]);
  const htxActivityCount = htxActivityItems.filter((item) => item.urgent).length || htxActivityItems.length;
  const farmerNotifications = useMemo(
    () => user.role === 'Nông hộ' && user.farmerId ? getNotificationsByFarmer(user.farmerId).slice(0, 6) : [],
    [user.farmerId, user.role, state.notifications],
  );

  const toggleNoticePopup = () => {
    setAvatarMenuOpen(false);
    setNoticeOpen((open) => !open);
  };

  return (
    <div className="min-h-[100dvh] bg-slate-50 flex overflow-x-hidden">
      {/* Desktop sidebar */}
      <Sidebar
        user={user}
        onLogout={logout}
        collapsed={sidebarCollapsed}
      />

      {/* Main content area */}
      <div className="flex-1 flex flex-col min-w-0 max-w-[430px] md:max-w-[720px] lg:max-w-none mx-auto w-full">
        {/* Header — only on mobile/tablet, hidden on desktop since sidebar has branding */}
        <header className="h-14 bg-agrida-600 text-white flex items-center justify-between px-3 sm:px-4 shrink-0 sticky top-0 z-40 lg:hidden shadow-sm">
          <div className="flex items-center gap-2.5 min-w-0">
            <button
              type="button"
              onClick={() => setMenuOpen(true)}
              className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-white/15 transition-colors active:scale-95"
              aria-label="Mở menu"
            >
              <i className="ri-menu-line text-xl" />
            </button>
            <span className="w-7 h-7 flex items-center justify-center">
              <i className="ri-plant-line text-xl" />
            </span>
            <span className="font-bold text-base">Agrida</span>
          </div>

          {/* Desktop sidebar toggle — visible when sidebar exists */}
          <div className="hidden lg:flex items-center gap-2">
            <button
              type="button"
              onClick={() => setSidebarCollapsed(!sidebarCollapsed)}
              className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-white/15 transition-colors"
              aria-label={sidebarCollapsed ? 'Mở rộng sidebar' : 'Thu gọn sidebar'}
            >
              <i className={`text-lg ${sidebarCollapsed ? 'ri-menu-unfold-line' : 'ri-menu-fold-line'}`} />
            </button>
          </div>

          <div className="flex items-center gap-1">
            {user.role === 'Nông hộ' && (
              <button
                type="button"
                onClick={toggleNoticePopup}
                className="relative flex h-9 w-9 items-center justify-center rounded-lg hover:bg-white/15 transition-colors active:scale-95"
                aria-label="Mở thông báo"
              >
                <i className="ri-notification-3-line text-lg" />
                {unreadNotificationCount > 0 && (
                  <span className="absolute -right-0.5 -top-0.5 min-w-4 rounded-full bg-rose-500 px-1 text-[9px] font-bold leading-4 text-white">
                    {unreadNotificationCount > 9 ? '9+' : unreadNotificationCount}
                  </span>
                )}
              </button>
            )}
            {user.role === 'Hợp tác xã' && (
              <button
                type="button"
                onClick={toggleNoticePopup}
                className="relative flex h-9 w-9 items-center justify-center rounded-lg hover:bg-white/15 transition-colors active:scale-95"
                aria-label="Mở hoạt động gần đây"
              >
                <i className="ri-notification-3-line text-lg" />
                {htxActivityCount > 0 && (
                  <span className="absolute -right-0.5 -top-0.5 min-w-4 rounded-full bg-rose-500 px-1 text-[9px] font-bold leading-4 text-white">
                    {htxActivityCount > 9 ? '9+' : htxActivityCount}
                  </span>
                )}
              </button>
            )}

            {/* Avatar button — AvatarMenu handles its own overlay */}
            <button
              type="button"
              onClick={() => setAvatarMenuOpen(!avatarMenuOpen)}
              className="flex items-center gap-2 py-1 px-1.5 rounded-lg hover:bg-white/15 transition-colors active:scale-95"
              aria-label="Mở menu tài khoản"
              aria-expanded={avatarMenuOpen}
            >
              <span className="text-xs font-medium truncate max-w-[100px] opacity-90 hidden sm:inline">
                {user.displayName}
              </span>
              <span className="w-7 h-7 rounded-full bg-white/20 flex items-center justify-center text-xs font-bold">
                {user.displayName.charAt(0)}
              </span>
            </button>
          </div>
        </header>

        {/* Desktop header — compact, only shown when sidebar exists */}
        <header className="hidden lg:flex h-14 bg-white border-b border-gray-100 items-center justify-end gap-2 px-6 shrink-0 sticky top-0 z-30">
          {user.role === 'Nông hộ' && (
            <button
              type="button"
              onClick={toggleNoticePopup}
              className="relative flex h-9 w-9 items-center justify-center rounded-lg text-gray-500 hover:bg-gray-100 transition-colors active:scale-95"
              aria-label="Mở thông báo"
            >
              <i className="ri-notification-3-line text-lg" />
              {unreadNotificationCount > 0 && (
                <span className="absolute -right-0.5 -top-0.5 min-w-4 rounded-full bg-rose-500 px-1 text-[9px] font-bold leading-4 text-white">
                  {unreadNotificationCount > 9 ? '9+' : unreadNotificationCount}
                </span>
              )}
            </button>
          )}
          {user.role === 'Hợp tác xã' && (
            <button
              type="button"
              onClick={toggleNoticePopup}
              className="relative flex h-9 w-9 items-center justify-center rounded-lg text-gray-500 hover:bg-gray-100 transition-colors active:scale-95"
              aria-label="Mở hoạt động gần đây"
            >
              <i className="ri-notification-3-line text-lg" />
              {htxActivityCount > 0 && (
                <span className="absolute -right-0.5 -top-0.5 min-w-4 rounded-full bg-rose-500 px-1 text-[9px] font-bold leading-4 text-white">
                  {htxActivityCount > 9 ? '9+' : htxActivityCount}
                </span>
              )}
            </button>
          )}
          <button
            type="button"
            onClick={() => setAvatarMenuOpen(!avatarMenuOpen)}
            className="flex items-center gap-2 py-1 px-1.5 rounded-lg hover:bg-gray-100 transition-colors active:scale-95"
            aria-label="Mở menu tài khoản"
            aria-expanded={avatarMenuOpen}
          >
            <span className="text-sm font-medium text-gray-700 truncate max-w-[160px]">
              {user.displayName}
            </span>
            <span className="w-8 h-8 rounded-full bg-agrida-100 flex items-center justify-center text-agrida-700 text-sm font-bold">
              {user.displayName.charAt(0)}
            </span>
          </button>
        </header>

        <main className="flex-1 pb-24 lg:pb-8 overflow-y-auto overflow-x-hidden">
          <Outlet />
        </main>

        {/* Bottom nav — mobile/tablet only */}
        <div className="lg:hidden">
          <BottomNav user={user} />
        </div>
      </div>

      {/* Avatar menu — self-contained with its own overlay */}
      <AvatarMenu
        open={avatarMenuOpen}
        onClose={() => setAvatarMenuOpen(false)}
        user={{
          displayName: user.displayName,
          role: user.role,
          kycStatus: (user.kycStatus || 'registered') as KycStatus,
          creditScore: user.creditScore,
          code: user.code,
        }}
        onLogout={logout}
      />

      {noticeOpen && (
        <CompactNoticePopup
          role={user.role}
          notifications={farmerNotifications}
          htxItems={htxActivityItems}
          onClose={() => setNoticeOpen(false)}
          onOpenAll={() => {
            setNoticeOpen(false);
            navigate(user.role === 'Nông hộ' ? '/nong-ho/thong-bao' : '/htx/vay-han-muc');
          }}
        />
      )}

      {/* Slide menu — self-contained with its own overlay */}
      <SlideMenu
        open={menuOpen}
        onClose={() => setMenuOpen(false)}
        user={{
          displayName: user.displayName,
          role: user.role,
          kycStatus: (user.kycStatus || 'registered') as KycStatus,
          creditScore: user.creditScore,
          code: user.code,
        }}
      />

      <ToastContainer />
      <ConfirmModal />
    </div>
  );
}

interface HtxActivityItem {
  id: string;
  title: string;
  content: string;
  icon: string;
  tone: 'emerald' | 'amber' | 'rose' | 'sky' | 'slate';
  urgent?: boolean;
}

function buildHtxActivityItems(state: ReturnType<typeof useStore>): HtxActivityItem[] {
  const pendingLoans = state.advanceRequests.filter((loan) => ['Chờ kiểm tra', 'Cần bổ sung'].includes(loan.status));
  const pendingLimits = state.limitRequests.filter((request) => request.status === 'Chờ duyệt');
  const pendingDisbursements = state.advanceRequests.filter((loan) => ['Đã duyệt', 'approved_locked', 'Chờ giải ngân'].includes(loan.status));
  const paymentIntents = state.paymentIntents.filter((intent) => intent.status === 'waiting_htx_confirmation' || intent.status === 'bank_credit_received');

  return [
    pendingLoans.length > 0 && {
      id: 'loan',
      title: `${pendingLoans.length} yêu cầu vay cần xử lý`,
      content: 'Có yêu cầu vay của nông hộ đang chờ HTX kiểm tra hoặc yêu cầu bổ sung.',
      icon: 'ri-hand-coin-line',
      tone: 'amber' as const,
      urgent: true,
    },
    pendingLimits.length > 0 && {
      id: 'limit',
      title: `${pendingLimits.length} yêu cầu hạn mức chờ duyệt`,
      content: 'Cần xem risk profile, eKYC và hợp đồng bao tiêu trước khi cấp thêm hạn mức.',
      icon: 'ri-scales-3-line',
      tone: 'sky' as const,
      urgent: true,
    },
    pendingDisbursements.length > 0 && {
      id: 'disburse',
      title: `${pendingDisbursements.length} khoản chờ giải ngân`,
      content: 'Các khoản đã duyệt cần giải ngân trong thời gian khóa hạn mức.',
      icon: 'ri-wallet-3-line',
      tone: 'emerald' as const,
      urgent: true,
    },
    paymentIntents.length > 0 && {
      id: 'debt',
      title: `${paymentIntents.length} giao dịch trả nợ chờ xác nhận`,
      content: 'Nông hộ đã xác nhận chuyển khoản, HTX cần đối soát công nợ.',
      icon: 'ri-bank-card-line',
      tone: 'rose' as const,
      urgent: true,
    },
  ].filter(Boolean) as HtxActivityItem[];
}

function CompactNoticePopup({
  role,
  notifications,
  htxItems,
  onClose,
  onOpenAll,
}: {
  role: string;
  notifications: Notification[];
  htxItems: HtxActivityItem[];
  onClose: () => void;
  onOpenAll: () => void;
}) {
  const isFarmer = role === 'Nông hộ';
  const toneClass = (tone: HtxActivityItem['tone']) => {
    if (tone === 'emerald') return 'bg-emerald-50 text-emerald-700';
    if (tone === 'amber') return 'bg-amber-50 text-amber-700';
    if (tone === 'rose') return 'bg-rose-50 text-rose-700';
    if (tone === 'sky') return 'bg-sky-50 text-sky-700';
    return 'bg-slate-50 text-slate-700';
  };

  return (
    <>
      <div className="fixed inset-0 z-[88]" onClick={onClose} />
      <div className="fixed right-[max(12px,calc((100vw-430px)/2+12px))] top-14 z-[89] w-[min(380px,calc(100vw-24px))] overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl">
        <div className="flex items-center justify-between border-b border-slate-100 px-4 py-3">
          <div>
            <h3 className="text-sm font-bold text-slate-900">{isFarmer ? 'Thông báo' : 'Hoạt động HTX'}</h3>
            <p className="text-[10px] text-slate-400">{isFarmer ? 'Các cập nhật mới nhất' : 'Các việc cần chú ý gần đây'}</p>
          </div>
          <button type="button" onClick={onClose} className="flex h-8 w-8 items-center justify-center rounded-full text-slate-400 hover:bg-slate-100">
            <i className="ri-close-line text-lg" />
          </button>
        </div>
        <div className="max-h-[58dvh] space-y-2 overflow-y-auto p-3">
          {isFarmer ? (
            notifications.length === 0 ? (
              <p className="py-6 text-center text-xs text-slate-400">Chưa có thông báo mới</p>
            ) : notifications.map((item) => (
              <article key={item.id} className={`rounded-xl border p-3 ${item.daDoc ? 'border-slate-100 bg-slate-50' : 'border-emerald-100 bg-emerald-50/50'}`}>
                <div className="flex gap-2">
                  <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-white text-agrida-600">
                    <i className="ri-notification-3-line" />
                  </span>
                  <div className="min-w-0">
                    <p className="line-clamp-1 text-xs font-bold text-slate-900">{item.title}</p>
                    <p className="mt-0.5 line-clamp-2 text-[11px] text-slate-600">{item.content}</p>
                    <p className="mt-1 text-[10px] text-slate-400">{new Date(item.ngayTao).toLocaleString('vi-VN')}</p>
                  </div>
                </div>
              </article>
            ))
          ) : (
            htxItems.length === 0 ? (
              <p className="py-6 text-center text-xs text-slate-400">Chưa có hoạt động cần xử lý</p>
            ) : htxItems.map((item) => (
              <article key={item.id} className="rounded-xl border border-slate-100 bg-white p-3 shadow-sm">
                <div className="flex gap-2">
                  <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${toneClass(item.tone)}`}>
                    <i className={item.icon} />
                  </span>
                  <div className="min-w-0">
                    <p className="line-clamp-1 text-xs font-bold text-slate-900">{item.title}</p>
                    <p className="mt-0.5 line-clamp-2 text-[11px] text-slate-600">{item.content}</p>
                  </div>
                </div>
              </article>
            ))
          )}
        </div>
        <div className="border-t border-slate-100 p-3">
          <button type="button" onClick={onOpenAll} className="min-h-10 w-full rounded-xl bg-agrida-600 px-4 text-xs font-bold text-white">
            {isFarmer ? 'Xem tất cả thông báo' : 'Mở module xử lý'}
          </button>
        </div>
      </div>
    </>
  );
}
