import {
  addBankLimitRequest,
  addEditHistory,
  addHtxLoanSource,
  getState,
  updateBankLimitRequest,
} from '@/store';
import {
  addBankLoanRequest,
  updateBankLoanRequest,
} from '@/store/bankLoanStore';
import { recordBalancedEntry } from '@/utils/moneyLedger';
import type { AntescoFundingRequest, AntescoLimitRequest } from '@/types';

export interface AntescoFundingResponse {
  status: 'Đã duyệt' | 'Từ chối' | 'Cần bổ sung';
  approvedAmount?: number;
  interestRate?: number;
  message: string;
}

const ANTESCO_NAME = 'Công ty Cổ phần Rau quả Thực phẩm An Giang (Antesco)';

function createAntescoSource(amount: number, term: string, rate: number, requestId: string, purpose: string) {
  const current = getState();
  const today = new Date();
  const termMonths = Number.parseInt(term, 10) || 12;
  const endDate = new Date(today);
  endDate.setMonth(endDate.getMonth() + termMonths);

  const source = addHtxLoanSource({
    maNguonVay: `ANT-${String(current.htxLoanSources.length + 1).padStart(3, '0')}`,
    tenNguonVay: `Nguồn vốn Antesco #${requestId}`,
    loaiNguon: 'Antesco',
    hanMuc: amount,
    daSuDung: 0,
    laiSuat: rate / 12,
    kyHan: term,
    ngayBatDau: today.toISOString().split('T')[0],
    ngayKetThuc: endDate.toISOString().split('T')[0],
    status: 'Đang hiệu lực',
    ghiChu: `Antesco cấp vốn trực tiếp cho HTX. Mục đích: ${purpose}`,
  });

  recordBalancedEntry({
    code: `ANTESCO-${requestId}`,
    type: 'ANTESCO_TO_HTX',
    description: `Antesco cấp vốn cho HTX qua nguồn ${source.maNguonVay}`,
    postings: [
      { account: 'ANTESCO_CAPITAL', amount: -amount, label: 'Antesco cấp vốn' },
      { account: 'HTX_CASH', amount, label: 'HTX nhận nguồn vốn' },
    ],
  });

  addEditHistory({
    entityType: 'AntescoFunding',
    entityId: requestId,
    truong: 'Luồng tiền',
    giaTriCu: `Antesco -${amount}`,
    giaTriMoi: `HTX +${amount}`,
    ngaySua: new Date().toISOString(),
    nguoiSua: 'Antesco',
  });
}

export async function requestAntescoFunding(options: {
  htxUserId: string;
  amount: number;
  purpose: string;
  term: string;
  proposedRate?: number;
  note?: string;
}): Promise<AntescoFundingResponse> {
  const request = addBankLoanRequest({
    htxUserId: options.htxUserId,
    soTienVay: options.amount,
    mucDich: options.purpose,
    thoiHanVay: options.term,
    laiSuatDeXuat: options.proposedRate,
    ghiChu: options.note,
    nganHangDeXuat: ANTESCO_NAME,
    ngayYeuCau: new Date().toISOString(),
    status: 'Chờ duyệt',
  });

  await new Promise((resolve) => setTimeout(resolve, 700));
  const approvedAmount = options.amount;
  const interestRate = options.proposedRate || 5.5;
  const now = new Date().toISOString();
  const transactionCode = `ANT-${now.slice(0, 10).replace(/-/g, '')}-${request.id.slice(-6)}`;

  updateBankLoanRequest(request.id, {
    status: 'Đã giải ngân',
    soTienDuyet: approvedAmount,
    laiSuatDuyet: interestRate,
    ngayCapNhat: now,
    ngayGiaiNgan: now,
    maGiaoDich: transactionCode,
  });
  createAntescoSource(approvedAmount, options.term, interestRate, request.id, options.purpose);

  return {
    status: 'Đã duyệt',
    approvedAmount,
    interestRate,
    message: 'Antesco đã cấp vốn trực tiếp vào nguồn tiền HTX.',
  };
}

export async function requestAntescoLimit(options: {
  htxUserId: string;
  amount: number;
  purpose: string;
  note?: string;
  expectedDate?: string;
}): Promise<AntescoFundingResponse> {
  const request = addBankLimitRequest({
    htxUserId: options.htxUserId,
    soTienDeNghi: options.amount,
    lyDo: options.purpose,
    ghiChu: options.note,
    nganHangDeXuat: ANTESCO_NAME,
    thoiGianMongMuon: options.expectedDate,
    ngayYeuCau: new Date().toISOString(),
    status: 'Chờ duyệt',
  });

  await new Promise((resolve) => setTimeout(resolve, 700));
  updateBankLimitRequest(request.id, {
    status: 'Đã duyệt',
    ketQuaHanMucMoi: options.amount,
    ngayCapNhat: new Date().toISOString(),
  });
  createAntescoSource(options.amount, '24 tháng', 5.2, request.id, options.purpose);

  return {
    status: 'Đã duyệt',
    approvedAmount: options.amount,
    interestRate: 5.2,
    message: 'Antesco đã phê duyệt hạn mức và bổ sung nguồn tiền cho HTX.',
  };
}

export function getAntescoFundingRequests(htxUserId?: string): AntescoFundingRequest[] {
  const requests = getState().bankLoanRequests as AntescoFundingRequest[];
  return htxUserId ? requests.filter((request) => request.htxUserId === htxUserId) : requests;
}

export function getAntescoLimitRequests(htxUserId?: string): AntescoLimitRequest[] {
  const requests = getState().bankLimitRequests as AntescoLimitRequest[];
  return htxUserId ? requests.filter((request) => request.htxUserId === htxUserId) : requests;
}

