import { useState, useRef, useCallback, useEffect } from 'react';
import { formatDate, todayInputValue } from '@/utils/format';
import { showToast } from '@/components/base/Toast';
import { useModalBackHandler } from '@/hooks/useModalBackHandler';
import { parseMaterialsNote } from '@/utils/logParser';
import type { Diary, Field, Season, MaterialSuggestion, Material } from '@/types';
import { getMaterialsByFarmer, updateMaterial, addMaterial, addEditHistory } from '@/store';

interface LogFormModalProps {
  editItem?: Diary | null;
  fields: Field[];
  seasons: Season[];
  farmerId: string;
  farmerMaterials: Material[];
  onSave: (data: Omit<Diary, 'id'>) => void;
  onUpdate?: (id: string, data: Partial<Diary>, materialChanges?: { itemId?: string; tenVatTu: string; nhomVatTu?: string; soLuongGiam: number; donVi: string }[]) => void;
  onClose: () => void;
}

const DEMO_SCRIPTS = [
  'Hôm nay kiểm tra đồng thấy lúa phát triển tốt, không có sâu bệnh. Đã bón thúc NPK 50kg cho khu vực phía Đông.',
  'Phát hiện một số diện tích bị vàng lá, cần phun thuốc bổ sung. Đã phun 2 lít thuốc đặc trị.',
  'Đã bón thúc NPK 16-16-8 cho lúa giai đoạn đẻ nhánh, cây xanh tốt. Tưới nước đầy đủ.',
  'Thời tiết nắng nóng, cần tưới nước bổ sung cho ruộng. Kiểm tra thấy có rầy nâu rải rác.',
];

export function LogFormModal({ editItem, fields, seasons, farmerId, farmerMaterials, onSave, onUpdate, onClose }: LogFormModalProps) {
  useModalBackHandler(true, onClose);

  const [fieldId, setFieldId] = useState(editItem?.fieldId || fields[0]?.id || '');
  const [seasonId, setSeasonId] = useState(editItem?.seasonId || '');
  const [ngay, setNgay] = useState(editItem?.ngay || todayInputValue());
  const [hoatDong, setHoatDong] = useState(editItem?.hoatDong || '');
  const [chiTiet, setChiTiet] = useState(editItem?.chiTiet || '');
  const [materialsNote, setMaterialsNote] = useState(editItem?.materialsNote || '');
  const [ghiChuKhac, setGhiChuKhac] = useState(editItem?.ghiChuKhac || '');
  const [hinhAnhList, setHinhAnhList] = useState<string[]>(editItem?.hinhAnhList || (editItem?.hinhAnh ? [editItem.hinhAnh] : []));
  const [videoUrl, setVideoUrl] = useState(editItem?.videoUrl || '');
  const [ghiAmScript, setGhiAmScript] = useState(editItem?.ghiAmScript || '');
  const [recording, setRecording] = useState(false);

  const [materialSuggestions, setMaterialSuggestions] = useState<MaterialSuggestion[]>(editItem?.materialSuggestions || []);
  const [aiSummary, setAiSummary] = useState('');
  const [showSuggestionBox, setShowSuggestionBox] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const filteredSeasons = seasons.filter((s) => s.fieldId === fieldId);

  useEffect(() => {
    if (editItem) {
      setFieldId(editItem.fieldId || fields[0]?.id || '');
      setSeasonId(editItem.seasonId || '');
      setNgay(editItem.ngay || todayInputValue());
      setHoatDong(editItem.hoatDong || '');
      setChiTiet(editItem.chiTiet || '');
      setMaterialsNote(editItem.materialsNote || '');
      setGhiChuKhac(editItem.ghiChuKhac || '');
      setHinhAnhList(editItem.hinhAnhList || (editItem.hinhAnh ? [editItem.hinhAnh] : []));
      setVideoUrl(editItem.videoUrl || '');
      setGhiAmScript(editItem.ghiAmScript || '');
      setMaterialSuggestions(editItem.materialSuggestions || []);
    }
  }, [editItem, fields]);

  const handleFieldChange = (fid: string) => {
    setFieldId(fid);
    const nextSeason = seasons.find((season) => season.fieldId === fid && ['Đang canh tác', 'Chuẩn bị'].includes(season.status)) || seasons.find((season) => season.fieldId === fid);
    setSeasonId(nextSeason?.id || '');
  };

  const analyzeMaterials = useCallback((note: string) => {
    if (note.trim().length < 3) {
      setShowSuggestionBox(false);
      setMaterialSuggestions([]);
      setAiSummary('');
      return;
    }
    const currentSeasonId = seasonId || undefined;
    const { suggestions, summary } = parseMaterialsNote(note, currentSeasonId);
    if (suggestions.length > 0) {
      setMaterialSuggestions(suggestions);
      setAiSummary(summary);
      setShowSuggestionBox(true);
    } else {
      setShowSuggestionBox(false);
      setMaterialSuggestions([]);
      setAiSummary('');
    }
  }, [seasonId]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (materialsNote.trim()) {
        analyzeMaterials(materialsNote);
      } else {
        setShowSuggestionBox(false);
      }
    }, 600);
    return () => clearTimeout(timer);
  }, [materialsNote, analyzeMaterials]);

  const applyMaterialSuggestion = (idx: number) => {
    const s = materialSuggestions[idx];
    if (s.applied) return;

    const existingMat = farmerMaterials.find(
      (m) => m.tenVatTu.toLowerCase().includes(s.tenVatTu.toLowerCase()) || s.tenVatTu.toLowerCase().includes(m.tenVatTu.toLowerCase())
    );

    if (existingMat) {
      const newTonKho = Math.max(0, (existingMat.tonKho || existingMat.soLuong) - s.soLuong);
      updateMaterial(existingMat.id, {
        tonKho: newTonKho,
        soLuong: existingMat.soLuong,
        ghiChu: `Giảm ${s.soLuong}${s.donVi} từ nhật ký ngày ${ngay}`,
      });
      const editor = 'Nông hộ (từ nhật ký)';
      addEditHistory({
        entityType: 'Material', entityId: existingMat.id, farmerId,
        truong: 'tonKho', giaTriCu: String(existingMat.tonKho || existingMat.soLuong), giaTriMoi: String(newTonKho),
        ngaySua: new Date().toISOString(), nguoiSua: editor,
      });
      showToast(`Đã cập nhật "${existingMat.tenVatTu}": còn ${newTonKho}${s.donVi}`, 'success');
    } else {
      addMaterial({
        farmerId,
        seasonId: s.seasonId,
        tenVatTu: s.tenVatTu,
        nhomVatTu: s.nhomVatTu,
        soLuong: s.soLuong,
        tonKho: s.soLuong,
        donVi: s.donVi,
        nguonGoc: 'Nông hộ tự mua',
        ngayCap: ngay,
        status: 'Đủ',
        ghiChu: `Tạo từ nhật ký ngày ${ngay}`,
      });
      showToast(`Đã tạo vật tư mới "${s.tenVatTu}" (${s.soLuong}${s.donVi})`, 'success');
    }

    const updated = [...materialSuggestions];
    updated[idx] = { ...updated[idx], applied: true };
    setMaterialSuggestions(updated);
  };

  const dismissSuggestion = (idx: number) => {
    const updated = [...materialSuggestions];
    updated[idx] = { ...updated[idx], applied: true };
    setMaterialSuggestions(updated);
    if (updated.every((s) => s.applied)) setShowSuggestionBox(false);
  };

  const dismissAllSuggestions = () => {
    setShowSuggestionBox(false);
    setMaterialSuggestions(materialSuggestions.map((s) => ({ ...s, applied: true })));
  };

  const toggleRecord = () => {
    if (!recording) {
      setRecording(true);
      showToast('Đang ghi âm...', 'info');
    } else {
      setRecording(false);
      const script = DEMO_SCRIPTS[Math.floor(Math.random() * DEMO_SCRIPTS.length)];
      setGhiAmScript(script);
      setChiTiet((prev) => (prev ? `${prev}\n\n${script}` : script));
      showToast('Đã chuyển ghi âm thành văn bản (mock)', 'success');
    }
  };

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    Array.from(files).forEach((file) => {
      const url = URL.createObjectURL(file);
      setHinhAnhList((prev) => [...prev, url]);
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  }, []);

  const handleVideoSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const url = URL.createObjectURL(files[0]);
    setVideoUrl(url);
    if (videoInputRef.current) videoInputRef.current.value = '';
  }, []);

  const removeImage = (idx: number) => {
    setHinhAnhList((prev) => prev.filter((_, i) => i !== idx));
  };

  const removeVideo = () => setVideoUrl('');

  const handleSubmit = () => {
    if (!fieldId) { showToast('Vui lòng chọn thửa đất', 'warning'); return; }
    if (!ngay) { showToast('Vui lòng chọn ngày ghi nhật ký', 'warning'); return; }
    if (!hoatDong.trim()) { showToast('Vui lòng nhập tiêu đề nhật ký', 'warning'); return; }
    if (!chiTiet.trim()) { showToast('Vui lòng nhập nội dung nhật ký', 'warning'); return; }

    const activeSuggestions = materialSuggestions.filter((s) => !s.applied);

    const payload: Partial<Diary> = {
      fieldId,
      seasonId: seasonId || undefined,
      ngay,
      hoatDong: hoatDong.trim(),
      chiTiet: chiTiet.trim(),
      materialsNote: materialsNote.trim() || undefined,
      materialSuggestions: activeSuggestions.length > 0 ? activeSuggestions : undefined,
      ghiChuKhac: ghiChuKhac.trim() || undefined,
      hinhAnhList: hinhAnhList.length > 0 ? hinhAnhList : undefined,
      hinhAnh: hinhAnhList.length > 0 ? hinhAnhList[0] : undefined,
      videoUrl: videoUrl || undefined,
      ghiAmScript: ghiAmScript || undefined,
    };

    if (editItem && onUpdate) {
      onUpdate(editItem.id, payload);
    } else {
      onSave(payload as Omit<Diary, 'id'>);
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
      <div className="absolute inset-0 bg-black/50 animate-modal-backdrop" onClick={onClose} />
      <div onClick={(e) => e.stopPropagation()} className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-lg max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto animate-modal-slide-up">
        <div className="sticky top-0 bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between z-10">
          <h3 className="text-base font-semibold text-slate-900">
            {editItem ? 'Sửa nhật ký' : 'Tạo nhật ký mới'}
          </h3>
          <button type="button" onClick={onClose} className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-slate-600">
            <i className="ri-close-line text-xl" />
          </button>
        </div>

        <div className="p-4 space-y-4">
          {/* Field - season is inferred from active crop cycle */}
          <div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Thửa đất <span className="text-red-500">*</span></label>
              <select
                value={fieldId}
                onChange={(e) => handleFieldChange(e.target.value)}
                className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
              >
                <option value="">Chọn thửa đất</option>
                {fields.map((f) => (
                  <option key={f.id} value={f.id}>{f.maThuaDat} - {f.name}</option>
                ))}
              </select>
            </div>
            {fieldId && (
              <p className="mt-1 text-xs text-slate-400">
                Mùa vụ tự gắn: {filteredSeasons.find((season) => season.id === seasonId)?.name || 'chưa có mùa vụ đang canh tác'}
              </p>
            )}
          </div>

          {/* Date */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Ngày ghi nhật ký <span className="text-red-500">*</span></label>
            <input
              type="date"
              value={ngay}
              onChange={(e) => setNgay(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
            />
          </div>

          {/* Content + Voice recording */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Tiêu đề <span className="text-red-500">*</span></label>
            <input
              type="text"
              value={hoatDong}
              onChange={(e) => setHoatDong(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
              placeholder="VD: Kiểm tra sâu bệnh sau mưa"
            />
          </div>
          <div>
            <div className="flex items-center justify-between mb-1">
              <label className="block text-sm font-medium text-slate-700">Chi tiết kiểm tra <span className="text-red-500">*</span></label>
              <button
                type="button"
                onClick={toggleRecord}
                className={`text-xs font-medium flex items-center gap-1 px-2 py-1 rounded-full transition-colors whitespace-nowrap ${
                  recording ? 'bg-red-100 text-red-700 animate-pulse' : ghiAmScript ? 'bg-emerald-50 text-emerald-600 border border-emerald-200' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
                }`}
              >
                <span className="w-3 h-3 flex items-center justify-center">
                  <i className={recording ? 'ri-stop-circle-fill' : ghiAmScript ? 'ri-mic-fill' : 'ri-mic-line'} />
                </span>
                {recording ? 'Dừng' : ghiAmScript ? 'Đã ghi' : 'Ghi âm'}
              </button>
            </div>
            {recording && (
              <div className="flex items-center gap-2 text-xs text-red-600 mb-1">
                <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
                Đang ghi âm... (mock)
              </div>
            )}
            {ghiAmScript && (
              <div className="bg-emerald-50 border border-emerald-100 rounded-lg p-2.5 mb-2 text-xs text-emerald-800 flex items-start gap-2">
                <span className="w-4 h-4 flex items-center justify-center text-emerald-600 shrink-0 mt-0.5"><i className="ri-mic-fill" /></span>
                <span>"{ghiAmScript}"</span>
              </div>
            )}
            <textarea
              value={chiTiet}
              onChange={(e) => setChiTiet(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500 min-h-[100px] resize-none"
              placeholder="Mô tả chi tiết hoạt động sản xuất hôm nay..."
            />
          </div>

          {/* Materials note + AI suggestion */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú vật tư sử dụng</label>
            <input
              type="text"
              value={materialsNote}
              onChange={(e) => setMaterialsNote(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
              placeholder="VD: Dùng NPK 50kg, thuốc BVTV 2 lít..."
            />

            {showSuggestionBox && materialSuggestions.length > 0 && (
              <div className="mt-3 bg-gradient-to-r from-agrida-50 to-emerald-50 border border-agrida-200 rounded-xl p-3 animate-slide-down">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-1.5">
                    <span className="w-4 h-4 flex items-center justify-center text-agrida-600"><i className="ri-robot-line" /></span>
                    <span className="text-xs font-semibold text-agrida-800">AI gợi ý vật tư</span>
                  </div>
                  <button type="button" onClick={dismissAllSuggestions} className="text-xs text-slate-400 hover:text-slate-600 whitespace-nowrap">Bỏ qua tất cả</button>
                </div>

                {aiSummary && (
                  <p className="text-xs text-slate-600 mb-2">{aiSummary}</p>
                )}

                <div className="space-y-2">
                  {materialSuggestions.filter((s) => !s.applied).map((s, idx) => {
                    const realIdx = materialSuggestions.indexOf(s);
                    return (
                      <div key={realIdx} className="bg-white rounded-lg border border-slate-100 p-2.5 flex items-center justify-between gap-2">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-sm font-semibold text-slate-800">{s.tenVatTu}</span>
                            {s.nhomVatTu && (
                              <span className="text-[10px] bg-slate-100 text-slate-600 px-1.5 py-0.5 rounded">{s.nhomVatTu}</span>
                            )}
                          </div>
                          <p className="text-xs text-slate-500 mt-0.5">
                            {s.soLuong} {s.donVi}
                          </p>
                        </div>
                        <div className="flex items-center gap-1.5 shrink-0">
                          <button
                            type="button"
                            onClick={() => applyMaterialSuggestion(realIdx)}
                            className="px-2.5 py-1.5 rounded-lg text-[10px] font-bold bg-agrida-600 hover:bg-agrida-700 text-white transition-colors whitespace-nowrap"
                          >
                            Cập nhật vào vật tư
                          </button>
                          <button
                            type="button"
                            onClick={() => dismissSuggestion(realIdx)}
                            className="w-6 h-6 flex items-center justify-center text-slate-300 hover:text-slate-500"
                          >
                            <i className="ri-close-line" />
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>

          {/* Ghi chú khác */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">Ghi chú khác</label>
            <input
              type="text"
              value={ghiChuKhac}
              onChange={(e) => setGhiChuKhac(e.target.value)}
              className="w-full px-3 py-2.5 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
              placeholder="Ghi chú thêm..."
            />
          </div>

          {/* Photo / Video attachments */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Ảnh / Video đính kèm</label>
            <div className="flex gap-2 mb-2 flex-wrap">
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="px-3 py-2 rounded-lg border border-slate-200 text-xs font-medium text-slate-700 hover:bg-slate-50 flex items-center gap-1 whitespace-nowrap"
              >
                <span className="w-3.5 h-3.5 flex items-center justify-center"><i className="ri-image-add-line" /></span>
                Thêm ảnh
              </button>
              <button
                type="button"
                onClick={() => videoInputRef.current?.click()}
                className="px-3 py-2 rounded-lg border border-slate-200 text-xs font-medium text-slate-700 hover:bg-slate-50 flex items-center gap-1 whitespace-nowrap"
              >
                <span className="w-3.5 h-3.5 flex items-center justify-center"><i className="ri-video-add-line" /></span>
                Thêm video
              </button>
              <input ref={fileInputRef} type="file" accept="image/*" multiple className="hidden" onChange={handleFileSelect} />
              <input ref={videoInputRef} type="file" accept="video/*" className="hidden" onChange={handleVideoSelect} />
            </div>

            {hinhAnhList.length > 0 && (
              <div className="grid grid-cols-3 sm:grid-cols-4 gap-2 mb-2">
                {hinhAnhList.map((url, idx) => (
                  <div key={idx} className="relative aspect-square rounded-lg overflow-hidden bg-slate-100 group">
                    <img src={url} alt={`preview-${idx}`} className="w-full h-full object-cover" />
                    <button
                      type="button"
                      onClick={() => removeImage(idx)}
                      className="absolute top-1 right-1 w-5 h-5 bg-black/50 rounded-full text-white flex items-center justify-center text-xs opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      <i className="ri-close-line" />
                    </button>
                  </div>
                ))}
              </div>
            )}

            {videoUrl && (
              <div className="relative rounded-lg overflow-hidden bg-slate-100 mb-2">
                <video src={videoUrl} controls className="w-full max-h-[200px]" />
                <button type="button" onClick={removeVideo} className="absolute top-2 right-2 w-6 h-6 bg-black/50 rounded-full text-white flex items-center justify-center text-xs">
                  <i className="ri-close-line" />
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="sticky bottom-0 bg-white border-t border-slate-100 px-4 py-3 flex gap-3 justify-end">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2.5 rounded-md text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
          >
            Hủy
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            className="px-4 py-2.5 rounded-md text-sm font-medium text-white bg-agrida-700 hover:bg-agrida-800 transition-colors whitespace-nowrap min-h-[44px]"
          >
            {editItem ? 'Lưu thay đổi' : 'Tạo nhật ký'}
          </button>
        </div>
      </div>
    </div>
  );
}
