import { useState, useEffect, useCallback, useRef } from 'react';
import {
  expireAllOverdueLocks, getState, getLimitLocks, updateLoan,
  getDisbursements, cancelDisbursementByLockExpired, addEditHistory,
  addNotification, getActiveLockByLoan, releaseLimitLock,
} from '@/store';
import { useStore } from '@/hooks/useStore';

/**
 * Global lock checker — runs every 10 seconds.
 * When locks expire:
 *   1. expireAllOverdueLocks() marks lock as expired
 *   2. Find linked loans → update to lock_expired
 *   3. Find linked disbursements → cancel if pending
 *   4. Send notifications
 */
export function useGlobalLockChecker() {
  useStore();
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const processedLockIds = useRef<Set<string>>(new Set());

  useEffect(() => {
    timerRef.current = setInterval(() => {
      const { count: expiredCount, expiredLockIds } = expireAllOverdueLocks();

      if (expiredCount > 0) {
        const state = getState();
        const expiredLocks = state.limitLocks.filter(
          (l) => expiredLockIds.includes(l.id) && !processedLockIds.current.has(l.id),
        );

        expiredLocks.forEach((lock) => {
          processedLockIds.current.add(lock.id);

          // Update linked loan → lock_expired
          updateLoan(lock.loanId, {
            status: 'lock_expired',
            ghiChu: 'Hết thời gian khóa hạn mức (10 phút). Cần duyệt lại để tạo lock mới.',
          });

          // Cancel linked disbursement if still pending
          const activeDr = state.disbursementRequests.find(
            (d) => d.advanceRequestId === lock.loanId
              && (d.status === 'sent_to_bank' || d.status === 'timeout' || d.status === 'Đã gửi ngân hàng'),
          );
          if (activeDr) {
            cancelDisbursementByLockExpired(activeDr.id);

            addEditHistory({
              entityType: 'Disbursement',
              entityId: activeDr.id,
              farmerId: lock.farmerId,
              truong: 'status',
              giaTriCu: activeDr.status,
              giaTriMoi: 'cancelled_by_lock_expired',
              ngaySua: new Date().toISOString(),
              nguoiSua: 'Hệ thống (auto)',
            });
          }

          // Release lock
          releaseLimitLock(lock.id, 'Hết thời gian khóa hạn mức (10 phút)');

          // Send notification
          addNotification({
            farmerId: lock.farmerId,
            title: 'Hết thời gian khóa hạn mức',
            content: `Khóa hạn mức ${lock.amount.toLocaleString('vi-VN')}đ cho khoản vay ${lock.loanId.toUpperCase()} đã hết hạn. Vui lòng duyệt lại nếu cần giải ngân.`,
            type: 'general',
            ngayTao: new Date().toISOString(),
            daDoc: false,
            sentBy: 'Hệ thống',
          });
        });

        console.log(`[LimitLock] Expired ${expiredCount} locks, processed ${expiredLocks.length} linked loans`);
      }
    }, 10000);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);
}

/**
 * Hook that returns remaining time for a specific loan's limit lock.
 * Returns live countdown info that updates every second.
 */
export function useLimitLockCountdown(loanId: string) {
  useStore();
  const [, setTick] = useState(0);

  useEffect(() => {
    const state = getState();
    const lock = state.limitLocks.find((l) => l.loanId === loanId && l.status === 'active');
    if (!lock) return;

    const timer = setInterval(() => {
      setTick((t) => t + 1);
      // Check if this lock expired
      const now = new Date().toISOString();
      if (lock.expiresAt <= now) {
        expireAllOverdueLocks();
      }
    }, 1000);

    return () => clearInterval(timer);
  }, [loanId]);

  const state = getState();
  const lock = state.limitLocks.find((l) => l.loanId === loanId && l.status === 'active');

  if (!lock) {
    // Check if there was an expired lock
    const expiredLock = state.limitLocks.find((l) => l.loanId === loanId && l.status === 'expired');
    if (expiredLock) {
      return { isLocked: false, isExpired: true, isWarning: false, remainingSeconds: 0, displayText: 'Đã hết khóa', lock: expiredLock };
    }
    return { isLocked: false, isExpired: false, isWarning: false, remainingSeconds: 0, displayText: '', lock: null };
  }

  const now = Date.now();
  const expiresMs = new Date(lock.expiresAt).getTime();
  const remainingMs = Math.max(0, expiresMs - now);
  const remainingSeconds = Math.floor(remainingMs / 1000);
  const isExpired = remainingSeconds <= 0;
  const isWarning = !isExpired && remainingSeconds <= 120;

  const mins = Math.floor(remainingSeconds / 60);
  const secs = remainingSeconds % 60;
  const displayText = isExpired ? 'Đã hết khóa' : `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;

  return { isLocked: true, isExpired, isWarning, remainingSeconds, displayText, lock };
}

/**
 * Get badge class for lock countdown display.
 * - Active (>2min): green/sky
 * - Under 2min: orange
 * - Expired: red
 */
export function getLockBadgeClass(lockInfo: { isLocked: boolean; isExpired: boolean; isWarning: boolean }): string {
  if (!lockInfo.isLocked && !lockInfo.isExpired) return 'bg-slate-100 text-slate-500 border-slate-200';
  if (lockInfo.isExpired) return 'bg-red-100 text-red-700 border-red-300';
  if (lockInfo.isWarning) return 'bg-orange-100 text-orange-700 border-orange-300';
  return 'bg-emerald-100 text-emerald-700 border-emerald-300';
}