import { useEffect, useMemo, useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { MobileMetricCard, MobileSectionHeader } from '@/components/base/MobileUi';
import { showToast } from '@/components/base/Toast';
import { HtxFundRequestSheet } from '@/components/feature/HtxFundRequestSheet';
import type { HtxFundAction } from '@/components/feature/HtxFundRequestSheet';
import { useStore } from '@/hooks/useStore';
import { addEditHistory, addFinance, getState, updateHtxLoanSource } from '@/store';
import { getAntescoFundingRequests, getAntescoLimitRequests } from '@/services/antescoFundingService';
import { getHtxMoneySummary, getHtxSourceRemaining } from '@/utils/financeEngine';
import { formatCurrencyCompact } from '@/utils/formatters';
import { recordBalancedEntry } from '@/utils/moneyLedger';
import type { BankLimitRequest, BankLoanRequest, HtxLoanSource } from '@/types';

type FundDetail =
  | { kind: 'source'; source: HtxLoanSource }
  | { kind: 'loan'; request: BankLoanRequest }
  | { kind: 'limit'; request: BankLimitRequest };

export function HtxFundTab({ initialAction }: { initialAction?: HtxFundAction }) {
  useStore();
  const state = getState();
  const summary = getHtxMoneySummary();
  const [open, setOpen] = useState(false);
  const [mode, setMode] = useState<HtxFundAction>('loan');
  const [showSources, setShowSources] = useState(false);
  const [repaySourceId, setRepaySourceId] = useState('');
  const [repayAmount, setRepayAmount] = useState('');
  const [repayResult, setRepayResult] = useState<{ code: string; amount: number; sourceName: string } | null>(null);
  const [detail, setDetail] = useState<FundDetail | null>(null);

  const sources = useMemo(
    () => [...state.htxLoanSources].sort((a, b) => b.ngayBatDau.localeCompare(a.ngayBatDau)),
    [state.htxLoanSources],
  );
  const loanHistory = getAntescoFundingRequests(state.currentUser?.id).sort((a, b) => b.ngayYeuCau.localeCompare(a.ngayYeuCau));
  const limitHistory = getAntescoLimitRequests(state.currentUser?.id).sort((a, b) => b.ngayYeuCau.localeCompare(a.ngayYeuCau));
  const outstandingSources = sources.filter((source) => source.daSuDung > 0);
  const repaySource = sources.find((source) => source.id === repaySourceId);
  const repayTransferContent = repaySource ? `AGRIDA HTX REPAY ${repaySource.maNguonVay}` : '';

  useEffect(() => {
    if (!initialAction) return;
    setMode(initialAction);
    setOpen(true);
  }, [initialAction]);

  const openForm = (action: HtxFundAction) => {
    setMode(action);
    setOpen(true);
  };

  const openRepay = (sourceId: string) => {
    const source = sources.find((item) => item.id === sourceId);
    setRepaySourceId(sourceId);
    setRepayAmount(source ? String(Math.min(source.daSuDung, 300000000)) : '');
    setRepayResult(null);
  };

  const closeRepay = () => {
    setRepaySourceId('');
    setRepayAmount('');
    setRepayResult(null);
  };

  const submitRepay = () => {
    if (!repaySource) return;
    const amount = Number(repayAmount);
    if (!Number.isFinite(amount) || amount <= 0) {
      showToast('Vui lòng nhập số tiền trả nợ hợp lệ.', 'warning');
      return;
    }
    if (amount > repaySource.daSuDung) {
      showToast('Số tiền trả vượt dư nợ nguồn vốn.', 'warning');
      return;
    }

    const now = new Date().toISOString();
    const code = `ANT-REPAY-${Date.now().toString(36).toUpperCase()}`;
    updateHtxLoanSource(repaySource.id, { daSuDung: Math.max(0, repaySource.daSuDung - amount) });
    addFinance({
      farmerId: 'htx',
      loai: 'Chi',
      soTien: amount,
      moTa: `HTX trả nợ bên cấp vốn - ${repaySource.tenNguonVay}`,
      ngay: now.split('T')[0],
      trangThai: 'Hoàn thành',
      nguonGoc: repaySource.tenNguonVay,
      maGiaoDich: code,
      phanLoai: 'Trả nợ',
    });
    addEditHistory({
      entityType: 'HtxLoanSource',
      entityId: repaySource.id,
      truong: 'daSuDung',
      giaTriCu: String(repaySource.daSuDung),
      giaTriMoi: String(Math.max(0, repaySource.daSuDung - amount)),
      ngaySua: now,
      nguoiSua: 'HTX Hòa Phát',
    });
    recordBalancedEntry({
      code,
      type: 'HTX_TO_ANTESCO',
      description: `HTX trả nợ mock cho bên cấp vốn qua nguồn ${repaySource.maNguonVay}`,
      postings: [
        { account: 'HTX_CASH', amount: -amount, label: 'HTX trả nợ' },
        { account: 'ANTESCO_CAPITAL', amount, label: 'Bên cấp vốn nhận tiền' },
      ],
    });
    setRepayResult({ code, amount, sourceName: repaySource.tenNguonVay });
    showToast('Bên cấp vốn đã xác nhận nhận tiền mock.', 'success');
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        <MobileMetricCard label="Tổng quỹ" value={formatCurrencyCompact(summary.totalLimit)} caption="Tổng ngân sách Ví HTX" tone="sky" icon="ri-wallet-3-line" />
        <MobileMetricCard label="Khả dụng" value={formatCurrencyCompact(summary.availableLimit)} caption="Có thể giải ngân" tone="emerald" icon="ri-hand-coin-line" />
        <MobileMetricCard label="Đã sử dụng" value={formatCurrencyCompact(summary.usedLimit)} caption="Đã chuyển nông hộ" tone="amber" icon="ri-arrow-right-up-line" />
        <MobileMetricCard label="Đang khóa" value={formatCurrencyCompact(summary.lockedAmount)} caption="Chờ giải ngân" tone="slate" icon="ri-lock-line" />
      </div>

      <div className="grid grid-cols-2 gap-2">
        <button type="button" onClick={() => openForm('loan')} className="mobile-card flex min-h-24 flex-col items-center justify-center gap-2 border-emerald-200 bg-emerald-50 p-3 text-center">
          <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-600 text-white"><i className="ri-hand-coin-line" /></span>
          <span><strong className="block text-sm text-emerald-900">Gửi yêu cầu vay</strong><span className="metric-caption mt-0.5 block text-[10px] text-emerald-700">Bổ sung tiền vào quỹ</span></span>
        </button>
        <button type="button" onClick={() => openForm('limit')} className="mobile-card flex min-h-24 flex-col items-center justify-center gap-2 border-teal-200 bg-teal-50 p-3 text-center">
          <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-teal-600 text-white"><i className="ri-scales-3-line" /></span>
          <span><strong className="block text-sm text-teal-900">Xin cấp hạn mức</strong><span className="metric-caption mt-0.5 block text-[10px] text-teal-700">Tăng ngân sách khả dụng</span></span>
        </button>
      </div>

      <section>
        <MobileSectionHeader title="Dư nợ bên cấp vốn" count={`${outstandingSources.length} nguồn`} />
        {outstandingSources.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-slate-200 py-6 text-center text-xs text-slate-400">Chưa có dư nợ bên cấp vốn</div>
        ) : (
          <div className="space-y-2">
            {outstandingSources.map((source) => (
              <article
                key={source.id}
                role="button"
                tabIndex={0}
                onClick={() => setDetail({ kind: 'source', source })}
                onKeyDown={(event) => { if (event.key === 'Enter') setDetail({ kind: 'source', source }); }}
                className="mobile-card cursor-pointer p-3.5 transition active:scale-[0.99]"
              >
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <h4 className="truncate text-sm font-bold text-slate-900">{source.tenNguonVay}</h4>
                    <p className="metric-caption mt-0.5 text-[10px] text-slate-400">{source.maNguonVay} · lãi đơn {source.laiSuat}%/tháng</p>
                  </div>
                  <strong className="shrink-0 text-sm text-rose-700">{formatCurrencyCompact(source.daSuDung)}</strong>
                </div>
                <div className="mt-3 flex gap-2">
                  <button type="button" onClick={(event) => { event.stopPropagation(); openRepay(source.id); }} className="min-h-11 flex-1 rounded-xl bg-emerald-700 px-3 text-xs font-bold text-white">Trả nợ</button>
                  <span className="flex min-h-11 items-center rounded-xl bg-slate-50 px-3 text-[10px] font-semibold text-slate-500">Xem chi tiết</span>
                </div>
              </article>
            ))}
          </div>
        )}
      </section>

      <section>
        <MobileSectionHeader title="Cấu phần Quỹ HTX" count={`${sources.length} khoản hình thành quỹ`} actionLabel={showSources ? 'Thu gọn' : 'Xem nguồn'} onAction={() => setShowSources((value) => !value)} />
        {showSources && <div className="space-y-2">{sources.map((source, index) => {
          const remaining = getHtxSourceRemaining(source);
          const percent = source.hanMuc > 0 ? Math.min(100, source.daSuDung / source.hanMuc * 100) : 0;
          const label = source.kyHan ? `Khoản vay ${String(sources.length - index).padStart(2, '0')}` : `Hạn mức ${String(sources.length - index).padStart(2, '0')}`;
          return (
            <button
              key={source.id}
              type="button"
              onClick={() => setDetail({ kind: 'source', source })}
              className="mobile-card w-full p-3.5 text-left transition active:scale-[0.99]"
            >
              <div className="flex items-center justify-between gap-3">
                <div className="min-w-0">
                  <h4 className="text-sm font-bold text-slate-900">{label}</h4>
                  <p className="metric-caption mt-0.5 text-[10px] text-slate-400">{source.kyHan || 'Theo thỏa thuận'} · {new Date(source.ngayBatDau).toLocaleDateString('vi-VN')}</p>
                </div>
                <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${source.status === 'Sắp hết hạn' ? 'bg-amber-100 text-amber-700' : source.status === 'Đã kết thúc' ? 'bg-slate-100 text-slate-600' : 'bg-emerald-100 text-emerald-700'}`}>{source.status}</span>
              </div>
              <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-emerald-500" style={{ width: `${percent}%` }} /></div>
              <div className="mt-3 grid grid-cols-3 gap-2">
                <FundMetric label="Tổng" value={formatCurrencyCompact(source.hanMuc)} />
                <FundMetric label="Đã dùng" value={formatCurrencyCompact(source.daSuDung)} tone="amber" />
                <FundMetric label="Còn lại" value={formatCurrencyCompact(remaining)} tone="emerald" />
              </div>
            </button>
          );
        })}</div>}
      </section>

      <HistorySection title="Lịch sử vay" items={loanHistory.map((item) => ({ id: item.id, amount: item.soTienDuyet || item.soTienVay, purpose: item.mucDich, date: item.ngayYeuCau, status: item.status, kind: 'loan' as const, raw: item }))} onView={(item) => setDetail({ kind: 'loan', request: item.raw as BankLoanRequest })} />
      <HistorySection title="Lịch sử cấp hạn mức" items={limitHistory.map((item) => ({ id: item.id, amount: item.ketQuaHanMucMoi || item.soTienDeNghi, purpose: item.lyDo, date: item.ngayYeuCau, status: item.status, kind: 'limit' as const, raw: item }))} onView={(item) => setDetail({ kind: 'limit', request: item.raw as BankLimitRequest })} />

      <HtxFundRequestSheet open={open} mode={mode} onClose={() => setOpen(false)} />

      <BottomSheet open={!!repaySourceId} onClose={closeRepay} title="HTX trả nợ bên cấp vốn">
        {repaySource && (
          <div className="space-y-4">
            <div className="rounded-xl bg-slate-50 p-3">
              <p className="text-xs font-bold text-slate-900">{repaySource.tenNguonVay}</p>
              <p className="mt-1 text-[11px] text-slate-500">Dư nợ mock: <span className="font-bold text-rose-700">{formatCurrencyCompact(repaySource.daSuDung)}</span></p>
            </div>
            {!repayResult ? (
              <>
                <label className="block">
                  <span className="mb-1.5 block text-xs font-medium text-slate-600">Số tiền trả</span>
                  <input type="number" value={repayAmount} onChange={(event) => setRepayAmount(event.target.value)} className="w-full rounded-xl border border-slate-200 px-3 py-3 text-sm outline-none focus:border-emerald-500" />
                </label>
                <div className="rounded-2xl border border-slate-200 bg-white p-3 text-center">
                  <MockQrCode seed={`${repaySource.id}-${repayAmount}-${repayTransferContent}`} />
                  <div className="mt-3 rounded-xl bg-slate-50 p-3 text-left">
                    <p className="text-[10px] font-semibold uppercase tracking-wide text-slate-400">Nội dung chuyển khoản</p>
                    <p className="mt-1 break-words text-xs font-bold text-slate-800">{repayTransferContent}</p>
                    <p className="mt-1 text-[11px] text-slate-500">Số tiền: <span className="font-bold text-emerald-700">{formatCurrencyCompact(Number(repayAmount) || 0)}</span></p>
                  </div>
                </div>
                <div className="rounded-xl border border-emerald-100 bg-emerald-50 p-3 text-[11px] leading-relaxed text-emerald-700">
                  Luồng này chỉ mô phỏng thao tác HTX trả nợ và kết quả xác nhận từ bên cấp vốn. Không tạo thêm user hay role.
                </div>
                <button type="button" onClick={submitRepay} className="w-full rounded-xl bg-emerald-700 px-4 py-3 text-sm font-bold text-white">Xác nhận trả nợ</button>
              </>
            ) : (
              <div className="space-y-3">
                <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-center">
                  <i className="ri-checkbox-circle-line text-3xl text-emerald-600" />
                  <p className="mt-2 text-sm font-bold text-emerald-900">Bên cấp vốn đã xác nhận</p>
                  <p className="mt-1 text-xs text-emerald-700">{formatCurrencyCompact(repayResult.amount)} · {repayResult.code}</p>
                </div>
                <button type="button" onClick={closeRepay} className="w-full rounded-xl bg-slate-100 px-4 py-3 text-sm font-bold text-slate-700">Đóng</button>
              </div>
            )}
          </div>
        )}
      </BottomSheet>

      <BottomSheet open={!!detail} onClose={() => setDetail(null)} title="Chi tiết nguồn vốn">
        {detail && (
          <FundDetailContent
            detail={detail}
            onRepay={(source) => {
              setDetail(null);
              openRepay(source.id);
            }}
          />
        )}
      </BottomSheet>
    </div>
  );
}

function FundMetric({ label, value, tone = 'slate' }: { label: string; value: string; tone?: 'slate' | 'amber' | 'emerald' }) {
  const color = tone === 'amber' ? 'text-amber-700' : tone === 'emerald' ? 'text-emerald-700' : 'text-slate-800';
  return <div className="min-w-0 rounded-xl bg-slate-50 p-2.5 text-center"><p className="text-[10px] text-slate-400">{label}</p><p className={`mt-0.5 truncate text-xs font-bold ${color}`}>{value}</p></div>;
}

type HistoryItem = {
  id: string;
  amount: number;
  purpose: string;
  date: string;
  status: string;
  kind: 'loan' | 'limit';
  raw: BankLoanRequest | BankLimitRequest;
};

function HistorySection({ title, items, onView }: { title: string; items: HistoryItem[]; onView: (item: HistoryItem) => void }) {
  const [expanded, setExpanded] = useState(false);
  const visible = expanded ? items : items.slice(0, 2);

  return (
    <section>
      <MobileSectionHeader
        title={title}
        count={`${items.length} yêu cầu`}
        actionLabel={items.length > 2 ? (expanded ? 'Thu gọn' : 'Xem tất cả') : undefined}
        onAction={items.length > 2 ? () => setExpanded((value) => !value) : undefined}
      />
      <div className="space-y-2">
        {visible.map((item) => (
          <button key={item.id} type="button" onClick={() => onView(item)} className="mobile-card w-full p-3.5 text-left transition active:scale-[0.99]">
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0">
                <p className="text-sm font-bold text-slate-900">{formatCurrencyCompact(item.amount)}</p>
                <p className="mt-1 line-clamp-2 text-xs text-slate-500">{item.purpose}</p>
                <p className="metric-caption mt-1 text-[10px] text-slate-400">{new Date(item.date).toLocaleDateString('vi-VN')}</p>
              </div>
              <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${getStatusClass(item.status)}`}>{item.status}</span>
            </div>
            <p className="mt-2 text-[10px] font-semibold text-emerald-700">Bấm để xem chi tiết</p>
          </button>
        ))}
        {items.length === 0 && <div className="rounded-2xl border border-dashed border-slate-200 py-6 text-center text-xs text-slate-400">Chưa có yêu cầu</div>}
      </div>
    </section>
  );
}

function FundDetailContent({ detail, onRepay }: { detail: FundDetail; onRepay: (source: HtxLoanSource) => void }) {
  if (detail.kind === 'source') {
    const source = detail.source;
    const remaining = getHtxSourceRemaining(source);
    const dueDays = getDaysRemaining(source.ngayKetThuc);
    const interest = calculateMonthlySimpleInterest(source.daSuDung, source.laiSuat, source.ngayBatDau);
    const alert = buildDueAlert(dueDays, source.status, source.daSuDung > 0);

    return (
      <div className="space-y-4">
        <div className="rounded-2xl border border-slate-200 bg-white p-4">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <p className="text-sm font-bold text-slate-900">{source.tenNguonVay}</p>
              <p className="mt-1 text-[11px] text-slate-400">{source.maNguonVay} · {source.loaiNguon}</p>
            </div>
            <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${getStatusClass(source.status)}`}>{source.status}</span>
          </div>
          <div className="mt-4 grid grid-cols-2 gap-2">
            <DetailMetric label="Tổng hạn mức" value={formatCurrencyCompact(source.hanMuc)} />
            <DetailMetric label="Dư nợ HTX" value={formatCurrencyCompact(source.daSuDung)} tone={source.daSuDung > 0 ? 'rose' : 'slate'} />
            <DetailMetric label="Lãi tạm tính" value={formatCurrencyCompact(interest)} tone="amber" />
            <DetailMetric label="Còn lại" value={formatCurrencyCompact(remaining)} tone="emerald" />
          </div>
          <div className="mt-4 space-y-2">
            <DetailLine label="Lãi suất" value={`${source.laiSuat}%/tháng · lãi đơn`} />
            <DetailLine label="Kỳ hạn" value={source.kyHan} />
            <DetailLine label="Ngày bắt đầu" value={formatDateShort(source.ngayBatDau)} />
            <DetailLine label="Ngày đến hạn" value={`${formatDateShort(source.ngayKetThuc)} · ${formatRemainingDays(dueDays)}`} />
          </div>
        </div>

        <StatusAlert tone={alert.tone} text={alert.text} />
        {source.ghiChu && <p className="rounded-xl bg-slate-50 p-3 text-xs leading-relaxed text-slate-600">{source.ghiChu}</p>}
        {source.daSuDung > 0 && (
          <button type="button" onClick={() => onRepay(source)} className="w-full rounded-xl bg-emerald-700 px-4 py-3 text-sm font-bold text-white">
            Trả nợ nguồn vốn này
          </button>
        )}
      </div>
    );
  }

  if (detail.kind === 'loan') {
    const request = detail.request;
    const amount = request.soTienDuyet || request.soTienVay;
    const startDate = request.ngayGiaiNgan || request.ngayCapNhat || request.ngayYeuCau;
    const dueDate = addMonths(startDate, parseTermMonths(request.thoiHanVay));
    const dueDays = getDaysRemaining(dueDate);
    const annualRate = request.laiSuatDuyet || request.laiSuatDeXuat || 5.5;
    const interest = request.status === 'Đã giải ngân' ? calculateAnnualSimpleInterest(amount, annualRate, startDate) : 0;
    const alert = buildRequestAlert(request.status, dueDays, request.lyDoTuChoi || request.noiDungBoSung);

    return (
      <div className="space-y-4">
        <div className="rounded-2xl border border-slate-200 bg-white p-4">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <p className="text-sm font-bold text-slate-900">{formatCurrencyCompact(amount)}</p>
              <p className="mt-1 line-clamp-2 text-xs text-slate-500">{request.mucDich}</p>
            </div>
            <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${getStatusClass(request.status)}`}>{request.status}</span>
          </div>
          <div className="mt-4 grid grid-cols-2 gap-2">
            <DetailMetric label="Số tiền đề nghị" value={formatCurrencyCompact(request.soTienVay)} />
            <DetailMetric label="Số tiền duyệt" value={formatCurrencyCompact(amount)} tone="emerald" />
            <DetailMetric label="Lãi tạm tính" value={formatCurrencyCompact(interest)} tone="amber" />
            <DetailMetric label="Lãi suất" value={`${annualRate}%/năm`} />
          </div>
          <div className="mt-4 space-y-2">
            <DetailLine label="Kỳ hạn" value={request.thoiHanVay} />
            <DetailLine label="Ngày yêu cầu" value={formatDateShort(request.ngayYeuCau)} />
            <DetailLine label="Ngày giải ngân" value={request.ngayGiaiNgan ? formatDateShort(request.ngayGiaiNgan) : 'Chưa giải ngân'} />
            <DetailLine label="Ngày đến hạn" value={`${formatDateShort(dueDate)} · ${formatRemainingDays(dueDays)}`} />
            {request.maGiaoDich && <DetailLine label="Mã giao dịch" value={request.maGiaoDich} />}
          </div>
        </div>
        <StatusAlert tone={alert.tone} text={alert.text} />
        {request.ghiChu && <p className="rounded-xl bg-slate-50 p-3 text-xs leading-relaxed text-slate-600">{request.ghiChu}</p>}
      </div>
    );
  }

  const request = detail.request;
  const amount = request.ketQuaHanMucMoi || request.soTienDeNghi;
  const alert = buildRequestAlert(request.status, 999, request.lyDoTuChoi || request.noiDungBoSung);

  return (
    <div className="space-y-4">
      <div className="rounded-2xl border border-slate-200 bg-white p-4">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="text-sm font-bold text-slate-900">{formatCurrencyCompact(amount)}</p>
            <p className="mt-1 line-clamp-2 text-xs text-slate-500">{request.lyDo}</p>
          </div>
          <span className={`shrink-0 rounded-full px-2 py-1 text-[10px] font-semibold ${getStatusClass(request.status)}`}>{request.status}</span>
        </div>
        <div className="mt-4 grid grid-cols-2 gap-2">
          <DetailMetric label="Đề nghị" value={formatCurrencyCompact(request.soTienDeNghi)} />
          <DetailMetric label="Kết quả" value={request.ketQuaHanMucMoi ? formatCurrencyCompact(request.ketQuaHanMucMoi) : 'Chưa có'} tone={request.ketQuaHanMucMoi ? 'emerald' : 'slate'} />
          <DetailMetric label="Ngày yêu cầu" value={formatDateShort(request.ngayYeuCau)} />
          <DetailMetric label="Cập nhật" value={request.ngayCapNhat ? formatDateShort(request.ngayCapNhat) : 'Chờ phản hồi'} />
        </div>
      </div>
      <StatusAlert tone={alert.tone} text={alert.text} />
      {request.ghiChu && <p className="rounded-xl bg-slate-50 p-3 text-xs leading-relaxed text-slate-600">{request.ghiChu}</p>}
    </div>
  );
}

function DetailMetric({ label, value, tone = 'slate' }: { label: string; value: string; tone?: 'slate' | 'emerald' | 'amber' | 'rose' }) {
  const color = tone === 'emerald' ? 'text-emerald-700' : tone === 'amber' ? 'text-amber-700' : tone === 'rose' ? 'text-rose-700' : 'text-slate-800';
  return <div className="min-w-0 rounded-xl bg-slate-50 p-3"><p className="text-[10px] text-slate-400">{label}</p><p className={`mt-0.5 truncate text-xs font-bold ${color}`}>{value}</p></div>;
}

function DetailLine({ label, value }: { label: string; value: string }) {
  return <div className="flex items-start justify-between gap-3 text-xs"><span className="shrink-0 text-slate-400">{label}</span><span className="min-w-0 text-right font-semibold text-slate-700">{value}</span></div>;
}

function StatusAlert({ tone, text }: { tone: 'emerald' | 'amber' | 'rose' | 'slate'; text: string }) {
  const className = tone === 'rose'
    ? 'border-rose-200 bg-rose-50 text-rose-700'
    : tone === 'amber'
      ? 'border-amber-200 bg-amber-50 text-amber-700'
      : tone === 'emerald'
        ? 'border-emerald-200 bg-emerald-50 text-emerald-700'
        : 'border-slate-200 bg-slate-50 text-slate-600';
  const icon = tone === 'rose' ? 'ri-alert-line' : tone === 'amber' ? 'ri-time-line' : tone === 'emerald' ? 'ri-checkbox-circle-line' : 'ri-information-line';
  return <div className={`flex items-start gap-2 rounded-xl border p-3 text-xs leading-relaxed ${className}`}><i className={`${icon} mt-0.5 shrink-0`} /><span>{text}</span></div>;
}

function MockQrCode({ seed }: { seed: string }) {
  const base = hashSeed(seed || 'agrida');
  const cells = Array.from({ length: 81 }, (_, index) => ((base + index * 17 + (index % 5) * 13) % 9) < 4);
  return (
    <div className="mx-auto grid h-40 w-40 grid-cols-9 gap-0.5 rounded-xl border-2 border-slate-800 bg-white p-3">
      {cells.map((active, index) => (
        <span key={index} className={`rounded-[2px] ${active || index < 3 || index > 77 ? 'bg-slate-900' : 'bg-transparent'}`} />
      ))}
    </div>
  );
}

function hashSeed(seed: string): number {
  return seed.split('').reduce((hash, char) => ((hash << 5) - hash + char.charCodeAt(0)) >>> 0, 0);
}

function parseTermMonths(term?: string): number {
  if (!term) return 12;
  const value = Number.parseInt(term, 10);
  return Number.isFinite(value) && value > 0 ? value : 12;
}

function addMonths(dateValue: string, months: number): string {
  const date = new Date(dateValue);
  if (Number.isNaN(date.getTime())) return dateValue;
  date.setMonth(date.getMonth() + months);
  return date.toISOString().split('T')[0];
}

function getDaysRemaining(dateValue: string): number {
  const target = new Date(dateValue);
  if (Number.isNaN(target.getTime())) return 999;
  const today = new Date();
  const todayStart = new Date(today.getFullYear(), today.getMonth(), today.getDate());
  const targetStart = new Date(target.getFullYear(), target.getMonth(), target.getDate());
  return Math.ceil((targetStart.getTime() - todayStart.getTime()) / (1000 * 60 * 60 * 24));
}

function calculateMonthlySimpleInterest(principal: number, monthlyRate: number, startDate: string): number {
  if (principal <= 0) return 0;
  const start = new Date(startDate);
  if (Number.isNaN(start.getTime())) return 0;
  const days = Math.max(0, Math.floor((Date.now() - start.getTime()) / (1000 * 60 * 60 * 24)));
  return Math.round(principal * (monthlyRate / 30 / 100) * days);
}

function calculateAnnualSimpleInterest(principal: number, annualRate: number, startDate: string): number {
  if (principal <= 0) return 0;
  const start = new Date(startDate);
  if (Number.isNaN(start.getTime())) return 0;
  const days = Math.max(0, Math.floor((Date.now() - start.getTime()) / (1000 * 60 * 60 * 24)));
  return Math.round(principal * (annualRate / 365 / 100) * days);
}

function formatDateShort(dateValue: string): string {
  const date = new Date(dateValue);
  return Number.isNaN(date.getTime()) ? dateValue : date.toLocaleDateString('vi-VN');
}

function formatRemainingDays(days: number): string {
  if (days < 0) return `quá hạn ${Math.abs(days)} ngày`;
  if (days === 0) return 'đến hạn hôm nay';
  return `còn ${days} ngày`;
}

function buildDueAlert(days: number, status: string, hasDebt: boolean): { tone: 'emerald' | 'amber' | 'rose' | 'slate'; text: string } {
  if (status === 'Đã kết thúc') return { tone: 'slate', text: 'Nguồn vốn đã kết thúc, chỉ giữ để đối chiếu lịch sử.' };
  if (!hasDebt) return { tone: 'emerald', text: 'Nguồn vốn chưa phát sinh dư nợ, chưa cần thao tác trả nợ.' };
  if (days < 0) return { tone: 'rose', text: `Nguồn vốn đã quá hạn ${Math.abs(days)} ngày. Cần ưu tiên trả nợ hoặc gia hạn với bên cấp vốn.` };
  if (days <= 7) return { tone: 'rose', text: `Nguồn vốn còn ${days} ngày đến hạn. Cần xử lý trả nợ ngay.` };
  if (days <= 30) return { tone: 'amber', text: `Nguồn vốn còn ${days} ngày đến hạn. Nên chuẩn bị kế hoạch trả nợ hoặc gia hạn.` };
  return { tone: 'emerald', text: `Nguồn vốn còn ${days} ngày đến hạn, đang trong trạng thái theo dõi bình thường.` };
}

function buildRequestAlert(status: string, days: number, note?: string): { tone: 'emerald' | 'amber' | 'rose' | 'slate'; text: string } {
  if (status === 'Từ chối') return { tone: 'rose', text: note || 'Yêu cầu bị từ chối bởi bên cấp vốn mô phỏng.' };
  if (status === 'Cần bổ sung') return { tone: 'amber', text: note || 'Cần bổ sung hồ sơ trước khi bên cấp vốn phê duyệt.' };
  if (status === 'Chờ duyệt') return { tone: 'amber', text: 'Yêu cầu đang chờ bên cấp vốn phản hồi mockdata.' };
  if (status === 'Đã giải ngân' && days < 0) return { tone: 'rose', text: `Khoản vay đã quá hạn ${Math.abs(days)} ngày. Cần kiểm tra kế hoạch trả nợ.` };
  if (status === 'Đã giải ngân' && days <= 30) return { tone: 'amber', text: `Khoản vay còn ${days} ngày đến hạn. Nên chuẩn bị thanh toán.` };
  if (status.includes('Đã')) return { tone: 'emerald', text: 'Yêu cầu đã có kết quả phê duyệt từ bên cấp vốn mô phỏng.' };
  return { tone: 'slate', text: 'Thông tin đang được hiển thị bằng mockdata, không tạo thêm role bên thứ ba.' };
}

function getStatusClass(status: string): string {
  if (status === 'Từ chối' || status.includes('lỗi') || status.includes('quá hạn')) return 'bg-rose-100 text-rose-700';
  if (status === 'Cần bổ sung' || status.includes('Chờ') || status === 'Sắp hết hạn') return 'bg-amber-100 text-amber-700';
  if (status.includes('Đã') || status === 'Đang hiệu lực') return 'bg-emerald-100 text-emerald-700';
  return 'bg-slate-100 text-slate-600';
}
