import { useState, useMemo } from 'react';
import type { Farmer, RiskProfile } from '../../../../types';
import { getFarmerKyc, getKycLabel, getRiskProfileByFarmer, getDebtsByFarmer, getLogsByFarmer, getHarvestsByFarmer, getSeasonsByFarmer, getContractsByFarmer, getFinancesByFarmer, updateRiskProfile, addRiskProfile } from '../../../../store';
import { StatusBadge } from '../../../../components/base/StatusBadge';
import { showToast } from '../../../../components/base/Toast';
import { formatDate, formatVND } from '../../../../utils/format';
import { useStore } from '../../../../hooks/useStore';
import { DEBT_STATUS, CONTRACT_STATUS, getCreditScoreColor, getCreditScoreBg, getCreditScoreBorder } from '../../../../utils/status';
import { getScoreBand, getRiskLevelFromScore, getScoreBarPercent, getScoreBarColor, SCORE_BANDS } from '../../../../utils/creditScore';

interface DetailEkycRiskTabProps {
  farmer: Farmer;
}

export default function DetailEkycRiskTab({ farmer }: DetailEkycRiskTabProps) {
  useStore();
  const kyc = getFarmerKyc(farmer);
  const existing = getRiskProfileByFarmer(farmer.id);
  const kycLabel = getKycLabel(kyc.kycStatus);
  const [requesting, setRequesting] = useState(false);
  const [editing, setEditing] = useState(false);
  const [mucDo, setMucDo] = useState<RiskProfile['mucDo']>(existing?.mucDo || 'Tốt');
  const [moTa, setMoTa] = useState(existing?.moTa || '');

  const isVerified = kyc.kycStatus === 'ekyc_verified';
  const needsMore = kyc.kycStatus === 'ekyc_need_more';
  const isFailed = kyc.kycStatus === 'ekyc_failed';
  const isPending = kyc.kycStatus === 'ekyc_pending';

  const handleRequestReverify = () => {
    setRequesting(true);
    setTimeout(() => { setRequesting(false); showToast(`Đã gửi yêu cầu xác thực lại cho ${farmer.name}`, 'success'); }, 1500);
  };

  // ─── Risk factors ───
  const diaries = getLogsByFarmer(farmer.id).filter((d) => !d.isDeleted);
  const seasons = getSeasonsByFarmer(farmer.id);
  const debts = getDebtsByFarmer(farmer.id);
  const contracts = getContractsByFarmer(farmer.id);
  const harvests = getHarvestsByFarmer(farmer.id).filter((h) => !h.isDeleted);
  const finances = getFinancesByFarmer(farmer.id);

  const ekycScore = useMemo(() => {
    if (isVerified && (kyc.creditScore ?? 0) >= 760) return 20;
    if (isVerified && (kyc.creditScore ?? 0) >= 650) return 16;
    if (isVerified && (kyc.creditScore ?? 0) >= 550) return 12;
    if (isVerified) return 8;
    if (isPending) return 4;
    if (needsMore) return 2;
    return 0;
  }, [kyc, isVerified, isPending, needsMore]);

  const diaryScore = useMemo(() => {
    const last30Days = diaries.filter((d) => { const days = Math.floor((Date.now() - new Date(d.ngay).getTime()) / (1000 * 60 * 60 * 24)); return days <= 30; }).length;
    if (last30Days >= 6) return 16;
    if (last30Days >= 3) return 10;
    if (last30Days >= 1) return 5;
    return 0;
  }, [diaries]);

  const yieldScore = useMemo(() => {
    const confirmed = harvests.filter((h) => h.actualYieldConfirmed && h.actualYieldConfirmed > 0);
    if (confirmed.length === 0) {
      const active = seasons.filter((s) => s.status === 'Đang canh tác' || s.status === 'Sắp thu hoạch');
      return active.length > 0 ? 12 : 14;
    }
    const ratios = confirmed.map((h) => { const s = seasons.find((se) => se.id === h.seasonId); const e = s ? s.expectedYield * 1000 : h.soLuong * 1000; return e > 0 ? h.actualYieldConfirmed! / e : 1; });
    const avg = ratios.reduce((s, r) => s + r, 0) / ratios.length;
    if (avg >= 0.9) return 20;
    if (avg >= 0.7) return 12;
    return 4;
  }, [harvests, seasons]);

  const debtScore = useMemo(() => {
    const overDue = debts.filter((d) => d.status === DEBT_STATUS.OVERDUE);
    const dueSoon = debts.filter((d) => d.status === DEBT_STATUS.DUE_SOON || d.status === DEBT_STATUS.DUE);
    const settled = debts.filter((d) => d.status === DEBT_STATUS.SETTLED).length;
    if (overDue.length > 0) return 0;
    if (dueSoon.length > 0) return 10;
    if (settled >= 2) return 20;
    return 14;
  }, [debts]);

  const contractScore = useMemo(() => {
    const valid = contracts.filter((c) => c.status === CONTRACT_STATUS.ACTIVE);
    const expiring = contracts.filter((c) => c.status === CONTRACT_STATUS.EXPIRING_SOON);
    if (valid.length >= 2) return 20;
    if (valid.length >= 1) return 16;
    if (expiring.length > 0) return 8;
    return 4;
  }, [contracts]);

  const totalScore = ekycScore + diaryScore + yieldScore + debtScore + contractScore;
  const autoRisk: RiskProfile['mucDo'] = totalScore >= 70 ? 'Tốt' : totalScore >= 45 ? 'Cần chú ý' : 'Nguy cơ';

  // Credit score band
  const scoreBand = getScoreBand(kyc.creditScore);
  const scoreBarPercent = getScoreBarPercent(kyc.creditScore);
  const scoreBarColor = getScoreBarColor(kyc.creditScore);

  const handleSaveRisk = () => {
    const now = new Date().toISOString();
    if (existing) updateRiskProfile(existing.id, { mucDo, moTa, ngayCapNhat: now });
    else addRiskProfile({ farmerId: farmer.id, mucDo, moTa, ngayCapNhat: now });
    setEditing(false);
    showToast('Đã cập nhật risk profile', 'success');
  };

  const scoreColor = getCreditScoreColor(kyc.creditScore);
  const scoreBg = getCreditScoreBg(kyc.creditScore);

  const hasOcr = !!(kyc.ocrName || kyc.ocrDob || kyc.ocrGender || kyc.ocrAddress);
  const selfieLabel = kyc.selfieResult || 'Chưa có';

  const paymentStats = useMemo(() => {
    const completed = finances.filter((f) => f.loai === 'Chi' && f.trangThai === 'Hoàn thành');
    const settled = debts.filter((d) => d.status === DEBT_STATUS.SETTLED).length;
    const totalPaid = completed.reduce((s, f) => s + f.soTien, 0);
    return { onTime: completed.length, settled, totalPaid };
  }, [finances, debts]);

  return (
    <div className="space-y-4">
      {/* ── eKYC Section ── */}
      <div className="bg-white rounded-xl border border-slate-200 p-4 md:p-5">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-base font-semibold text-slate-900">Trạng thái eKYC</h3>
          <StatusBadge status={kycLabel} />
        </div>

        {isVerified && <div className="p-3 rounded-lg bg-emerald-50 border border-emerald-100 mb-4 text-sm text-emerald-800 font-medium">Nông hộ đã hoàn tất xác thực eKYC</div>}
        {isPending && <div className="p-3 rounded-lg bg-sky-50 border border-sky-100 mb-4 text-sm text-sky-800 font-medium">Hồ sơ eKYC đang được hệ thống xử lý.</div>}
        {needsMore && <div className="p-3 rounded-lg bg-amber-50 border border-amber-100 mb-4"><p className="text-sm text-amber-800 font-medium">Cần bổ sung thông tin eKYC</p>{kyc.kycReason && <p className="text-xs text-amber-700 mt-1"><span className="font-medium">Lý do:</span> {kyc.kycReason}</p>}</div>}
        {isFailed && <div className="p-3 rounded-lg bg-red-50 border border-red-100 mb-4"><p className="text-sm text-red-800 font-medium">eKYC thất bại</p>{kyc.kycReason && <p className="text-xs text-red-700 mt-1"><span className="font-medium">Lý do:</span> {kyc.kycReason}</p>}</div>}

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          <div><p className="text-xs text-slate-500">Ngày xác thực</p><p className="text-sm font-medium text-slate-800 mt-0.5">{kyc.verifiedAt ? formatDate(kyc.verifiedAt) : '—'}</p></div>
          <div><p className="text-xs text-slate-500">Số CCCD</p><p className="text-sm font-medium text-slate-800 mt-0.5">{kyc.cccdMask || '—'}</p></div>
          <div><p className="text-xs text-slate-500">Credit score</p><p className={`text-lg font-bold ${scoreColor}`}>{kyc.creditScore ?? '—'}</p></div>
          <div><p className="text-xs text-slate-500">Kết quả selfie</p><span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium mt-0.5 ${selfieLabel === 'Khớp' ? 'bg-emerald-100 text-emerald-700' : selfieLabel === 'Không khớp' ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-500'}`}>{selfieLabel}</span></div>
        </div>

        {/* OCR details */}
        {hasOcr && (
          <div className="mt-3 pt-3 border-t border-slate-100">
            <p className="text-xs text-slate-500 mb-2">Kết quả OCR</p>
            <div className="grid grid-cols-2 gap-2 text-xs">
              {kyc.ocrName && <div><span className="text-slate-400">Tên CCCD:</span> <span className="font-medium text-slate-700 ml-1">{kyc.ocrName}</span></div>}
              {kyc.ocrDob && <div><span className="text-slate-400">Ngày sinh:</span> <span className="font-medium text-slate-700 ml-1">{kyc.ocrDob}</span></div>}
              {kyc.ocrGender && <div><span className="text-slate-400">Giới tính:</span> <span className="font-medium text-slate-700 ml-1">{kyc.ocrGender}</span></div>}
              {kyc.ocrIssueDate && <div><span className="text-slate-400">Ngày cấp:</span> <span className="font-medium text-slate-700 ml-1">{kyc.ocrIssueDate}</span></div>}
              {kyc.ocrAddress && <div className="col-span-2"><span className="text-slate-400">Địa chỉ:</span> <span className="font-medium text-slate-700 ml-1">{kyc.ocrAddress}</span></div>}
            </div>
          </div>
        )}

        {/* Action */}
        <div className="mt-4 flex gap-3">
          {!isVerified && (
            <button type="button" onClick={handleRequestReverify} disabled={requesting} className="flex-1 px-4 py-2.5 rounded-lg text-sm font-medium bg-emerald-700 hover:bg-emerald-800 text-white transition-colors whitespace-nowrap min-h-[44px] disabled:opacity-60">
              {requesting ? 'Đang gửi...' : 'Yêu cầu xác thực lại'}
            </button>
          )}
          {isVerified && (
            <button type="button" onClick={handleRequestReverify} disabled={requesting} className="flex-1 px-4 py-2.5 rounded-lg text-sm font-medium bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors whitespace-nowrap min-h-[44px]">
              {requesting ? 'Đang gửi...' : 'Yêu cầu xác thực lại (làm mới)'}
            </button>
          )}
        </div>
      </div>

      {/* ── Credit Score 5-Band Visualization ── */}
      {kyc.creditScore && (
        <div className="bg-white rounded-xl border border-slate-200 p-4 md:p-5">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-base font-semibold text-slate-900">Điểm tín dụng — Hệ thống 5 cấp</h3>
            <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold ${scoreBg} ${scoreColor} border ${getCreditScoreBorder(kyc.creditScore)}`}>
              <span className="w-3 h-3 flex items-center justify-center"><i className="ri-funds-line text-[10px]" /></span>
              {kyc.creditScore}/900
            </span>
          </div>

          {/* Score bar with 5 bands */}
          <div className="mb-3">
            <div className="h-3 rounded-full overflow-hidden flex">
              <div className="bg-red-400 flex items-center justify-center" style={{ width: '16.67%' }}>
                <span className="text-[8px] text-white font-semibold">Nguy cơ</span>
              </div>
              <div className="bg-orange-400 flex items-center justify-center" style={{ width: '16.67%' }}>
                <span className="text-[8px] text-white font-semibold">Rủi ro</span>
              </div>
              <div className="bg-amber-400 flex items-center justify-center" style={{ width: '16.67%' }}>
                <span className="text-[8px] text-white font-semibold">Chú ý</span>
              </div>
              <div className="bg-teal-400 flex items-center justify-center" style={{ width: '16.67%' }}>
                <span className="text-[8px] text-white font-semibold">Khá</span>
              </div>
              <div className="bg-emerald-400 flex items-center justify-center" style={{ width: '33.33%' }}>
                <span className="text-[8px] text-white font-semibold">Tốt</span>
              </div>
            </div>
            <div className="flex justify-between text-[9px] text-slate-400 mt-1">
              <span>300</span><span>450</span><span>550</span><span>650</span><span>760</span><span>900</span>
            </div>
            {/* Current score marker */}
            <div className="relative mt-1">
              <div className="absolute w-3 h-3 bg-white border-2 border-slate-800 rounded-full transform -translate-x-1/2" style={{ left: `${Math.min(98, scoreBarPercent)}%` }} />
            </div>
          </div>

          {/* Band legend */}
          <div className="grid grid-cols-5 gap-1.5">
            {SCORE_BANDS.map((band) => (
              <div key={band.band} className={`text-center p-1.5 rounded-lg border ${scoreBand.band === band.band ? `${band.bgColor} ${band.borderColor} ring-2 ring-offset-1 ${band.barColor}` : 'border-slate-100 bg-slate-50'}`}>
                <span className="text-[9px] font-semibold">{band.band}</span>
                <p className="text-[8px] text-slate-400">{band.min}–{band.max}</p>
              </div>
            ))}
          </div>

          {/* System recommendation for this score */}
          <div className={`mt-3 p-2.5 rounded-lg border ${scoreBand.bgColor} ${scoreBand.borderColor}`}>
            <p className={`text-xs font-bold ${scoreBand.color}`}>Khuyến nghị: </p>
            <p className="text-[11px] text-slate-600 mt-0.5">{scoreBand.recommendation}</p>
          </div>
        </div>
      )}

      {/* ── Risk Assessment Section ── */}
      <div className="bg-white rounded-xl border border-slate-200 p-4 md:p-5">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-base font-semibold text-slate-900">Đánh giá rủi ro</h3>
            <p className="text-xs text-slate-500 mt-0.5">Tổng điểm: {totalScore}/100 → <strong className="text-slate-700">{autoRisk}</strong></p>
          </div>
          <StatusBadge status={mucDo} />
        </div>

        {/* Score bar */}
        <div className="mb-4">
          <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all ${totalScore >= 70 ? 'bg-emerald-500' : totalScore >= 45 ? 'bg-amber-500' : 'bg-red-500'}`} style={{ width: `${Math.max(4, totalScore)}%` }} />
          </div>
          <div className="flex justify-between text-xs text-slate-400 mt-1"><span>0 — Nguy cơ</span><span>45 — Cần chú ý</span><span>70 — Tốt</span></div>
        </div>

        {/* Factors */}
        <div className="space-y-1.5">
          {[
            { label: 'eKYC & Định danh', score: ekycScore, desc: isVerified ? (kyc.creditScore ? `Score ${kyc.creditScore}/900` : 'Đã xác thực') : 'Chưa xác thực' },
            { label: 'Nhật ký canh tác', score: diaryScore, desc: `${diaries.filter((d) => { const days = Math.floor((Date.now() - new Date(d.ngay).getTime()) / (1000 * 60 * 60 * 24)); return days <= 30; }).length} nhật ký / 30 ngày` },
            { label: 'Sản lượng thu hoạch', score: yieldScore, desc: `${harvests.filter((h) => h.actualYieldConfirmed && h.actualYieldConfirmed > 0).length} lần thu hoạch đã xác nhận` },
            { label: 'Thanh toán & Công nợ', score: debtScore, desc: debts.some((d) => d.status === DEBT_STATUS.OVERDUE) ? 'Có nợ quá hạn' : debts.filter((d) => d.status === DEBT_STATUS.SETTLED).length >= 2 ? `${debts.filter((d) => d.status === DEBT_STATUS.SETTLED).length} khoản đã tất toán` : 'Đang vay' },
            { label: 'Hợp đồng bao tiêu', score: contractScore, desc: `${contracts.filter((c) => c.status === CONTRACT_STATUS.ACTIVE).length} hợp đồng hiệu lực` },
          ].map((f, idx) => (
            <div key={idx} className="flex items-center justify-between p-2.5 rounded-lg bg-slate-50">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-medium text-slate-400 w-4">{idx + 1}.</span>
                  <p className="text-sm font-medium text-slate-800">{f.label}</p>
                </div>
                <p className="text-xs text-slate-500 ml-6">{f.desc}</p>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <span className={`text-xs font-bold ${f.score >= 14 ? 'text-emerald-600' : f.score >= 8 ? 'text-amber-600' : 'text-red-600'}`}>{f.score}/20</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ── Payment history ── */}
      <div className="bg-white rounded-xl border border-slate-200 p-4 md:p-5">
        <h3 className="text-base font-semibold text-slate-900 mb-3">Lịch sử trả nợ</h3>
        <div className="grid grid-cols-3 gap-3">
          <div className="p-3 rounded-lg bg-emerald-50 text-center"><p className="text-xs text-slate-500">Trả đúng hạn</p><p className="text-lg font-bold text-emerald-700">{paymentStats.onTime}</p></div>
          <div className="p-3 rounded-lg bg-sky-50 text-center"><p className="text-xs text-slate-500">Đã tất toán</p><p className="text-lg font-bold text-sky-700">{paymentStats.settled}</p></div>
          <div className="p-3 rounded-lg bg-amber-50 text-center"><p className="text-xs text-slate-500">Tổng đã trả</p><p className="text-sm font-bold text-amber-700">{formatVND(paymentStats.totalPaid)}</p></div>
        </div>
      </div>

      {/* ── Manual risk editor ── */}
      <div className="bg-white rounded-xl border border-slate-200 p-4 md:p-5">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-base font-semibold text-slate-900">Đánh giá thủ công</h3>
          {!editing && (
            <button type="button" onClick={() => setEditing(true)} className="px-3 py-2 rounded-md text-sm font-medium bg-emerald-50 text-emerald-700 hover:bg-emerald-100 transition-colors whitespace-nowrap min-h-[44px]">
              <span className="w-4 h-4 inline-flex items-center justify-center mr-1"><i className="ri-edit-line" /></span>Cập nhật
            </button>
          )}
        </div>
        {editing ? (
          <div className="space-y-3">
            <div className="flex flex-wrap gap-2">
              {(['Tốt', 'Khá', 'Cần chú ý', 'Rủi ro cao', 'Nguy cơ'] as const).map((m) => (
                <button key={m} type="button" onClick={() => setMucDo(m)} className={`px-3 py-1.5 rounded-lg text-sm font-medium border transition-colors ${mucDo === m ? (m === 'Tốt' ? 'bg-emerald-100 border-emerald-300 text-emerald-800' : m === 'Khá' ? 'bg-teal-100 border-teal-300 text-teal-800' : m === 'Cần chú ý' ? 'bg-amber-100 border-amber-300 text-amber-800' : m === 'Rủi ro cao' ? 'bg-orange-100 border-orange-300 text-orange-800' : 'bg-red-100 border-red-300 text-red-800') : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}>{m}</button>
              ))}
            </div>
            <textarea value={moTa} onChange={(e) => setMoTa(e.target.value)} rows={3} maxLength={500} className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500" placeholder="Nhập nhận xét về rủi ro..." />
            <div className="flex gap-3 justify-end">
              <button type="button" onClick={() => setEditing(false)} className="px-4 py-2 rounded-md text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]">Hủy</button>
              <button type="button" onClick={handleSaveRisk} className="px-4 py-2 rounded-md text-sm font-medium bg-emerald-700 hover:bg-emerald-800 text-white transition-colors whitespace-nowrap min-h-[44px]">Lưu</button>
            </div>
          </div>
        ) : (
          <div className="space-y-2">
            <div className="flex items-center gap-3"><p className="text-sm text-slate-600">Mức risk:</p><StatusBadge status={mucDo} /></div>
            {existing && <p className="text-xs text-slate-400">Cập nhật lần cuối: {formatDate(existing.ngayCapNhat)}</p>}
            {moTa && <div className="p-3 rounded-lg bg-slate-50 border border-slate-100"><p className="text-xs text-slate-500">Nhận xét:</p><p className="text-sm text-slate-700 mt-0.5">{moTa}</p></div>}
          </div>
        )}
      </div>
    </div>
  );
}