import { useState, useMemo } from 'react';
import type { Farmer } from '../../../types';
import FarmerDetailSheet from './components/FarmerDetailSheet';
import { getFarmers, getFarmerKyc, getDebtsByFarmer, getLimitsByFarmer, getContractsByFarmer, getLoansByFarmer, getFieldsByFarmer } from '../../../store';
import { StatusBadge } from '../../../components/base/StatusBadge';
import { formatCompactCurrency } from '../../../utils/format';
import { useStore } from '../../../hooks/useStore';
import { DEBT_STATUS, LOAN_STATUS } from '../../../utils/status';
import { getCreditScoreColor } from '../../../utils/status';
import { SearchFilterBar } from '@/components/base/SearchFilterBar';

function getDebtSummary(farmerId: string): { label: string; hasOverdue: boolean; hasDueSoon: boolean; hasActive: boolean } {
  const debts = getDebtsByFarmer(farmerId).filter((d) => d.conNo > 0);
  if (debts.length === 0) return { label: 'Không nợ', hasOverdue: false, hasDueSoon: false, hasActive: false };
  if (debts.some((d) => d.status === DEBT_STATUS.OVERDUE)) return { label: 'Quá hạn', hasOverdue: true, hasDueSoon: false, hasActive: false };
  if (debts.some((d) => d.status === DEBT_STATUS.DUE_SOON || d.status === DEBT_STATUS.DUE)) return { label: 'Sắp đến hạn', hasOverdue: false, hasDueSoon: true, hasActive: false };
  if (debts.some((d) => d.status === DEBT_STATUS.ACTIVE || d.status === DEBT_STATUS.PENDING_PAYMENT)) return { label: 'Đang vay', hasOverdue: false, hasDueSoon: false, hasActive: true };
  return { label: 'Không nợ', hasOverdue: false, hasDueSoon: false, hasActive: false };
}

function FarmerCard({ farmer, isSelected, onClick }: { farmer: Farmer; isSelected: boolean; onClick: () => void }) {
  const kyc = getFarmerKyc(farmer);
  const fields = getFieldsByFarmer(farmer.id);
  const debts = getDebtsByFarmer(farmer.id);
  const limits = getLimitsByFarmer(farmer.id);
  const totalArea = fields.reduce((sum, fi) => sum + fi.area, 0);
  const totalNo = debts.filter((d) => d.conNo > 0).reduce((sum, d) => sum + d.conNo, 0);
  const hanMucTong = limits.reduce((sum, l) => sum + l.hanMuc, 0);
  const daDung = limits.reduce((sum, l) => sum + l.daSuDung, 0);
  const conLai = hanMucTong - daDung;
  const pendingLoans = getLoansByFarmer(farmer.id).filter((l) => l.status === LOAN_STATUS.PENDING_CHECK || l.status === LOAN_STATUS.NEED_MORE);
  const debtSummary = getDebtSummary(farmer.id);
  const isLocked = kyc.kycStatus !== 'ekyc_verified';
  const isHighRisk = kyc.riskLevel === 'Nguy cơ';
  const scoreColor = getCreditScoreColor(kyc.creditScore);

  return (
    <button
      type="button"
      onClick={onClick}
      data-testid={isSelected ? 'farmer-detail-active' : 'farmer-detail-button'}
      className={`w-full text-left p-3 rounded-xl border transition-colors ${isSelected ? 'border-emerald-700 bg-emerald-50/50 ring-1 ring-emerald-700' : 'border-slate-200 bg-white hover:border-emerald-300'}`}
    >
      <div className="flex items-start gap-2.5">
        <div className="w-9 h-9 rounded-full bg-emerald-100 flex items-center justify-center shrink-0">
          <span className="text-xs font-bold text-emerald-700">{farmer.name.charAt(0)}</span>
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5 flex-wrap">
            <p className="text-sm font-semibold text-slate-900 leading-tight truncate">{farmer.name}</p>
            <span className="text-xs text-slate-400 shrink-0">{farmer.code}</span>
          </div>
          <p className="text-xs text-slate-500 mt-0.5 truncate">{farmer.phone} · {farmer.loaiCay} · {totalArea.toFixed(1)}ha</p>
        </div>
      </div>

      {/* Mini indicators */}
      <div className="flex flex-wrap items-center gap-1 mt-2">
        <span className={`inline-flex items-center px-1.5 py-0.5 rounded-full text-xs font-medium ${isLocked ? 'bg-slate-100 text-slate-500' : 'bg-emerald-100 text-emerald-700'}`}>
          {isLocked ? 'Chưa eKYC' : 'eKYC OK'}
        </span>
        {kyc.creditScore && (
          <span className={`inline-flex items-center px-1.5 py-0.5 rounded-full text-xs font-medium ${scoreColor === 'text-emerald-600' ? 'bg-emerald-100 text-emerald-700' : scoreColor === 'text-amber-600' ? 'bg-amber-100 text-amber-700' : 'bg-red-100 text-red-700'}`}>
            {kyc.creditScore}
          </span>
        )}
        {debtSummary.hasOverdue && <span className="inline-flex items-center px-1.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-700">Quá hạn</span>}
        {pendingLoans.length > 0 && <span className="inline-flex items-center px-1.5 py-0.5 rounded-full text-xs font-medium bg-sky-100 text-sky-700">{pendingLoans.length} y/c vay</span>}
      </div>

      {/* Quick numbers */}
      <div className="grid grid-cols-2 gap-x-2 gap-y-0.5 mt-2 text-xs">
        <div><span className="text-slate-400">Hạn mức còn:</span> <span className={`font-medium ${hanMucTong > 0 ? 'text-slate-700' : 'text-slate-400'}`}>{hanMucTong > 0 ? formatCompactCurrency(conLai) : '—'}</span></div>
        <div><span className="text-slate-400">Dư nợ:</span> <span className={`font-medium ${totalNo > 0 ? 'text-red-600' : 'text-slate-400'}`}>{totalNo > 0 ? formatCompactCurrency(totalNo) : '0'}</span></div>
      </div>
    </button>
  );
}

export default function HtxFarmerPage() {
  useStore();
  const farmers = getFarmers();
  const [selectedFarmer, setSelectedFarmer] = useState<Farmer | null>(null);
  const [sheetOpen, setSheetOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');

  const stats = useMemo(() => {
    const total = farmers.length;
    const verified = farmers.filter((f) => getFarmerKyc(f).kycStatus === 'ekyc_verified').length;
    const pending = farmers.filter((f) => getFarmerKyc(f).kycStatus === 'ekyc_pending').length;
    const needMore = farmers.filter((f) => getFarmerKyc(f).kycStatus === 'ekyc_need_more').length;
    const failed = farmers.filter((f) => getFarmerKyc(f).kycStatus === 'ekyc_failed').length;
    const notKyc = farmers.filter((f) => getFarmerKyc(f).kycStatus === 'registered').length;
    const totalFields = farmers.reduce((sum, f) => sum + getFieldsByFarmer(f.id).length, 0);
    const totalArea = farmers.reduce((sum, f) => sum + getFieldsByFarmer(f.id).reduce((s, fi) => s + fi.area, 0), 0);
    return { total, verified, pending, needMore, failed, notKyc, totalFields, totalArea };
  }, [farmers]);

  const filtered = useMemo(() => {
    const s = search.toLowerCase();
    return farmers.filter((farmer) => {
      const matchesSearch = !s || farmer.name.toLowerCase().includes(s) || farmer.code.toLowerCase().includes(s) || farmer.phone.includes(s);
      if (!matchesSearch) return false;
      const kyc = getFarmerKyc(farmer);
      if (statusFilter === 'verified') return kyc.kycStatus === 'ekyc_verified';
      if (statusFilter === 'pending') return kyc.kycStatus === 'ekyc_pending';
      if (statusFilter === 'need_more') return kyc.kycStatus === 'ekyc_need_more';
      if (statusFilter === 'overdue') return getDebtSummary(farmer.id).hasOverdue;
      return true;
    });
  }, [farmers, search, statusFilter]);

  return (
    <div className="flex flex-col h-full min-h-0">
      {/* ── Farmer list (full width) ── */}
      <div className="flex flex-col w-full h-[calc(100dvh-120px)] lg:h-[calc(100vh-64px)] overflow-hidden">
        <div className="px-4 pt-4 pb-3 shrink-0">
          <h2 className="text-lg font-bold text-slate-900">Quản lý nông hộ</h2>

          <div className="mt-3">
            <SearchFilterBar
              value={search}
              onChange={setSearch}
              placeholder="Tìm tên, mã, SĐT..."
              selected={statusFilter}
              onSelect={setStatusFilter}
              options={[
                { value: '', label: 'Tất cả', count: stats.total },
                { value: 'verified', label: 'Đã xác thực eKYC', count: stats.verified, dotClass: 'bg-emerald-500' },
                { value: 'pending', label: 'Chờ xác thực', count: stats.pending, dotClass: 'bg-sky-500' },
                { value: 'need_more', label: 'Cần bổ sung', count: stats.needMore, dotClass: 'bg-amber-500' },
                { value: 'overdue', label: 'Có nợ quá hạn', dotClass: 'bg-rose-500' },
              ]}
            />
          </div>
          <p className="text-xs text-slate-400 mt-1.5">{filtered.length} nông hộ</p>
        </div>

        {/* Farmer cards scroll — grid layout */}
        <div className="flex-1 overflow-y-auto px-4 pb-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-3">
            {filtered.map((f) => (
              <FarmerCard
                key={f.id}
                farmer={f}
                isSelected={selectedFarmer?.id === f.id}
                onClick={() => { setSelectedFarmer(f); setSheetOpen(true); }}
              />
            ))}
            {filtered.length === 0 && (
              <div className="col-span-full bg-white rounded-xl border border-slate-200 p-8 text-center">
                <div className="w-10 h-10 mx-auto mb-2 rounded-full bg-slate-100 flex items-center justify-center"><i className="ri-user-search-line text-xl text-slate-400" /></div>
                <p className="text-sm text-slate-500">Không tìm thấy nông hộ</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* ── Farmer detail sheet (all devices) ── */}
      {selectedFarmer && (
        <FarmerDetailSheet
          farmer={selectedFarmer}
          open={sheetOpen}
          onClose={() => setSheetOpen(false)}
        />
      )}
    </div>
  );
}
