import { useMemo } from 'react';
import type { Farmer } from '../../../../types';
import { getLoansByFarmer, getDebtsByFarmer, getLimitsByFarmer, getContractsByFarmer, getSeasonsByFarmer } from '../../../../store';
import { StatusBadge } from '../../../../components/base/StatusBadge';
import { EmptyState } from '../../../../components/base/EmptyState';
import { formatDate, formatVND, formatCompactCurrency } from '../../../../utils/format';
import { useStore } from '../../../../hooks/useStore';
import { DEBT_STATUS, CONTRACT_STATUS } from '../../../../utils/status';

interface DetailFinanceTabProps {
  farmer: Farmer;
}

export default function DetailFinanceTab({ farmer }: DetailFinanceTabProps) {
  useStore();
  const loans = getLoansByFarmer(farmer.id);
  const debts = getDebtsByFarmer(farmer.id);
  const limits = getLimitsByFarmer(farmer.id);
  const contracts = getContractsByFarmer(farmer.id);
  const seasons = getSeasonsByFarmer(farmer.id);

  const totalNo = debts.filter((d) => d.conNo > 0).reduce((s, d) => s + d.conNo, 0);
  const noQuaHan = debts.filter((d) => d.status === DEBT_STATUS.OVERDUE).reduce((s, d) => s + d.conNo, 0);
  const noSapDenHan = debts.filter((d) => d.status === DEBT_STATUS.DUE_SOON || d.status === DEBT_STATUS.DUE).reduce((s, d) => s + d.conNo, 0);
  const hasOverdue = noQuaHan > 0;
  const hanMucTong = limits.reduce((s, l) => s + l.hanMuc, 0);
  const daDung = limits.reduce((s, l) => s + l.daSuDung, 0);
  const conLai = hanMucTong - daDung;
  const validContracts = contracts.filter((c) => c.status === CONTRACT_STATUS.ACTIVE);
  const expiringContracts = contracts.filter((c) => c.status === CONTRACT_STATUS.EXPIRING_SOON);
  const activeDebts = debts.filter((d) => d.conNo > 0);
  const usagePercent = hanMucTong > 0 ? (daDung / hanMucTong) * 100 : 0;
  const usageColor = usagePercent >= 90 ? 'bg-red-500' : usagePercent >= 70 ? 'bg-amber-500' : 'bg-emerald-500';

  return (
    <div className="space-y-5">
      {/* ── Summary cards ── */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 md:gap-3">
        <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
          <p className="text-xs text-slate-400">Tổng hạn mức</p>
          <p className="text-sm font-bold text-slate-900">{hanMucTong > 0 ? formatCompactCurrency(hanMucTong) : '—'}</p>
        </div>
        <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
          <p className="text-xs text-slate-400">Còn lại</p>
          <p className={`text-sm font-bold ${hanMucTong > 0 ? 'text-emerald-700' : 'text-slate-400'}`}>{hanMucTong > 0 ? formatCompactCurrency(conLai) : '—'}</p>
        </div>
        <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
          <p className="text-xs text-slate-400">Dư nợ</p>
          <p className={`text-sm font-bold ${totalNo > 0 ? 'text-red-600' : 'text-slate-400'}`}>{totalNo > 0 ? formatCompactCurrency(totalNo) : '0'}</p>
        </div>
        <div className="bg-white rounded-xl border border-slate-200 p-3 text-center">
          <p className="text-xs text-slate-400">HĐ hiệu lực</p>
          <p className="text-sm font-bold text-sky-700">{validContracts.length}</p>
        </div>
      </div>

      {/* ── Usage progress ── */}
      {hanMucTong > 0 && (
        <div className="bg-white rounded-xl border border-slate-200 p-4">
          <div className="flex justify-between text-xs text-slate-400 mb-1">
            <span>Đã dùng {formatCompactCurrency(daDung)} / {formatCompactCurrency(hanMucTong)}</span>
            <span>{usagePercent.toFixed(0)}%</span>
          </div>
          <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all ${usageColor}`} style={{ width: `${Math.min(100, usagePercent)}%` }} />
          </div>
        </div>
      )}

      {/* ── Contracts ── */}
      <div>
        <h3 className="text-base font-semibold text-slate-900 mb-3">Hợp đồng bao tiêu ({contracts.length})</h3>
        {validContracts.length === 0 && expiringContracts.length === 0 ? (
          <EmptyState icon="ri-file-text-line" title="Chưa có hợp đồng hiệu lực" description="Nông hộ chưa có hợp đồng bao tiêu nào đang hiệu lực." />
        ) : (
          <div className="space-y-3">
            {[...validContracts, ...expiringContracts].slice(0, 3).map((c) => (
              <div key={c.id} className="bg-white rounded-xl border border-slate-200 p-3 md:p-4">
                <div className="flex items-center gap-2 flex-wrap mb-1">
                  <p className="text-sm font-semibold text-slate-900">{c.soHopDong}</p>
                  <StatusBadge status={c.status} size="sm" />
                </div>
                <p className="text-xs text-slate-500">{c.loaiHopDong} · {c.doiTac}</p>
                <div className="flex flex-wrap gap-x-4 gap-y-1 mt-1.5 text-xs">
                  <span className="text-slate-600">Giá trị: <span className="font-medium">{formatVND(c.giaTri)}</span></span>
                  <span className="text-slate-400">{formatDate(c.ngayHieuLuc || c.ngayKy)} - {formatDate(c.ngayHetHan)}</span>
                  {c.cayTrong && <span className="text-slate-500">{c.cayTrong} ({c.dienTich}ha)</span>}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ── Limits ── */}
      {limits.length > 0 && (
        <div>
          <h3 className="text-base font-semibold text-slate-900 mb-3">Hạn mức ({limits.length})</h3>
          <div className="space-y-2">
            {limits.map((l) => (
              <div key={l.id} className="bg-white rounded-xl border border-slate-200 p-3 flex items-center justify-between gap-3">
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-slate-800">{l.loaiDinhMuc}</p>
                  <p className="text-xs text-slate-500">Hạn mức: {formatCompactCurrency(l.hanMuc)} · Đã dùng: {formatCompactCurrency(l.daSuDung)} · Còn: {formatCompactCurrency(l.hanMuc - l.daSuDung)}</p>
                </div>
                <div className="w-20 h-2 bg-slate-200 rounded-full overflow-hidden shrink-0">
                  <div className="h-full bg-emerald-600 rounded-full" style={{ width: `${Math.min(100, (l.daSuDung / l.hanMuc) * 100)}%` }} />
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Loan history ── */}
      <div>
        <h3 className="text-base font-semibold text-slate-900 mb-3">Lịch sử vay ({loans.length})</h3>
        {loans.length === 0 ? (
          <EmptyState icon="ri-money-cny-circle-line" title="Chưa có yêu cầu" description="Nông hộ chưa có yêu cầu tạm ứng nào." />
        ) : (
          <div className="space-y-2">
            {loans.slice(0, 5).map((l) => (
              <div key={l.id} className="bg-white rounded-xl border border-slate-200 p-3">
                <div className="flex items-center gap-2 flex-wrap mb-0.5">
                  <p className="text-xs font-semibold text-slate-900">Mã: {l.id}</p>
                  <StatusBadge status={l.status} size="sm" />
                  {l.isOverLimit && <span className="inline-flex items-center px-1.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-700">Vượt HM</span>}
                </div>
                <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-xs">
                  <span className="text-slate-600">{formatVND(l.soTien)}</span>
                  <span className="text-slate-400">{l.mucDich}</span>
                  <span className="text-slate-400">{formatDate(l.ngayYeuCau)}</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ── Current debts ── */}
      <div>
        <h3 className="text-base font-semibold text-slate-900 mb-3">
          Dư nợ ({activeDebts.length})
          {hasOverdue && <span className="ml-2 text-xs font-normal text-red-600">— có {debts.filter((d) => d.status === DEBT_STATUS.OVERDUE).length} khoản quá hạn</span>}
        </h3>
        {activeDebts.length === 0 ? (
          <EmptyState icon="ri-file-list-3-line" title="Không có dư nợ" description="Nông hộ không có khoản nợ nào đang hoạt động." />
        ) : (
          <div className="space-y-2">
            {activeDebts.map((d) => (
              <div key={d.id} className={`bg-white rounded-xl border p-3 ${d.status === DEBT_STATUS.OVERDUE ? 'border-red-200 bg-red-50/30' : 'border-slate-200'}`}>
                <div className="flex items-center gap-2 flex-wrap mb-1">
                  <p className="text-sm font-semibold text-slate-900">{d.maKhoanVay || d.id}</p>
                  <StatusBadge status={d.status} size="sm" />
                </div>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-x-3 gap-y-0.5 text-xs">
                  <div><span className="text-slate-400">Tổng nợ:</span> <span className="font-medium text-slate-700">{formatVND(d.soTien)}</span></div>
                  <div><span className="text-slate-400">Đã trả:</span> <span className="font-medium text-emerald-700">{formatVND(d.daTra)}</span></div>
                  <div><span className="text-slate-400">Còn nợ:</span> <span className={`font-medium ${d.conNo > 0 ? 'text-red-600' : 'text-emerald-700'}`}>{formatVND(d.conNo)}</span></div>
                  <div><span className="text-slate-400">Đến hạn:</span> <span className="font-medium text-slate-700">{formatDate(d.ngayDenHan)}</span></div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}