import { useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { CurrencyAmount } from '@/components/base/CurrencyAmount';
import { showToast } from '@/components/base/Toast';
import { useStore } from '@/hooks/useStore';
import type { AdvanceRequest } from '@/types';
import { checkDisburseEligibility, submitHtxDisbursement } from '@/utils/disbursementService';
import { getHtxMoneySummary } from '@/utils/financeEngine';
import { formatCurrencyFull } from '@/utils/formatters';

export function HtxDisbursementSheet({ loan, farmerName, onClose }: { loan: AdvanceRequest | null; farmerName: string; onClose: () => void }) {
  useStore();
  const summary = getHtxMoneySummary();
  const [submitting, setSubmitting] = useState(false);

  const submit = async () => {
    if (!loan) return;
    const check = checkDisburseEligibility(loan);
    if (!check.eligible) {
      showToast(check.reason, 'warning');
      return;
    }
    setSubmitting(true);
    const result = await submitHtxDisbursement(loan, farmerName, 'HTX giải ngân trực tiếp từ Ví HTX');
    setSubmitting(false);
    if (result.status === 'success') onClose();
    else showToast(result.message, 'error');
  };

  return (
    <BottomSheet
      open={!!loan}
      onClose={onClose}
      title="Xác nhận giải ngân"
      footer={(
        <div className="mobile-action-row">
          <button type="button" onClick={onClose} className="rounded-xl bg-slate-100 px-4 py-3 text-sm font-semibold text-slate-700">Hủy</button>
          <button type="button" disabled={submitting} onClick={submit} className="rounded-xl bg-emerald-700 px-4 py-3 text-sm font-semibold text-white disabled:bg-slate-300">{submitting ? 'Đang xử lý...' : 'Giải ngân'}</button>
        </div>
      )}
    >
      {loan && (
        <div className="space-y-3">
          <div className="rounded-2xl bg-slate-50 p-3.5 text-center">
            <p className="text-sm font-bold text-slate-900">{farmerName}</p>
            <p className="mt-2 text-xl font-bold text-emerald-700">{formatCurrencyFull(loan.soTien)}</p>
            <p className="metric-caption mt-1 text-[10px] text-slate-400">Ví HTX giảm và dư nợ nông hộ tăng cùng số tiền</p>
          </div>
          <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-center">
            <p className="text-[10px] font-medium uppercase tracking-wide text-emerald-600">Nguồn giải ngân</p>
            <div className="mt-1 flex items-center justify-center gap-1 text-sm font-bold text-emerald-800"><span>Ví HTX · còn</span><CurrencyAmount value={summary.availableLimit} /></div>
          </div>
        </div>
      )}
    </BottomSheet>
  );
}
