import { useState } from 'react';
import type { Season, Field } from '../../../../types';
import { getSeasonsByFarmer, getFieldsByFarmer, addSeason, updateSeason, deleteSeason } from '../../../../store';
import { StatusBadge } from '../../../../components/base/StatusBadge';
import { EmptyState } from '../../../../components/base/EmptyState';
import { showToast } from '../../../../components/base/Toast';
import { confirmModal } from '../../../../components/base/ConfirmModal';
import { formatDate } from '../../../../utils/format';
import { useStore } from '../../../../hooks/useStore';

interface SeasonTabProps {
  farmerId: string;
}

const cayTrongOptions = ['Lúa', 'Mít Thái', 'Sầu riêng', 'Cà phê', 'Bưởi da xanh', 'Thanh long', 'Rau màu'];
const statusOptions: Season['status'][] = ['Chuẩn bị', 'Đang canh tác', 'Sắp thu hoạch', 'Đã thu hoạch', 'Kết thúc', 'Có rủi ro'];

export default function SeasonTab({ farmerId }: SeasonTabProps) {
  const store = useStore();
  const seasons = getSeasonsByFarmer(farmerId);
  const fields = getFieldsByFarmer(farmerId);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [viewing, setViewing] = useState<Season | null>(null);
  const [form, setForm] = useState<Partial<Season>>({
    maMuaVu: '',
    name: '',
    fieldId: fields[0]?.id || '',
    cayTrong: cayTrongOptions[0],
    variety: '',
    startDate: '',
    endDate: '',
    expectedYield: 0,
    unit: 'tấn',
    dinhMucVatTu: '',
    status: 'Chuẩn bị',
    ghiChu: '',
  });

  const openCreate = () => {
    setEditingId(null);
    setForm({
      maMuaVu: '',
      name: '',
      fieldId: fields[0]?.id || '',
      cayTrong: cayTrongOptions[0],
      variety: '',
      startDate: '',
      endDate: '',
      expectedYield: 0,
      unit: 'tấn',
      dinhMucVatTu: '',
      status: 'Chuẩn bị',
      ghiChu: '',
    });
    setModalOpen(true);
  };

  const openEdit = (season: Season) => {
    setEditingId(season.id);
    setForm({ ...season });
    setModalOpen(true);
  };

  const openView = (season: Season) => {
    setViewing(season);
  };

  const closeView = () => setViewing(null);

  const fieldName = (fieldId?: string) => {
    if (!fieldId) return '-';
    const f = fields.find((x) => x.id === fieldId);
    return f ? `${f.name} (${f.maThuaDat})` : '-';
  };

  const canDelete = (seasonId: string) => {
    const hasDiary = store.diaries.some((d) => d.seasonId === seasonId);
    const hasHarvest = store.harvests.some((h) => h.seasonId === seasonId);
    const hasContract = store.contracts.some((c) => c.seasonIds?.includes(seasonId));
    const hasAdvance = store.advanceRequests.some((a) => a.seasonId === seasonId);
    return !hasDiary && !hasHarvest && !hasContract && !hasAdvance;
  };

  const handleSave = () => {
    if (!form.name || !form.maMuaVu || !form.fieldId || !form.startDate || !form.variety) {
      showToast('Vui lòng điền đầy đủ thông tin bắt buộc', 'warning');
      return;
    }
    const payload: Omit<Season, 'id'> = {
      farmerId,
      maMuaVu: form.maMuaVu || '',
      name: form.name || '',
      fieldId: form.fieldId || '',
      cayTrong: form.cayTrong || cayTrongOptions[0],
      variety: form.variety || '',
      startDate: form.startDate || '',
      endDate: form.endDate || undefined,
      expectedYield: Number(form.expectedYield) || 0,
      unit: form.unit || 'tấn',
      dinhMucVatTu: form.dinhMucVatTu || undefined,
      status: (form.status as Season['status']) || 'Chuẩn bị',
      ghiChu: form.ghiChu || undefined,
    };
    if (editingId) {
      updateSeason(editingId, payload);
      showToast('Đã cập nhật mùa vụ', 'success');
    } else {
      addSeason(payload);
      showToast('Đã tạo mùa vụ mới', 'success');
    }
    setModalOpen(false);
  };

  const handleDelete = async (season: Season) => {
    if (!canDelete(season.id)) {
      await confirmModal({
        title: 'Không thể xóa',
        message: 'Không thể xóa mùa vụ đã có nhật ký, thu hoạch, hợp đồng hoặc tạm ứng liên quan.',
        confirmText: 'Đã hiểu',
        cancelText: 'Đóng',
        variant: 'danger',
      });
      return;
    }
    const ok = await confirmModal({
      title: 'Xác nhận xóa',
      message: `Bạn có chắc muốn xóa mùa vụ "${season.name}"?`,
      confirmText: 'Xóa',
      cancelText: 'Hủy',
      variant: 'danger',
    });
    if (!ok) return;
    deleteSeason(season.id);
    showToast('Đã xóa mùa vụ', 'success');
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-base font-semibold text-slate-900">
          Mùa vụ ({seasons.length})
        </h3>
        <button
          type="button"
          onClick={openCreate}
          className="px-3 py-2 rounded-md text-sm font-medium bg-agrida-700 hover:bg-agrida-800 text-white transition-colors whitespace-nowrap min-h-[44px]"
        >
          <span className="w-4 h-4 inline-flex items-center justify-center mr-1">
            <i className="ri-add-line" />
          </span>
          Tạo mùa vụ
        </button>
      </div>

      {seasons.length === 0 ? (
        <EmptyState icon="ri-calendar-line" title="Chưa có mùa vụ" description="Hãy tạo mùa vụ để theo dõi quá trình canh tác." />
      ) : (
        <div className="space-y-3">
          {seasons.map((season) => (
            <div key={season.id} className="bg-white rounded-xl border border-slate-200 p-4 md:p-5">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-3">
                <div className="min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="text-sm font-semibold text-slate-900">{season.name}</p>
                    <StatusBadge status={season.status} />
                  </div>
                  <p className="text-xs text-slate-500 mt-1">
                    Mã: {season.maMuaVu} · {season.cayTrong} ({season.variety}) · {fieldName(season.fieldId)}
                  </p>
                  <p className="text-xs text-slate-400 mt-0.5">
                    {formatDate(season.startDate)}{season.endDate ? ` - ${formatDate(season.endDate)}` : ''} · Sản lượng dự kiến: {season.expectedYield} {season.unit}
                  </p>
                  {season.dinhMucVatTu && (
                    <p className="text-xs text-slate-500 mt-0.5">Định mức: {season.dinhMucVatTu}</p>
                  )}
                  {season.ghiChu && <p className="text-xs text-slate-500 mt-0.5">Ghi chú: {season.ghiChu}</p>}
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <button
                    type="button"
                    onClick={() => openView(season)}
                    className="px-3 py-1.5 rounded-md text-xs font-medium text-slate-600 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
                  >
                    Xem chi tiết
                  </button>
                  <button
                    type="button"
                    onClick={() => openEdit(season)}
                    className="px-3 py-1.5 rounded-md text-xs font-medium text-agrida-700 bg-agrida-50 hover:bg-agrida-100 transition-colors whitespace-nowrap min-h-[44px]"
                  >
                    Sửa
                  </button>
                  <button
                    type="button"
                    onClick={() => handleDelete(season)}
                    className="px-3 py-1.5 rounded-md text-xs font-medium text-red-700 bg-red-50 hover:bg-red-100 transition-colors whitespace-nowrap min-h-[44px]"
                  >
                    Xóa
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* View modal */}
      {viewing && (
        <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={closeView} />
          <div className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-lg max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto animate-modal-panel">
            <div className="sticky top-0 bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between z-10">
              <h3 className="text-base font-semibold text-slate-900">Chi tiết mùa vụ</h3>
              <button type="button" onClick={closeView} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400">
                <i className="ri-close-line text-lg" />
              </button>
            </div>
            <div className="p-4 space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div><p className="text-xs text-slate-400">Mã mùa vụ</p><p className="text-sm font-medium">{viewing.maMuaVu}</p></div>
                <div><p className="text-xs text-slate-400">Tên mùa vụ</p><p className="text-sm font-medium">{viewing.name}</p></div>
                <div><p className="text-xs text-slate-400">Thửa đất</p><p className="text-sm font-medium">{fieldName(viewing.fieldId)}</p></div>
                <div><p className="text-xs text-slate-400">Cây trồng</p><p className="text-sm font-medium">{viewing.cayTrong} ({viewing.variety})</p></div>
                <div><p className="text-xs text-slate-400">Ngày bắt đầu</p><p className="text-sm font-medium">{formatDate(viewing.startDate)}</p></div>
                <div><p className="text-xs text-slate-400">Ngày kết thúc dự kiến</p><p className="text-sm font-medium">{viewing.endDate ? formatDate(viewing.endDate) : '-'}</p></div>
                <div><p className="text-xs text-slate-400">Sản lượng dự kiến</p><p className="text-sm font-medium">{viewing.expectedYield} {viewing.unit}</p></div>
                <div><p className="text-xs text-slate-400">Tình trạng</p><StatusBadge status={viewing.status} /></div>
              </div>
              {viewing.dinhMucVatTu && (
                <div><p className="text-xs text-slate-400">Định mức vật tư dự kiến</p><p className="text-sm">{viewing.dinhMucVatTu}</p></div>
              )}
              {viewing.ghiChu && (
                <div><p className="text-xs text-slate-400">Ghi chú</p><p className="text-sm">{viewing.ghiChu}</p></div>
              )}
            </div>
            <div className="sticky bottom-0 bg-white border-t border-slate-100 px-4 py-3">
              <button
                type="button"
                onClick={closeView}
                className="w-full px-4 py-2.5 rounded-lg text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
              >
                Đóng
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Create/Edit modal */}
      {modalOpen && (
        <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="absolute inset-0 bg-black/40 animate-modal-backdrop" onClick={() => setModalOpen(false)} />
          <div className="relative bg-white rounded-t-xl sm:rounded-xl shadow-xl w-full sm:max-w-lg max-h-[100dvh] sm:max-h-[90vh] overflow-y-auto animate-modal-panel">
            <div className="sticky top-0 bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between z-10">
              <h3 className="text-base font-semibold text-slate-900">{editingId ? 'Sửa mùa vụ' : 'Tạo mùa vụ'}</h3>
              <button type="button" onClick={() => setModalOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-100 text-slate-400">
                <i className="ri-close-line text-lg" />
              </button>
            </div>
            <div className="px-4 py-4 space-y-3">
              <div>
                <label className="block text-xs text-slate-500 mb-1">Mã mùa vụ *</label>
                <input
                  type="text"
                  value={form.maMuaVu || ''}
                  onChange={(e) => setForm((p) => ({ ...p, maMuaVu: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Tên mùa vụ *</label>
                <input
                  type="text"
                  value={form.name || ''}
                  onChange={(e) => setForm((p) => ({ ...p, name: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Chọn thửa đất *</label>
                <select
                  value={form.fieldId || ''}
                  onChange={(e) => setForm((p) => ({ ...p, fieldId: e.target.value }))}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                >
                  {fields.map((f) => (
                    <option key={f.id} value={f.id}>{f.name} ({f.maThuaDat})</option>
                  ))}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Cây trồng</label>
                  <select
                    value={form.cayTrong || cayTrongOptions[0]}
                    onChange={(e) => setForm((p) => ({ ...p, cayTrong: e.target.value }))}
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                  >
                    {cayTrongOptions.map((o) => <option key={o} value={o}>{o}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Giống cây *</label>
                  <input
                    type="text"
                    value={form.variety || ''}
                    onChange={(e) => setForm((p) => ({ ...p, variety: e.target.value }))}
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Ngày bắt đầu *</label>
                  <input
                    type="date"
                    value={form.startDate || ''}
                    onChange={(e) => setForm((p) => ({ ...p, startDate: e.target.value }))}
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                  />
                </div>
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Ngày kết thúc dự kiến</label>
                  <input
                    type="date"
                    value={form.endDate || ''}
                    onChange={(e) => setForm((p) => ({ ...p, endDate: e.target.value || undefined }))}
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Sản lượng dự kiến</label>
                  <input
                    type="number"
                    step="0.1"
                    value={form.expectedYield || ''}
                    onChange={(e) => setForm((p) => ({ ...p, expectedYield: Number(e.target.value) }))}
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                  />
                </div>
                <div>
                  <label className="block text-xs text-slate-500 mb-1">Đơn vị</label>
                  <select
                    value={form.unit || 'tấn'}
                    onChange={(e) => setForm((p) => ({ ...p, unit: e.target.value }))}
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                  >
                    <option value="tấn">tấn</option>
                    <option value="kg">kg</option>
                    <option value="tạ">tạ</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Định mức vật tư dự kiến</label>
                <textarea
                  value={form.dinhMucVatTu || ''}
                  onChange={(e) => setForm((p) => ({ ...p, dinhMucVatTu: e.target.value }))}
                  rows={2}
                  maxLength={500}
                  placeholder="Ví dụ: Giống 300kg, NPK 500kg..."
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Tình trạng mùa vụ</label>
                <select
                  value={form.status || 'Chuẩn bị'}
                  onChange={(e) => setForm((p) => ({ ...p, status: e.target.value as Season['status'] }))}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                >
                  {statusOptions.map((o) => <option key={o} value={o}>{o}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs text-slate-500 mb-1">Ghi chú</label>
                <textarea
                  value={form.ghiChu || ''}
                  onChange={(e) => setForm((p) => ({ ...p, ghiChu: e.target.value }))}
                  rows={2}
                  maxLength={500}
                  className="w-full px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-agrida-500"
                />
              </div>
            </div>
            <div className="sticky bottom-0 bg-white border-t border-slate-100 px-4 py-3 flex gap-3 justify-end">
              <button
                type="button"
                onClick={() => setModalOpen(false)}
                className="px-4 py-2.5 rounded-lg text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 transition-colors whitespace-nowrap min-h-[44px]"
              >
                Hủy
              </button>
              <button
                type="button"
                onClick={handleSave}
                className="px-4 py-2.5 rounded-lg text-sm font-medium bg-agrida-700 hover:bg-agrida-800 text-white transition-colors whitespace-nowrap min-h-[44px]"
              >
                {editingId ? 'Lưu thay đổi' : 'Tạo'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
