import { useEffect, useMemo, useState } from 'react';
import { BottomSheet } from '@/components/base/BottomSheet';
import { MobileMetricCard } from '@/components/base/MobileUi';
import { showToast } from '@/components/base/Toast';
import { useStore } from '@/hooks/useStore';
import {
  getContractsByFarmer,
  getFarmerById,
  getFarmerKyc,
  getLimitRequests,
  getLimitsByContract,
} from '@/store';
import { getHtxMoneySummary } from '@/utils/financeEngine';
import { formatCurrencyCompact } from '@/utils/formatters';
import { formatVND } from '@/utils/format';
import { executeGrantLimit } from '@/utils/limitGrantService';
import { calculateLimitProposal } from '@/utils/limitProposal';

interface FarmerLimitSheetProps {
  open: boolean;
  farmerId: string;
  contractId?: string;
  requestId?: string;
  onClose: () => void;
}

export function FarmerLimitSheet({ open, farmerId, contractId, requestId, onClose }: FarmerLimitSheetProps) {
  useStore();
  const farmer = getFarmerById(farmerId);
  const contract = useMemo(() => {
    const contracts = getContractsByFarmer(farmerId);
    return contracts.find((item) => item.id === contractId)
      || contracts.find((item) => item.loaiHopDong === 'HTX-Nông hộ' && ['Đang hiệu lực', 'Sắp hết hạn'].includes(item.status));
  }, [contractId, farmerId]);
  const existingLimit = contract ? getLimitsByContract(contract.id)[0] : undefined;
  const request = requestId ? getLimitRequests().find((item) => item.id === requestId) : undefined;
  const kyc = farmer ? getFarmerKyc(farmer) : null;
  const proposal = contract && kyc
    ? calculateLimitProposal(contract.giaTri, kyc.riskLevel, contract.hanMucDaCap || 0, kyc.creditScore)
    : null;
  const htxMoney = getHtxMoneySummary();
  const [amount, setAmount] = useState('');
  const [reason, setReason] = useState('');

  useEffect(() => {
    if (!open) return;
    setAmount(String(request?.hanMucDeXuat || existingLimit?.hanMuc || proposal?.suggestedLimit || ''));
    setReason(request?.lyDoVuot || '');
  }, [existingLimit?.hanMuc, open, proposal?.suggestedLimit, request?.hanMucDeXuat, request?.lyDoVuot]);

  const numericAmount = Number(amount);
  const needsReason = !!contract && !!proposal && (
    numericAmount > proposal.suggestedLimit
    || numericAmount > (contract.hanMucConLai ?? contract.giaTri)
    || (kyc?.creditScore || 0) < 550
    || ['Rủi ro cao', 'Nguy cơ'].includes(kyc?.riskLevel || '')
  );

  const submit = () => {
    if (!farmer || !contract || !proposal) {
      showToast('Nông hộ chưa có hợp đồng phù hợp để cấp hạn mức.', 'warning');
      return;
    }
    if (kyc?.kycStatus !== 'ekyc_verified') {
      showToast('Nông hộ cần hoàn tất eKYC trước khi cấp hạn mức.', 'warning');
      return;
    }
    if (!numericAmount || numericAmount <= 0) {
      showToast('Vui lòng nhập hạn mức hợp lệ.', 'warning');
      return;
    }
    if (needsReason && !reason.trim()) {
      showToast('Vui lòng nhập lý do phê duyệt.', 'warning');
      return;
    }
    try {
      const result = executeGrantLimit({
        farmerId: farmer.id,
        farmerName: farmer.name,
        contractId: contract.id,
        hanMuc: numericAmount,
        limitId: existingLimit?.id,
        requestId: request?.id,
        overrideReason: reason.trim() || undefined,
      });
      showToast(result.isUpdate ? 'Đã điều chỉnh hạn mức nông hộ.' : 'Đã cấp hạn mức nông hộ.', 'success');
      onClose();
    } catch (error) {
      showToast(error instanceof Error ? error.message : 'Không thể cập nhật hạn mức.', 'error');
    }
  };

  return (
    <BottomSheet
      open={open}
      onClose={onClose}
      title={existingLimit ? 'Điều chỉnh hạn mức' : 'Hạn mức nông hộ'}
      footer={(
        <div className="mobile-action-row">
          <button type="button" onClick={onClose} className="rounded-xl bg-slate-100 px-4 py-3 text-sm font-semibold text-slate-700">Hủy</button>
          <button type="button" onClick={submit} className="rounded-xl bg-emerald-700 px-4 py-3 text-sm font-semibold text-white">{existingLimit ? 'Lưu thay đổi' : 'Xác nhận cấp'}</button>
        </div>
      )}
    >
      {!farmer || !contract || !proposal ? (
        <div className="rounded-2xl border border-dashed border-slate-200 py-8 text-center text-sm text-slate-400">Không có hợp đồng phù hợp.</div>
      ) : (
        <div className="space-y-4">
          <div className="rounded-2xl bg-slate-50 p-3.5">
            <p className="text-sm font-bold text-slate-900">{farmer.name}</p>
            <p className="metric-caption mt-1 text-[10px] text-slate-400">{contract.soHopDong} · Giá trị {formatCurrencyCompact(contract.giaTri)}</p>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <MobileMetricCard label="Mức đề xuất" value={formatCurrencyCompact(proposal.suggestedLimit)} caption={`${proposal.riskLevel} · ${proposal.ratioPercent}`} tone="emerald" />
            <MobileMetricCard label="Ví HTX khả dụng" value={formatCurrencyCompact(htxMoney.availableLimit)} caption="Không trừ tiền khi cấp hạn mức" tone="sky" />
          </div>
          <label className="block">
            <span className="mb-1.5 block text-xs font-semibold text-slate-600">Hạn mức duyệt</span>
            <input type="number" value={amount} onChange={(event) => setAmount(event.target.value)} className="h-12 w-full rounded-xl border border-slate-200 px-3 text-sm outline-none focus:border-emerald-500" />
            <span className="metric-caption mt-1 block text-[10px] text-slate-400">{formatVND(numericAmount || 0)}</span>
          </label>
          {needsReason && (
            <label className="block">
              <span className="mb-1.5 block text-xs font-semibold text-slate-600">Lý do phê duyệt</span>
              <textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={3} className="w-full resize-none rounded-xl border border-slate-200 px-3 py-2.5 text-sm outline-none focus:border-emerald-500" placeholder="Nhập lý do ngắn gọn" />
            </label>
          )}
        </div>
      )}
    </BottomSheet>
  );
}
