import { useState, useCallback, useMemo } from 'react';
import { useStore } from '../../../hooks/useStore';
import {
  getContracts, getFarmers, getSeasons, getHarvests, getRiskProfileByFarmer,
  getFarmerKyc, getLimitsByContract, getLoans,
  getEditHistories,
  addContract, updateContract, deleteContract, addEditHistory,
  updateSeason, updateFarmer,
} from '../../../store';
import { showToast } from '../../../components/base/Toast';
import { confirmModal } from '../../../components/base/ConfirmModal';
import { EmptyState } from '../../../components/base/EmptyState';
import { FarmerLimitSheet } from '../../../components/feature/FarmerLimitSheet';
import ContractStats from './components/ContractStats';
import ContractFilters from './components/ContractFilters';
import ContractCard from './components/ContractCard';
import ContractFormModal from './components/ContractFormModal';
import ContractDetailModal from './components/ContractDetailModal';
import type { Contract, ContractAttachment } from '../../../types';

export default function HtxContractPage() {
  useStore();
  const contracts = getContracts();
  const farmers = getFarmers();
  const allSeasons = getSeasons();
  const allHarvests = getHarvests();
  const allLoans = getLoans();
  const allEditHistories = getEditHistories();

  const [filtered, setFiltered] = useState<Contract[]>(contracts);
  const [formOpen, setFormOpen] = useState(false);
  const [editItem, setEditItem] = useState<Contract | null>(null);
  const [detailItem, setDetailItem] = useState<Contract | null>(null);
  const [limitContract, setLimitContract] = useState<Contract | null>(null);

  const farmerOptions = useMemo(() => farmers.map((f) => ({ id: f.id, name: f.name })), [farmers]);
  const seasonOptions = useMemo(() => allSeasons.map((s) => ({ id: s.id, name: s.name })), [allSeasons]);

  const farmerKycMap = useMemo(() => {
    const map: Record<string, ReturnType<typeof getFarmerKyc>> = {};
    farmers.forEach((f) => {
      map[f.id] = getFarmerKyc(f);
    });
    return map;
  }, [farmers]);

  const getFarmerName = (id: string) => farmers.find((f) => f.id === id)?.name || id;
  const getSeasonNames = (ids?: string[]) => (ids || []).map((sid) => allSeasons.find((s) => s.id === sid)?.name || '').filter(Boolean);
  const getCayTrong = (ids?: string[]) => {
    const s = allSeasons.find((se) => ids?.includes(se.id));
    return s?.cayTrong || '';
  };

  const openCreate = () => {
    setEditItem(null);
    setFormOpen(true);
  };

  const openEdit = (item: Contract) => {
    setEditItem(item);
    setFormOpen(true);
  };

  const openDetail = (item: Contract) => {
    setDetailItem(item);
  };

  const getCanAllocateInfo = (contract: Contract) => {
    if (contract.loaiHopDong !== 'HTX-Nông hộ') return { canAllocate: false, canAllocateWithWarning: false };
    if (contract.status === 'Đang hiệu lực') return { canAllocate: true, canAllocateWithWarning: false };
    if (contract.status === 'Sắp hết hạn') return { canAllocate: true, canAllocateWithWarning: true };
    return { canAllocate: false, canAllocateWithWarning: false };
  };

  const handleAllocateLimit = (contract: Contract) => {
    setDetailItem(null);
    setLimitContract(contract);
  };

  const handleViewLimits = (contract: Contract) => {
    setDetailItem(null);
    showToast(`Đang chuyển đến hạn mức của ${getFarmerName(contract.farmerId)}`, 'info');
  };

  const handleViewRisk = (contract: Contract) => {
    setDetailItem(null);
    showToast(`Đang chuyển đến hồ sơ rủi ro của ${getFarmerName(contract.farmerId)}`, 'info');
  };

  const handleAddDocs = (contract: Contract) => {
    setDetailItem(null);
    setEditItem(contract);
    setFormOpen(true);
    showToast('Vui lòng thêm tài liệu trong bước 2 của form', 'info');
  };

  const handleExtend = async (contract: Contract) => {
    const newEndDate = new Date(contract.ngayHetHan);
    newEndDate.setFullYear(newEndDate.getFullYear() + 1);
    const newDateStr = newEndDate.toISOString().split('T')[0];
    const ok = await confirmModal({
      title: 'Gia hạn hợp đồng', message: `Gia hạn hợp đồng ${contract.soHopDong} đến ${newDateStr}?\nTrạng thái sẽ chuyển về "Đang hiệu lực".`,
      variant: 'primary', confirmText: 'Gia hạn',
    });
    if (ok) {
      updateContract(contract.id, { ngayHetHan: newDateStr, status: 'Đang hiệu lực' });
      addEditHistory({ entityType: 'Contract', entityId: contract.id, farmerId: contract.farmerId, truong: 'ngayHetHan', giaTriCu: contract.ngayHetHan, giaTriMoi: newDateStr, ngaySua: new Date().toISOString(), nguoiSua: 'HTX Hòa Phát' });
      showToast(`Đã gia hạn hợp đồng đến ${newDateStr}`, 'success');
    }
  };

  const handleSave = useCallback((data: Omit<Contract, 'id' | 'soHopDong'>, attachments: ContractAttachment[]) => {
    if (editItem) {
      const oldData = { ...editItem };
      const updated: Contract = { ...oldData, ...data, attachments };
      updateContract(editItem.id, updated);
      if (oldData.giaTri !== updated.giaTri) {
        addEditHistory({ entityType: 'Contract', entityId: editItem.id, farmerId: editItem.farmerId, truong: 'giaTri', giaTriCu: String(oldData.giaTri), giaTriMoi: String(updated.giaTri), ngaySua: new Date().toISOString(), nguoiSua: 'HTX Hòa Phát' });
      }
      if (oldData.status !== updated.status) {
        addEditHistory({ entityType: 'Contract', entityId: editItem.id, farmerId: editItem.farmerId, truong: 'status', giaTriCu: oldData.status, giaTriMoi: updated.status, ngaySua: new Date().toISOString(), nguoiSua: 'HTX Hòa Phát' });
      }
      updated.seasonIds?.forEach((sid) => {
        const season = allSeasons.find((s) => s.id === sid);
        if (season) updateSeason(sid, { ghiChu: `${season.ghiChu || ''} | Hợp đồng: ${updated.soHopDong}`.trim() });
      });
      const farmer = farmers.find((f) => f.id === updated.farmerId);
      if (farmer) updateFarmer(farmer.id, { ghiChu: `${farmer.ghiChu || ''} | Hợp đồng: ${updated.soHopDong}`.trim() });
      showToast('Đã cập nhật hợp đồng', 'success');
    } else {
      const nextNum = contracts.filter((c) => !c.isDeleted).length + 1;
      const soHopDong = `HD-${new Date().getFullYear()}-${String(nextNum).padStart(3, '0')}`;
      const newContract: Contract = { id: `c${Date.now()}`, soHopDong, ...data, attachments, hanMucDaCap: 0, hanMucConLai: data.giaTri || 0 };
      addContract(newContract);
      newContract.seasonIds?.forEach((sid) => {
        const season = allSeasons.find((s) => s.id === sid);
        if (season) updateSeason(sid, { ghiChu: `${season.ghiChu || ''} | Hợp đồng: ${soHopDong}`.trim() });
      });
      const farmer = farmers.find((f) => f.id === newContract.farmerId);
      if (farmer) updateFarmer(farmer.id, { ghiChu: `${farmer.ghiChu || ''} | Hợp đồng: ${soHopDong}`.trim() });
      showToast('Đã tạo hợp đồng mới', 'success');
    }
    setFormOpen(false);
    setEditItem(null);
  }, [editItem, contracts, farmers, allSeasons]);

  const handleDelete = async (item: Contract) => {
    const relatedHarvests = allHarvests.filter((h) => h.seasonId && item.seasonIds?.includes(h.seasonId) && h.status === 'HTX đã xác nhận');
    const isActive = item.status === 'Đang hiệu lực';
    const hasConfirmedHarvests = relatedHarvests.length > 0;
    if (isActive && hasConfirmedHarvests) {
      const choice = await confirmModal({ title: 'Không thể xóa hợp đồng', message: `Hợp đồng ${item.soHopDong} đang hiệu lực và đã có ${relatedHarvests.length} lần thu hoạch được xác nhận.`, variant: 'primary', confirmText: 'Chuyển Tạm dừng', cancelText: 'Chuyển Hủy' });
      if (choice) { updateContract(item.id, { status: 'Tạm dừng' }); showToast('Đã chuyển hợp đồng sang Tạm dừng', 'success'); }
      else { updateContract(item.id, { status: 'Hủy' }); showToast('Đã chuyển hợp đồng sang Hủy', 'success'); }
      return;
    }
    const ok = await confirmModal({ title: 'Xóa hợp đồng', message: `Bạn có chắc muốn xóa "${item.soHopDong}"?`, variant: 'danger', confirmText: 'Xóa' });
    if (ok) { deleteContract(item.id); showToast('Đã xóa hợp đồng', 'success'); }
  };

  const activeList = filtered.filter((c) => !c.isDeleted);

  // Detail data computed when detailItem changes
  const detailData = detailItem ? (() => {
    const allocInfo = getCanAllocateInfo(detailItem);
    const riskProfile = getRiskProfileByFarmer(detailItem.farmerId);
    const contractLoans = allLoans.filter((l) =>
      l.loai === 'Tiền' &&
      l.seasonId &&
      detailItem.seasonIds?.includes(l.seasonId)
    );
    const contractEditHistories = allEditHistories.filter(
      (eh) => eh.entityType === 'Contract' && eh.entityId === detailItem.id
    );
    return { allocInfo, riskProfile, contractLoans, contractEditHistories };
  })() : null;

  return (
    <div className="flex flex-col h-full min-h-0">
      {/* ── Main content area ── */}
      <div className="flex-1 overflow-y-auto">
        <div className="mobile-page md:px-6 md:py-5">

          {/* ── Header ── */}
          <div className="mb-4 flex items-center justify-between gap-3">
            <div className="min-w-0">
              <h2 className="text-lg font-bold text-slate-900">Hợp đồng</h2>
              <p className="metric-caption mt-0.5 text-[11px] text-slate-400">Quản lý hồ sơ và giá trị hợp đồng</p>
            </div>
            <button
              type="button"
              onClick={openCreate}
              className="flex min-h-11 shrink-0 items-center gap-1.5 rounded-xl bg-emerald-700 px-3.5 text-xs font-semibold text-white"
            >
              <span className="w-4 h-4 flex items-center justify-center"><i className="ri-add-line" /></span>
              Tạo mới
            </button>
          </div>

          {/* ── Stats ── */}
          <div className="mb-4">
            <ContractStats />
          </div>

          {/* ── Filters ── */}
          <div className="mb-4">
            <ContractFilters contracts={contracts} farmers={farmerOptions} seasons={seasonOptions} onFilterChange={setFiltered} />
          </div>

          {/* ── List header ── */}
          <div className="mb-2.5 flex items-center justify-between"><h3 className="text-sm font-semibold text-slate-900">Danh sách hợp đồng</h3><span className="text-[11px] text-slate-400">{activeList.length} hợp đồng</span></div>

          {/* ── Contract list ── */}
          {activeList.length === 0 ? (
            <EmptyState
              icon="ri-draft-line"
              title="Chưa có hợp đồng"
              description="Hãy tạo hợp đồng đầu tiên để bắt đầu quản lý bao tiêu và cấp hạn mức."
            />
          ) : (
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-3">
              {activeList.map((c) => (
                <ContractCard
                  key={c.id}
                  contract={c}
                  farmerName={getFarmerName(c.farmerId)}
                  farmerId={c.farmerId}
                  farmerKyc={farmerKycMap[c.farmerId]}
                  seasonNames={getSeasonNames(c.seasonIds)}
                  cayTrong={getCayTrong(c.seasonIds)}
                  onViewDetail={() => openDetail(c)}
                  onEdit={() => openEdit(c)}
                  onDelete={() => handleDelete(c)}
                  onAllocateLimit={() => handleAllocateLimit(c)}
                  onAddDocs={() => handleAddDocs(c)}
                  onExtend={() => handleExtend(c)}
                />
              ))}
            </div>
          )}

          {/* ── Bottom spacer ── */}
          <div className="h-8" />
        </div>
      </div>

      {/* ── MODALS ── */}

      {/* Detail modal — popup on all devices */}
      {detailItem && detailData && (
        <ContractDetailModal
          contract={detailItem}
          farmerName={getFarmerName(detailItem.farmerId)}
          farmerId={detailItem.farmerId}
          farmerKyc={farmerKycMap[detailItem.farmerId] || { kycStatus: 'ekyc_verified', creditScore: 600, riskLevel: 'Cần chú ý' }}
          seasonNames={getSeasonNames(detailItem.seasonIds)}
          seasons={allSeasons}
          relatedHarvests={allHarvests.filter((h) => h.seasonId && detailItem.seasonIds?.includes(h.seasonId))}
          relatedLimits={getLimitsByContract(detailItem.id)}
          relatedLoans={detailData.contractLoans}
          editHistories={detailData.contractEditHistories}
          riskMucDo={detailData.riskProfile?.mucDo}
          riskMoTa={detailData.riskProfile?.moTa}
          canAllocate={detailData.allocInfo.canAllocate}
          canAllocateWithWarning={detailData.allocInfo.canAllocateWithWarning}
          onClose={() => setDetailItem(null)}
          onEdit={() => { setDetailItem(null); openEdit(detailItem); }}
          onAllocateLimit={() => handleAllocateLimit(detailItem)}
          onViewLimits={() => handleViewLimits(detailItem)}
          onAddDocs={() => handleAddDocs(detailItem)}
          onExtend={() => handleExtend(detailItem)}
          onViewRisk={() => handleViewRisk(detailItem)}
        />
      )}

      {/* Form modal */}
      {formOpen && (
        <ContractFormModal editItem={editItem} onClose={() => { setFormOpen(false); setEditItem(null); }} onSave={handleSave} />
      )}

      <FarmerLimitSheet
        open={!!limitContract}
        farmerId={limitContract?.farmerId || ''}
        contractId={limitContract?.id}
        onClose={() => setLimitContract(null)}
      />

    </div>
  );
}
