import { useState, useEffect, useCallback } from 'react';
import { getState, subscribe, login as storeLogin, logout as storeLogout, register as storeRegister, updateKycStatus as storeUpdateKyc } from '../store';
import type { User, KycStatus } from '../types';

export function useAuth() {
  const [user, setUser] = useState<User | null>(getState().currentUser);

  useEffect(() => {
    return subscribe(() => {
      setUser(getState().currentUser);
    });
  }, []);

  const login = useCallback((username: string, password: string): User | null => {
    return storeLogin(username, password);
  }, []);

  const register = useCallback((data: {
    username: string;
    password: string;
    role: 'Nông hộ' | 'Hợp tác xã';
    displayName: string;
    code: string;
    phone?: string;
    address?: string;
    tinhThanh?: string;
    huyen?: string;
    xa?: string;
    loaiCay?: string;
    nguoiDaiDien?: string;
    chucVu?: string;
    dienTich?: number;
  }): User => {
    return storeRegister(data);
  }, []);

  const updateKycStatus = useCallback((userId: string, newStatus: KycStatus, reason?: string, creditScore?: number, riskLevel?: 'Tốt' | 'Cần chú ý' | 'Nguy cơ') => {
    storeUpdateKyc(userId, newStatus, reason, creditScore, riskLevel);
  }, []);

  const logout = useCallback(() => {
    storeLogout();
  }, []);

  return { user, login, register, updateKycStatus, logout };
}